# ============ RBAC ROLE HIERARCHY ============
ROLE_LEVELS = {
    'Accountant':  1,
    'Admin':       2,
    'Super Admin': 3,
    'Developer':   4,
}
ALL_ADMIN_ROLES = list(ROLE_LEVELS.keys())

def get_role_level(role_name):
    """Return numeric level for a role string. Unknown roles get 0."""
    return ROLE_LEVELS.get(role_name, 0)


def require_role(min_role='Admin'):
    """Decorator: require that the logged-in admin has at least `min_role` level."""
    min_level = get_role_level(min_role)
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            if 'admin_id' not in session:
                flash("Unauthorized Access!", "danger")
                return redirect(url_for('admin_login', next=request.path))
            user_level = get_role_level(session.get('admin_role', ''))
            if user_level < min_level:
                flash("You do not have permission to access this page.", "danger")
                return redirect(url_for('admin_dashboard'))
            return f(*args, **kwargs)
        return wrapper
    return decorator


def require_admin(f=None):
    """Backward-compatible. Works as @require_admin decorator or require_admin() function call."""
    if f is None:
        if 'admin_id' not in session:
            return redirect(url_for('admin_login', next=request.path))
        if get_role_level(session.get('admin_role', '')) < get_role_level('Admin'):
            flash("You do not have permission to access this page.", "danger")
            return redirect(url_for('admin_dashboard'))
        return None
    @wraps(f)
    def wrapper(*args, **kwargs):
        if 'admin_id' not in session:
            flash("Unauthorized Access!", "danger")
            return redirect(url_for('admin_login', next=request.path))
        if get_role_level(session.get('admin_role', '')) < get_role_level('Admin'):
            flash("You do not have permission to access this page.", "danger")
            return redirect(url_for('admin_dashboard'))
        return f(*args, **kwargs)
    return wrapper


def require_accountant_or_role(min_role='Super Admin'):
    """Allow Accountant role OR minimum role level."""
    min_level = get_role_level(min_role)
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            if 'admin_id' not in session:
                flash("Unauthorized Access!", "danger")
                return redirect(url_for('admin_login', next=request.path))
            role = session.get('admin_role', '')
            if role != 'Accountant' and get_role_level(role) < min_level:
                flash("You do not have permission to access this page.", "danger")
                return redirect(url_for('admin_dashboard'))
            return f(*args, **kwargs)
        return wrapper
    return decorator

