def _is_unit_quiz_file(name: str) -> bool:
    """Return True if this filename belongs to a Unit Quiz JSON."""
    return name.lower().endswith("_unit_questions.json")


def _editor_dir_for(filename: str) -> str:
    """Return which folder the given filename belongs to."""
    return UNIT_QUIZ_DIR if _is_unit_quiz_file(filename) else FINAL_DIR


def _list_all_mcq_files():
    """List all final & unit quiz JSON files combined."""
    finals = [f for f in os.listdir(FINAL_DIR) if f.endswith(".json")]
    units = [f for f in os.listdir(UNIT_QUIZ_DIR) if f.endswith(".json")]
    return sorted(set(finals + units), key=str.lower)


