def _unit_slug(s): return (s or "").strip().lower().replace(" ", "_")


def unit_questions_filename(course):
    slug = _unit_slug(getattr(course, "code", "")) or f"course_{course.id}"
    return f"{slug}_unit_questions.json"


def unit_questions_path(filename):
    return os.path.join(UNIT_QUIZ_DIR, os.path.basename(filename))


def unit_placement_path(course_id: int):
    return os.path.join(UNIT_PLACEMENTS_DIR, f"course_{course_id}_placement.json")


def load_unit_questions_safe(path: str):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, list) else []
    except Exception:
        return []


def save_placement(course_id: int, payload: dict):
    with open(unit_placement_path(course_id), "w", encoding="utf-8") as f:
        json.dump(payload, f, ensure_ascii=False, indent=2)


def load_placement(course_id: int) -> dict:
    p = unit_placement_path(course_id)
    if not os.path.exists(p):
        # { chapter_id(str): [question_id(int), ...] }
        return {"by_chapter": {}}
    try:
        with open(p, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            data = {"by_chapter": {}}
        data.setdefault("by_chapter", {})
        return data
    except Exception:
        return {"by_chapter": {}}

