### Helper: find ID document file (supports .jpg and .pdf) ###

def _find_id_file(student_id):
    """Return the ID filename (e.g. '12345_id.jpg' or '12345_id.pdf') if it exists, else None."""
    folder = os.path.join(app.config['UPLOAD_FOLDER'], str(student_id))
    for ext in ('jpg', 'pdf'):
        fname = f"{student_id}_id.{ext}"
        if os.path.exists(os.path.join(folder, fname)):
            return fname
    return None

######################################################
### Require Acceptance for the POPI Act before proceeding###


def require_popia(f):
    @wraps(f)
    def _wrap(*args, **kwargs):
        if 'student_id' not in session:
            return redirect(url_for('login'))
        # Your session stores the public student_id (string), so fetch by that:
        student = Student.query.filter_by(
            student_id=session['student_id']).first()
        v = current_app.config.get('POPIA_VERSION', '1')
        if not student or not student.has_popia_consent(v):
            session['post_login_next'] = request.path
            return redirect(url_for('popia_notice'))

        # Admins bypass selfie/ID onboarding requirements
        if 'admin_id' not in session:
            # Gate: selfie must exist
            sid = session['student_id']
            student_folder = os.path.join(app.config['UPLOAD_FOLDER'], sid)
            selfie_path = os.path.join(student_folder, f"{sid}_selfie.jpg")
            if not os.path.exists(selfie_path):
                return redirect(url_for('onboarding_selfie'))

            # Gate: ID document must exist
            if not _find_id_file(sid):
                return redirect(url_for('onboarding_id_upload'))

        return f(*args, **kwargs)
    return _wrap

######################################################


def _score_mcq(questions, form):
    # form fields: answer_<qid> = index (string)
    total = 0
    right = 0
    answers = []
    for q in questions:
        qid = q["id"]
        total += 1
        selected = int(form.get(f"answer_{qid}", -1))
        is_right = (selected == q["correct_index"])
        if is_right:
            right += 1
        answers.append({
            "id": qid,
            "selected": selected,
            "correct": q["correct_index"],
            "is_right": is_right
        })
    pct = round((right / total) * 100, 2) if total else 0.0
    return pct, right, total, answers


@app.route("/course/<int:course_id>/unit/quiz", methods=["GET", "POST"])
def take_unit_quiz(course_id):
    # minimal access control for demo; adjust to your learner auth if needed
    course = Course.query.get_or_404(course_id)
    # load bank + placement
    uq_filename = unit_questions_filename(course)
    # placeholder so the name exists
    bank = [_ for _ in [_norm for _norm in []]]
    raw = load_unit_questions_safe(unit_questions_path(uq_filename))

    def _norm(item, idx):
        qid = item.get("id", idx + 1)
        prompt = (item.get("question") or item.get("q") or "").strip()
        if isinstance(item.get("options"), dict):
            keys = sorted(item["options"].keys())
            opts = [item["options"][k] for k in keys]
            ans = (item.get("answer") or "").strip().upper()
            ci = (ord(ans) - 65) if ans and "A" <= ans <= "Z" else 0
        else:
            opts = [str(x) for x in (item.get("options") or [])]
            ci = int(item.get("correct_index") or 0)
        if ci < 0 or ci >= len(opts):
            ci = 0 if opts else -1
        return {"id": qid, "prompt": prompt, "options": opts, "correct_index": ci}

    bank = [_norm(x, i) for i, x in enumerate(raw)]
    placement = load_placement(course.id).get("by_chapter", {})

    # flatten questions in chapter order
    qids = []
    # chapters in current display order
    chapters = (CourseChapter.query
                .filter_by(course_id=course.id, parent_id=None)
                .order_by(CourseChapter.position)
                .all())
    for ch in chapters:
        qids += placement.get(str(ch.id), [])
    # de-dupe while preserving order
    seen = set()
    ordered = []
    for qid in qids:
        if qid in seen:
            continue
        seen.add(qid)
        ordered.append(qid)
    id_map = {q["id"]: q for q in bank}
    questions = [id_map[qid] for qid in ordered if qid in id_map]

    if request.method == "POST":
        pct, right, total, answers = _score_mcq(questions, request.form)
        # try to persist (optional)
        try:
            # if you have UnitQuizAttempt model:
            attempt = UnitQuizAttempt(
                course_id=course.id,
                unit_key="course_level",  # or a more specific key if you add per-chapter runs
                student_id=str(session.get("student_id") or "admin"),
                full_name=session.get("admin_name") or "",
                email="",
                score=pct,
                passed=(pct >= 50.0),
                answers_json=json.dumps(answers),
                submitted_at=_now_sast()
            )
            db.session.add(attempt)
            db.session.commit()
            flash(
                f"Scored {pct}% ({right}/{total}). Saved attempt #{attempt.id}.", "success")
        except Exception:
            flash(
                f"Scored {pct}% ({right}/{total}). (Attempt not stored.)", "info")
        return redirect(url_for("take_unit_quiz", course_id=course.id))

    # render a very small form
    return render_template_string("""
    <html><head><meta charset="utf-8"><title>Unit Quiz — {{course.title}}</title>
    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/tailwindcss@3.4.10/dist/tailwind.min.css">
    </head><body class="p-6">
      <div class="max-w-3xl mx-auto">
        <div class="flex justify-between items-center mb-4">
          <h1 class="text-xl font-semibold">Unit Quiz — {{ course.title }}</h1>
          <a href="{{ url_for('manage_course', course_id=course.id) }}" class="underline">← Back</a>
        </div>
        {% if not questions %}
          <div class="p-4 bg-amber-50 border border-amber-200 rounded">No questions placed yet.</div>
        {% else %}
          <form method="POST" class="space-y-4">
            {% for q in questions %}
              <section class="p-4 rounded border bg-white">
                <div class="font-medium mb-2">Q{{ loop.index }}. {{ q.prompt }}</div>
                <div class="space-y-2">
                  {% for opt in q.options %}
                    <label class="flex items-center gap-2">
                      <input type="radio" name="answer_{{ q.id }}" value="{{ loop.index0 }}" required>
                      <span>{{ opt }}</span>
                    </label>
                  {% endfor %}
                </div>
              </section>
            {% endfor %}
            <button class="px-4 py-2 rounded bg-indigo-600 text-white">Submit</button>
          </form>
        {% endif %}
      </div>
    </body></html>
    """, course=course, questions=questions)


