BASE_DIR = os.path.dirname(os.path.abspath(__file__))
UNIT_QUIZ_DIR = os.path.join(BASE_DIR, "data", "unit_quizzes")


def _slug(s):
    return (s or "").strip().lower().replace(" ", "_")


def unit_quiz_filename_for(course):
    return f"{(_slug(getattr(course, 'code', '')) or f'course_{course.id}')}_unit_questions.json"


def load_unit_bank(course):
    """Return (list_of_items, by_id) from the JSON file.
       Each item normalized to: {id:int, question:str, options:list|dict, ...}
    """
    fname = unit_quiz_filename_for(course)
    fpath = os.path.join(UNIT_QUIZ_DIR, fname)
    try:
        raw = json.load(open(fpath, "r", encoding="utf-8"))
    except Exception:
        raw = []

    items = raw.get("questions") if isinstance(raw, dict) else raw
    if not isinstance(items, list):
        items = []

    out = []
    for i, it in enumerate(items, 1):
        if not isinstance(it, dict):
            continue
        qtxt = (it.get("question") or it.get("q") or "").strip()
        if not qtxt:
            continue
        qid = int(it.get("id") or i)
        out.append({**it, "id": qid, "question": qtxt})
    by_id = {x["id"]: x for x in out}
    return out, by_id


def compute_unit_quiz_plan(course):
    """Read placements and return a structure per chapter with ordered questions."""
    from app import db, UnitQuizPlacement, CourseChapter  # adjust import path if needed

    bank_list, bank_by_id = load_unit_bank(course)

    # placements
    rows = (UnitQuizPlacement.query
            .filter_by(course_id=course.id)
            .order_by(asc(UnitQuizPlacement.chapter_id), asc(UnitQuizPlacement.position))
            .all())

    # chapters (id -> object)
    chs = (CourseChapter.query
           .filter_by(course_id=course.id, parent_id=None)
           .order_by(CourseChapter.position)
           .all())
    ch_by_id = {c.id: c for c in chs}

    plan = []
    for ch in chs:
        placed = [r for r in rows if r.chapter_id == ch.id]
        q_items = [bank_by_id[r.question_id]
                   for r in placed if r.question_id in bank_by_id]
        plan.append({
            "chapter_id": ch.id,
            "chapter_title": ch.title,
            "questions": q_items,           # ordered delivery
        })

    # also return any unplaced questions (for the pool)
    placed_ids = {r.question_id for r in rows}
    unplaced = [q for q in bank_list if q["id"] not in placed_ids]
    return plan, unplaced


