# app.py  (near your other helpers / context processors)


def get_template_identity():
    """
    Build a safe identity dict for templates.
    Works whether the Student model has first_name/last_name or just name, etc.
    Never raises AttributeError.
    """
    identity = {
        "student_id": "",
        "student_name": "Unknown",
        "student_email": "",
        "student_number": "",
    }

    sid = session.get("student_id")
    if not sid:
        return identity

    # Try both "public" id and PK
    s = (Student.query.filter_by(student_id=str(sid)).first()
         or Student.query.get(sid))
    if not s:
        return identity

    # IDs
    identity["student_id"] = getattr(
        s, "student_id", "") or getattr(s, "id", "") or ""

    # Email (common variants)
    identity["student_email"] = (
        getattr(s, "email", "")
        or getattr(s, "student_email", "")
        or getattr(s, "contact_email", "")
        or ""
    )

    # Student number (many installs use different names)
    identity["student_number"] = (
        getattr(s, "student_number", "")
        or getattr(s, "student_no", "")
        or getattr(s, "studentid", "")
        or ""  # do NOT fall back to student_id here; the template already does that
    )

    # Name — try structured first/last; fall back to a single 'name' field; finally anything reasonable
    first = (
        getattr(s, "first_name", "")
        or getattr(s, "firstname", "")
        or getattr(s, "given_name", "")
        or ""
    )
    last = (
        getattr(s, "last_name", "")
        or getattr(s, "surname", "")
        or getattr(s, "family_name", "")
        or ""
    )
    full = (first + " " + last).strip()

    if not full:
        # Try a single 'name' or display field
        full = (
            getattr(s, "name", "")
            or getattr(s, "full_name", "")
            or getattr(s, "display_name", "")
            or getattr(s, "student_name", "")
            or ""
        )

    # If we still don’t have a full name but 'name' looks like "First Last", split it
    if not full:
        raw = getattr(s, "name", "")
        if isinstance(raw, str) and " " in raw:
            a, b = raw.split(" ", 1)
            full = f"{a} {b}".strip()

    identity["student_name"] = full or "Student"
    return identity

# Make sure your context processor uses the safe helper


@app.context_processor
def inject_identity():
    return get_template_identity()
