# --- HELPERS: unit quiz paths + normalization/reuse grader ---

def unit_quiz_path(course_id: int, unit_key: str):
    """
    Where we store per-unit quiz JSON files.
    You can change this to match your structure.
    """
    root = os.path.dirname(__file__)
    folder = os.path.join(root, "static", "questions", "units", str(course_id))
    os.makedirs(folder, exist_ok=True)
    return os.path.join(folder, f"{_slug(unit_key)}.json")


def load_unit_quiz(course_id: int, unit_key: str):
    """
    UPDATED: Returns (cfg, questions_normalized)
    Questions are now filtered and ordered according to UnitQuizPlacement in the DB
    for the chapter corresponding to the unit_key.
    """
    # 1. Find the target chapter ID using the unit_key (slug)
    # Assumes CourseChapter model is available globally.
    chapter = CourseChapter.query.filter_by(
        course_id=course_id, slug=_slug(unit_key)).first()
    if not chapter:
        raise Exception(f"Chapter/Unit not found for key: {unit_key}")

    target_chapter_id = chapter.id
    path = unit_quiz_path(course_id, unit_key)

    # 2. Load the Question Bank and Config (Meta)
    if not os.path.isfile(path):
        # Fall back gracefully if the quiz file hasn't been created yet
        raw_bank = []
        title, pass_mark, max_q = f"Unit Quiz — {unit_key}", 60, 5
    else:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)

        if isinstance(data, dict):
            title = data.get("title") or f"Unit Quiz — {unit_key}"
            pass_mark = int(data.get("pass_mark") or 60)
            max_q = int(data.get("max_questions") or 5)
            raw_bank = data.get("questions") or []
        elif isinstance(data, list):
            title = f"Unit Quiz — {unit_key}"
            pass_mark, max_q = 60, 5
            raw_bank = data
        else:
            raise ValueError("Unsupported unit quiz JSON structure")

    # Normalize the entire bank once (Ensure 'normalize_bank' is defined elsewhere)
    normalized_bank = normalize_bank(raw_bank)
    # Create a map for quick lookup: {question_id: question_data}
    id_map = {q.get("id"): q for q in normalized_bank if q.get(
        "id") is not None}

    # 3. Load Placements from the database using the new helper
    placements_by_chapter = _load_placements_by_chapter_id(course_id)

    # Get the list of question IDs saved for this specific chapter
    ordered_qids = placements_by_chapter.get(target_chapter_id, [])

    # 4. Filter and Order Questions
    # Use the ordered QIDs to pull questions from the map
    ordered_questions = [id_map[qid] for qid in ordered_qids if qid in id_map]

    # 5. Apply Max Questions limit (if necessary, use the start of the ordered list)
    final_questions = ordered_questions[:max_q]

    class _Cfg:
        pass
    cfg = _Cfg()
    cfg.title = title
    cfg.pass_mark = pass_mark
    cfg.max_questions = max_q

    # Return the config and the placed, ordered, and limited questions
    return cfg, final_questions


def grade_unit_from_form(norm_questions, form_multi_dict):
    """
    Same grading as finals, yields (answers_dict, score, total, percentage, detailed[]).
    """
    answers, score, total, pct = grade_from_form(
        norm_questions, form_multi_dict)
    # detailed like finals (id, selected, correct, is_right)
    detailed = []
    for q in norm_questions:
        qid = str(q["id"])
        selected = (answers.get(qid) or "").lower()
        correct = (q.get("correct") or "a").lower()
        detailed.append({"id": int(qid), "selected": selected,
                        "correct": correct, "is_right": selected == correct})
    return answers, score, total, pct, detailed

