class UnitQuizAttempt(db.Model):
    __tablename__ = "unit_quiz_attempt"
    id = db.Column(db.Integer, primary_key=True)

    # linkage
    course_id = db.Column(db.Integer, nullable=False)
    # slug/identifier of the unit/chapter
