    # optional human key if you use it
    course_key = db.Column(db.String(128), nullable=True)

    # student snapshot
    student_id = db.Column(db.String(64), nullable=False)
    student_number = db.Column(db.String(64), nullable=True)
    full_name = db.Column(db.String(128), nullable=True)
    email = db.Column(db.String(128), nullable=True)

    # scoring (store percentage like finals page logic)
    score = db.Column(db.Float, nullable=False,
                      default=0.0)   # percentage 0..100
    passed = db.Column(db.Boolean, nullable=False, default=False)

    # detail
