    # convenience index
    submitted_at = db.Column(db.DateTime, nullable=False,
                             default=_now_sast, index=True)

    def __repr__(self):
        return f"<UnitQuizAttempt id={self.id} course_id={self.course_id} unit={self.unit_key} student={self.student_id}>"

