@app.route("/course/<int:course_id>/unit/<unit_key>/quiz/result/<int:attempt_id>", methods=["GET"], endpoint="unit_quiz_result")
def unit_quiz_result(course_id, unit_key, attempt_id):
    a = UnitQuizAttempt.query.get_or_404(attempt_id)

    detailed = json.loads(a.answers_json or "[]") if a.answers_json else []
    correct = sum(1 for x in detailed if x.get("is_right"))
    total = len(detailed) or 1
    percentage = float(a.score or 0.0)

    # load cfg to know pass_mark (optional)
    try:
        cfg, _ = load_unit_quiz(course_id, unit_key)
        pass_mark = int(cfg.pass_mark)
    except Exception:
        pass_mark = 60

    return render_template(
        "assessment_result.html",  # reuse your new pretty template
        title=f"Unit Quiz — {unit_key}",
        score=percentage,
        passed=bool(a.passed),
        correct=correct,
        total=total,
        pass_mark=pass_mark,
        full_name=a.full_name,
        student_id=a.student_id,
        attempt_id=a.id,
        video_filename=None,
        # optional buttons (you can adapt)
        course_id=course_id,
        course_code=unit_key,
        back_url=url_for("dashboard"),
    )


