# Helper function to load unit quiz questions and config
def load_unit_quiz(course_id, unit_key):
    # unit_key can be a slug (string) or a chapter ID (string representation of int).
    chapter = None

    # 1. Try finding the chapter by ID first, as it's definitive and now used in the URL.
    try:
        chapter_id = int(unit_key)
        chapter = CourseChapter.query.filter_by(
            course_id=course_id, id=chapter_id).first()
    except ValueError:
        # If unit_key is not an integer, it must be a slug.
        pass

    # 2. If not found by ID, try finding by slug.
    if not chapter:
        slug = _slug(unit_key)
        chapter = CourseChapter.query.filter_by(
            course_id=course_id, slug=slug).first()

    if not chapter:
        raise Exception(
            f"Chapter/Unit '{unit_key}' not found for course {course_id}")

    # 3. Get quiz configuration (CourseUnitQuiz)
    cfg = CourseUnitQuiz.query.filter_by(
        course_id=course_id, chapter_id=chapter.id).first()
    if not cfg:
        # If no explicit config, use defaults, but must have a chapter
        cfg = CourseUnitQuiz(
            # Use defaults
            title=f"Unit Quiz: {chapter.title}", pass_mark=100.0)

    # 4. Load question placements
    placements = UnitQuizPlacement.query.filter_by(
        chapter_id=chapter.id).order_by(UnitQuizPlacement.order).all()

    # 5. Build the list of questions
    questions = []
    # Fetch all unique question IDs needed
    q_ids = [p.question_id for p in placements]
    if q_ids:
        # Using in_() for efficient batch loading
        q_map = {q.id: q for q in CourseQuestion.query.filter(
            CourseQuestion.id.in_(q_ids)).all()}

        # Order the questions based on the placement order
        for p in placements:
            if p.question_id in q_map:
                questions.append(q_map[p.question_id])

    # CHANGE: Return chapter object as well for use in unit_quiz_take
    return cfg, questions, chapter

