# --- LEARNER: take unit quiz ---


@app.route("/course/<int:course_id>/unit/<unit_key>/quiz", methods=["GET", "POST"], endpoint="unit_quiz_take")
def unit_quiz_take(course_id, unit_key):
    # NEW DEBUG
    print(
        f"DEBUG_TAKE_QUIZ: Incoming course_id={course_id}, unit_key='{unit_key}'")

    stu = current_student()
    if not stu:
        flash("Please log in first.", "warning")
        return redirect(url_for("login"))

    try:
        # CHANGE: Unpack the chapter object from the helper function
        cfg, questions, chapter = load_unit_quiz(course_id, unit_key)
        # NEW DEBUG
        print(
            f"DEBUG_TAKE_QUIZ: Quiz loaded {len(questions)} questions. Chapter ID: {chapter.id}, Slug: {chapter.slug}")
    except Exception as e:
        # NEW DEBUG: Print the specific error that caused the redirect
        print(f"DEBUG_TAKE_QUIZ: FAILED to load quiz. Error: {e}")
        flash(f"Unit quiz unavailable: {e}", "danger")
        return redirect(url_for("dashboard"))

    # DEBUG CHECK: log if no questions are found.
    if not questions or len(questions) == 0:
        print(
            f"DEBUG: Quiz load failed for Course ID {course_id}, Unit Key '{unit_key}' (Chapter ID: {chapter.id}).")
        print("DEBUG: load_unit_quiz returned 0 questions. Check if UnitQuizPlacement has entries for this chapter_id.")

        # Flash a message but allow rendering the quiz page so the user sees the warning message there.
        # The unit_quiz.html template handles the empty state gracefully.
        flash("The administrator has not yet assigned any questions to this unit quiz. Please try again later.", "warning")
    # --- END DEBUG CHECK ---

    if request.method == "GET":
        session[f"unit_{course_id}_{unit_key}_started_at"] = _now_sast(
        ).isoformat()
        return render_template("unit_quiz.html",
                               title=cfg.title, pass_mark=cfg.pass_mark,
                               questions=questions,
                               student_name=stu["full_name"],
                               student_id=stu["student_id"],
                               student_email=stu["email"])

    # POST: grade logic remains the same...
    submitted = request.form.to_dict(flat=True)
    answers, score, total, pct, detailed = grade_unit_from_form(
        questions, submitted)

    pm = float(cfg.pass_mark)
    passed = (pct >= pm)

    # meta
    started_iso = session.pop(f"unit_{course_id}_{unit_key}_started_at", None)
    started_at = datetime.fromisoformat(started_iso) if started_iso else None
    finished_at = _now_sast()
    duration_s = int((finished_at - started_at).total_seconds()
                     ) if started_at else 0
    ip, ua = client_info()

    # store attempt
    attempt = UnitQuizAttempt(
        course_id=course_id,
        # CHANGE: Store the actual chapter slug from the loaded object
        unit_key=chapter.slug,
        course_key=None,
        student_id=stu["student_id"],
        student_number=stu.get("student_number"),
        full_name=stu["full_name"], email=stu["email"],
        score=pct, passed=passed,
        answers_json=json.dumps(detailed, ensure_ascii=False),
        started_at=started_at, finished_at=finished_at, duration_s=duration_s,
        ip_address=ip, user_agent=ua,
    )
    db.session.add(attempt)
    db.session.commit()

    target = url_for("unit_quiz_result", course_id=course_id,
                     unit_key=unit_key, attempt_id=attempt.id)
    return jsonify({"redirect": target}) if request.headers.get("X-Requested-With", "").lower() == "xmlhtthttprequest" else redirect(target)


