@app.route("/admin/unit-assessments", methods=["GET", "POST"], endpoint="admin_unit_assessments")
def admin_unit_assessments():
    # same auth style as the rest of your admin pages
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash('Unauthorized Access!', 'danger')
        return redirect(url_for('admin_login'))

    # CREATE
    if request.method == "POST":
        raw = (request.form.get("name") or "").strip()
        if not raw:
            flash("Please enter a name/slug.", "danger")
            return redirect(url_for("admin_unit_assessments"))

        # sanitize and enforce suffix
        base = re.sub(r"[^a-zA-Z0-9_-]+", "_", raw).lower().strip("_")
        if not base:
            flash("Invalid name.", "danger")
            return redirect(url_for("admin_unit_assessments"))
        if not base.endswith("_unit_questions"):
            base = f"{base}_unit_questions"

        fname = f"{base}.json"
        fpath = os.path.join(UNIT_QUIZ_DIR, fname)
        if os.path.exists(fpath):
            flash(f"File already exists: {fname}", "warning")
            return redirect(url_for("admin_unit_assessments"))

        try:
            with open(fpath, "w", encoding="utf-8") as f:
                json.dump({"questions": []}, f, ensure_ascii=False, indent=2)
                f.write("\n")
            flash(f"Created {fname}", "success")
            # Open directly in your MCQ editor
            return redirect(url_for("questions_mcq", filename=fname))
        except Exception as e:
            flash(f"Could not create file: {e}", "danger")
            return redirect(url_for("admin_unit_assessments"))

    # LIST
    files = []
    try:
        for name in sorted(os.listdir(UNIT_QUIZ_DIR), key=str.lower):
            if not name.endswith(".json"):
                continue
            path = os.path.join(UNIT_QUIZ_DIR, name)
            files.append({
                "name": name,
                "count": _read_unit_count(path),
                "last_saved": _fmt_mtime(path),
            })
    except Exception as e:
        flash(f"File not found.", "danger")
        files = []

    return render_template(
        "admin_unit_assessments.html",
        files=files,
        unit_dir=UNIT_QUIZ_DIR,
    )
