MAX_ATTEMPTS = 2


def _attempts_file(student_number: str, course_id: int):
    """
    Returns (folder_path, attempts_json_path) for this student+course.
    """
    base_upload = app.config.get(
        "UPLOAD_FOLDER", os.path.join(app.root_path, "uploads"))
    folder = os.path.join(
        base_upload, secure_filename(student_number or "unsure"))
    os.makedirs(folder, exist_ok=True)
    return folder, os.path.join(folder, f"attempts_{course_id}.json")


def get_attempts(student_number: str, course_id: int) -> int:
    """
    Read attempts count for a student/course from JSON (defaults to 0).
    """
    _, path = _attempts_file(student_number, course_id)
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
                return int(data.get("attempts", 0))
    except Exception:
        pass
    return 0


def increment_attempts(student_number: str, course_id: int) -> int:
    """
    Increment and persist attempts; returns the new attempts number.
    """
    folder, path = _attempts_file(student_number, course_id)
    attempts = get_attempts(student_number, course_id) + 1
    try:
        with open(path, "w") as f:
            json.dump({
                "attempts": attempts,
                "updated_at": _now_sast().isoformat() + "Z"
            }, f)
    except Exception as e:
        app.logger.warning("Could not write attempts file %s: %s", path, e)
    return attempts


