@app.template_filter('file_mtime')
def file_mtime_filter(path):
    """Return the file's modification timestamp (int seconds) for cache-busting
    image URLs after an admin re-uploads a selfie or ID document. Returns 0 if
    the file is missing so templates can still substitute the value safely.
    """
    try:
        return int(os.path.getmtime(path))
    except (OSError, TypeError):
        return 0

