# ✅ Send Email Helper
def send_email(recipient, subject, html_body, use_template=True):
    try:
        msg = Message(subject=subject, recipients=[recipient])
        if use_template:
            msg.html = wrap_email_template(html_body)
        else:
            msg.html = html_body
        mail.send(msg)
    except Exception as e:
        print(f"❌ Failed to send email to {recipient}: {e}")

