# UPLOAD_ROOT will be set after app.config['UPLOAD_FOLDER'] is properly configured
# For now, use a function to get it dynamically
def get_upload_root():
    """Get the upload root directory, ensuring it's an absolute path."""
    upload_folder = app.config.get('UPLOAD_FOLDER', 'uploads')
    if os.path.isabs(upload_folder):
        return upload_folder
    return os.path.join(app.root_path, upload_folder)


@app.route('/uploads/<path:subpath>')
def uploads(subpath):
    # Simple guard: prevent .. traversal
    upload_root = get_upload_root()
    # Normalize the subpath: remove leading slashes (both / and \)
    norm = subpath.lstrip('/\\')
    # Replace any backslashes with forward slashes for consistency
    norm = norm.replace('\\', '/')
    # Join paths properly
    full = os.path.join(upload_root, norm)
    # Normalize the full path to handle Windows/Unix differences
    full = os.path.normpath(full)
    
    # Security check: ensure the resolved path is within upload_root
    upload_root_abs = os.path.abspath(upload_root)
    full_abs = os.path.abspath(full)
    if not full_abs.startswith(upload_root_abs):
        abort(404)
    
    if not os.path.isfile(full):
        abort(404)
    
    # For send_from_directory, we need the relative path from upload_root
    rel_path = os.path.relpath(full, upload_root)
    # Use forward slashes for the path component (works on both Windows and Unix)
    rel_path = rel_path.replace('\\', '/')
    
    # conditional=True enables 304 for caching
    return send_from_directory(upload_root, rel_path, conditional=True)

