###### Purge####


def _purge_student_dependencies(student_pk: int, public_sid: str):
    # Tables that reference numeric PK (student.id)
    pk_tables = [
        "support_ticket_message",
        "support_ticket",
        "chapter_progress",
        "course_progress",
        "course_enrollment",
        "final_assessment_submission",
        "assessment_attempts",        # Pluralized to match common naming
        "final_assessment_attempts",  # Matches your error log exactly
        "student_final_result",
        "login_logs",
        "activity_log",
        "moderation_log",
        "moderation_violation",
        "certificate_log",
        "course_feedback",
        "suspension_log",
        "admin_notes",
        "popia_consent",
        "handbook_page_map_progress",
        "student_activity",
        "assessment_session",
    ]

    # Clean up CompanyEmployee and its EmployeeDocuments (FK chain)
    try:
        db.session.execute(text(
            "DELETE FROM employee_document WHERE employee_id IN "
            "(SELECT id FROM company_employee WHERE student_id = :sid)"
        ), {"sid": student_pk})
        db.session.execute(text(
            "DELETE FROM company_employee WHERE student_id = :sid"
        ), {"sid": student_pk})
    except Exception:
        pass

    # Tables that store the public code (8-digit) instead of PK
    code_tables = [
        "course_enrollment_archive",
        "certificate_records",
        "final_assessment_archive",
    ]

    for tbl in pk_tables:
        try:
            db.session.execute(text(f"DELETE FROM {tbl} WHERE student_id = :sid"), {
                               "sid": student_pk})
        except Exception:
            pass

    for tbl in code_tables:
        try:
            db.session.execute(text(f"DELETE FROM {tbl} WHERE student_code = :scode"), {
                               "scode": public_sid})
        except Exception:
            pass

    # IMPORTANT: Clear the session memory so SQLAlchemy knows these records are gone
    db.session.flush()
    db.session.expire_all()


