# Delete Student

@app.route('/delete_student/<int:student_id>', methods=['POST'])
def delete_student(student_id):
    # Auth — Super Admin (3) or Developer (4) only
    if not session.get('admin_id') or get_role_level(session.get('admin_role', '')) < get_role_level('Super Admin'):
        if request.is_json:
            return jsonify(ok=False, message="Unauthorized"), 401
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    # Reason
    if request.is_json:
        payload = request.get_json(silent=True) or {}
        reason = (payload.get("reason") or "").strip()
        ajax = True
    else:
        reason = (request.form.get("reason") or "").strip()
        ajax = request.headers.get("X-Requested-With") == "XMLHttpRequest"

    if not reason or len(reason) < 5:
        msg = "Please provide a valid reason (min 5 characters)."
        if ajax:
            return jsonify(ok=False, message=msg), 400
        flash(msg, "danger")
        return redirect(url_for('view_students'))

    # Load student
    student = db.session.get(Student, student_id)
    if not student:
        if ajax:
            return jsonify(ok=False, message="Student not found."), 404
        flash("⚠ Student not found.", "warning")
        return redirect(url_for('view_students'))

    public_sid = str(getattr(student, "student_id", "") or "")
    uploads_root = app.config.get('UPLOAD_FOLDER', 'uploads')
    src_folder = os.path.join(uploads_root, public_sid)
    backup_root = "/var/enroll/student_backup"
    os.makedirs(backup_root, exist_ok=True)

    # Ensure log table exists
    try:
        StudentDeletionLog.__table__.create(db.engine, checkfirst=True)
    except Exception:
        pass

    admin_id = session.get("admin_id")
    admin_name = session.get("admin_name") or "Admin"

    # Backup uploads
    ts = _now_sast().strftime("%Y%m%d%H%M%S")
    backup_path = None
    try:
        if os.path.isdir(src_folder):
            backup_path = os.path.join(backup_root, f"{public_sid}_{ts}")
            shutil.copytree(src_folder, backup_path, dirs_exist_ok=True)
    except Exception:
        app.logger.exception("Student backup failed")
        backup_path = None

    try:
        # 1. Purge dependents FIRST
        _purge_student_dependencies(
            student_pk=student.id, public_sid=public_sid)

        # 2. Log deletion
        try:
            log = StudentDeletionLog(
                student_id=student.id,
                student_code=public_sid,
                admin_id=admin_id,
                admin_name=admin_name,
                reason=reason,
                backup_path=backup_path,
            )
            db.session.add(log)
            db.session.flush()
        except Exception:
            app.logger.exception("Failed to insert deletion log")

        # 3. Delete student (This will now work because dependencies are gone)
        db.session.delete(student)
        db.session.commit()

        # Cleanup original uploads
        try:
            if os.path.isdir(src_folder):
                shutil.rmtree(src_folder, ignore_errors=True)
        except Exception:
            app.logger.exception("Failed to cleanup original uploads folder")

        if ajax:
            return jsonify(ok=True, message=f"Student {public_sid} deleted.", student_id=student_id)
        flash("✅ Student deleted successfully!", "success")
        return redirect(url_for('view_students'))

    except Exception:
        db.session.rollback()
        app.logger.exception("Delete Error")
        if ajax:
            return jsonify(ok=False, message="Error deleting student. Please try again."), 500
        flash("⚠ Error deleting student. Please try again.", "danger")
        return redirect(url_for('view_students'))
