def _uq_slug(s: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", (s or "").lower()).strip("_")


def unit_quiz_filename(course) -> str:
    code = getattr(course, "code", None) or f"course_{course.id}"
    return f"{_uq_slug(code)}_unit_questions.json"


def unit_quiz_path(filename: str) -> str:
    # safety fence
    fname = (filename or "").lower()
    if not re.fullmatch(r"[a-z0-9_]+_unit_questions\.json", fname):
        raise ValueError("Bad filename")
    return os.path.join(UNIT_QUIZ_DIR, fname)


def _uq_load(path: str):
    if not os.path.exists(path):
        return []
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
            return data if isinstance(data, list) else []
    except Exception:
        return []


def _uq_starter():
    return [{
        "id": 1,
        "type": "mcq",
        "question": "Example Question — replace me",
        "options": {"A": "Option A", "B": "Option B", "C": "Option C", "D": "Option D"},
        "answer": "B"
    }]

