def get_recipients_for_category(category):
    """Get active email recipients for a notification category"""
    recipients = EmailRecipient.query.filter_by(
        category=category,
        is_active=True
    ).all()
    return [r.email for r in recipients]


# ── Certificate Queue helpers ──────────────────────────

def enqueue_certificate(student, course, score):
    """Add a pending certificate to the queue (idempotent)."""
    existing = CertificateQueue.query.filter_by(
        student_id=student.id, course_id=course.id, status='pending').first()
    if existing:
        return
    company = student.company or (
        student.created_by_company.name if student.created_by_company else None)
    entry = CertificateQueue(
        student_id=student.id,
        course_id=course.id,
        course_title=course.title,
        student_name=f"{student.name} {student.surname}",
        student_email=student.email,
        national_id=student.national_id,
        company=company,
        score=score,
        passed_at=_now_sast(),
    )
    db.session.add(entry)
    db.session.commit()


def enqueue_certificate_from_session(stu_dict, course_key, score):
    """Lookup student/course from session dict + course key, then enqueue.

    Note: Course.code is a Python @property, not a real column — do NOT reference it
    in a WHERE clause. We match on final_assessment_key only.
    """
    try:
        sid = stu_dict.get("student_id") or stu_dict.get("number") or stu_dict.get("id")
        if not sid:
            return
        student = Student.query.filter_by(student_id=str(sid)).first()
        if not student:
            return
        course = Course.query.filter(
            func.lower(Course.final_assessment_key) == (course_key or "").lower()
        ).first()
        if not course:
            app.logger.warning(
                "enqueue_certificate_from_session: no Course row has "
                "final_assessment_key=%r — certificate NOT enqueued for "
                "student %s. Set this course's Final Assessment Key in "
                "Manage Courses to fix.", course_key, sid)
            return
        enqueue_certificate(student, course, score)
    except Exception as exc:
        print(f"enqueue_certificate_from_session failed: {exc}")


def _trigger_certificate_after_feedback(student, course_key):
    """
    Called after feedback is submitted. Checks if the student passed the final
    assessment for this course_key and, if so, sends the certificate email
    and enqueues the certificate. This ensures certificates are only processed
    after mandatory feedback is completed.

    Looks at three possible persistence layers:
      1. FinalAssessmentAttempt (legacy standalone finals)
      2. AssessmentAttempt (RPAS, ASAT, etc.)
      3. FinalAssessmentSubmission (used by run_final for virtual courses in v1.1.0)
    """
    try:
        attempt = None

        # course_key is matched case-insensitively throughout: register_assessment
        # lowercases the attempt key ('dgge') while the feedback route / course
        # record may pass it in original case ('DGGE'). An exact match here would
        # miss the passing attempt and silently skip the certificate enqueue.
        ck_lower = (course_key or "").lower()

        # Check FinalAssessmentAttempt table
        attempt = FinalAssessmentAttempt.query.filter(
            ((FinalAssessmentAttempt.student_id == student.id) |
             (FinalAssessmentAttempt.student_number == student.student_id)),
            func.lower(FinalAssessmentAttempt.course_key) == ck_lower,
            FinalAssessmentAttempt.passed == True,
            FinalAssessmentAttempt.is_active.is_(True)
        ).order_by(FinalAssessmentAttempt.submitted_at.desc()).first()

        if not attempt:
            # Also check AssessmentAttempt table (RPAS, ASAT, etc.). Filter on
            # the stored `passed` flag (computed against the course's actual
            # pass_mark at submission time) rather than a hardcoded score
            # threshold, which silently missed courses with a pass_mark != 80.
            attempt = AssessmentAttempt.query.filter(
                AssessmentAttempt.student_id == str(student.student_id),
                func.lower(AssessmentAttempt.course_key) == ck_lower,
                AssessmentAttempt.passed == True,
                AssessmentAttempt.is_active.is_(True)
            ).order_by(AssessmentAttempt.created_at.desc()).first()

        # Resolve the Course once — used both for FinalAssessmentSubmission lookup
        # below and for the idempotency / enqueue calls.
        course = Course.query.filter(
            func.lower(Course.final_assessment_key) == ck_lower
        ).first()

        if not attempt and course:
            # Virtual courses (and any other run_final-driven finals) land in
            # FinalAssessmentSubmission. Look the pass up by course_id.
            sub = (
                FinalAssessmentSubmission.query
                .filter_by(student_id=student.id, course_id=course.id,
                           is_active=True)
                .order_by(FinalAssessmentSubmission.submitted_at.desc())
                .first()
            )
            if sub and (sub.percentage or 0) >= 80:
                attempt = sub  # treat it like any other passing attempt below

        if not attempt:
            app.logger.warning(
                "_trigger_certificate_after_feedback: no passing attempt found "
                "for student %s on course_key=%r — certificate NOT enqueued.",
                student.student_id, course_key)
            return  # No passing attempt found — nothing to do

        # Check if certificate was already enqueued (idempotent)
        if course:
            existing = CertificateQueue.query.filter_by(
                student_id=student.id, course_id=course.id
            ).first()
            if existing:
                return  # Already enqueued — don't send duplicate email

        # Build student dict for the notification function
        stu = {
            "id": student.id,
            "student_id": student.student_id,
            "number": student.student_id,
            "full_name": f"{student.name} {student.surname}" if hasattr(student, 'surname') else student.name,
            "email": student.email,
        }

        # Resolve score and attempt_id based on which table had the result
        if isinstance(attempt, FinalAssessmentAttempt):
            score = attempt.percentage
            attempt_id = attempt.id
        elif isinstance(attempt, FinalAssessmentSubmission):
            score = attempt.percentage
            attempt_id = attempt.id
        else:
            score = attempt.score
            attempt_id = attempt.id

        # Load assessment title from config or, when that misses, from the
        # Course record. The previous version called `.get()` on the parsed
        # JSON, but assessments.json is a *list* of dicts, not a dict keyed by
        # course_key — so `.get()` raised AttributeError, was swallowed by the
        # bare except, and the email title fell through to the course_key
        # string. When the caller had also fallen back to `str(course.id)`
        # (no final_assessment_key mapped on the course), the email then read
        # the course as e.g. "30" instead of "Catering".
        title = None
        try:
            with open("config/assessments.json", "r") as f:
                assessments = json.load(f)
            if isinstance(assessments, list):
                match = next((a for a in assessments if a.get("key") == course_key), None)
                if match:
                    title = match.get("title")
            elif isinstance(assessments, dict):  # legacy shape, kept for compat
                title = (assessments.get(course_key) or {}).get("title")
        except Exception:
            pass
        if not title and course is not None:
            title = getattr(course, 'title', None)
        if not title and str(course_key).isdigit():
            try:
                by_id = db.session.get(Course, int(course_key))
                if by_id:
                    title = by_id.title
            except Exception:
                pass
        if not title:
            title = course_key

        # Send the certificate notification email
        try:
            send_final_pass_notification(title, course_key, stu, score, attempt_id)
        except Exception as e:
            app.logger.warning(f"Certificate email after feedback failed: {e}")

        # Enqueue the certificate
        enqueue_certificate_from_session(stu, course_key, score)
        app.logger.info(f"Certificate triggered after feedback for {student.student_id} on {course_key}")

    except Exception as exc:
        app.logger.warning(f"_trigger_certificate_after_feedback failed: {exc}")


def check_and_send_overdue_reminders():
    """Send a single summary email for overdue certificates (lazy, deduped)."""
    cutoff = _now_sast() - timedelta(hours=24)
    overdue = CertificateQueue.query.filter(
        CertificateQueue.status == 'pending',
        CertificateQueue.passed_at <= cutoff,
        CertificateQueue.reminder_sent_at.is_(None),
    ).all()
    if not overdue:
        return 0
    recipients = get_recipients_for_category('certificate_queue')
    if not recipients:
        return 0

    rows_html = ""
    for e in overdue:
        hours_overdue = round(
            (_now_sast() - e.passed_at).total_seconds() / 3600, 1)
        rows_html += f"""<tr>
            <td style="padding:8px;border:1px solid #e2e8f0">{e.student_name}</td>
            <td style="padding:8px;border:1px solid #e2e8f0">{e.company or '—'}</td>
            <td style="padding:8px;border:1px solid #e2e8f0">{e.course_title}</td>
            <td style="padding:8px;border:1px solid #e2e8f0">{e.score:.0f}%</td>
            <td style="padding:8px;border:1px solid #e2e8f0">{e.passed_at.strftime('%d %b %Y, %H:%M')}</td>
            <td style="padding:8px;border:1px solid #e2e8f0;color:#dc2626;font-weight:700">{hours_overdue}h overdue</td>
        </tr>"""

    html_body = f"""
    <h2 style="color:#dc2626">Overdue Certificate Alert</h2>
    <p>The following <strong>{len(overdue)}</strong> certificate(s) have exceeded the
    24-hour creation deadline and require immediate attention:</p>
    <table style="width:100%;border-collapse:collapse;margin:16px 0">
        <tr style="background:#17306B;color:#fff">
            <th style="padding:8px;text-align:left">Student</th>
            <th style="padding:8px;text-align:left">Company</th>
            <th style="padding:8px;text-align:left">Course</th>
            <th style="padding:8px;text-align:left">Score</th>
            <th style="padding:8px;text-align:left">Passed At</th>
            <th style="padding:8px;text-align:left">Status</th>
        </tr>
        {rows_html}
    </table>
    <p>Please log in and create these certificates as soon as possible.</p>
    """

    subject = f"OVERDUE: {len(overdue)} certificate(s) past 24h deadline"
    for recipient in recipients:
        try:
            send_email(recipient, subject, html_body)
        except Exception as exc:
            print(f"Certificate reminder email failed for {recipient}: {exc}")

    for e in overdue:
        e.reminder_sent_at = _now_sast()
    db.session.commit()
    return len(overdue)


