class CertificateLog(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    student_id = db.Column(db.Integer, db.ForeignKey(
        'student.id'), nullable=False)
    course_id = db.Column(db.Integer, db.ForeignKey(
        'course.id'), nullable=False)
    issued_at = db.Column(db.DateTime, default=_now_sast)
    reissued = db.Column(db.Boolean, default=False)
    admin_note = db.Column(db.Text, nullable=True)
    student = db.relationship('Student', backref='certificate_logs')
    course = db.relationship('Course', backref='certificate_logs')


class CertificateQueue(db.Model):
    __tablename__ = 'certificate_queue'
    id = db.Column(db.Integer, primary_key=True)
    student_id = db.Column(db.Integer, db.ForeignKey('student.id'), nullable=False)
