### Assessment Session (Final Assessment Heartbeat Tracking) ###
# Records each sit-down at a final assessment. Created on first heartbeat from
# the proctored assessment page, updated every heartbeat, and closed when the
# student submits. Lets admins see who is currently in an assessment, when it
# started, when it ended, and whether the session went stale.

class AssessmentSession(db.Model):
    __tablename__ = 'assessment_session'
    id = db.Column(db.Integer, primary_key=True)
    student_id = db.Column(db.Integer, db.ForeignKey('student.id'), nullable=False, index=True)
    student_number = db.Column(db.String(32))            # public Student.student_id, for display
    course_key = db.Column(db.String(64), nullable=False, index=True)
    started_at = db.Column(db.DateTime, default=_now_sast, nullable=False)
    last_heartbeat_at = db.Column(db.DateTime, default=_now_sast, nullable=False)
    finished_at = db.Column(db.DateTime, nullable=True)
    finish_reason = db.Column(db.String(32), nullable=True)  # 'submitted', 'stale', 'cancelled'

    # cascade='all, delete-orphan' makes sure that deleting a Student also
    # deletes their AssessmentSession rows. Without it, SQLAlchemy tries to NULL
    # the student_id FK (which is NOT NULL) and the delete fails with an
    # IntegrityError.
    student = db.relationship('Student',
                              backref=db.backref('assessment_sessions',
                                                 cascade='all, delete-orphan',
                                                 lazy=True))


### Session Log (Login/Logout Audit Trail) ###


class SessionLog(db.Model):
    __tablename__ = 'session_log'
    id = db.Column(db.Integer, primary_key=True)
    user_type = db.Column(db.String(20), nullable=False)  # 'student', 'admin', 'company'
    user_id = db.Column(db.String(60), nullable=False)     # student_id, admin email, company user email
    user_name = db.Column(db.String(160))
    action = db.Column(db.String(20), nullable=False)       # 'login', 'logout'
    ip_address = db.Column(db.String(45))
    user_agent = db.Column(db.String(300))
    timestamp = db.Column(db.DateTime, default=_now_sast, index=True)


