# === Course cover upload/delete ===

ALLOWED_IMG = {'png', 'jpg', 'jpeg', 'webp'}
MAX_BYTES = 5 * 1024 * 1024  # 5MB


@app.post('/admin/courses/<int:course_id>/cover')
def upload_course_cover(course_id):
    course = Course.query.get_or_404(course_id)

    f = request.files.get('cover')
    if not f or f.filename == '':
        flash('No file selected.', 'danger')
        return redirect(url_for('edit_course', course_id=course_id))

    ext = f.filename.rsplit('.', 1)[-1].lower() if '.' in f.filename else ''
    if ext not in ALLOWED_IMG:
        flash('Unsupported file type. Use PNG/JPG/WEBP.', 'danger')
        return redirect(url_for('edit_course', course_id=course_id))

    if request.content_length and request.content_length > MAX_BYTES:
        flash('Image too large (max 5 MB).', 'danger')
        return redirect(url_for('edit_course', course_id=course_id))

    upload_dir = os.path.join(current_app.static_folder, 'uploads', 'courses')
    os.makedirs(upload_dir, exist_ok=True)

    fname = f"{uuid.uuid4().hex}_{secure_filename(f.filename)}"
    f.save(os.path.join(upload_dir, fname))

    course.cover_image = fname
    db.session.commit()

    flash('Course cover updated.', 'success')
    return redirect(url_for('edit_course', course_id=course_id))


@app.post('/admin/courses/<int:course_id>/cover/delete')
def delete_course_cover(course_id):
    course = Course.query.get_or_404(course_id)
    if course.cover_image:
        try:
            path = os.path.join(current_app.static_folder,
                                'uploads', 'courses', course.cover_image)
            if os.path.exists(path):
                os.remove(path)
        except Exception:
            pass
        course.cover_image = None
        db.session.commit()
    flash('Course cover removed.', 'success')
    return redirect(url_for('edit_course', course_id=course_id))


# === Course handbook upload/delete ===

ALLOWED_PDF = {'pdf'}
MAX_HANDBOOK_BYTES = 100 * 1024 * 1024  # 100 MB


@app.post('/admin/courses/<int:course_id>/handbook')
@require_role('Admin')
def upload_course_handbook(course_id):
    course = Course.query.get_or_404(course_id)

    f = request.files.get('handbook')
    if not f or f.filename == '':
        flash('No file selected.', 'danger')
        return redirect(url_for('manage_course', course_id=course_id))

    ext = f.filename.rsplit('.', 1)[-1].lower() if '.' in f.filename else ''
    if ext not in ALLOWED_PDF:
        flash('Only PDF files are accepted.', 'danger')
        return redirect(url_for('manage_course', course_id=course_id))

    if request.content_length and request.content_length > MAX_HANDBOOK_BYTES:
        flash('File too large (max 100 MB).', 'danger')
        return redirect(url_for('manage_course', course_id=course_id))

    upload_dir = os.path.join(current_app.static_folder, 'manuals')
    os.makedirs(upload_dir, exist_ok=True)

    fname = f"{uuid.uuid4().hex}_{secure_filename(f.filename)}"
    f.save(os.path.join(upload_dir, fname))

    # Deactivate any existing active handbook for this course
    existing = Handbook.query.filter_by(course_id=course.id, is_active=True).first()
    if existing:
        existing.is_active = False

    handbook = Handbook(
        course_id=course.id,
        title=secure_filename(f.filename).rsplit('.', 1)[0].replace('_', ' '),
        pdf_filename=fname,
        published_at=datetime.now(),
        is_active=True,
    )
    db.session.add(handbook)
    db.session.commit()

    flash('Handbook uploaded successfully.', 'success')
    return redirect(url_for('manage_course', course_id=course_id))


@app.post('/admin/courses/<int:course_id>/handbook/delete')
@require_role('Admin')
def delete_course_handbook(course_id):
    course = Course.query.get_or_404(course_id)
    handbook = Handbook.query.filter_by(course_id=course.id, is_active=True).first()

    if handbook:
        try:
            path = os.path.join(current_app.static_folder, 'manuals', handbook.pdf_filename)
            if os.path.exists(path):
                os.remove(path)
        except Exception:
            pass
        db.session.delete(handbook)
        db.session.commit()

    flash('Handbook removed.', 'success')
    return redirect(url_for('manage_course', course_id=course_id))


