class Course(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(255), nullable=False)
    description = db.Column(db.Text, nullable=False)
    category = db.Column(db.String(100), nullable=True)
    created_at = db.Column(db.DateTime, default=_now_sast)
    enrollments = db.relationship(
        'CourseEnrollment', back_populates='course', lazy=True)
    progress = db.relationship(
        "CourseProgress", back_populates="course", cascade="all, delete-orphan")
    final_assessment_key = db.Column(db.String(64), nullable=True)

    # NEW
    # stores filename only
    cover_image = db.Column(db.String(255), nullable=True)

    # Virtual Training Portal (v1.1.0): distinguishes courses that are delivered live
    # via Microsoft Teams from regular self-paced courses. Virtual courses skip
    # chapter content entirely and only use the final assessment engine.
    course_type = db.Column(db.String(16), default='normal', nullable=False, index=True)

    # Course-level unlock for virtual courses. When True, every enrolled student's
    # final assessment button goes live in one shot. Admins flip this from the
    # Virtual Courses admin page after finishing the Teams class.
    virtual_unlocked = db.Column(db.Boolean, default=False, nullable=False)

    @property
    def cover_url(self):
        """Public URL for the course cover (fallbacks to placeholder)."""
        if self.cover_image:
            # If you added the /media route, you can do: return url_for('media', filename=f'courses/{self.cover_image}')
            return url_for('static', filename=f'uploads/courses/{self.cover_image}')
        return url_for('static', filename='images/course_placeholder.jpg')

    @property
    def code(self):
        return (
            getattr(self, "key", None)
            or getattr(self, "slug", None)
            or getattr(self, "course_key", None)
            or getattr(self, "course_code", None)
            or (str(self.id) if getattr(self, "id", None) is not None else None)
        )


