### Mascot narration (v1.2) ###
# A slide can carry one voiceline plus a track of gesture swaps, so the meerkat
# mascot "speaks" the slide. Three tables:
#   MascotGesture  - the shared gesture library (one row per artwork)
#   ChapterMascot  - one voiceline attached to one chapter
#   MascotCue      - "at this millisecond, switch to this gesture"
# Playback completion is recorded server side in MascotPlayback so the
# acknowledgement gate is not purely a client-side promise.


class MascotGesture(db.Model):
    """One mascot artwork. Shared library, reused across every course."""
    __tablename__ = "mascot_gesture"

    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), nullable=False, unique=True)
    # Path relative to the uploads root, e.g. "mascot/gestures/wave.webp".
    # Uploads live on /home (large disk) rather than the root filesystem.
    image_path = db.Column(db.String(255), nullable=False)
    position = db.Column(db.Integer, default=0, nullable=False)
    is_active = db.Column(db.Boolean, default=True, nullable=False, index=True)
    created_at = db.Column(db.DateTime, default=_now_sast)

    def __repr__(self):
        return f"<MascotGesture {self.name}>"


class ChapterMascot(db.Model):
    """The voiceline attached to a single chapter."""
    __tablename__ = "chapter_mascot"

    id = db.Column(db.Integer, primary_key=True)
    chapter_id = db.Column(db.Integer, db.ForeignKey("course_chapter.id",
                                                     ondelete="CASCADE"),
                           nullable=False, unique=True, index=True)
    audio_path = db.Column(db.String(255), nullable=True)
    # Duration is measured in the browser on upload and stored so the server
    # can judge whether a student actually heard the whole thing.
    duration_ms = db.Column(db.Integer, nullable=True)
    is_enabled = db.Column(db.Boolean, default=True, nullable=False)
    # When true the student must also finish any <video> on the slide before
    # the acknowledgement checkbox unlocks.
    require_video = db.Column(db.Boolean, default=True, nullable=False)
    created_at = db.Column(db.DateTime, default=_now_sast)
    updated_at = db.Column(db.DateTime, default=_now_sast, onupdate=_now_sast)

    chapter = db.relationship("CourseChapter",
                              backref=db.backref("mascot", uselist=False,
                                                 cascade="all, delete-orphan"))
    cues = db.relationship("MascotCue", back_populates="mascot",
                           cascade="all, delete-orphan",
                           order_by="MascotCue.at_ms.asc()")

    @property
    def is_ready(self):
        """Only gate a student when there is actually something to play."""
        return bool(self.is_enabled and self.audio_path)


class MascotCue(db.Model):
    """Switch to `gesture` at `at_ms` into the voiceline."""
    __tablename__ = "mascot_cue"

    id = db.Column(db.Integer, primary_key=True)
    mascot_id = db.Column(db.Integer, db.ForeignKey("chapter_mascot.id",
                                                    ondelete="CASCADE"),
                          nullable=False, index=True)
    gesture_id = db.Column(db.Integer, db.ForeignKey("mascot_gesture.id"),
                           nullable=False)
    at_ms = db.Column(db.Integer, nullable=False, default=0)

    mascot = db.relationship("ChapterMascot", back_populates="cues")
    gesture = db.relationship("MascotGesture")


class MascotPlayback(db.Model):
    """Server-side record that a student heard a slide's voiceline.

    Without this the gate is a client-side courtesy: anyone can enable the
    checkbox from the console. acknowledge_chapter checks this table instead of
    trusting the browser.
    """
    __tablename__ = "mascot_playback"
    __table_args__ = (
        db.UniqueConstraint("student_id", "chapter_id",
                            name="uq_mascot_playback_student_chapter"),
    )

    id = db.Column(db.Integer, primary_key=True)
    student_id = db.Column(db.Integer, db.ForeignKey("student.id"),
                           nullable=False, index=True)
    chapter_id = db.Column(db.Integer, db.ForeignKey("course_chapter.id"),
                           nullable=False, index=True)
    # Highest playback position reported by the browser, in milliseconds.
    heard_ms = db.Column(db.Integer, default=0, nullable=False)
    completed_at = db.Column(db.DateTime, nullable=True)
    video_completed_at = db.Column(db.DateTime, nullable=True)
    # Elapsed video playback actually observed, and the video's own length.
    # Seeking forward does not add to watched time, so these two together prove
    # the video was watched rather than skipped.
    video_watched_ms = db.Column(db.Integer, default=0)
    video_duration_ms = db.Column(db.Integer, nullable=True)
    updated_at = db.Column(db.DateTime, default=_now_sast, onupdate=_now_sast)


#################### ****************######################


# Languages offered for slide subtitles. English is first and is the default:
# the course itself is delivered in English and subtitles are an accessibility
# aid on top of it, not an alternative language mode.
#
# All eleven spoken official languages of South Africa (South African Sign
# Language, the twelfth, cannot be subtitled). The first five were the original
# set; the rest follow alphabetically. A learner is only ever offered the
# languages that have text on the slide in front of them, so an untranslated
# language costs nothing on the student side.
SUBTITLE_LANGUAGES = [
    ("en", "English"),
    ("af", "Afrikaans"),
    ("zu", "isiZulu"),
    ("xh", "isiXhosa"),
    ("tn", "Setswana"),
    ("nr", "isiNdebele"),
    ("nso", "Sepedi"),
    ("st", "Sesotho"),
    ("ss", "siSwati"),
    ("ve", "Tshivenḓa"),
    ("ts", "Xitsonga"),
]
SUBTITLE_LANG_CODES = [c for c, _ in SUBTITLE_LANGUAGES]
SUBTITLE_LANG_NAMES = dict(SUBTITLE_LANGUAGES)


class MascotSubtitle(db.Model):
    """One subtitle block on a slide's narration timeline.

    Timing is held here and only here, against the English voiceline, and every
    language shares it. That is deliberate: if each language carried its own
    timings they would have to be re-timed four more times per slide and would
    drift apart as scripts were edited. A translation inherits the window its
    English block already occupies, which is how subtitling normally works.

    Unlike MascotCue, which is a single point in time that simply persists until
    the next cue, a subtitle has to appear AND disappear, so it carries both
    ends.
    """
    __tablename__ = "mascot_subtitle"
    id = db.Column(db.Integer, primary_key=True)
    mascot_id = db.Column(db.Integer,
                          db.ForeignKey("chapter_mascot.id", ondelete="CASCADE"),
                          nullable=False, index=True)
    start_ms = db.Column(db.Integer, nullable=False, default=0)
    end_ms = db.Column(db.Integer, nullable=False, default=0)
    seq = db.Column(db.Integer, nullable=False, default=0)

    texts = db.relationship("MascotSubtitleText", backref="subtitle",
                            lazy="selectin", cascade="all, delete-orphan")

    def text_for(self, lang):
        """The text in one language, or None if it has not been written yet."""
        for t in self.texts:
            if t.lang == lang:
                return (t.text or "").strip() or None
        return None

    @property
    def duration_ms(self):
        return max(0, (self.end_ms or 0) - (self.start_ms or 0))


class MascotSubtitleText(db.Model):
    """The wording of one subtitle block in one language."""
    __tablename__ = "mascot_subtitle_text"
    __table_args__ = (db.UniqueConstraint("subtitle_id", "lang",
                                          name="uq_subtitle_lang"),)
    id = db.Column(db.Integer, primary_key=True)
    subtitle_id = db.Column(db.Integer,
                            db.ForeignKey("mascot_subtitle.id", ondelete="CASCADE"),
                            nullable=False, index=True)
    lang = db.Column(db.String(5), nullable=False, index=True)
    text = db.Column(db.Text, nullable=False, default="")


