# CArt Helpers,


def _cart_key():
    return f"cart_company_{session.get('company_id')}"


def cart_get():
    # structure: [{"course_id": 1, "employee_ids": [2,3]} , ...]
    return session.get(_cart_key(), [])


def cart_save(cart):
    session[_cart_key()] = cart


def cart_clear():
    session.pop(_cart_key(), None)
