class Student(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    student_id = db.Column(db.String(8), unique=True, nullable=False)
    name = db.Column(db.String(50), nullable=False)
    surname = db.Column(db.String(50), nullable=False)
    national_id = db.Column(db.String(20), unique=True, nullable=False)
    email = db.Column(db.String(100), nullable=False, index=True)
    cell_number = db.Column(db.String(15), nullable=True)
    password = db.Column(db.String(255), nullable=False)
    selfie_filename = db.Column(db.String(255), nullable=True)
    is_banned = db.Column(db.Boolean, default=False)

    # Legacy one-off POPIA fields (kept for backward compatibility)
    popi_version = db.Column(db.String(64), nullable=True, index=True)
    popi_accepted_at = db.Column(db.DateTime, nullable=True, index=True)
    # Subtitle preferences. Every slide opens from these, so a learner who has
    # not opted in never sees subtitles and the course stays English by default.
    subtitles_enabled = db.Column(db.Boolean, nullable=False, default=False)
    subtitle_lang = db.Column(db.String(5), nullable=False, default="en")
    popi_ip = db.Column(db.String(64), nullable=True)
    popi_user_agent = db.Column(db.Text, nullable=True)

    # Legacy (keep for backward-compat in old code/queries)
    registration_date = db.Column(db.DateTime, default=_now_sast)

    # New, explicit field for signup
    date_joined = db.Column(db.DateTime, nullable=False,
                            default=_now_sast, index=True)

    last_login = db.Column(db.DateTime, nullable=True)
    otp = db.Column(db.String(8))
    is_suspended = db.Column(db.Boolean, default=False)

    # --- Company fields ---
    company = db.Column(db.String(160), nullable=True)  # free-text from individual signup
    password_setup_token = db.Column(db.String(64), nullable=True)
    password_setup_token_expires = db.Column(db.DateTime, nullable=True)
    created_by_company_id = db.Column(db.Integer, db.ForeignKey("company.id"), nullable=True)
    created_by_company = db.relationship("Company", foreign_keys=[created_by_company_id], lazy="select")
    branch_id = db.Column(db.Integer, db.ForeignKey("company_branch.id"), nullable=True)

    enrollments = db.relationship(
        'CourseEnrollment', back_populates='student', cascade="all, delete-orphan")
    chapter_progress = db.relationship(
        lambda: ChapterProgress, backref='student', cascade="all, delete-orphan")
    course_progress = db.relationship(
        "CourseProgress", back_populates="student", cascade="all, delete-orphan")

    # --- NEW: POPIA consent relationship & helpers ---
    popia_consents = db.relationship(
        "PopiaConsent",
        backref="student",
        lazy="dynamic",
        cascade="all, delete-orphan"
    )

    def has_popia_consent(self, version=None):
        """True iff student accepted the current POPIA_VERSION (or given version)."""
        v = version or current_app.config.get("POPIA_VERSION", "1")
        return self.popia_consents.filter_by(version=v).first() is not None

    def popia_for(self, version=None):
        """Return the PopiaConsent row for the given/current version, else None."""
        v = version or current_app.config.get("POPIA_VERSION", "1")
        return self.popia_consents.filter_by(version=v).first()

    @property
    def latest_popia(self):
        """Most recent PopiaConsent row (any version) or None."""
        return self.popia_consents.order_by(PopiaConsent.accepted_at.desc()).first()

    def sync_legacy_popia_fields(self):
        """
        Mirror the newest consent into legacy columns (popi_*).
        Call this right after creating a PopiaConsent to keep old UI/queries working.
        """
        c = self.latest_popia
        if c:
            self.popi_version = c.version
            self.popi_accepted_at = c.accepted_at
            self.popi_ip = c.ip_address
            self.popi_user_agent = c.user_agent

    @property
    def full_name(self):
        return f"{self.name} {self.surname}"

