    # Track when student last accessed this course
    last_accessed = db.Column(db.DateTime, nullable=True)

    # v1.2 / CAA condition: the student may not sit the final assessment until
    # FINAL_ASSESSMENT_MIN_WAIT_HOURS after they FIRST opened the course. Set
    # once, on first entry, and never overwritten (see _touch_course_access).
    # NULL on enrollments that predate v1.2; those fall back to enrolled_at,
    # which grandfathers everyone already on the platform.
    first_accessed_at = db.Column(db.DateTime, nullable=True)

    # Virtual training portal fields (v1.1.0)
    # delivery_mode is authoritative; account_type on Student is just a routing hint.
    delivery_mode = db.Column(db.String(16), default='in_person', nullable=False, index=True)
    teams_meeting_link = db.Column(db.String(500), nullable=True)
    virtual_session_date = db.Column(db.DateTime, nullable=True)
    # Manual gate flipped by admin after the Teams class. False = student cannot access final assessment.
    assessment_unlocked = db.Column(db.Boolean, default=False, nullable=False)

