    answers_json = db.Column(db.Text, nullable=True)
    submitted_at = db.Column(db.DateTime, default=_now_sast, nullable=False)

    quiz = db.relationship(
        'VirtualQuiz',
        backref=db.backref('attempts', lazy='dynamic', cascade='all, delete-orphan'),
    )
    student = db.relationship('Student')


