    course_key = db.Column(db.String(100), nullable=True)
    # optional link to final attempt
    attempt_id = db.Column(db.Integer, nullable=True)

    # Likert 0..4 (Completely Disagree..Completely Agree)
    # "The course was easy to navigate."
    q_navigate = db.Column(db.Integer, nullable=False)
    # "The materials were easy to follow…"
    q_understand = db.Column(db.Integer, nullable=False)
    # "I will be able to use the knowledge…"
