    # "The materials provided valuable insights…"
    q_value = db.Column(db.Integer, nullable=False)

    comments = db.Column(db.Text, nullable=True)
    confirm_own = db.Column(db.Boolean, nullable=False,
                            default=False)  # must be True to accept

    # audit
    user_agent = db.Column(db.String(255))
    ip_address = db.Column(db.String(64))
    created_at = db.Column(
        db.DateTime, default=_now_sast, nullable=False)

    __table_args__ = (
        db.UniqueConstraint('student_id', 'course_id',
                            name='uq_feedback_student_course'),
    )


