# If you have decorators like @require_admin, keep them.
# Adjust imports according to your project layout.


def _has_col(model, name: str) -> bool:
    try:
        return name in model.__table__.c
    except Exception:
        return False


def _split_name(full_name: str):
    full = (full_name or "").strip()
    if not full:
        return ("", "")
    parts = full.split()
    if len(parts) == 1:
        return (parts[0], "")
    return (" ".join(parts[:-1]), parts[-1])


def _student_kwargs_from_employee(emp):
    """
    Build a kwargs dict for Student(**kwargs) that only includes columns that exist
    to avoid AttributeError: can't set attribute.
    """
    from models import Student  # or your actual import path

    first_name, last_name = _split_name(emp.full_name)

    kw = {}

    # Common fields seen in your previous signup route
    if _has_col(Student, "name"):
        kw["name"] = first_name or emp.full_name
    if _has_col(Student, "surname"):
        kw["surname"] = last_name
    if _has_col(Student, "full_name"):
        kw["full_name"] = emp.full_name

    if _has_col(Student, "email"):
        kw["email"] = (emp.email or "").lower()
    if _has_col(Student, "cell_number"):
        kw["cell_number"] = emp.phone or ""
    if _has_col(Student, "national_id"):
        kw["national_id"] = emp.national_id or ""

    # Optional convenience fields if your Student has them
    if _has_col(Student, "student_id"):
        # generate an 8-digit ID similar to your signup flow
        import random
        kw["student_id"] = str(random.randint(10_000_000, 99_999_999))
    if _has_col(Student, "otp"):
        import random
        kw["otp"] = str(random.randint(10_000_000, 99_999_999))
    if _has_col(Student, "selfie_filename"):
        kw["selfie_filename"] = None

    return kw


@app.route("/admin/companies")
@require_role('Admin')
def admin_companies():
    """
    List companies with search + counts (employees, users).
    Inject a map of employees per company for inline management.
    """
    q = (request.args.get("q") or "").strip()

    emp_count_sq = (
        db.session.query(
            CompanyEmployee.company_id.label("cid"),
            func.count(CompanyEmployee.id).label("emp_count"),
        )
        .group_by(CompanyEmployee.company_id)
        .subquery()
    )

    user_count_sq = (
        db.session.query(
            CompanyUser.company_id.label("cid"),
            func.count(CompanyUser.id).label("user_count"),
        )
        .group_by(CompanyUser.company_id)
        .subquery()
    )

    query = (
        db.session.query(
            Company,
            func.coalesce(emp_count_sq.c.emp_count, 0).label("employee_count"),
            func.coalesce(user_count_sq.c.user_count, 0).label("user_count"),
        )
        .outerjoin(emp_count_sq, emp_count_sq.c.cid == Company.id)
        .outerjoin(user_count_sq, user_count_sq.c.cid == Company.id)
    )

    if q:
        like = f"%{q}%"
        query = query.filter(
            or_(
                Company.name.ilike(like),
                Company.reg_no.ilike(like),
                Company.industry.ilike(like),
                Company.contact_name.ilike(like),
                Company.contact_email.ilike(like),
                Company.contact_phone.ilike(like),
            )
        )

    rows = query.order_by(Company.created_at.desc()).all()

    # --- load employees per company for inline panel ---
    company_ids = [c.id for (c, _ec, _uc) in rows]
    employees_map = defaultdict(list)
    if company_ids:
        all_emps = (
            CompanyEmployee.query
            .filter(CompanyEmployee.company_id.in_(company_ids))
            .order_by(CompanyEmployee.created_at.desc())
            .all()
        )
        for e in all_emps:
            employees_map[e.company_id].append(e)

    return render_template("admin/companies.html", rows=rows, q=q, employees_map=employees_map)

