def _unique_student_id():
    # S-YYYYMMDD-XXXX (retry until unique)
    alphabet = string.ascii_uppercase + string.digits
    for _ in range(50):
        candidate = f"S-{_now_sast():%Y%m%d}-{''.join(secrets.choice(alphabet) for _ in range(4))}"
        if not Student.query.filter_by(student_id=candidate).first():
            return candidate
    # ultra fallback
    return f"S-{int(_now_sast().timestamp())}"


