@app.post("/admin/companies/<int:company_id>/employees/new")
@require_role('Super Admin')
def admin_company_employee_create(company_id):
    company = db.session.get(Company, company_id)
    if not company:
        flash("Company not found.", "danger")
        return redirect(url_for("admin_companies"))

    full_name = (request.form.get("full_name") or "").strip()
    email = (request.form.get("email") or "").strip().lower() or None
    phone = (request.form.get("phone") or "").strip() or None
    student_number = (request.form.get("student_number")
                      or "").strip() or None  # ← “Student #” from form

    if not full_name:
        flash("Full name is required.", "danger")
        return redirect(url_for("admin_companies") + f"#company-{company_id}")

    try:
        # 1) Find or create Student
        student = None

        # Prefer lookup by student_number if given
        if student_number:
            student = Student.query.filter_by(
                student_id=student_number).first()

        # Else fallback to email (if present)
        if not student and email:
            student = Student.query.filter(
                func.lower(Student.email) == email).first()

        if not student:
            # Build name/surname from full_name
            name, surname = (
                full_name, "") if " " not in full_name else full_name.split(" ", 1)

            # Ensure we have a student_id (required NOT NULL)
            new_student_id = student_number or _unique_student_id()

            student = Student(
                student_id=new_student_id,          # REQUIRED by your schema
                name=name,
                surname=surname,
                email=email,
                cell_number=phone,
                registration_date=_now_sast(),
                date_joined=_now_sast(),
                is_banned=False,
                is_suspended=False,
            )

            # Bypass OTP if these columns exist
            if _has_col(Student, "otp"):
                student.otp = None
            if _has_col(Student, "popi_version"):
                student.popi_version = None
            if _has_col(Student, "popi_accepted_at"):
                student.popi_accepted_at = None
            if _has_col(Student, "popi_ip"):
                student.popi_ip = None
            if _has_col(Student, "popi_user_agent"):
                student.popi_user_agent = None

            db.session.add(student)
            db.session.flush()  # get student.id

        # 2) Create CompanyEmployee (do NOT pass unknown kwargs)
        emp = CompanyEmployee(
            company_id=company.id,
            full_name=full_name,
            email=email,
            phone=phone,
        )
        # If CompanyEmployee has a business student number column, store it
        if _has_col(CompanyEmployee, "student_number") and student_number:
            emp.student_number = student_number
        # If it has a FK to Student.id, link it
        if _has_col(CompanyEmployee, "student_id") and hasattr(student, "id"):
            emp.student_id = student.id

        db.session.add(emp)
        db.session.commit()

        flash(
            f"Employee '{full_name}' added to {company.name} and linked to student '{student.student_id}'.", "success")
        return redirect(url_for("admin_companies") + f"#company-{company_id}")

    except SQLAlchemyError as exc:
        db.session.rollback()
        current_app.logger.exception(
            "Error creating employee/student: %s", exc)
        flash(
            "An error occurred while creating the employee/student. Check logs.", "danger")
        return redirect(url_for("admin_companies") + f"#company-{company_id}")

