@app.route("/admin/companies/<int:company_id>/delete", methods=["POST"])
@require_role('Super Admin')
def admin_delete_company(company_id):
    """Delete a company after verifying the admin typed the exact company name.

    Orchestrates cleanup across every child table that references the company.
    Wrapped in try/except with a rollback so a missed FK doesn't leave the
    session in a bad state and doesn't blow up to a 50x error page.
    """
    company = Company.query.get_or_404(company_id)
    confirm_name = (request.form.get("confirm_name") or "").strip()

    if confirm_name != company.name:
        flash("Company name did not match. Deletion cancelled.", "danger")
        return redirect(url_for("admin_company_detail", company_id=company.id))

    company_name = company.name

    try:
        # Cache child ids up-front so we can wipe grandchildren without
        # relying on ORM cascades (which bulk `.delete()` skips).
        branch_ids = [b.id for b in CompanyBranch.query.filter_by(company_id=company.id).all()]
        user_ids = [u.id for u in CompanyUser.query.filter_by(company_id=company.id).all()]
        emp_ids = [e.id for e in CompanyEmployee.query.filter_by(company_id=company.id).all()]
        order_ids = [o.id for o in CompanyOrder.query.filter_by(company_id=company.id).all()]

        # 1) Detach students. They stay in the platform but lose the company +
        #    branch link (branches belong to the company we're deleting).
        Student.query.filter_by(created_by_company_id=company.id).update(
            {"created_by_company_id": None, "branch_id": None},
            synchronize_session=False,
        )

        # 2) POPIA consents (child of CompanyUser).
        if user_ids:
            CompanyPopiaConsent.query.filter(
                CompanyPopiaConsent.company_user_id.in_(user_ids)
            ).delete(synchronize_session=False)

        # 3) Orders (items first, then order rows).
        if order_ids:
            CompanyOrderItem.query.filter(
                CompanyOrderItem.order_id.in_(order_ids)
            ).delete(synchronize_session=False)
        CompanyOrder.query.filter_by(company_id=company.id).delete(
            synchronize_session=False)

        # 4) Credit ledger (missed by the original delete — was the FK that
        #    blew this up before).
        CreditTransaction.query.filter_by(company_id=company.id).delete(
            synchronize_session=False)

        # 5) Employee documents (child of CompanyEmployee — bulk delete on
        #    CompanyEmployee skips ORM cascade, so we clear the children by
        #    hand first).
        if emp_ids:
            EmployeeDocument.query.filter(
                EmployeeDocument.employee_id.in_(emp_ids)
            ).delete(synchronize_session=False)
        CompanyEmployee.query.filter_by(company_id=company.id).delete(
            synchronize_session=False)

        # 6) Company users.
        CompanyUser.query.filter_by(company_id=company.id).delete(
            synchronize_session=False)

        # 7) Approved-courses M2M join rows for this company.
        db.session.execute(
            company_approved_course.delete().where(
                company_approved_course.c.company_id == company.id
            )
        )

        # 8) Branches (safe now that no student.branch_id and no
        #    CompanyUser.branch_id references them).
        if branch_ids:
            CompanyBranch.query.filter_by(company_id=company.id).delete(
                synchronize_session=False)

        # 9) The company itself.
        db.session.delete(company)
        db.session.commit()

        flash(f"Company \"{company_name}\" has been permanently deleted.", "success")
        return redirect(url_for("admin_companies"))

    except Exception as e:
        db.session.rollback()
        app.logger.exception(
            "admin_delete_company failed for company_id=%s (%s): %s",
            company.id, company_name, e,
        )
        flash(
            f"Could not delete \"{company_name}\": {e}. Nothing was removed. "
            "Please share this error with the platform admin.",
            "danger",
        )
        return redirect(url_for("admin_company_detail", company_id=company.id))


@app.route("/admin/companies/<int:company_id>/edit", methods=["POST"])
@require_role('Super Admin')
def admin_edit_company(company_id):
    """Edit company details (Super Admin+ only).

    Accepts every user-editable Company field so admins can correct typos in any
    block of the profile, not just the name. Empty strings collapse to None so
    we don't store whitespace-only values.
    """
    company = Company.query.get_or_404(company_id)

    def _str_or_none(field):
        v = (request.form.get(field) or "").strip()
        return v or None

    # Name is the one required field — fall back to existing value if blank.
    company.name = (request.form.get("company_name") or company.name).strip()

    # Status & Registration block
    company.reg_no = _str_or_none("reg_no")
    company.industry = _str_or_none("industry")
    company.vat_number = _str_or_none("vat_number")
    company.entity_responsible = _str_or_none("entity_responsible")
    company.purchase_order_number = _str_or_none("purchase_order_number")

    # Address block
    company.address = _str_or_none("address")
    company.postal_address = _str_or_none("postal_address")
    company.postal_code = _str_or_none("postal_code")
    company.street_address = _str_or_none("street_address")
    company.street_postal_code = _str_or_none("street_postal_code")

    # Contact block
    company.contact_name = _str_or_none("contact_name")
    company.contact_email = _str_or_none("contact_email")
    company.contact_phone = _str_or_none("contact_phone")
    company.cellphone = _str_or_none("cellphone")

    db.session.commit()
    flash(f"Company \"{company.name}\" has been updated.", "success")
    return redirect(url_for("admin_company_detail", company_id=company.id))


@app.route("/admin/companies/<int:company_id>")
@require_role('Admin')
def admin_company_detail(company_id):
    """
    Company profile + employees table (with Register as Student action).
    """
    company = Company.query.get_or_404(company_id)

    q = (request.args.get("q") or "").strip()
    emp_query = CompanyEmployee.query.filter_by(company_id=company.id)
    if q:
        like = f"%{q}%"
        emp_query = emp_query.filter(
            or_(
                CompanyEmployee.full_name.ilike(like),
                CompanyEmployee.email.ilike(like),
                CompanyEmployee.phone.ilike(like),
                CompanyEmployee.national_id.ilike(like),
                CompanyEmployee.passport_no.ilike(like),
                CompanyEmployee.position.ilike(like),
            )
        )

    employees = emp_query.order_by(CompanyEmployee.created_at.desc()).all()

    # counts
    emp_count = CompanyEmployee.query.filter_by(company_id=company.id).count()
    user_count = CompanyUser.query.filter_by(company_id=company.id).count()

    # Company's students
    company_students = Student.query.filter_by(
        created_by_company_id=company.id).order_by(Student.date_joined.desc()).all()

    # Build progress map: {enrollment_id: {completed, total, percent, passed, ...}}
    progress_map = {}
    now = _now_sast()
    for s in company_students:
        for enr in s.enrollments:
            total = CourseChapter.query.filter_by(course_id=enr.course_id).count()
            done = CourseProgress.query.filter_by(
                student_id=s.id, course_id=enr.course_id, completed=True
            ).count()
            pct = int(done / total * 100) if total > 0 else 0

            passed_final = False
            final_passed_date = None
            course_obj = enr.course
            key = (getattr(course_obj, "final_assessment_key", None)
                   or str(course_obj.id)).strip().lower().replace(" ", "_")

            sub = FinalAssessmentSubmission.query.filter_by(
                student_id=s.id, course_id=enr.course_id, is_active=True
            ).order_by(FinalAssessmentSubmission.submitted_at.desc()).first()
            if sub and sub.percentage is not None and sub.percentage >= 80:
                passed_final = True
                final_passed_date = sub.submitted_at

            if not passed_final:
                fa = FinalAssessmentAttempt.query.filter_by(
                    student_id=s.id, course_key=key, is_active=True
                ).order_by(FinalAssessmentAttempt.submitted_at.desc()).first()
                if fa and fa.percentage is not None and fa.percentage >= 80:
                    passed_final = True
                    final_passed_date = fa.submitted_at

            if not passed_final:
                aa = AssessmentAttempt.query.filter_by(
                    student_id=str(s.student_id), course_key=key, is_active=True
                ).order_by(AssessmentAttempt.created_at.desc()).first()
                if aa and aa.score is not None and aa.score >= 80:
                    passed_final = True
                    final_passed_date = aa.created_at

            # Attempt counts & last score
            attempts_used, attempts_left = get_attempt_counts(s.id, key)

            last_score = None
            failed = False
            if not passed_final and attempts_used > 0:
                failed = True

            # Always fetch last score (for both passed and failed display)
            if attempts_used > 0:
                latest_sub = FinalAssessmentSubmission.query.filter_by(
                    student_id=s.id, course_id=enr.course_id, is_active=True
                ).order_by(FinalAssessmentSubmission.submitted_at.desc()).first()
                latest_fa = FinalAssessmentAttempt.query.filter_by(
                    student_id=s.id, course_key=key, is_active=True
                ).order_by(FinalAssessmentAttempt.submitted_at.desc()).first()
                latest_aa = AssessmentAttempt.query.filter_by(
                    student_id=str(s.student_id), course_key=key, is_active=True
                ).order_by(AssessmentAttempt.created_at.desc()).first()
                scores = []
                if latest_sub and latest_sub.percentage is not None:
                    scores.append((latest_sub.submitted_at, latest_sub.percentage))
                if latest_fa and latest_fa.percentage is not None:
                    scores.append((latest_fa.submitted_at, latest_fa.percentage))
                if latest_aa and latest_aa.score is not None:
                    scores.append((latest_aa.created_at, latest_aa.score))
                if scores:
                    scores.sort(key=lambda x: x[0] or datetime.min, reverse=True)
                    last_score = round(scores[0][1])

            cert_expiry = None
            time_remaining = None
            expired = False
            if passed_final and final_passed_date:
                cert_expiry = final_passed_date + timedelta(days=730)
                if now < cert_expiry:
                    delta = cert_expiry - now
                    years = delta.days // 365
                    months = (delta.days % 365) // 30
                    days_left = delta.days % 30
                    if years > 0:
                        time_remaining = f"{years}y {months}m"
                    elif months > 0:
                        time_remaining = f"{months}m {days_left}d"
                    else:
                        time_remaining = f"{days_left} days"
                else:
                    expired = True
                    time_remaining = "Expired"

            progress_map[enr.id] = {
                "completed": done, "total": total, "percent": pct,
                "passed": passed_final, "passed_date": final_passed_date,
                "cert_expiry": cert_expiry, "time_remaining": time_remaining,
                "expired": expired,
                "attempts_used": attempts_used, "attempts_left": attempts_left,
                "failed": failed, "last_score": last_score,
            }

    return render_template(
        "admin/company_detail.html",
        company=company,
        employees=employees,
        emp_count=emp_count,
        user_count=user_count,
        q=q,
        company_students=company_students,
        progress_map=progress_map,
    )

