@app.route("/admin/credits/adjust", methods=["POST"])
@require_role('Admin')
def admin_credits_adjust():
    """Add or deduct credits for a company."""
    company_id = request.form.get("company_id", type=int)
    amount = request.form.get("amount", type=int)
    reason = (request.form.get("reason") or "").strip()

    if not company_id or not amount:
        flash("Company and amount are required.", "warning")
        return redirect(url_for("admin_credits"))

    company = db.session.get(Company, company_id)
    if not company:
        flash("Company not found.", "danger")
        return redirect(url_for("admin_credits"))

    company.enrollment_credits = (company.enrollment_credits or 0) + amount
    if company.enrollment_credits < 0:
        company.enrollment_credits = 0

    admin_name = session.get("admin_name", "Admin")
    txn = CreditTransaction(
        company_id=company.id,
        amount=amount,
        balance_after=company.enrollment_credits,
        description=reason or ("Credits added" if amount > 0 else "Credits deducted"),
        admin_id=session.get("admin_id"),
        admin_name=admin_name,
    )
    db.session.add(txn)
    db.session.commit()

    action = "added" if amount > 0 else "deducted"
    flash(f"{abs(amount)} credit(s) {action} for {company.name}. New balance: {company.enrollment_credits}", "success")
    return redirect(url_for("admin_credits", company_id=company.id))


