@app.route("/admin/employees/<int:emp_id>/register_student", methods=["POST"])
@require_role('Super Admin')
def admin_register_employee_student(emp_id):
    """
    Admin-side 'Register as Student' (does NOT rely on session['company_id']).
    - If a Student with same email exists -> link.
    - Else create a new Student with best-effort field mapping.
    """
    from models import Student  # adjust to your import

    emp = CompanyEmployee.query.get_or_404(emp_id)

    # Try to match by email (case-insensitive)
    student = None
    if emp.email:
        student = Student.query.filter(func.lower(
            Student.email) == emp.email.lower()).first()

    if not student:
        # Build kwargs safely against whatever Student columns you actually have
        kwargs = _student_kwargs_from_employee(emp)

        # temp password if student requires one
        # adjust policy if needed
        temp_pw = request.form.get("password") or "Temp1234!"

        # Set password if model supports set_password or password attribute
        # Do not put 'password' in kwargs; set after instance creation to avoid unknown-column issues
        student = Student(**kwargs)
        if hasattr(student, "set_password"):
            student.set_password(temp_pw)
        elif _has_col(Student, "password_hash"):
            student.password_hash = generate_password_hash(temp_pw)
        elif hasattr(student, "password"):  # write-only property
            student.password = temp_pw
        # else: no password field required

        db.session.add(student)
        db.session.flush()  # get student.id

    # Link employee -> student
    emp.student_id = student.id
    db.session.add(emp)
    db.session.commit()

    flash(
        f"Employee '{emp.full_name}' registered/linked as student.", "success")
    # Redirect back to company detail if we came from there
    company_id = emp.company_id
    return redirect(url_for("admin_company_detail", company_id=company_id))


