# Helper


def _attach_choices_for_view(q):
    """
    Ensure q has option_a..option_d populated from whatever the record has
    (option_* columns, options JSON mapping, or options_json array).
    """
    # already present
    if any([getattr(q, 'option_a', None),
            getattr(q, 'option_b', None),
            getattr(q, 'option_c', None),
            getattr(q, 'option_d', None)]):
        return q

    # dict-like mapping on q.options (may be a JSON string)
    opts = getattr(q, 'options', None)
    if isinstance(opts, str):
        try:
            opts = json.loads(opts)
        except Exception:
            opts = None
    if isinstance(opts, dict):
        q.option_a = opts.get('a')
        q.option_b = opts.get('b')
        q.option_c = opts.get('c')
        q.option_d = opts.get('d')
        return q

    # legacy list JSON on q.options_json
    raw = getattr(q, 'options_json', None)
    if raw:
        try:
            arr = json.loads(raw) if isinstance(raw, str) else list(raw)
        except Exception:
            arr = []
        arr = (arr + [None, None, None, None])[:4]
        q.option_a, q.option_b, q.option_c, q.option_d = arr
        return q

    return q

