@app.route('/chapter/<int:chapter_id>/quiz/add', methods=['GET', 'POST'])
def add_quiz_question(chapter_id):
    # ✅ Admin guard
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized access", "danger")
        return redirect(url_for('admin_login'))

    # ✅ Ensure chapter exists
    ch = CourseChapter.query.get_or_404(chapter_id)

    if request.method == 'GET':
        return render_template('add_quiz_question_basic.html', chapter=ch)

    # --- POST: create question ---
    import json

    qtext = (request.form.get('question') or '').strip()

    # supports opt1..opt4 OR opt_a..opt_d
    raw_opts = [
        (request.form.get('opt1') or request.form.get('opt_a') or '').strip(),
        (request.form.get('opt2') or request.form.get('opt_b') or '').strip(),
        (request.form.get('opt3') or request.form.get('opt_c') or '').strip(),
        (request.form.get('opt4') or request.form.get('opt_d') or '').strip(),
    ]
    # keep order, drop empties at the end
    opts = [o for o in raw_opts if o != '']

    # correct can be index or a/b/c/d
    correct_raw = (request.form.get('correct') or '0').strip().lower()
    if correct_raw in ('a', 'b', 'c', 'd'):
        map_to_idx = {'a': 0, 'b': 1, 'c': 2, 'd': 3}
        correct_idx = map_to_idx[correct_raw]
    else:
        try:
            correct_idx = int(correct_raw)
        except ValueError:
            correct_idx = 0

    # guard rails
    if not qtext or not opts:
        flash("Please provide a question and at least one option.", "danger")
        return redirect(url_for('edit_chapter', chapter_id=ch.id))

    # clamp correct_index
    if correct_idx < 0 or correct_idx >= len(opts):
        correct_idx = 0

    # 🔧 Use ChapterQuizQuestion, not QuizQuestion
    try:
        next_pos = (
            db.session.query(db.func.max(ChapterQuizQuestion.position))
            .filter_by(chapter_id=chapter_id)
            .scalar()
            or 0
        ) + 1
    except Exception:
        # if position column not present in some legacy env
        next_pos = 1

    # Create the record using whichever fields your model actually has
    q = ChapterQuizQuestion(chapter_id=chapter_id)

    # Unified fields
    if hasattr(q, 'position'):
        q.position = next_pos
    if hasattr(q, 'qtype'):
        q.qtype = (request.form.get('qtype') or 'mcq').strip().lower() or 'mcq'

    # Text field name differences
    if hasattr(q, 'prompt'):
        q.prompt = qtext
    elif hasattr(q, 'question'):
        q.question = qtext

    # Options: support both column layout and JSON
    # 1) Column layout option_a..option_d
    if hasattr(q, 'option_a') or hasattr(q, 'option_b') or hasattr(q, 'option_c') or hasattr(q, 'option_d'):
        # fill from opts list (A..D)
        oa = opts[0] if len(opts) > 0 else ''
        ob = opts[1] if len(opts) > 1 else ''
        oc = opts[2] if len(opts) > 2 else ''
        od = opts[3] if len(opts) > 3 else ''
        if hasattr(q, 'option_a'):
            q.option_a = oa
        if hasattr(q, 'option_b'):
            q.option_b = ob
        if hasattr(q, 'option_c'):
            q.option_c = oc
        if hasattr(q, 'option_d'):
            q.option_d = od

    # 2) JSON mapping {'a': '...', 'b': '...', 'c': '...', 'd': '...'} on q.options
    if hasattr(q, 'options'):
        opt_map = {}
        labels = ['a', 'b', 'c', 'd']
        for i, label in enumerate(labels):
            if i < len(opts):
                opt_map[label] = opts[i]
        q.options = json.dumps(opt_map)

    # 3) Legacy list JSON on options_json
    if hasattr(q, 'options_json'):
        q.options_json = json.dumps(opts)

    # Correct answer: either key ('a'..'d') or index
    if hasattr(q, 'correct'):
        # Map index back to key; default to 'a'
        idx_to_key = {0: 'a', 1: 'b', 2: 'c', 3: 'd'}
        q.correct = idx_to_key.get(correct_idx, 'a')

    if hasattr(q, 'correct_index'):
        q.correct_index = correct_idx

    db.session.add(q)
    db.session.commit()
    flash("✅ Question added.", "success")
    return redirect(url_for('edit_chapter', chapter_id=ch.id))


