@app.route("/course/<int:course_id>/final/retake", methods=["POST"])
def retake_final_assessment(course_id):
    # Require login
    sid = session.get("student_id")
    if not sid:
        flash("⚠ Please log in first.", "danger")
        return redirect(url_for("login"))

    # Public student number -> Student row (internal PK)
    student = Student.query.filter_by(student_id=str(sid)).first()
    if not student:
        flash("⚠ Student not found.", "danger")
        return redirect(url_for("dashboard"))

    course = Course.query.get_or_404(course_id)

    # If a previous attempt id was posted, mark it as failed (if not already terminal)
    prev_attempt_id = request.form.get("prev_attempt_id")
    if prev_attempt_id and prev_attempt_id.isdigit():
        prev = None

        # New table
        try:
            prev = (FinalAssessmentSubmission.query
                    .filter_by(id=int(prev_attempt_id),
                               course_id=course.id,
                               student_id=student.id)
                    .first())
        except NameError:
            prev = None

        # Legacy table fallback
        if not prev:
            try:
                prev = (FinalAssessmentAttempt.query
                        .filter_by(id=int(prev_attempt_id),
                                   course_id=course.id,
                                   student_id=student.id)
                        .first())
            except NameError:
                prev = None

        if prev:
            updated = False
            if hasattr(prev, "review_status"):
                if (prev.review_status or "").lower() not in ("passed", "failed"):
                    prev.review_status = "failed"
                    updated = True
            elif hasattr(prev, "status"):
                if (prev.status or "").lower() not in ("passed", "failed"):
                    prev.status = "failed"
                    updated = True

            if updated:
                try:
                    db.session.add(prev)
                    db.session.commit()
                    current_app.logger.info(
                        "Retake: marked prev attempt %s as failed", prev_attempt_id)
                except Exception as e:
                    current_app.logger.warning(
                        "Retake: commit failed for prev %s: %s", prev_attempt_id, e)
                    db.session.rollback()

    # Route to the active final flow (prefer intro/start if present)
    if "final_assessment_start" in current_app.view_functions:
        return redirect(url_for("final_assessment_start", course_id=course.id))
    if "final_assessment_intro" in current_app.view_functions:
        return redirect(url_for("final_assessment_intro", course_id=course.id))
    if "final_assessment" in current_app.view_functions:
        return redirect(url_for("final_assessment", course_id=course.id))

    # Final fallback: run_final with mapped key or course id
    key = (getattr(course, "final_assessment_key", None)
           or str(course.id) or "").strip()
    code = key.lower().replace(" ", "_")
    current_app.logger.info(
        "Retake: falling back to run_final with code=%s", code)
    return redirect(url_for(f'{code}_take'))

