# in the route that renders your Tailwind template


def _student_ctx():
    sid_public = session.get("student_id")
    out = dict(student_id=None, student_name=None,
               student_email=None, student_number=None)
    if not sid_public:
        return out
    s = Student.query.filter_by(student_id=str(sid_public)).first()
    if not s:
        return out

    full = (" ".join(filter(None, [
        getattr(s, "first_name", None),
        getattr(s, "last_name", None),
    ])) or getattr(s, "name", None) or "").strip() or None

    out["student_id"] = s.student_id
    out["student_name"] = full
    out["student_email"] = (getattr(s, "email", "") or None)
    out["student_number"] = (
        getattr(s, "student_number", None)
        or getattr(s, "student_no", None)
        or s.student_id
    )
    return out

