@app.route("/final_assessment/<int:course_id>")
@require_popia
def final_assessmentt(course_id):
    # (optional) require login like elsewhere
    if "student_id" not in session and "fa_student_id" not in session:
        flash("⚠ Please log in first.", "danger")
        return redirect(url_for("login"))

    course = db.session.get(Course, course_id)
    if not course:
        flash("Course not found.", "danger")
        return redirect(url_for("dashboard"))

    # CAA minimum wait (v1.2). This route is a dispatcher that forwards to the
    # real assessment endpoint, and it is the first rule registered for
    # /final_assessment/<id>, so the gate has to be here too.
    _fa_student = Student.query.filter_by(
        student_id=str(session.get("student_id")
                       or session.get("fa_student_id") or "")).first()
    if _fa_student:
        _blocked = _enforce_final_wait(_fa_student.id, course.id)
        if _blocked:
            return _blocked

    # Prefer explicit final key, else key/slug/id
    raw_code = (
        getattr(course, "final_assessment_key", None)
        or getattr(course, "key", None)
        or getattr(course, "slug", None)
        or f"course_{course.id}"
    )
    raw_code = (raw_code or "").strip()

    # Try the original-case endpoint first (e.g. DGGE_take),
    # then lowercase (e.g. dgge_take), then fall back to run_final
    for candidate in (raw_code, raw_code.lower().replace(" ", "_")):
        ep = f'{candidate}_take'
        if ep in current_app.view_functions:
            current_app.logger.info(
                "final_assessment -> matched endpoint %s", ep)
            return redirect(url_for(ep))

    code = raw_code.lower().replace(" ", "_")
    current_app.logger.warning(
        "final_assessment -> fallback to /run_final/%s", code)
    return redirect(url_for('run_final', code=code))

