### Course Feedback ###


@app.route("/course/<int:course_id>/feedback", methods=["POST"])
def course_feedback(course_id):
    # --- Auth guard
    sid = session.get("student_id")
    if not sid:
        flash("⚠ Please log in first.", "danger")
        return redirect(url_for("login"))

    # --- Resolve student + course
    student = Student.query.filter_by(student_id=sid).first()
    if not student:
        flash("⚠ Student not found.", "danger")
        return redirect(url_for("dashboard"))

    course = Course.query.get_or_404(course_id)

    # --- Helpers
    def safe_score(v):
        try:
            n = int(v)
        except (TypeError, ValueError):
            n = 0
        return max(0, min(4, n))  # clamp to 0..4

    def safe_attempt(v):
        try:
            return int(v) if v not in (None, "", "null") else None
        except (TypeError, ValueError):
            return None

    # --- Extract form fields
    attempt_id = safe_attempt(request.form.get("attempt_id"))
    q_navigate = safe_score(request.form.get("q_navigate"))
    q_understand = safe_score(request.form.get("q_understand"))
    q_apply = safe_score(request.form.get("q_apply"))
    q_value = safe_score(request.form.get("q_value"))
    comments_raw = request.form.get("comments") or ""
    comments = comments_raw[:2000]  # keep it sane
    confirm_own = True                 # enforced consent
    ua = (request.headers.get("User-Agent") or "")[:255]
    ip = (request.headers.get("X-Forwarded-For")
          or request.remote_addr or "")[:64]

    # --- Upsert (unique on (student_id, course_id))
    fb = CourseFeedback.query.filter_by(
        student_id=student.id, course_id=course.id).first()
    if not fb:
        fb = CourseFeedback(student_id=student.id, course_id=course.id)

    fb.attempt_id = attempt_id if attempt_id is not None else fb.attempt_id
    fb.q_navigate = q_navigate
    fb.q_understand = q_understand
    fb.q_apply = q_apply
    fb.q_value = q_value
    fb.comments = comments
    fb.confirm_own = confirm_own
    fb.user_agent = ua
    fb.ip_address = ip
    # Refresh created_at on every save (see note in assessment_feedback): the
    # dashboard's feedback-required gate compares created_at to the latest
    # passing attempt's timestamp, so an in-place upsert that keeps the old
    # created_at would make a fresh submission look stale.
    fb.created_at = _now_sast()

    db.session.add(fb)
    db.session.commit()

    # --- Optional SACAA appeal/dispute, submitted alongside feedback ---
    # Wrapped so a failure here (e.g. transient DB error) can never block the
    # certificate trigger below — that must always run once feedback is saved.
    if (request.form.get("lodge_appeal") or "").strip() == "yes":
        try:
            create_appeal(
                student,
                request.form.get("appeal_description"),
                source="feedback",
                course=course,
                feedback_id=fb.id,
            )
        except Exception:
            app.logger.exception("create_appeal failed during course_feedback submission")

    # --- Trigger certificate workflow now that feedback is submitted ---
    # Derive the course_key from the Course record
    ck = getattr(course, 'final_assessment_key', None) or getattr(course, 'code', None) or str(course.id)
    _trigger_certificate_after_feedback(student, ck)

    # --- Return fragment for fetch/XHR or full page fallback
    try:
        html_fragment = render_template(
            "partials/feedback_thanks_fragment.html",
            course=course, student=student
        )
    except TemplateNotFound:
        # Tailwind-styled default fragment (no redirect)
        html_fragment = render_template_string("""
<div class="border border-emerald-200 bg-emerald-50 rounded-lg p-4">
  <div class="font-extrabold text-emerald-800 text-lg mb-1">🎉 Thank you!</div>
  <div class="text-emerald-800">Your feedback was received.</div>
</div>
""", course=course, student=student)

    xr = (request.headers.get("X-Requested-With") or "").lower()
    if xr in ("fetch", "xmlhttprequest"):
        return html_fragment, 200

    # Non-JS fallback (rare)
    return render_template("course_feedback_thanks.html", course=course, student=student)


