@app.route("/assessment/<course_key>/feedback", methods=["POST"])
def assessment_feedback(course_key):
    """Handle feedback for final assessments that use course_key instead of course_id"""
    # --- Auth guard
    sid = session.get("student_id")
    if not sid:
        flash("⚠ Please log in first.", "danger")
        return redirect(url_for("login"))

    # --- Resolve student
    student = Student.query.filter_by(student_id=sid).first()
    if not student:
        flash("⚠ Student not found.", "danger")
        return redirect(url_for("dashboard"))

    # --- Load assessment info from config (same list-vs-dict + Course.title
    # fallback as in `_trigger_certificate_after_feedback`). Without this the
    # feedback "Thank you" panel reads "Your feedback for 30 was received."
    # when the caller landed here via a course id rather than a real key.
    assessment_title = None
    try:
        with open("config/assessments.json", "r") as f:
            assessments = json.load(f)
        if isinstance(assessments, list):
            match = next((a for a in assessments if a.get("key") == course_key), None)
            if match:
                assessment_title = match.get("title")
        elif isinstance(assessments, dict):
            assessment_title = (assessments.get(course_key) or {}).get("title")
    except Exception:
        pass
    if not assessment_title:
        # Try the Course table — first by final_assessment_key, then by id when
        # course_key is a numeric string.
        course_lookup = Course.query.filter_by(final_assessment_key=course_key).first()
        if not course_lookup and str(course_key).isdigit():
            try:
                course_lookup = db.session.get(Course, int(course_key))
            except Exception:
                course_lookup = None
        if course_lookup and course_lookup.title:
            assessment_title = course_lookup.title
    if not assessment_title:
        assessment_title = course_key

    # --- Helpers
    def safe_score(v):
        try:
            n = int(v)
        except (TypeError, ValueError):
            n = 0
        return max(0, min(4, n))

    def safe_attempt(v):
        try:
            return int(v) if v not in (None, "", "null") else None
        except (TypeError, ValueError):
            return None

    # --- Extract form fields
    attempt_id = safe_attempt(request.form.get("attempt_id"))
    q_navigate = safe_score(request.form.get("q_navigate"))
    q_understand = safe_score(request.form.get("q_understand"))
    q_apply = safe_score(request.form.get("q_apply"))
    q_value = safe_score(request.form.get("q_value"))
    comments_raw = request.form.get("comments") or ""
    comments = comments_raw[:2000]
    confirm_own = True
    ua = (request.headers.get("User-Agent") or "")[:255]
    ip = (request.headers.get("X-Forwarded-For")
          or request.remote_addr or "")[:64]

    # --- Upsert (unique on (student_id, course_key))
    # Normalize the key to lowercase on write so it always matches the
    # lowercased attempt key (register_assessment stores 'dgge'); a mixed-case
    # key here would make the dashboard's feedback gate miss the row.
    norm_course_key = (course_key or "").lower()
    fb = CourseFeedback.query.filter(
        CourseFeedback.student_id == student.id,
        func.lower(CourseFeedback.course_key) == norm_course_key).first()
    if not fb:
        fb = CourseFeedback(student_id=student.id, course_key=norm_course_key)
    else:
        fb.course_key = norm_course_key

    fb.attempt_id = attempt_id if attempt_id is not None else fb.attempt_id
    fb.q_navigate = q_navigate
    fb.q_understand = q_understand
    fb.q_apply = q_apply
    fb.q_value = q_value
    fb.comments = comments
    fb.confirm_own = confirm_own
    fb.user_agent = ua
    fb.ip_address = ip
    # Refresh created_at on every save so the dashboard's timestamp-aware
    # feedback gate (feedback.created_at >= latest_pass_timestamp) treats the
    # row as belonging to the most recent passing attempt. Without this, an
    # in-place upsert keeps the old created_at and the dashboard keeps
    # nagging "Feedback required" even after a fresh submission.
    fb.created_at = _now_sast()

    db.session.add(fb)
    db.session.commit()

    # --- Optional SACAA appeal/dispute, submitted alongside feedback ---
    # Wrapped so a failure here (e.g. transient DB error) can never block the
    # certificate trigger below — that must always run once feedback is saved.
    if (request.form.get("lodge_appeal") or "").strip() == "yes":
        try:
            create_appeal(
                student,
                request.form.get("appeal_description"),
                source="feedback",
                course_key=norm_course_key,
                feedback_id=fb.id,
            )
        except Exception:
            app.logger.exception("create_appeal failed during assessment_feedback submission")

    # --- Trigger certificate workflow now that feedback is submitted ---
    _trigger_certificate_after_feedback(student, course_key)

    # --- Return fragment for fetch/XHR or full page fallback
    html_fragment = render_template_string("""
<div class="border border-emerald-200 bg-emerald-50 rounded-lg p-4">
  <div class="font-extrabold text-emerald-800 text-lg mb-1">🎉 Thank you!</div>
  <div class="text-emerald-800">Your feedback for {{ title }} was received.</div>
</div>
""", title=assessment_title)

    xr = (request.headers.get("X-Requested-With") or "").lower()
    if xr in ("fetch", "xmlhttprequest"):
        return html_fragment, 200

    flash("✅ Thank you for your feedback!", "success")
    return redirect(url_for("dashboard"))


### Course Feedback Standalone Page ###


@app.route("/course/<int:course_id>/feedback-form", methods=["GET"])
def course_feedback_page(course_id):
    """Standalone feedback page — linked from dashboard when feedback is required."""
    sid = session.get("student_id")
    if not sid:
        flash("Please log in first.", "warning")
        return redirect(url_for("login"))

    student = Student.query.filter_by(student_id=sid).first()
    if not student:
        flash("Student not found.", "danger")
        return redirect(url_for("dashboard"))

    course = Course.query.get_or_404(course_id)

    # Determine the course_key for the feedback form action
    course_key = getattr(course, 'final_assessment_key', None) or getattr(course, 'code', None)

    # Find the latest passing attempt across all three persistence layers, so
    # we can compare feedback age. This is the same logic the dashboard uses
    # to decide whether to show the "Feedback required" gate; without it,
    # stale feedback rows from a previous attempt would make this page show
    # "Thank you, already submitted" even when the student needs to submit
    # fresh feedback for the current pass.
    latest_pass_ts = None
    attempt_id = None
    if course_key:
        att = FinalAssessmentAttempt.query.filter(
            ((FinalAssessmentAttempt.student_id == student.id) |
             (FinalAssessmentAttempt.student_number == student.student_id)),
            FinalAssessmentAttempt.course_key == course_key,
            FinalAssessmentAttempt.passed == True,
            FinalAssessmentAttempt.is_active.is_(True)
        ).order_by(FinalAssessmentAttempt.submitted_at.desc()).first()
        if att:
            attempt_id = att.id
            latest_pass_ts = getattr(att, 'submitted_at', None)
        else:
            aa = AssessmentAttempt.query.filter(
                AssessmentAttempt.student_id == str(student.student_id),
                func.lower(AssessmentAttempt.course_key) == course_key.lower(),
                AssessmentAttempt.is_active.is_(True)
            ).order_by(AssessmentAttempt.created_at.desc()).first()
            if aa and aa.score is not None and aa.score >= 80:
                attempt_id = aa.id
                latest_pass_ts = getattr(aa, 'finished_at', None) or getattr(aa, 'created_at', None)

    # Also consider a passing FinalAssessmentSubmission row (run_final path) —
    # take whichever timestamp is most recent across the three tables.
    sub = (
        FinalAssessmentSubmission.query
        .filter_by(student_id=student.id, course_id=course.id, is_active=True)
        .order_by(FinalAssessmentSubmission.submitted_at.desc())
        .first()
    )
    if sub and (sub.percentage or 0) >= 80:
        sub_ts = getattr(sub, 'submitted_at', None)
        if sub_ts and (latest_pass_ts is None or sub_ts > latest_pass_ts):
            latest_pass_ts = sub_ts

    # Feedback is "already submitted" only if a row exists that was created
    # on or after the latest passing attempt. Stale rows from a previous
    # attempt don't count.
    fb_query = CourseFeedback.query.filter(
        CourseFeedback.student_id == student.id,
        db.or_(
            CourseFeedback.course_id == course.id,
            func.lower(CourseFeedback.course_key) == course_key.lower(),
        ) if course_key else (CourseFeedback.course_id == course.id),
    )
    if latest_pass_ts is not None:
        fb_query = fb_query.filter(CourseFeedback.created_at >= latest_pass_ts)
    already_submitted = fb_query.first() is not None

    return render_template(
        "course_feedback.html",
        course=course,
        course_key=course_key,
        student=student,
        attempt_id=attempt_id,
        already_submitted=already_submitted,
    )


