@app.route('/admin/course_feedback/export')
def admin_course_feedback_export():
    if 'admin_id' not in session:
        flash("⚠ Unauthorized Access! Please log in.", "danger")
        return redirect(url_for('admin_login'))

    # Load assessment titles from config for course_key lookups
    assessment_titles = {}
    try:
        with open("config/assessments.json", "r") as f:
            assessments = json.load(f)
            for item in assessments:
                assessment_titles[item.get("key")] = item.get("title", item.get("key"))
    except Exception:
        pass

    # Use outerjoin to include feedback for both regular courses AND final assessments
    q = (db.session.query(
        CourseFeedback,
        Course.title.label('course_title'),
        Student
    )
        .outerjoin(Course, Course.id == CourseFeedback.course_id)
        .join(Student, Student.id == CourseFeedback.student_id)
        .order_by(CourseFeedback.created_at.desc())
    )

    rows = q.all()

    import csv
    import io
    from flask import make_response

    # Use BytesIO with UTF-8 BOM for proper Excel compatibility
    output = io.BytesIO()
    # Write UTF-8 BOM (Byte Order Mark) so Excel recognizes the encoding
    output.write(b'\xef\xbb\xbf')

    # Create a text wrapper for csv.writer
    text_output = io.StringIO()
    writer = csv.writer(text_output)
    writer.writerow(["Created", "Course", "Student", "Student Code",
                     "Navigate", "Understand", "Apply", "Value",
                     "Comments", "Confirmed Own", "IP", "User Agent"])

    _rating_labels = {"1": "Poor", "2": "Average", "3": "Excellent"}

    def _fmt_rating(val):
        return _rating_labels.get(str(val), val or "")

    for (fb, course_title, student) in rows:
        # Determine display title - use course_title if available, else look up course_key
        if course_title:
            display_title = course_title
        elif fb.course_key:
            display_title = assessment_titles.get(fb.course_key, fb.course_key)
        else:
            display_title = "Unknown"

        writer.writerow([
            fb.created_at.strftime("%Y-%m-%d %H:%M") if fb.created_at else "",
            display_title,
            getattr(student, 'full_name',
                    '') or f"{getattr(student, 'first_name', '')} {getattr(student, 'last_name', '')}".strip(),
            getattr(student, 'student_id', '') or "",
            _fmt_rating(fb.q_navigate), _fmt_rating(fb.q_understand),
            _fmt_rating(fb.q_apply), _fmt_rating(fb.q_value),
            (fb.comments or "").replace("\n", " ").strip(),
            "Yes" if fb.confirm_own else "No",
            fb.ip_address or "",
            fb.user_agent or ""
        ])

    # Encode the CSV content and append to output with BOM
    output.write(text_output.getvalue().encode('utf-8'))
    output.seek(0)

    resp = make_response(output.getvalue())
    resp.headers["Content-Disposition"] = "attachment; filename=course_feedback.csv"
    resp.headers["Content-Type"] = "text/csv; charset=utf-8-sig"
    return resp

