@app.route("/onboarding/selfie", methods=["GET", "POST"])
def onboarding_selfie():
    """Onboarding step: Capture selfie photo (before ID upload)."""
    if 'student_id' not in session:
        flash("Please log in first.", "warning")
        return redirect(url_for('login'))

    student_id = session['student_id']
    student_folder = os.path.join(app.config['UPLOAD_FOLDER'], student_id)
    selfie_path = os.path.join(student_folder, f"{student_id}_selfie.jpg")

    # If selfie already exists, skip to next step
    if os.path.exists(selfie_path):
        if not _find_id_file(student_id):
            return redirect(url_for('onboarding_id_upload'))
        return redirect(url_for('dashboard', tab='courses'))

    if request.method == "POST":
        selfie_data = request.form.get('selfie') or ""
        if not selfie_data:
            flash("Please capture a selfie before continuing.", "warning")
            return render_template("onboarding_selfie.html")

        try:
            os.makedirs(student_folder, exist_ok=True)
            selfie_binary = base64.b64decode(selfie_data.split(',')[1])
            with open(selfie_path, "wb") as f:
                f.write(selfie_binary)

            # Update student record
            student = Student.query.filter_by(student_id=student_id).first()
            if student:
                student.selfie_filename = f"{student_id}_selfie.jpg"
                db.session.commit()

            flash("Selfie captured successfully!", "success")
            return redirect(url_for('onboarding_id_upload'))
        except Exception as e:
            print(f"Error saving onboarding selfie: {e}")
            flash("Error saving selfie. Please try again.", "danger")
            return render_template("onboarding_selfie.html")

    return render_template("onboarding_selfie.html")


@app.route("/onboarding/upload-id", methods=["GET", "POST"])
def onboarding_id_upload():
    """Onboarding step: Upload ID document after POPIA consent."""
    if 'student_id' not in session:
        flash("⚠ Please log in first.", "warning")
        return redirect(url_for('login'))

    student_id = session['student_id']

    # Check if ID already uploaded - if so, skip to dashboard
    student_folder = os.path.join(app.config['UPLOAD_FOLDER'], student_id)
    if _find_id_file(student_id):
        return redirect(url_for('dashboard', tab='courses'))

    if request.method == "POST":
        file = request.files.get('id_file')

        if file and file.filename != '':
            ext = 'pdf' if (file.content_type == 'application/pdf' or file.filename.lower().endswith('.pdf')) else 'jpg'
            filename = f"{student_id}_id.{ext}"
            os.makedirs(student_folder, exist_ok=True)
            # Remove old ID file with other extension
            other_ext = 'jpg' if ext == 'pdf' else 'pdf'
            old_file = os.path.join(student_folder, f"{student_id}_id.{other_ext}")
            if os.path.exists(old_file):
                os.remove(old_file)
            file.save(os.path.join(student_folder, filename))
            flash('✅ ID document uploaded successfully. Welcome to your dashboard!', 'success')
            # Redirect to dashboard with courses tab active
            return redirect(url_for('dashboard', tab='courses'))
        else:
            flash('⚠️ Please select a file to upload.', 'warning')

    return render_template("onboarding_id_upload.html")


@app.route("/update_selfie", methods=["POST"])
@require_popia
def update_selfie():
    """Update or replace the student's selfie photo from the dashboard."""
    student_id = session['student_id']
    student_folder = os.path.join(app.config['UPLOAD_FOLDER'], student_id)
    os.makedirs(student_folder, exist_ok=True)
    selfie_path = os.path.join(student_folder, f"{student_id}_selfie.jpg")

    method = request.form.get('method', '')

    if method == 'camera':
        selfie_data = request.form.get('selfie') or ""
        if not selfie_data or ',' not in selfie_data:
            flash("No selfie captured. Please try again.", "warning")
            return redirect(url_for('dashboard', tab='profile'))
        try:
            selfie_binary = base64.b64decode(selfie_data.split(',')[1])
            with open(selfie_path, "wb") as f:
                f.write(selfie_binary)
        except Exception as e:
            print(f"Error saving camera selfie: {e}")
            flash("Error saving selfie. Please try again.", "danger")
            return redirect(url_for('dashboard', tab='profile'))

    elif method == 'upload':
        file = request.files.get('selfie_file')
        if not file or file.filename == '':
            flash("Please select a file to upload.", "warning")
            return redirect(url_for('dashboard', tab='profile'))
        if not file.content_type.startswith('image/'):
            flash("Please upload an image file.", "warning")
            return redirect(url_for('dashboard', tab='profile'))
        try:
            file.save(selfie_path)
        except Exception as e:
            print(f"Error saving uploaded selfie: {e}")
            flash("Error saving selfie. Please try again.", "danger")
            return redirect(url_for('dashboard', tab='profile'))
    else:
        flash("Invalid request.", "warning")
        return redirect(url_for('dashboard', tab='profile'))

    # Update student record
    student = Student.query.filter_by(student_id=student_id).first()
    if student:
        student.selfie_filename = f"{student_id}_selfie.jpg"
        db.session.commit()

    flash("Profile photo updated successfully!", "success")
    return redirect(url_for('dashboard', tab='profile'))


