ANNOUNCEMENT_UPLOAD_DIR = os.path.join(app.root_path, "static", "uploads", "announcements")
os.makedirs(ANNOUNCEMENT_UPLOAD_DIR, exist_ok=True)
_ANNOUNCEMENT_IMG_EXTS = {'jpg', 'jpeg', 'png', 'webp', 'gif'}


@app.route('/announce', methods=['GET', 'POST'])
def announce():
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    if request.method == 'POST':
        title = (request.form.get('title') or '').strip()
        content = (request.form.get('content') or '').strip()
        if not title or not content:
            flash("Title and message are required.", "warning")
            return redirect(url_for('announce'))

        ann = Announcement(title=title, content=content, is_active=True)
        db.session.add(ann)
        db.session.flush()  # need ann.id for the image filename

        # Optional banner image. JPG/PNG/WebP/GIF only, saved into
        # static/uploads/announcements/ann_<id>.<ext>.
        img = request.files.get('image_file')
        if img and img.filename:
            ext = img.filename.rsplit('.', 1)[-1].lower()
            if ext not in _ANNOUNCEMENT_IMG_EXTS:
                flash("Image must be JPG, PNG, WebP, or GIF.", "warning")
            else:
                safe_name = f"ann_{ann.id}.{ext}"
                target = os.path.join(ANNOUNCEMENT_UPLOAD_DIR, safe_name)
                try:
                    img.save(target)
                    ann.image_filename = safe_name
                except Exception as e:
                    flash(f"⚠ Could not save image: {e}", "warning")

        db.session.commit()
        flash('Announcement posted successfully!', 'success')
        return redirect(url_for('announce'))

    # GET: render form + list of existing announcements (most recent first).
    announcements = Announcement.query.order_by(Announcement.date_posted.desc()).all()
    return render_template('announce.html', announcements=announcements)


@app.route('/announce/<int:ann_id>/toggle', methods=['POST'])
def announce_toggle(ann_id):
    """Flip is_active on an existing announcement so admins can hide one without
    deleting it."""
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        return redirect(url_for('admin_login'))
    ann = db.session.get(Announcement, ann_id)
    if ann:
        ann.is_active = not bool(ann.is_active)
        db.session.commit()
        flash(f"Announcement '{ann.title}' is now {'visible' if ann.is_active else 'hidden'}.", "success")
    return redirect(url_for('announce'))


@app.route('/announce/<int:ann_id>/delete', methods=['POST'])
def announce_delete(ann_id):
    """Hard-delete an announcement plus its banner image, if any."""
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        return redirect(url_for('admin_login'))
    ann = db.session.get(Announcement, ann_id)
    if ann:
        if ann.image_filename:
            try:
                os.remove(os.path.join(ANNOUNCEMENT_UPLOAD_DIR, ann.image_filename))
            except OSError:
                pass
        db.session.delete(ann)
        db.session.commit()
        flash("Announcement deleted.", "success")
    return redirect(url_for('announce'))

