@app.route("/add_chapter_content", methods=["POST"])
def add_chapter_content():
    course_id = request.form["course_id"]
    chapter_id = request.form["chapter_id"]
    content_type = request.form["content_type"]

    if content_type == "pdf" or content_type == "video":
        content_url = request.files["file"]
        filename = secure_filename(content_url.filename)
        content_url.save(os.path.join("uploads", filename))
    elif content_type == "quiz":
        content_url = request.form["quiz_id"]

    # Save to database
    query = """
        INSERT INTO chapter_content (course_id, chapter_id, content_type, content_url) 
        VALUES (?, ?, ?, ?)
        """
    db.session.execute(
        query, (course_id, chapter_id, content_type, content_url))
    db.commit()

    return redirect(url_for("manage_courses"))

