def send_otp(email, otp):
    subject = "Your OTP for Registration"
    body = f"Your one-time PIN (OTP) for registration is: {otp}"
    msg = EmailMessage()
    msg["Subject"] = subject
    msg["To"] = [email]
    msg["From"] = 'no-reply@professionaltraining.co.za'
    msg.set_content(body)
    try:
        with smtplib.SMTP('smtp.professionaltraining.co.za', 587, timeout=10) as smtp:
            smtp.starttls()
            smtp.login('no-reply@professionaltraining.co.za', os.environ.get("MAIL_PASSWORD", "dev-disabled"))
            smtp.send_message(msg)
        print(f"✅ OTP sent to {email} | Debug OTP: {otp}")
        return True
    except Exception as e:
        print(f"❌ Error sending OTP: {e}")
        return False
