# --- Validators (keep near your imports) ---
NAME_RE = re.compile(r"^[A-Za-zÀ-ÿ' -]{2,60}$")
NID_RE = re.compile(r"^[A-Za-z0-9]{6,20}$")
EMAIL_RE = re.compile(r"^[^@]+@[^@]+\.[^@]+$")
PHONE_RE = re.compile(r"^\+?[0-9]{7,15}$")


def is_strong_password(pw: str) -> bool:
    return (
        len(pw) >= 8 and
        re.search(r"[A-Z]", pw) and
        re.search(r"[a-z]", pw) and
        re.search(r"[0-9]", pw) and
        re.search(r"[^\w\s]", pw)
    )


@app.route('/signup', methods=['GET', 'POST'])
def signup():
    if request.method == 'GET':
        # empty form
        return render_template('signup.html')

    # POST: collect + sanitize
    student_id = str(random.randint(10000000, 99999999))
    name = (request.form.get('name') or "").strip()
    surname = (request.form.get('surname') or "").strip()
    company_text = (request.form.get('company') or "").strip()
    national_id = (request.form.get('national_id') or "").strip()
    email = (request.form.get('email') or "").strip().lower()
    cell_number = (request.form.get('cell_number') or "").strip()
    password = request.form.get('password') or ""
    confirm_password = request.form.get('confirm_password') or ""
    selfie_data = request.form.get('selfie') or ""

    # per-field errors
    errors = {}

    # --- Validation (same requirements you asked for) ---
    if not NAME_RE.match(name):
        errors['name'] = "First name is invalid."
    if not NAME_RE.match(surname):
        errors['surname'] = "Surname is invalid."
    if not NID_RE.match(national_id):
        errors['national_id'] = "National ID must be 6–20 characters (letters and digits)."
    if not EMAIL_RE.match(email):
        errors['email'] = "Invalid email address."
    if not PHONE_RE.match(cell_number):
        errors['cell_number'] = "Invalid cell number (7-15 digits, optional +)."
    if password != confirm_password:
        errors['confirm_password'] = "Passwords do not match."
    if not is_strong_password(password):
        errors['password'] = "At least 8 chars, with uppercase, lowercase, digit & special char."
    if not selfie_data:
        errors['selfie'] = "Selfie is required."

    existing_user = Student.query.filter(
        (Student.email == email) | (Student.national_id == national_id)
    ).first()
    if existing_user:
        errors['email'] = "Email or ID Number already registered. Please log in."

    if errors:
        # Re-render the same form with values and field errors
        flash("Please correct the highlighted fields.", "danger")
        return render_template(
            'signup.html',
            errors=errors,
            name=name,
            surname=surname,
            company=company_text,
            national_id=national_id,
            email=email,
            cell_number=cell_number
        )

    # --- Folder setup + selfie save (unchanged behavior) ---
    student_folder = os.path.join(app.config['UPLOAD_FOLDER'], student_id)
    os.makedirs(student_folder, exist_ok=True)

    selfie_filename = None
    if selfie_data:
        selfie_filename = f"{student_id}_selfie.jpg"
        selfie_path = os.path.join(student_folder, selfie_filename)
        try:
            selfie_binary = base64.b64decode(selfie_data.split(',')[1])
            with open(selfie_path, "wb") as f:
                f.write(selfie_binary)
            print(f"📸 Selfie saved: {selfie_path}")
        except Exception as e:
            print(f"❌ Error saving selfie: {e}")
            flash("Error saving selfie. Please try again.", "danger")
            return render_template(
                'signup.html',
                name=name, surname=surname, company=company_text,
                national_id=national_id, email=email, cell_number=cell_number
            )

    # --- Save student ---
    hashed_password = generate_password_hash(password, method='pbkdf2:sha256')
    otp = str(random.randint(10000000, 99999999))

    new_student = Student(
        student_id=student_id,
        name=name,
        surname=surname,
        company=company_text or None,
        national_id=national_id,
        email=email,
        cell_number=cell_number,
        password=hashed_password,
        selfie_filename=selfie_filename,
        otp=otp
    )
    db.session.add(new_student)
    db.session.commit()

    # Skip OTP for local development or specific emails
    skip_otp_emails = ['jean@professional.za.com', 'jean@professional.co.za']
    if email.lower() in [e.lower() for e in skip_otp_emails]:
        new_student.otp = None
        db.session.commit()
        session['student_id'] = new_student.student_id
        flash('Registration successful! You have been automatically logged in.', 'success')
        return redirect(url_for('dashboard'))

    send_otp(email, otp)
    session['pending_user'] = email
    flash('OTP sent! Please verify your email.', 'info')
    return redirect(url_for('verify_otp'))

