# Student Dashboard


def cover_url_for(course):
    """Return a usable URL for a course cover image or a fallback."""
    img = getattr(course, "cover_image", None)
    if not img:
        return url_for("static", filename="images/coursepreview.jpg")
    # absolute URL already?
    if img.startswith("http://") or img.startswith("https://"):
        return img
    # if it's already a /static/... path, use as-is
    if img.startswith("/static/"):
        return img
    # otherwise treat it as a file in static/uploads
    return url_for("static", filename=f"uploads/{img}")


