@app.route('/dashboard')
@require_popia
def dashboard():
    if 'student_id' not in session:
        flash('Please log in first.', 'danger')
        return redirect(url_for('login'))

    user = Student.query.filter_by(student_id=session['student_id']).first()
    if not user:
        flash('User not found!', 'danger')
        return redirect(url_for('login'))

    # Check if student has been suspended
    if user.is_suspended:
        session.clear()
        flash('🚫 Your account has been suspended. Please contact your administrator for assistance.', 'danger')
        return redirect(url_for('frontpage'))

    selfie_path = (
        url_for('uploaded_file', student_id=user.student_id,
                filename=user.selfie_filename)
        if user.selfie_filename else url_for('static', filename='default_profile.jpg')
    )

    # Check if ID document exists and build its URL
    _id_filename = _find_id_file(user.student_id)
    id_doc_path = (
        url_for('uploaded_file', student_id=user.student_id, filename=_id_filename)
        if _id_filename else None
    )

    # Helper: build a display URL for a course cover image (handles absolute and relative)
    def cover_url_for(course: "Course") -> str:
        img = getattr(course, "cover_image", None)
        if not img:
            # fallback
            return url_for('static', filename='images/coursepreview.jpg')
        # if it's already an absolute URL, use it
        if img.startswith('http://') or img.startswith('https://'):
            return img
        # if it already points into /static, leave it as-is
        if img.startswith('/static/'):
            return img
        # otherwise assume we stored just a filename under static/uploads/courses/
        return url_for('static', filename=f'uploads/courses/{img}')

    # Courses this student is approved for
    approved_courses = (
        db.session.query(Course)
        .join(CourseEnrollment)
        .filter(
            CourseEnrollment.student_id == user.id,
            CourseEnrollment.approved == True
        )
        .all()
    )

    student_progress = []
    for course in approved_courses:
        try:
            chapters = (
                CourseChapter.query
                .filter_by(course_id=course.id, parent_id=None)
                .order_by(CourseChapter.position)
                .all()
            )
            total_chapters = len(chapters)

            completed_chapters = {
                cp.chapter_id
                for cp in CourseProgress.query.filter_by(
                    student_id=user.id, course_id=course.id, completed=True
                ).all()
            }

            enrollment = CourseEnrollment.query.filter_by(
                student_id=user.id, course_id=course.id
            ).first()

            is_completed = enrollment.completed if enrollment else False

            progress = (
                round((len(completed_chapters) / total_chapters) * 100, 1)
                if total_chapters > 0 else 0
            )
            progress = min(progress, 100)

            # Get the latest/best submission for this course
            # Check BOTH FinalAssessmentSubmission (course_id based) AND FinalAssessmentAttempt (course_key based)
            submission = FinalAssessmentSubmission.query.filter_by(
                student_id=user.id, course_id=course.id, is_active=True
            ).order_by(FinalAssessmentSubmission.submitted_at.desc()).first()

            # Also check FinalAssessmentAttempt for standalone finals (RPAS, ASAT, etc.)
            # These use course_key instead of course_id
            final_attempt = None
            final_key = getattr(course, 'final_assessment_key', None) or getattr(course, 'key', None) or getattr(course, 'slug', None)

            # Build list of potential keys to try
            potential_keys = []
            if final_key:
                potential_keys.append(final_key)

            # If no explicit key, try to derive from course title
            if course.title:
                title_lower = course.title.lower().strip()
                first_word = title_lower.split()[0] if title_lower else ""
                # Add potential keys based on common patterns
                if first_word:
                    potential_keys.extend([
                        first_word + "_awareness",  # e.g., rpas_awareness
                        first_word + "_final",  # e.g., rpas_final
                        first_word,  # Just the acronym
                    ])
                # Also try full title as slug
                potential_keys.append(title_lower.replace(" ", "_").replace("-", "_"))

            # Try each potential key until we find a match
            # We need to check multiple tables: FinalAssessmentAttempt AND AssessmentAttempt
            assessment_attempt = None  # For AssessmentAttempt table (where RPAS etc. are stored)

            # register_assessment() normalizes keys to lowercase, so try both cases
            potential_keys_with_lower = []
            for pk in potential_keys:
                if pk and pk not in potential_keys_with_lower:
                    potential_keys_with_lower.append(pk)
                if pk and pk.lower() != pk and pk.lower() not in potential_keys_with_lower:
                    potential_keys_with_lower.append(pk.lower())

            for key in potential_keys_with_lower:
                if not key:
                    continue
                # Try with student_id (FK to student.id)
                final_attempt = FinalAssessmentAttempt.query.filter_by(
                    student_id=user.id,
                    course_key=key,
                    is_active=True
                ).order_by(FinalAssessmentAttempt.submitted_at.desc()).first()

                if final_attempt:
                    break

                # Also try with student_number
                final_attempt = FinalAssessmentAttempt.query.filter_by(
                    student_number=user.student_id,
                    course_key=key,
                    is_active=True
                ).order_by(FinalAssessmentAttempt.submitted_at.desc()).first()

                if final_attempt:
                    break

                # ALSO check AssessmentAttempt table (where RPAS and dynamic assessments are stored)
                # This table uses student_id as string (student_number/national ID)
                assessment_attempt = AssessmentAttempt.query.filter_by(
                    student_id=str(user.student_id),
                    course_key=key,
                    is_active=True
                ).order_by(AssessmentAttempt.created_at.desc()).first()

                if assessment_attempt:
                    break

            # Check if student passed the final (80%+) and calculate certification expiry
            passed_final = False
            final_passed_date = None
            cert_expiry_date = None
            cert_time_remaining = None
            can_retake_final = False

            # Check FinalAssessmentSubmission first
            if submission and submission.percentage is not None:
                if submission.percentage >= 80:
                    passed_final = True
                    final_passed_date = submission.submitted_at

            # Also check FinalAssessmentAttempt (for standalone finals)
            if not passed_final and final_attempt:
                # FinalAssessmentAttempt has 'percentage' (int) and 'passed' (bool) fields
                # IMPORTANT: Always use percentage >= 80 check, don't rely on 'passed' boolean
                # (the 'passed' field may have been set with wrong threshold in older code)
                attempt_score = final_attempt.percentage if hasattr(final_attempt, 'percentage') else None
                if attempt_score is not None and attempt_score >= 80:
                    passed_final = True
                    final_passed_date = final_attempt.submitted_at

            # Also check AssessmentAttempt table (where RPAS and dynamic assessments store results)
            if not passed_final and assessment_attempt:
                # AssessmentAttempt has 'score' (float) and 'passed' (bool) fields
                # IMPORTANT: Always use score >= 80 check, don't rely on 'passed' boolean
                attempt_score = assessment_attempt.score if hasattr(assessment_attempt, 'score') else None
                if attempt_score is not None and attempt_score >= 80:
                    passed_final = True
                    final_passed_date = assessment_attempt.created_at

            # Calculate certification expiry if passed
            if passed_final and final_passed_date:
                # Certification valid for 2 years (730 days)
                cert_expiry_date = final_passed_date + timedelta(days=730)
                now = _now_sast()
                if now < cert_expiry_date:
                    # Calculate time remaining
                    delta = cert_expiry_date - now
                    years = delta.days // 365
                    months = (delta.days % 365) // 30
                    days = delta.days % 30
                    if years > 0:
                        cert_time_remaining = f"{years}y {months}m"
                    elif months > 0:
                        cert_time_remaining = f"{months}m {days}d"
                    else:
                        cert_time_remaining = f"{days} days"
                else:
                    # Certification expired - can retake
                    can_retake_final = True
                    cert_time_remaining = "Expired - retake available"

            # Build nested chapter list
            chapter_list = []
            for chapter in chapters:
                subchapters = (
                    CourseChapter.query
                    .filter_by(parent_id=chapter.id)
                    .order_by(CourseChapter.position)
                    .all()
                )
                chapter_list.append({
                    'id': chapter.id,
                    'title': chapter.title,
                    'completed': chapter.id in completed_chapters,
                    'subchapters': [
                        {'id': sc.id, 'title': sc.title,
                            'completed': sc.id in completed_chapters}
                        for sc in subchapters
                    ],
                })

            # Find next chapter if not completed
            next_chapter = None
            if not is_completed:
                next_chapter = next(
                    (c for c in chapters if c.id not in completed_chapters), None)

            # >>> Add image_url here <<<
            # has_submitted_final is True if ANY of the assessment tables have a submission
            has_submitted = submission is not None or final_attempt is not None or assessment_attempt is not None

            # Calculate final_attempts_left based on score (75-79% gets 1 retry, <75% or >=80% gets 0)
            final_attempts_left = 0
            final_latest_score = None
            attempts_count = 0  # Initialize for debug logging

            # Get the allowed attempts cap for this student/course (may be increased if admin approved 3rd attempt)
            allowed_cap = _allowed_cap(user.id, course.id)

            # Safety net: If allowed_cap is still 2 but there's an approved RetryRequest, grant 3rd attempt
            if allowed_cap == 2:
                approved_request = RetryRequest.query.filter_by(
                    student_id=user.id,
                    course_id=course.id,
                    status='approved'
                ).first()
                if approved_request:
                    allowed_cap = 3  # Grant the approved 3rd attempt

            # Count attempts and get latest score from all potential tables
            if assessment_attempt:
                # AssessmentAttempt table - count all attempts for this student/course_key
                used_key = assessment_attempt.course_key
                attempts_count = AssessmentAttempt.query.filter_by(
                    student_id=str(user.student_id),
                    course_key=used_key,
                    is_active=True
                ).count()
                final_latest_score = assessment_attempt.score
                final_attempts_left = _calculate_attempts_left(final_latest_score, attempts_count, allowed_cap)
            elif final_attempt:
                # FinalAssessmentAttempt table
                used_key = final_attempt.course_key
                attempts_count = FinalAssessmentAttempt.query.filter(
                    ((FinalAssessmentAttempt.student_id == user.id) |
                     (FinalAssessmentAttempt.student_number == user.student_id)),
                    FinalAssessmentAttempt.course_key == used_key,
                    FinalAssessmentAttempt.is_active.is_(True)
                ).count()
                final_latest_score = final_attempt.percentage
                final_attempts_left = _calculate_attempts_left(final_latest_score, attempts_count, allowed_cap)
            elif submission:
                # FinalAssessmentSubmission table
                attempts_count = FinalAssessmentSubmission.query.filter_by(
                    student_id=user.id,
                    course_id=course.id,
                    is_active=True
                ).count()
                final_latest_score = submission.percentage
                final_attempts_left = _calculate_attempts_left(final_latest_score, attempts_count, allowed_cap)

            # Check retry request eligibility (75-79.99% on 2nd attempt, no more auto-retries)
            can_request_retry = False
            has_pending_retry_request = False
            retry_request_status = None

            # DEBUG: Log retry eligibility calculation
            print(f"🔄 RETRY DEBUG → {course.title}: score={final_latest_score}, attempts_count={attempts_count}, allowed_cap={allowed_cap}, final_attempts_left={final_attempts_left}")

            if final_latest_score is not None and 75 <= final_latest_score < 80:
                print(f"🔄 RETRY DEBUG → Score in range 75-80, checking if final_attempts_left == 0: {final_attempts_left == 0}")
                # Check if they've used their 2 default attempts (no more auto-retries left)
                if final_attempts_left == 0:
                    # Check for existing retry request
                    existing_request = RetryRequest.query.filter_by(
                        student_id=user.id,
                        course_id=course.id
                    ).order_by(RetryRequest.created_at.desc()).first()

                    print(f"🔄 RETRY DEBUG → existing_request={existing_request}, status={existing_request.status if existing_request else 'N/A'}")
                    if existing_request:
                        retry_request_status = existing_request.status
                        has_pending_retry_request = (existing_request.status == 'pending')
                        print(f"🔄 RETRY DEBUG → retry_request_status={retry_request_status}, has_pending={has_pending_retry_request}")
                    else:
                        can_request_retry = True  # Eligible, no existing request
                        print(f"🔄 RETRY DEBUG → Setting can_request_retry=True")

            # Check if feedback is required (passed but no feedback submitted
            # AFTER the most recent passing attempt). A feedback row from
            # before the latest pass doesn't count — every fresh pass needs
            # its own feedback before the certificate can drop.
            feedback_required = False
            feedback_course_key = None
            if passed_final and not can_retake_final:
                # Determine which course_key was used for the passing attempt
                if assessment_attempt:
                    feedback_course_key = assessment_attempt.course_key
                elif final_attempt:
                    feedback_course_key = final_attempt.course_key
                else:
                    feedback_course_key = getattr(course, 'final_assessment_key', None) or getattr(course, 'code', None)

                # Find the timestamp of the most recent passing attempt across
                # all three persistence layers, so we can compare feedback age.
                latest_pass_ts = None
                if assessment_attempt and (assessment_attempt.score or 0) >= 80:
                    latest_pass_ts = getattr(assessment_attempt, 'finished_at', None) or getattr(assessment_attempt, 'created_at', None)
                if final_attempt and bool(getattr(final_attempt, 'passed', False)):
                    fa_ts = getattr(final_attempt, 'submitted_at', None)
                    if fa_ts and (latest_pass_ts is None or fa_ts > latest_pass_ts):
                        latest_pass_ts = fa_ts
                if submission and (submission.percentage or 0) >= 80:
                    sub_ts = getattr(submission, 'submitted_at', None)
                    if sub_ts and (latest_pass_ts is None or sub_ts > latest_pass_ts):
                        latest_pass_ts = sub_ts

                # Look for a feedback row that came in on or after the pass.
                # course_key is compared case-insensitively: register_assessment
                # lowercases the attempt key ('dgge') while the feedback row may
                # have been stored in the course's original case ('DGGE'). Without
                # the lower() the row never matches and the gate nags forever.
                fb_query = CourseFeedback.query.filter(
                    CourseFeedback.student_id == user.id,
                    db.or_(
                        CourseFeedback.course_id == course.id,
                        func.lower(CourseFeedback.course_key) == feedback_course_key.lower(),
                    ) if feedback_course_key else (CourseFeedback.course_id == course.id),
                )
                if latest_pass_ts is not None:
                    fb_query = fb_query.filter(CourseFeedback.created_at >= latest_pass_ts)
                has_feedback = fb_query.first() is not None
                feedback_required = not has_feedback

            # CAA minimum wait (v1.2). Surfaced on the dashboard so a student can
            # see when their final unlocks, instead of only finding out by
            # clicking and being bounced back.
            _fw_secs, _fw_unlock = _final_wait_remaining(user.id, course.id)

            student_progress.append({
                'course_id': course.id,
                'course_title': course.title,
                'progress': progress,
                'is_completed': is_completed,
                'chapters': chapter_list,
                'next_chapter': next_chapter,
                'has_submitted_final': has_submitted,
                'submission_id': submission.id if submission else (final_attempt.id if final_attempt else (assessment_attempt.id if assessment_attempt else None)),
                'image_url': cover_url_for(course),
                # New fields for certification tracking
                'passed_final': passed_final,
                'final_passed_date': final_passed_date,
                'cert_expiry_date': cert_expiry_date,
                'cert_time_remaining': cert_time_remaining,
                'can_retake_final': can_retake_final,
                # Attempts tracking for reattempt button
                'final_attempts_left': final_attempts_left,
                # CAA minimum wait: 0 seconds means eligible now.
                'final_wait_seconds': _fw_secs,
                'final_wait_human': _humanise_wait(_fw_secs) if _fw_secs else None,
                'final_unlock_at': _fw_unlock,
                # Retry request tracking (for 3rd attempt requests)
                'can_request_retry': can_request_retry,
                'has_pending_retry_request': has_pending_retry_request,
                'retry_request_status': retry_request_status,
                'latest_score': final_latest_score,
                # Feedback gating for certificate
                'feedback_required': feedback_required,
                'feedback_course_key': feedback_course_key,
                # Certificate PDF download.
                # Also filter by passed_at >= enrollment.enrolled_at so orphan rows
                # left behind when an old course was deleted and its course_id was
                # later reused by SQLite for a new course can't match. A stale orphan
                # always predates the current enrollment, so it drops out here.
                'cert_pdf_url': (lambda cq: url_for('download_certificate_pdf', entry_id=cq.id) if cq and cq.certificate_pdf else None)(
                    CertificateQueue.query.filter(
                        CertificateQueue.student_id == user.id,
                        CertificateQueue.course_id == course.id,
                        CertificateQueue.status == 'done',
                        CertificateQueue.passed_at >= (enrollment.enrolled_at if enrollment and enrollment.enrolled_at else datetime.min),
                    ).order_by(CertificateQueue.passed_at.desc()).first()
                ),
            })

            print(
                f"🧪 DASH CHECK → {course.title}: progress={progress}, final_submitted={has_submitted}, passed_final={passed_final}, can_retake={can_retake_final}, completed={is_completed}"
                f" | Keys tried: {potential_keys[:3]}, AssessmentAttempt found: {assessment_attempt is not None}")
        except Exception as e:
            print(f"❌ Error fetching progress for {course.title}: {e}")

    latest_announcement = (Announcement.query
                           .filter(Announcement.is_active.is_(True))
                           .order_by(Announcement.date_posted.desc())
                           .first())

    is_company_student = user.created_by_company_id is not None
    if is_company_student:
        all_courses = []
    else:
        # Hide virtual courses from the Courses tab — students cannot self-enroll
        # into virtual courses; admins do that via the dedicated virtual enrollment page.
        all_courses = Course.query.filter(
            (Course.course_type == 'normal') | (Course.course_type.is_(None))
        ).all()
    enrolled_courses = {
        enrollment.course_id
        for enrollment in CourseEnrollment.query.filter_by(student_id=user.id).all()
    }

    ticket_id = '{:010d}'.format(random.randint(1000000000, 9999999999))

    # Get student's support tickets
    open_tickets = SupportTicket.query.filter_by(student_id=user.id).filter(
        SupportTicket.status.in_(['Open', 'In Progress'])
    ).order_by(SupportTicket.created_at.desc()).all()

    closed_tickets = SupportTicket.query.filter_by(student_id=user.id).filter(
        SupportTicket.status == 'Closed'
    ).order_by(SupportTicket.created_at.desc()).limit(5).all()

    # Appeals/disputes for the dashboard's embedded Support widget
    appeals = AppealDispute.query.filter_by(student_id=user.id).order_by(
        AppealDispute.created_at.desc()).all()

    # Virtual Training Portal (v1.1.0): walk every student_progress entry, tag whether
    # it's a virtual course, and attach per-enrollment Teams metadata + lock state.
    # The template then filters the list into normal (Learn tab) vs virtual (Virtual tab)
    # so the SAME rich card logic (passed, renewable, retry, feedback-required, etc.)
    # applies to both.
    course_by_id = {c.id: c for c in approved_courses}
    enrollment_by_course = {
        en.course_id: en
        for en in CourseEnrollment.query.filter_by(student_id=user.id).all()
    }
    for entry in student_progress:
        course_obj = course_by_id.get(entry['course_id'])
        enrollment_obj = enrollment_by_course.get(entry['course_id'])
        is_virtual = bool(
            course_obj and getattr(course_obj, 'course_type', 'normal') == 'virtual'
        )
        entry['is_virtual'] = is_virtual

        if is_virtual:
            entry['teams_link'] = getattr(enrollment_obj, 'teams_meeting_link', None) if enrollment_obj else None
            entry['virtual_session_date'] = getattr(enrollment_obj, 'virtual_session_date', None) if enrollment_obj else None
            # Either the course-level switch OR the per-enrollment override unlocks.
            course_unlock = bool(getattr(course_obj, 'virtual_unlocked', False))
            enrollment_unlock = bool(getattr(enrollment_obj, 'assessment_unlocked', False)) if enrollment_obj else False
            admin_assessment_unlocked = course_unlock or enrollment_unlock
            entry['admin_assessment_unlocked'] = admin_assessment_unlocked

            # Pre-final quiz gating (v1.1.0 Phase 3e). For each quiz under the
            # course, decide its state from this student's perspective:
            #   passed    — has at least one VirtualQuizAttempt with passed=True
            #   available — quiz.unlocked is True and not yet passed
            #   locked    — quiz.unlocked is False and not yet passed
            # The final assessment requires both the admin gate AND every
            # required quiz to be in the 'passed' state.
            quizzes = (
                VirtualQuiz.query
                .filter_by(course_id=course_obj.id)
                .order_by(VirtualQuiz.position.asc(), VirtualQuiz.id.asc())
                .all()
            )
            quizzes_info = []
            all_required_passed = True
            for vq in quizzes:
                has_pass = (
                    VirtualQuizAttempt.query
                    .filter_by(quiz_id=vq.id, student_id=user.id, passed=True)
                    .first()
                    is not None
                )
                if has_pass:
                    state = 'passed'
                elif vq.unlocked:
                    state = 'available'
                else:
                    state = 'locked'
                if vq.required and not has_pass:
                    all_required_passed = False
                quizzes_info.append({
                    'quiz': vq,
                    'state': state,
                    'has_pass': has_pass,
                    'take_url': url_for('virtual_quiz_take', quiz_id=vq.id),
                })
            entry['quizzes_info'] = quizzes_info
            entry['required_quizzes_passed'] = all_required_passed
            entry['required_quizzes_pending'] = sum(
                1 for qi in quizzes_info
                if qi['quiz'].required and qi['state'] != 'passed'
            )
            # Final assessment is unlocked when BOTH the admin gate is open
            # AND all required quizzes are passed.
            entry['assessment_unlocked'] = admin_assessment_unlocked and all_required_passed

            # Handbook surface (v1.1.0 Phase 3f). Virtual courses don't render
            # chapter_content.html (no chapters), so the handbook button on the
            # student's card links straight to a standalone PDF.js viewer.
            handbook = Handbook.query.filter_by(course_id=course_obj.id, is_active=True).first()
            entry['handbook_url'] = url_for('virtual_course_handbook', course_id=course_obj.id) if handbook else None
            entry['handbook_title'] = handbook.title if handbook else None

            # Virtual courses have no chapter content, so treat them as "content complete"
            # which makes the existing status logic (FINAL button, passed, retry, etc.) work.
            entry['progress'] = 100
            entry['next_chapter'] = None
            # Send run_final the numeric course id so it short-circuits to Course.query.get().
            entry['final_url'] = url_for('run_final', code=str(course_obj.id))
            entry['has_assessment'] = bool((getattr(course_obj, 'final_assessment_key', None) or '').strip())
        else:
            entry['teams_link'] = None
            entry['virtual_session_date'] = None
            entry['assessment_unlocked'] = True  # normal courses have no lock concept
            entry['final_url'] = url_for('final_assessment', course_id=entry['course_id'])
            entry['has_assessment'] = True

    normal_progress = [e for e in student_progress if not e['is_virtual']]
    virtual_progress = [e for e in student_progress if e['is_virtual']]
    # Sort virtual cards by session date (earliest first, None at the end).
    virtual_progress.sort(key=lambda e: (e['virtual_session_date'] is None, e['virtual_session_date']))

    return render_template(
        'dashboard.html',
        user=user,
        selfie_path=selfie_path,
        id_doc_path=id_doc_path,
        student_progress=student_progress,  # kept for any legacy references
        normal_progress=normal_progress,
        virtual_progress=virtual_progress,
        latest_announcement=latest_announcement,
        courses=all_courses,
        enrolled_courses=enrolled_courses,
        approved_courses=approved_courses,
        is_company_student=is_company_student,
        ticket_id=ticket_id,
        open_tickets=open_tickets,
        closed_tickets=closed_tickets,
        appeals=appeals,
        sacaa_appeal_notice=SACAA_APPEAL_NOTICE,
        has_virtual_enrollments=bool(virtual_progress),
    )


############## *************************###################
# Request Retry (3rd attempt) - Student Route
############## *************************###################

@app.route('/request-retry/<int:course_id>', methods=['GET', 'POST'])
def request_retry(course_id):
    """
    Student requests a 3rd attempt after scoring 75-79.99% on their 2nd attempt.
    """
    if 'student_id' not in session:
        flash("Please log in first.", "warning")
        return redirect(url_for('login'))

    student = Student.query.filter_by(student_id=session['student_id']).first()
    if not student:
        flash("Student not found.", "danger")
        return redirect(url_for('login'))

    course = Course.query.get_or_404(course_id)

    # Verify eligibility: must have 2 attempts and latest score 75-79.99%
    # Check across all submission tables
    latest_score = None
    attempts_count = 0

    # Check FinalAssessmentSubmission
    submissions = FinalAssessmentSubmission.query.filter_by(
        student_id=student.id,
        course_id=course_id,
        is_active=True
    ).order_by(FinalAssessmentSubmission.submitted_at.desc()).all()

    if submissions:
        attempts_count = len(submissions)
        latest_score = submissions[0].percentage

    # Also check FinalAssessmentAttempt
    if not submissions:
        attempts = FinalAssessmentAttempt.query.filter(
            ((FinalAssessmentAttempt.student_id == student.id) |
             (FinalAssessmentAttempt.student_number == student.student_id)),
            FinalAssessmentAttempt.course_id == course_id,
            FinalAssessmentAttempt.is_active.is_(True)
        ).order_by(FinalAssessmentAttempt.submitted_at.desc()).all()

        if attempts:
            attempts_count = len(attempts)
            latest_score = attempts[0].percentage

    # Also check AssessmentAttempt table (where RPAS, ASAT and dynamic assessments store results)
    if latest_score is None:
        # Try to find attempts using course's final_assessment_key or other keys
        # Mirror the dashboard logic for finding keys
        potential_keys = []
        if hasattr(course, 'final_assessment_key') and course.final_assessment_key:
            potential_keys.append(course.final_assessment_key)
        if hasattr(course, 'code') and course.code:
            potential_keys.append(course.code)
        # Add common key patterns based on title
        title_lower = (course.title or "").lower()
        if 'asat' in title_lower or 'aviation' in title_lower:
            if 'general' in title_lower:
                potential_keys.append('asat_gen')
            elif 'cargo' in title_lower:
                potential_keys.append('asat2')
        if 'rpas' in title_lower:
            potential_keys.append('rpas_final')
        if 'airside' in title_lower:
            potential_keys.append('airside_induction')

        print(f"   🔍 Trying keys for AssessmentAttempt: {potential_keys}")

        for key in potential_keys:
            if not key:
                continue
            # Use course_key field (not assessment_key) and match dashboard logic
            assessment_attempts = AssessmentAttempt.query.filter(
                AssessmentAttempt.course_key == key,
                AssessmentAttempt.student_id == str(student.student_id),
                AssessmentAttempt.is_active.is_(True)
            ).order_by(AssessmentAttempt.created_at.desc()).all()

            if assessment_attempts:
                attempts_count = len(assessment_attempts)
                latest_score = assessment_attempts[0].score
                print(f"   ✓ Found {attempts_count} attempts with key '{key}', latest_score={latest_score}")
                break

    # Debug logging
    print(f"🔄 REQUEST RETRY: student={student.student_id}, course={course.title}, attempts={attempts_count}, score={latest_score}")

    # Verify eligibility
    if latest_score is None:
        flash("No assessment submissions found for this course.", "danger")
        print(f"   ❌ Rejected: No submissions found")
        return redirect(url_for('dashboard'))

    if latest_score >= 80:
        flash("You have already passed this assessment.", "info")
        print(f"   ❌ Rejected: Already passed (score={latest_score})")
        return redirect(url_for('dashboard'))

    if latest_score < 75:
        flash("Your score is below 75%. You are not eligible to request an additional attempt.", "danger")
        print(f"   ❌ Rejected: Score below 75% (score={latest_score})")
        return redirect(url_for('dashboard'))

    if attempts_count < 2:
        flash("You still have automatic retries available.", "info")
        print(f"   ❌ Rejected: Still has auto-retries (attempts={attempts_count})")
        return redirect(url_for('dashboard'))

    # Check for existing request
    existing_request = RetryRequest.query.filter_by(
        student_id=student.id,
        course_id=course_id
    ).first()

    if existing_request:
        if existing_request.status == 'pending':
            flash("You already have a pending retry request for this course.", "info")
        elif existing_request.status == 'approved':
            flash("Your retry request has been approved! You can now take the assessment.", "success")
        else:
            flash("Your retry request was previously rejected.", "warning")
        return redirect(url_for('dashboard'))

    if request.method == 'POST':
        # Create the retry request
        new_request = RetryRequest(
            student_id=student.id,
            course_id=course_id,
            score=latest_score,
            attempt_number=attempts_count,
            status='pending'
        )
        db.session.add(new_request)
        db.session.commit()

        flash(f"Your request for an additional attempt on '{course.title}' has been submitted. You will be notified once it is reviewed.", "success")
        return redirect(url_for('dashboard'))

    # GET request - show confirmation page (or just redirect back to dashboard with flash)
    # For simplicity, we'll auto-submit on GET (the button is the confirmation)
    new_request = RetryRequest(
        student_id=student.id,
        course_id=course_id,
        score=latest_score,
        attempt_number=attempts_count,
        status='pending'
    )
    db.session.add(new_request)
    db.session.commit()

    print(f"   ✅ Request created: ID={new_request.id}, student={student.student_id}, course={course.title}")
    flash(f"Your request for an additional attempt on '{course.title}' has been submitted. You will be notified once it is reviewed.", "success")
    return redirect(url_for('dashboard'))


