# Submit unit-quiz answers, then return to the same chapter page
@app.route('/unit_quiz/submit', methods=['POST'])
@app.route('/unit_quiz/submit/<int:course_id>/<int:chapter_id>', methods=['POST'])
@require_popia
def submit_unit_quiz(course_id=None, chapter_id=None):
    # --- auth ---
    if 'student_id' not in session:
        flash("⚠ Please log in first.", "danger")
        return redirect(url_for('login'))

    student = Student.query.filter_by(student_id=session['student_id']).first()
    if not student:
        flash("⚠ User not found!", "danger")
        return redirect(url_for('dashboard'))

    # Accept ids from path, querystring, or form (any will do)
    course_id = course_id or request.args.get(
        'course_id', type=int) or request.form.get('course_id', type=int)
    chapter_id = chapter_id or request.args.get(
        'chapter_id', type=int) or request.form.get('chapter_id', type=int)
    if not course_id or not chapter_id:
        flash("⚠ Missing course/chapter.", "danger")
        return redirect(url_for('dashboard'))

    course = db.session.get(Course, course_id)
    chapter = db.session.get(CourseChapter, chapter_id)
    unit_key = f"chapter:{chapter.id}"
    if not course or not chapter or chapter.course_id != course.id:
        flash("⚠ Invalid submission.", "danger")
        return redirect(url_for('dashboard'))

    # 🔒 Retake guard: only one attempt per chapter per student
    unit_key = f"chapter:{chapter.id}"
    existing = (UnitQuizAttempt.query
                .filter_by(student_id=student.student_id, course_id=course.id, unit_key=unit_key)
                .first())
    if existing:
        flash("ℹ️ You’ve already submitted answers for this unit. Retakes are disabled.", "info")
        return redirect(url_for('chapter_content', course_id=course.id, chapter_id=chapter.id))

    # ----- load the planned questions for THIS chapter -----
    def _by_chapter(plan_obj, ch_id):
        """Accept dict {chapter_id: [..]} or a list with 'chapter_id' items; return list of q-dicts."""
        if isinstance(plan_obj, dict):
            return plan_obj.get(ch_id, []) or []
        if isinstance(plan_obj, list):
            if plan_obj and isinstance(plan_obj[0], dict) and 'chapter_id' in plan_obj[0]:
                return [it for it in plan_obj if it.get('chapter_id') == ch_id]
            return plan_obj
        return []

    try:
        res = compute_unit_quiz_plan(course)  # can return dict or (dict, meta)
        plan = res[0] if isinstance(res, tuple) else res
    except Exception:
        plan = {}

    items = _by_chapter(plan, chapter.id)

    if not items:
        flash("⚠ No questions found for this unit.", "warning")
        return redirect(url_for('chapter_content', course_id=course.id, chapter_id=chapter.id))

    # ----- normalize & build answer key -----
    ordered = []
    key = {}   # qid -> correct_index
    for i, it in enumerate(items, 1):
        if not isinstance(it, dict):
            continue
        qid = it.get('id') or it.get('qid') or i
        opts = it.get('options') or []
        if isinstance(opts, dict):
            # preserve alphabetical option key order (A,B,C,...)
            opts = [opts[k] for k in sorted(opts.keys())]
        ci = it.get('correct_index', 0)
        ordered.append({
            'id': int(qid),
            'question': (it.get('question') or it.get('q') or '').strip(),
            'options': opts
        })
        key[int(qid)] = int(ci) if isinstance(ci, int) else 0

    # ----- read submitted answers -----
    answers = []
    correct = 0
    total = len(ordered) or 1
    for q in ordered:
        qid = q['id']
        raw = request.form.get(f"q_{qid}", None)
        try:
            chosen = int(raw) if raw is not None else -1
        except ValueError:
            chosen = -1
        is_right = (chosen == key.get(qid, -999))
        if is_right:
            correct += 1
        answers.append({
            'id': qid,
            'selected': chosen,
            'correct': key.get(qid, None),
            'is_right': is_right,
        })

    percent = round((correct / total) * 100, 1)
    passed = percent >= 70.0  # tweak threshold as needed

    # ----- persist using your UnitQuizAttempt schema -----
    try:
        attempt = UnitQuizAttempt(
            course_id=course.id,
            # important: used to find chapter attempts
            unit_key=unit_key,
            course_key=getattr(course, "code", None) or None,

            # student snapshot (your model stores string ids)
            student_id=student.student_id,
            student_number=getattr(student, "student_number", None),
            full_name=" ".join(filter(None, [getattr(student, "first_name", None),
                                             getattr(student, "last_name", None)])) or None,
            email=getattr(student, "email", None),

            score=percent,
            passed=passed,
            answers_json=json.dumps(answers, ensure_ascii=False),

            started_at=_now_sast(),
            finished_at=_now_sast(),
            duration_s=None,
            ip_address=request.headers.get(
                "X-Forwarded-For", request.remote_addr),
            user_agent=request.headers.get("User-Agent"),
        )
        db.session.add(attempt)
        db.session.commit()
        flash(
            f"✅ Answers submitted. Score: {correct}/{total} ({percent}%).", "success")
    except Exception as e:
        db.session.rollback()
        flash(f"❌ Could not save attempt: {e}", "danger")

    # Always go back to the same chapter page
    return redirect(url_for('chapter_content', course_id=course.id, chapter_id=chapter.id))
