@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        identifier = request.form.get('student_id')
        password = request.form.get('password')

        if not identifier or not password:
            flash("❌ Please enter both your Student ID / Email / ID Number and Password.", "danger")
            return redirect(url_for('frontpage'))

        # Try unique identifiers first (student_id, national_id),
        # then fall back to email only if it matches exactly one student.
        user = Student.query.filter(
            (Student.student_id == identifier) |
            (Student.national_id == identifier)
        ).first()

        if not user:
            # Check email — but only allow login if it's unique to one student
            email_matches = Student.query.filter(Student.email == identifier).all()
            if len(email_matches) == 1:
                user = email_matches[0]
            elif len(email_matches) > 1:
                flash("⚠ Multiple accounts share this email address. "
                      "Please log in with your Student ID or ID Number instead.", "warning")
                return redirect(url_for('frontpage'))

        if user and check_password_hash(user.password, password):
            # Check if OTP verification is still pending
            if user.otp is not None:
                flash("Please verify your email first. Check your inbox for the OTP code.", "warning")
                session['pending_user'] = user.email
                return redirect(url_for('verify_otp'))

            # Check if student is suspended
            if user.is_suspended:
                flash("🚫 Your account has been suspended. Please contact your administrator for assistance.", "danger")
                return redirect(url_for('frontpage'))

            # Set session
            # NOTE: your code uses the public 8-digit ID
            session['student_id'] = user.student_id
            session['email'] = user.email
            session['national_id'] = user.national_id
            session['selfie_filename'] = user.selfie_filename

            _log_session('student', user.student_id, f"{user.name} {user.surname}", 'login')

            # Where to go after consent
            session['post_login_next'] = url_for('dashboard')

            # POPIA gate — if not accepted for current version, go to /popia first
            v = current_app.config.get('POPIA_VERSION', '1')
            if not user.has_popia_consent(v):
                flash('📜 Please accept the POPIA notice to continue.', 'warning')
                return redirect(url_for('popia_notice'))

            flash('✅ Login successful!', 'success')
            return redirect(url_for('dashboard'))

        else:
            flash("❌ Invalid credentials. Please try again.", "danger")
            return redirect(url_for('frontpage'))

    # GET → back to front page
    return redirect(url_for('frontpage'))


