# UPLOAD_ROOT - will be set after app.config['UPLOAD_FOLDER'] is configured
# Use a function to get it dynamically
def get_upload_root_abs():
    """Get absolute path to upload root directory."""
    upload_folder = app.config.get('UPLOAD_FOLDER', 'uploads')
    if os.path.isabs(upload_folder):
        return upload_folder
    return os.path.join(app.root_path, upload_folder)

