# Whitelist of extensions you’re willing to serve as “video”
ALLOWED_VIDEO_EXTS = {".mp4", ".webm", ".mov", ".m4v", ".ogg", ".ogv",
                      ".jpg", ".jpeg", ".png", ".webp", ".pdf"}


def _is_allowed_video(filename: str) -> bool:
    ext = os.path.splitext(filename)[1].lower()
    return ext in ALLOWED_VIDEO_EXTS

