@app.route('/uploads/<student_id>/<path:filename>')
def uploaded_file(student_id, filename):
    """
    Serve a student's uploaded asset from UPLOAD_ROOT/<student_id>/<filename>.
    Example resolved path:
      /var/enroll/uploads/91643302/final.mp4
    """
    if not student_id or not filename:
        abort(404)

    # Normalize inputs
    safe_student = secure_filename(str(student_id))  # strips garbage like ../
    # Keep original dots in the filename but neutralize traversal
    # secure_filename can be overzealous; we only care about removing slashes.
    unsafe = str(filename)
    if "/" in unsafe or "\\" in unsafe:
        # block nested paths; our route expects exactly one directory level
        abort(404)

    # Optional: only allow known video files
    if not _is_allowed_video(unsafe):
        abort(404)

    # Use the configured upload folder path
    upload_root = app.config.get('UPLOAD_FOLDER', os.path.join(app.root_path, 'uploads'))
    folder = os.path.join(upload_root, safe_student)
    full_path = os.path.join(folder, unsafe)

    if not os.path.isfile(full_path):
        abort(404)

    # Tell browsers to treat it as inline media; Flask handles Range for <video>
    resp = send_from_directory(
        directory=folder,
        path=unsafe,
        as_attachment=False,  # inline
        conditional=True      # enables 304/Range
    )
    # Modest caching; tweak to your needs
    resp.headers.setdefault(
        "Cache-Control", "public, max-age=86400, immutable")
    return resp


