@app.route('/upload_id', methods=['POST'])
def upload_id():
    if 'student_id' not in session:
        flash('You must be logged in.', 'danger')
        return redirect(url_for('login'))

    student_id = session['student_id']
    file = request.files.get('id_file')

    if file and file.filename != '':
        ext = 'pdf' if (file.content_type == 'application/pdf' or file.filename.lower().endswith('.pdf')) else 'jpg'
        filename = f"{student_id}_id.{ext}"
        folder_path = os.path.join(app.config['UPLOAD_FOLDER'], student_id)
        os.makedirs(folder_path, exist_ok=True)
        # Remove old ID file with other extension
        other_ext = 'jpg' if ext == 'pdf' else 'pdf'
        old_file = os.path.join(folder_path, f"{student_id}_id.{other_ext}")
        if os.path.exists(old_file):
            os.remove(old_file)
        file.save(os.path.join(folder_path, filename))
        flash('✅ ID document uploaded successfully.', 'success')
    else:
        flash('⚠️ No file selected.', 'warning')

    return redirect(url_for('dashboard'))
