@app.route('/admin_dashboard')
def admin_dashboard():
    session.modified = True
    print(f"DEBUG: Stored Role -> {session.get('admin_role')}")

    # Auth guard — all admin roles (including Accountant) can see the dashboard
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 1:
        flash('❌ Unauthorized Access!', 'danger')
        return redirect(url_for('admin_login'))

    # --- Active students (last 30 min) ---
    thirty_minutes_ago = _now_sast() - timedelta(minutes=30)

    rows = (
        db.session.query(
            Student.id.label("sid"),
            (Student.name + " " + Student.surname).label("student_name"),
            Course.title.label("course_title"),
            Student.last_login.label("last_login"),
        )
        .join(CourseEnrollment, Student.id == CourseEnrollment.student_id)
        .join(Course, Course.id == CourseEnrollment.course_id)
        .filter(Student.last_login >= thirty_minutes_ago)
        .filter(CourseEnrollment.approved.is_(True))
        .order_by(Student.last_login.desc())
        .all()
    )

    # De-duplicate by student id, keep the most recent
    seen = set()
    active_students = []
    for sid, student_name, course_title, _ in rows:
        if sid in seen:
            continue
        seen.add(sid)
        active_students.append(
            {"student_name": student_name, "title": course_title})

    # --- Random motivation quote (with safe fallback) ---
    quote_text, quote_author = None, None
    try:
        quote = db.session.query(Motivation).order_by(func.random()).first()
        if quote:
            quote_text = quote.text
            quote_author = quote.author or ""
    except Exception:
        from random import choice
        FALLBACK_QUOTES = [
            ("The best way to predict the future is to create it.", "Peter Drucker"),
            ("Success is the sum of small efforts, repeated day in and day out.",
             "Robert Collier"),
            ("What we do now echoes in eternity.", "Marcus Aurelius"),
            ("Do what you can, with what you have, where you are.", "Theodore Roosevelt"),
        ]
        quote_text, quote_author = choice(FALLBACK_QUOTES)

    # --- KPIs (uses your AssessmentAttempt & SupportTicket) ---
    # If you already added get_kpis() from my earlier message, this will just work.
    # If not, paste that helper in once and keep this call.
    try:
        kpis = get_kpis()
    except NameError:
        # If helper not present yet, fall back to zeros to avoid breaking the page.
        kpis = dict(
            kpi_active_students=0,
            kpi_attempts_24h=0,
            kpi_pass_rate_7d=0.0,
            kpi_open_tickets=0,
        )

    # --- Dynamic Final Assessments catalog (for the dashboard tiles) ---
    try:
        assessments = load_assessments_cfg() or []
    except NameError:
        assessments = []

    # --- Open/In Progress ticket count for notification badge ---
    open_ticket_count = SupportTicket.query.filter(
        SupportTicket.status.in_(['Open', 'In Progress'])
    ).count()

    # --- Lazy check: send overdue certificate reminders if needed ---
    try:
        check_and_send_overdue_reminders()
    except Exception as e:
        print(f"[CertQueue] Overdue reminder check failed: {e}")

    return render_template(
        "admin_dashboard.html",
        active_students=active_students,
        admin_name=session.get("admin_name", "Admin"),
        motivation_quote=quote_text,
        motivation_author=quote_author,
        assessments_catalog=assessments,  # <-- makes new F/As appear without restart
        open_ticket_count=open_ticket_count,  # for notification badge on Support Tickets
        **kpis,  # kpi_active_students, kpi_attempts_24h, kpi_pass_rate_7d, kpi_open_tickets
    )

