@app.route('/developer/dashboard')
@require_role('Super Admin')
def developer_dashboard():
    """Analytics dashboard for Super Admins+. Dev tools shown only to Developers."""
    now = _now_sast()
    seven_days_ago = now - timedelta(days=7)

    total_students = Student.query.count()
    total_companies = Company.query.count()
    approved_companies = Company.query.filter_by(approved=True).count()
    total_certs = CertificateQueue.query.filter_by(status='done').count()
    pending_certs = CertificateQueue.query.filter_by(status='pending').count()
    total_enrollments = CourseEnrollment.query.count()
    active_enrollments = CourseEnrollment.query.filter_by(approved=True, completed=False).count()

    # Pass rate (7-day)
    attempts_7d = AssessmentAttempt.query.filter(AssessmentAttempt.created_at >= seven_days_ago).count()
    passed_7d = AssessmentAttempt.query.filter(AssessmentAttempt.created_at >= seven_days_ago, AssessmentAttempt.passed.is_(True)).count()
    pass_rate_7d = round((passed_7d / attempts_7d) * 100, 1) if attempts_7d else 0.0

    # Pass rate (all-time)
    attempts_all = AssessmentAttempt.query.count()
    passed_all = AssessmentAttempt.query.filter_by(passed=True).count()
    pass_rate_all = round((passed_all / attempts_all) * 100, 1) if attempts_all else 0.0

    # Unscored task count for notification badge on Task Board link
    try:
        unscored_task_count = BoardTask.query.filter(
            BoardTask.score.is_(None), BoardTask.status != 'done'
        ).count()
    except Exception:
        unscored_task_count = 0

    # Students stuck at the sign-up verification step. Surfaced as a badge on
    # the dashboard so support notices a mail-delivery problem early.
    # Both ways a student can be locked out: a pending OTP, or a password
    # setup link they never managed to use.
    pending_otp_count = Student.query.filter(db.or_(
        Student.otp.isnot(None),
        Student.password_setup_token.isnot(None))).count()

    return render_template(
        'developer_dashboard.html',
        admin_name=session.get('admin_name', 'Developer'),
        pending_otp_count=pending_otp_count,
        total_students=total_students,
        total_companies=total_companies,
        approved_companies=approved_companies,
        total_certs=total_certs,
        pending_certs=pending_certs,
        total_enrollments=total_enrollments,
        active_enrollments=active_enrollments,
        pass_rate_7d=pass_rate_7d,
        pass_rate_all=pass_rate_all,
        unscored_task_count=unscored_task_count,
    )


@app.route('/api/analytics/daily-trends')
@require_role('Super Admin')
def api_analytics_daily_trends():
    """Return daily counts for the last N days (default 30)."""
    days = min(int(request.args.get('days', 30)), 90)
    now = _now_sast()
    start = (now - timedelta(days=days - 1)).replace(hour=0, minute=0, second=0, microsecond=0)

    # Generate all date labels
    labels = [(start + timedelta(days=i)).strftime('%Y-%m-%d') for i in range(days)]
    date_map = {d: 0 for d in labels}

    def daily_counts(model, date_col, extra_filter=None):
        counts = dict(date_map)
        q = db.session.query(
            func.date(date_col).label('day'),
            func.count().label('cnt')
        ).filter(date_col >= start)
        if extra_filter is not None:
            q = q.filter(extra_filter)
        for row in q.group_by('day').all():
            day_str = str(row.day)
            if day_str in counts:
                counts[day_str] = row.cnt
        # Cumulative running total so graphs trend upward
        daily = [counts[d] for d in labels]
        cumulative = []
        total = 0
        for v in daily:
            total += v
            cumulative.append(total)
        return cumulative

    return jsonify({
        'labels': labels,
        'students': daily_counts(Student, Student.date_joined),
        'companies': daily_counts(Company, Company.created_at),
        'certificates': daily_counts(CertificateQueue, CertificateQueue.done_at,
                                     CertificateQueue.status == 'done'),
        'enrollments': daily_counts(CourseEnrollment, CourseEnrollment.enrolled_at),
    })

