@app.route('/admin_login', methods=['GET', 'POST'])
def admin_login():
    raw_next = request.args.get(
        'next') if request.method == 'GET' else request.form.get('next')

    next_path = ''
    if raw_next:
        parsed = urlparse(raw_next)
        if parsed.netloc == '' or parsed.netloc == request.host:
            next_path = parsed.path

    if request.method == 'POST':
        email = request.form.get('email')
        password = request.form.get('password')

        user = User.query.filter(User.email == email, User.role.in_(ALL_ADMIN_ROLES)).first()

        if user and check_password_hash(user.password_hash, password):
            # ✅ Set all necessary session values
            session['admin_id'] = user.id
            session['admin_role'] = user.role
            session['admin_name'] = user.name
            session['admin_email'] = user.email

            _log_session('admin', user.email, user.name, 'login')

            flash('✅ Login successful!', 'success')

            # ✅ Optional debug print to confirm session values
            print("✅ SESSION:", dict(session))

            # ✅ Redirect to intended page or dashboard
            if next_path and next_path.startswith('/'):
                return redirect(next_path)
            return redirect(url_for('admin_dashboard'))

        flash('❌ Invalid email or password!', 'danger')
        return redirect(url_for('admin_login', next=next_path))

    return render_template('admin_login.html', next=next_path)


@app.route('/admin/forgot-password', methods=['GET', 'POST'])
def admin_forgot_password():
    """Self-service password reset for the PAS Admin login (v1.2).

    Mirrors company_forgot_password: POST an email, mint a one-shot token with
    a 60-minute TTL, email the reset link, and ALWAYS render the same neutral
    message whether or not the address matched. The uniform response stops this
    endpoint being used to discover which addresses have admin accounts.

    Open to every role in ALL_ADMIN_ROLES (Accountant, Admin, Super Admin,
    Developer) — the same set the login itself accepts.
    """
    if request.method == 'POST':
        email = (request.form.get('email') or '').strip().lower()
        if email:
            u = User.query.filter(
                func.lower(User.email) == email,
                User.role.in_(ALL_ADMIN_ROLES)
            ).first()
            if u:
                token = secrets.token_urlsafe(32)
                u.password_reset_token = token
                u.password_reset_token_expires = (
                    _now_sast() + timedelta(minutes=60))
                db.session.commit()
                try:
                    reset_url = url_for(
                        'admin_reset_password', token=token, _external=True)
                    send_email(
                        u.email,
                        "Reset your PAS Admin password",
                        f"""<h2 style="color:#17306B; margin:0 0 16px;">Password reset</h2>
                        <p>Hi {u.name},</p>
                        <p>We received a request to reset the password for your Professional Aviation Training admin account.</p>
                        <p>Click the button below to choose a new password. This link is valid for 60 minutes and can only be used once.</p>
                        <div style="text-align:center; margin:24px 0;">
                          <a href="{reset_url}" style="display:inline-block; background:#17306B; color:#fff; padding:12px 32px; border-radius:8px; text-decoration:none; font-weight:600;">Reset Password</a>
                        </div>
                        <p style="font-size:13px; color:#64748b;">If you did not ask for this, you can safely ignore this email. Your password will not change. If you keep receiving these, please tell the development team.</p>"""
                    )
                except Exception as e:
                    # Never surface mail failures: the token is already
                    # committed and the admin can simply request another.
                    app.logger.warning(
                        f"admin_forgot_password send_email failed: {e}")
        # Same neutral response every time, matched account or not.
        return render_template('admin_forgot_password.html', sent=True)
    return render_template('admin_forgot_password.html', sent=False)


@app.route('/admin/reset-password/<token>', methods=['GET', 'POST'])
def admin_reset_password(token):
    """Consumes a User.password_reset_token and sets a new admin password.

    GET: show the new-password form if the token is valid and unexpired.
    POST: validate token + minimum length, hash, clear the token so the link
    cannot be replayed, then send the admin to the login page.
    """
    u = User.query.filter(
        User.password_reset_token == token,
        User.role.in_(ALL_ADMIN_ROLES)
    ).first()
    expired = (
        u is None or
        u.password_reset_token_expires is None or
        u.password_reset_token_expires < _now_sast()
    )

    if request.method == 'POST':
        if expired:
            flash("This reset link has expired. Please request a new one.",
                  "danger")
            return redirect(url_for('admin_forgot_password'))
        new_pwd = (request.form.get('password') or '').strip()
        confirm = (request.form.get('confirm') or '').strip()
        if len(new_pwd) < 8:
            flash("Password must be at least 8 characters.", "warning")
            return render_template('admin_reset_password.html',
                                   token=token, expired=False)
        if new_pwd != confirm:
            flash("Passwords do not match.", "warning")
            return render_template('admin_reset_password.html',
                                   token=token, expired=False)
        u.password_hash = generate_password_hash(
            new_pwd, method="pbkdf2:sha256")
        u.password_reset_token = None
        u.password_reset_token_expires = None
        db.session.commit()
        # Leave an audit trail alongside the login/logout events.
        try:
            _log_session('admin', u.email, u.name, 'password reset')
        except Exception:
            pass
        flash("Password updated. Please log in with your new password.",
              "success")
        return redirect(url_for('admin_login'))

    return render_template('admin_reset_password.html',
                           token=token, expired=expired)

