def send_password_reset_email(email, full_name, student_id, new_password):
    """ Sends a password reset email to the student """

    msg = Message(
        subject=f"🔑 Password Reset — {full_name} ({student_id})",
        recipients=[email]
    )

    msg.body = f"""
    Dear {full_name},

    Your password has been successfully reset for the Professional's Online Training Platform.

    To log in, please visit:
    https://enroll.professionaltraining.co.za/login

    Your new login credentials:
    📌 Username: {student_id}
    🔑 New Password: {new_password}

    For security reasons, please change your password after logging in.

    Best regards,  
    Professional Training Team
    """

    try:
        print(f"📨 Sending password reset email to {email}...")
        msg.body = msg.body.encode('utf-8').decode('utf-8')
        mail.send(msg)
        print(f"✅ Password reset email sent to {email}")
    except Exception as e:
        print(f"❌ Error sending email: {e}")


