@app.route('/reset_student_password/<int:student_id>', methods=['GET'])
def reset_student_password(student_id):
    """ Admin resets a student's password and emails them the new password """

    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access! Please log in as an admin.", "danger")
        return redirect(url_for('admin_login'))

    student = db.session.get(Student, student_id)

    if student:
        print(
            f"🔄 Resetting password for: {student.name} {student.surname} (ID: {student.student_id})")

        new_password = ''.join(random.choices(
            string.ascii_letters + string.digits, k=10))
        hashed_password = generate_password_hash(
            new_password, method='pbkdf2:sha256')

        print(f"🔑 RAW Password: {new_password}")
        print(f"🔐 HASHED Password: {hashed_password}")

        student.password = hashed_password

        try:
            db.session.commit()
            db.session.refresh(student)

            db.session.expire_all()
            student_reloaded = db.session.get(Student, student_id)
            print(f"🔍 RELOADED from DB: {student_reloaded.password}")

            if student_reloaded.password == hashed_password:
                print("✅ Password update successful!")
            else:
                print("❌ Password update failed. Check commit.")

        except Exception as e:
            db.session.rollback()
            flash(f"⚠ Database Error: {e}", "danger")
            return redirect(url_for('view_students'))

        # Email Notification
        try:
            send_password_reset_email(
                student.email, f"{student.name} {student.surname}", student.student_id, new_password)
            flash(
                f"✅ Password for {student.name} {student.surname} has been reset and emailed.", "success")
        except Exception as e:
            flash(f"⚠ Email could not be sent: {e}", "danger")

    else:
        flash("⚠ Student not found!", "danger")

    return redirect(url_for('view_students'))

