def send_enrollment_notification(student_name, course_name):
    """Send an email notification when a student enrolls."""
    # Get recipients from database (falls back to empty list if none configured)
    recipients = get_recipients_for_category('enrollment')
    if not recipients:
        print("⚠ No enrollment notification recipients configured in database.")
        return

    msg = Message(
        subject="📩 Enrollment Approval Requested",
        recipients=recipients,
        body=(
            f"Hello Professional Training Admin,\n\n"
            f"A new enrollment request has been made.\n\n"
            f"📌 Student Name: {student_name}\n"
            f"📖 Course Title: {course_name}\n\n"
            f"Please review and either approve or deny this enrollment in the Admin Dashboard.\n\n"
            f"Best regards,\n"
            f"Online Training Platform"
        )
    )

    # Print detailed send info so you can see in the terminal
    print("=== Sending enrollment notification ===")
    print(f"Subject: {msg.subject}")
    print("To:")
    for r in (msg.recipients or []):
        print("  -", r)
    # If you use cc/bcc, show them too (will be None if not set)
    if getattr(msg, "cc", None):
        print("CC:")
        for c in msg.cc:
            print("  -", c)
    if getattr(msg, "bcc", None):
        print("BCC:")
        for b in msg.bcc:
            print("  -", b)
    print("Message preview:")
    print(msg.body)
    print("=======================================")

    try:
        mail.send(msg)
        print("✅ Mail sent.")
    except Exception as e:
        print(f"❌ Error sending enrollment notification: {e}")
