@app.route('/enroll/<int:course_id>')
@require_popia
def enroll(course_id):
    if 'student_id' not in session:
        flash("⚠ Please log in first.", "danger")
        return redirect(url_for('login'))

    print(f"📌 Debug: Session Data - {session}")

    session_student_id = session['student_id']

    student = Student.query.filter(
        (Student.student_id == session_student_id) |
        (Student.student_id == int(session_student_id))
    ).first()

    course = db.session.get(Course, course_id)

    all_students = [s.student_id for s in Student.query.all()]
    print(f"📌 Debug: All students in DB: {all_students}")

    if not student:
        print(
            f"❌ Debug: Student ID {session_student_id} not found in database!")
        flash("⚠ Student not found!", "danger")
        return redirect(url_for('courses'))
    if not course:
        print(f"❌ Debug: Course ID {course_id} not found in database!")
        flash("⚠ Course not found!", "danger")
        return redirect(url_for('courses'))

    # Block company students from self-enrolling
    if student.created_by_company_id is not None:
        flash("Company students cannot self-enroll. Please contact your company administrator.", "warning")
        return redirect(url_for('dashboard'))

    # Block self-enrollment into virtual courses — admins handle those directly.
    if getattr(course, 'course_type', 'normal') == 'virtual':
        flash("This is a virtual course. Please contact your administrator to be enrolled.", "warning")
        return redirect(url_for('dashboard'))

    enrollment = CourseEnrollment.query.filter_by(
        student_id=student.id, course_id=course.id).first()
    if enrollment:
        flash("✅ You have already enrolled in this course.", "info")
        return redirect(url_for('dashboard'))

    db.session.query(CourseProgress).filter(
        CourseProgress.student_id == student.id,
        CourseProgress.course_id == course.id
    ).delete(synchronize_session=False)

    course_name = course.title

    new_enrollment = CourseEnrollment(
        student_id=student.id,
        course_id=course.id,
        approved=False,
        completed=False,
        reset_count=0
    )
    db.session.add(new_enrollment)

    chapters = CourseChapter.query.filter_by(course_id=course.id).all()
    for chapter in chapters:
        new_progress = CourseProgress(
            student_id=student.id,
            course_id=course.id,
            chapter_id=chapter.id,
            completed=False,
            reset_count=0
        )
        db.session.add(new_progress)

    db.session.commit()

    send_enrollment_notification(
        f"{student.name} {student.surname}", course_name)

    print(
        f"📩 Debug: Enrollment request sent for {student.name} {student.surname} -> {course_name}")

    flash(
        f"📩 Enrollment request sent for {course_name}. Awaiting admin approval.", "success")
    return redirect(url_for('dashboard'))

