def send_student_enrollment_email(student_email, student_name, course_name, approved, reason=None):
    """ Notify student when their enrollment is approved or rejected. """
    status = "approved" if approved else "rejected"

    msg = Message(
        subject=f"Enrollment {status.capitalize()} — {student_name} - {course_name}",
        recipients=[student_email]
    )

    if approved:
        msg.body = f"""
Dear {student_name},

Your enrollment for the course {course_name} has been approved.

Best regards,
Professional Training Team
"""
    else:
        msg.body = f"""
Dear {student_name},

Your enrollment for the course {course_name} has been rejected.
"""
        if reason:
            msg.body += f"\nReason: {reason}\n"

        msg.body += "\nBest regards,\nProfessional Training Team"

    try:
        mail.send(msg)
        print(f"✅ Enrollment {status} email sent to {student_email}")
    except Exception as e:
        print(f"❌ Error sending {status} email: {e}")

