@app.route('/create_course', methods=['GET', 'POST'])
def create_course():
    if 'admin_id' not in session:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    if request.method == 'POST':
        title = request.form.get('title')
        description = request.form.get('description')
        pass_mark = request.form.get('pass_mark', type=int)
        files = request.files

        if not title or not description:
            flash("⚠ Course title and description are required!", "danger")
            return redirect(url_for('create_course'))

        new_course = Course(title=title, description=description)
        if pass_mark:
            new_course.pass_mark = pass_mark  # optional pass mark logic
        db.session.add(new_course)
        db.session.commit()

        # Get block indices
        block_indexes = request.form.getlist('block_index')
        for idx in block_indexes:
            block_type = request.form.get(f'block[{idx}][type]')
            block_title = request.form.get(f'block[{idx}][title]', '')
            block_content = request.form.get(f'block[{idx}][content]', '')
            ch_file = request.files.get(f'block[{idx}][media]')
            media_url = None

            if ch_file and ch_file.filename != "":
                filename = secure_filename(ch_file.filename)
                media_path = os.path.join('static/uploads', filename)
                ch_file.save(media_path)
                media_url = f'/static/uploads/{filename}'

            # If it's a quiz, handle differently
            if block_type == 'quiz':
                question_texts = request.form.getlist(
                    f'block[{idx}][questions][]')
                answer_texts = request.form.getlist(f'block[{idx}][answers][]')
                correct_indices = request.form.getlist(
                    f'block[{idx}][correct_indices][]')

                for q_index, question in enumerate(question_texts):
                    question_record = QuizQuestion(
                        course_id=new_course.id,
                        question_text=question
                    )
                    db.session.add(question_record)
                    db.session.commit()

                    # answers separated by |
                    for a_index, answer in enumerate(answer_texts[q_index].split('|')):
                        is_correct = str(
                            a_index) in correct_indices[q_index].split(',')
                        answer_record = QuizAnswer(
                            question_id=question_record.id,
                            answer_text=answer.strip(),
                            is_correct=is_correct
                        )
                        db.session.add(answer_record)

            else:
                # Save as normal chapter block
                chapter = CourseChapter(
                    course_id=new_course.id,
                    title=block_title,
                    position=int(idx),
                    chapter_type=block_type,
                    content=block_content,
                    media_url=media_url
                )
                db.session.add(chapter)

        db.session.commit()
        flash("✅ Course and blocks created successfully!", "success")
        # return redirect(url_for('manage_course', course_id=new_course.id))
        return redirect(url_for('edit_course', course_id=new_course.id))

    return render_template('create_course.html')

