@app.route("/unit_quiz/upload/<int:course_id>", methods=["POST"], endpoint="unit_quiz_upload")
def unit_quiz_upload(course_id):
    # gate: admin only
    if "admin_id" not in session:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for("admin_login"))

    course = Course.query.get_or_404(course_id)

    f = request.files.get("quiz_file")
    if not f or f.filename.strip() == "":
        flash("Please choose a JSON file to upload.", "danger")
        return redirect(url_for("manage_course", course_id=course.id) + "#unit-quizzes")

    # save under uploads/unit_quizzes/<course_id>/<filename>.json
    filename = secure_filename(f.filename)
    if not filename.lower().endswith(".json"):
        filename += ".json"

    dest_dir = os.path.join("uploads", "unit_quizzes", str(course.id))
    os.makedirs(dest_dir, exist_ok=True)
    dest_path = os.path.join(dest_dir, filename)

    # (optional) validate JSON before saving
    try:
        raw = f.read()
        data = json.loads(raw.decode("utf-8", errors="replace"))
        # cheap shape check: expect list of questions
        if not isinstance(data, list) or len(data) == 0:
            flash("Quiz JSON should be a non-empty list of questions.", "warning")
        # write the original bytes only after we parse OK
        with open(dest_path, "wb") as out:
            out.write(raw)
    except Exception as e:
        flash(f"Invalid JSON: {e}", "danger")
        return redirect(url_for("manage_course", course_id=course.id) + "#unit-quizzes")

    flash(f"✅ Quiz file uploaded: {filename}", "success")
    return redirect(url_for("manage_course", course_id=course.id) + "#unit-quizzes")


