# Save Unit Quiz placements (pool -> chapters)
@app.route("/unit_quiz/reorder/<int:course_id>", methods=["POST"])
def unit_quiz_reorder(course_id):
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash('Unauthorized Access!', 'danger')
        return redirect(url_for('admin_login'))

    # FIX 1: Retrieve the correct form field name: "placement_order"
    raw_json = request.form.get("placement_order", "{}")

    try:
        # FIX 2: The structure is {chapter_id: [q_id, q_id, ...]}, not a flat list
        placements_by_chapter = json.loads(raw_json)

        # 1. Wipe existing placements for this course
        UnitQuizPlacement.query.filter_by(course_id=course_id).delete()

        # 2. Iterate through the dictionary and insert new records
        position_counter = 1
        for chapter_id_str, question_id_list in placements_by_chapter.items():

            # Ensure the chapter ID is an integer
            try:
                ch_id = int(chapter_id_str)
            except ValueError:
                # Skip if chapter ID is invalid (e.g., "None" or a string)
                continue

            # Iterate through the list of question IDs for that chapter
            for i, qid in enumerate(question_id_list, start=1):
                # We use 'i' here for position within the chapter
                # 'position_counter' could be used for global ordering if needed, but per-chapter is typical

                db.session.add(UnitQuizPlacement(
                    course_id=course_id,
                    chapter_id=ch_id,
                    # Ensure question ID is also an integer
                    question_id=int(qid),
                    position=i            # Position within this chapter
                ))

        db.session.commit()
        flash("✅ Unit quiz placement saved.", "success")

    except json.JSONDecodeError as e:
        db.session.rollback()
        # This occurs if the JSON string is malformed
        flash(f"❌ Failed to parse placement data (JSON Error): {e}", "danger")
    except Exception as e:
        db.session.rollback()
        # Catch other database or logic errors
        flash(f"❌ Could not save placement: {e}", "danger")

    return redirect(url_for("manage_course", course_id=course_id))

