@app.route("/manage_course/<int:course_id>")
def manage_course(course_id):
    if "admin_id" not in session:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for("admin_login"))

    # Core objects
    course = Course.query.get_or_404(course_id)
    chapters = (
        CourseChapter.query
        .filter_by(course_id=course.id, parent_id=None)
        .order_by(CourseChapter.position)
        .all()
    )

    # Final assessment count (safe)
    try:
        question_count = FinalAssessmentQuestion.query.filter_by(
            course_id=course.id).count()
    except Exception:
        question_count = 0

    # ---------- Unit quiz filename + data from file ----------
    import os
    import json
    BASE_DIR = os.path.dirname(os.path.abspath(__file__))
    UNIT_QUIZ_DIR = os.path.join(BASE_DIR, "data", "unit_quizzes")
    os.makedirs(UNIT_QUIZ_DIR, exist_ok=True)

    def _slug(s: str) -> str:
        return (s or "").strip().lower().replace(" ", "_")

    def _safe_listify(qdata):
        """
        Normalize whatever is on disk into a list of question dicts.
        Accepts either:
          - {'questions': [ ...items... ]}
          - [ ...items... ]
        Each item can be:
          - {'question': '...', 'id': n, ...}
          - {'q': '...', 'id': n, ...}
        Returns a list of {'id': int, 'question': 'short text'} for UI.
        """
        # unwrap container
        items = qdata.get("questions") if isinstance(qdata, dict) else qdata
        if not isinstance(items, list):
            return [], 0

        out = []
        for i, it in enumerate(items, 1):
            if not isinstance(it, dict):
                continue
            qtxt = (it.get("question") or it.get("q") or "").strip()
            if not qtxt:
                continue
            qid = it.get("id") or i
            # tiny preview trimming
            short = " ".join(qtxt.split())
            if len(short) > 140:
                short = short[:137] + "…"
            out.append({"id": int(qid), "question": short})
        return out, len(items)

    uq_filename = f"{(_slug(course.code) or f'course_{course.id}')}_unit_questions.json"
    uq_path = os.path.join(UNIT_QUIZ_DIR, uq_filename)

    try:
        with open(uq_path, "r", encoding="utf-8") as f:
            _raw = json.load(f)
    except Exception:
        _raw = []

    unit_questions, unit_question_count = _safe_listify(_raw)

    # ---------- Existing placements from DB (safe) ----------
    try:
        existing = (
            UnitQuizPlacement.query
            .filter_by(course_id=course.id)
            .order_by(UnitQuizPlacement.position.asc())
            .all()
        )
        unit_placements = [
            {
                "question_id": int(getattr(r, "question_id", 0)),
                "chapter_id": int(getattr(r, "chapter_id", 0)) if getattr(r, "chapter_id", None) is not None else None,
                "position": int(getattr(r, "position", 0)),
            }
            for r in existing
        ]
    except Exception:
        unit_placements = []

    # =================================================================
    # NEW LOGIC: Convert list of placements to a dictionary for the template
    # This solves the 'current_placements' is undefined error
    current_placements = {}
    for placement in unit_placements:
        chap_id = str(placement["chapter_id"])
        q_id = placement["question_id"]

        # Only process placements assigned to a valid chapter
        if chap_id and chap_id != 'None' and q_id:
            if chap_id not in current_placements:
                current_placements[chap_id] = []
            current_placements[chap_id].append(q_id)
    # =================================================================

    # Assessments catalog for mapping dropdown (safe if helper not present)
    try:
        assessments_catalog = load_assessments_cfg() or []
    except Exception:
        assessments_catalog = []

    # Feature flags
    has_unit_quiz_reorder = ("unit_quiz_reorder" in app.view_functions)
    has_preview_unit_quiz = ("preview_unit_quiz" in app.view_functions)

    # URLs
    # Open the unified MCQ editor directly on the unit-quiz file.
    # Include course_id so the editor's Back button can return here.
    unit_quiz_editor_url = url_for(
        "questions_mcq", filename=uq_filename, course_id=course.id)

    try:
        unit_quiz_reorder_url = url_for(
            "unit_quiz_reorder", course_id=course.id)
    except Exception:
        unit_quiz_reorder_url = "#"

    try:
        preview_unit_quiz_url = url_for(
            "preview_unit_quiz", course_id=course.id)
    except Exception:
        preview_unit_quiz_url = "#"

    try:
        back_url = url_for("manage_courses")
    except Exception:
        back_url = url_for(
            "admin_dashboard") if "admin_dashboard" in app.view_functions else url_for("index")

    # Handbook for this course
    try:
        course_handbook = Handbook.query.filter_by(course_id=course.id, is_active=True).first()
    except Exception:
        course_handbook = None

    return render_template(
        "manage_course.html",
        course=course,
        chapters=chapters,
        question_count=question_count,

        # Unit quiz
        uq_filename=uq_filename,
        unit_questions=unit_questions,          # <- normalized list for DnD pool
        # <- existing placement rows (raw list)
        unit_placements=unit_placements,
        # <--- CRITICAL FIX: The required dict for the template
        current_placements=current_placements,
        unit_question_count=unit_question_count,

        assessments_catalog=assessments_catalog,

        # Flags
        has_unit_quiz_reorder=has_unit_quiz_reorder,
        has_preview_unit_quiz=has_preview_unit_quiz,

        # URLs
        unit_quiz_editor_url=unit_quiz_editor_url,
        unit_quiz_reorder_url=unit_quiz_reorder_url,
        preview_unit_quiz_url=preview_unit_quiz_url,

        back_url=back_url,
        handbook=course_handbook,
    )

