@app.route('/view_students')
@require_role('Admin')
def view_students():
    from flask import current_app
    import os

    PER_PAGE = 20
    page = request.args.get('page', 1, type=int)
    search_q = (request.args.get('q') or '').strip()

    # ---- Build base query ----
    sq = Student.query
    if search_q:
        like = f"%{search_q}%"
        sq = sq.filter(or_(
            Student.student_id.ilike(like),
            Student.name.ilike(like),
            Student.surname.ilike(like),
            Student.email.ilike(like),
            Student.national_id.ilike(like),
            Student.company.ilike(like),
        ))
    if hasattr(Student, 'date_joined'):
        sq = sq.order_by(Student.date_joined.desc())
    elif hasattr(Student, 'created_at'):
        sq = sq.order_by(Student.created_at.desc())
    else:
        sq = sq.order_by(Student.id.desc())

    pagination = sq.paginate(page=page, per_page=PER_PAGE, error_out=False)
    students = pagination.items

    # ---- Build progress_map keyed by enrollment.id (same logic as company detail) ----
    progress_map = {}
    now = _now_sast()
    for student in students:
        # Check if ID document exists (supports .jpg and .pdf)
        student.id_uploaded = _find_id_file(student.student_id) is not None

        for enr in getattr(student, 'enrollments', []):
            prog = _build_enrollment_progress(student, enr, now)
            if prog:
                progress_map[enr.id] = prog

    return render_template(
        'view_students.html',
        students=students,
        progress_map=progress_map,
        pagination=pagination,
        search_q=search_q,
    )

