@app.route('/edit_course/<int:course_id>', methods=['GET', 'POST'])
def edit_course(course_id):
    # Admin guard
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized access!", "danger")
        return redirect(url_for('admin_login'))

    # Load course
    course = db.session.get(Course, course_id)
    if not course:
        flash("⚠ Course not found!", "danger")
        return redirect(url_for('manage_courses'))

    if request.method == 'POST':
        # ---- DEBUG: peek at incoming form once while we troubleshoot ----
        try:
            print("DEBUG edit_course POST form ->", dict(request.form))
        except Exception:
            pass

        action = (request.form.get('action') or '').strip()
        fa_key = (request.form.get('final_assessment_key') or '').strip()

        # ✅ Treat as mapping if either the action flag is set OR the mapping field is present
        if action == 'map_final' or ('final_assessment_key' in request.form):
            # Optional: validate against your assessments registry
            try:
                items = load_assessments_cfg()
                valid_keys = {i.get('key') for i in items if i.get('key')}
                if fa_key and fa_key not in valid_keys:
                    flash("Selected Final Assessment is not registered.", "danger")
                    return redirect(url_for('manage_course', course_id=course.id))
            except Exception:
                pass

            # Persist mapping (ensure the column exists on Course)
            course.final_assessment_key = fa_key or None
            db.session.commit()
            flash("✅ Final assessment mapping saved.", "success")
            return redirect(url_for('manage_course', course_id=course.id))

        # --- Normal edit branch (title/description) ---
        course.title = (request.form.get('title') or '').strip()
        course.description = (request.form.get('description') or '').strip()

        if not course.title or not course.description:
            flash("⚠ Course title and description cannot be empty!", "danger")
            return redirect(url_for('edit_course', course_id=course_id))

        db.session.commit()
        flash("✅ Course updated successfully!", "success")
        return redirect(url_for('manage_courses'))

    # GET: render page
    chapters = (CourseChapter.query
                .filter_by(course_id=course_id)
                .order_by(CourseChapter.position)
                .all())
    return render_template('edit_course.html', course=course, chapters=chapters)


