@app.route('/delete_course/<int:course_id>', methods=['POST'])
def delete_course(course_id):
    """ Admin deletes a course along with its associated data """

    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized access!", "danger")
        return redirect(url_for('admin_login'))

    course = db.session.get(Course, course_id)
    if not course:
        flash("⚠ Course not found!", "danger")
        return redirect(url_for('manage_courses'))

    try:
        # Delete related entries
        db.session.query(SupportTicket).filter_by(
            course_id=course_id).delete(synchronize_session=False)
        db.session.query(CourseProgress).filter_by(
            course_id=course_id).delete(synchronize_session=False)
        db.session.query(CourseEnrollment).filter_by(
            course_id=course_id).delete(synchronize_session=False)
        db.session.query(CertificateLog).filter_by(
            course_id=course_id).delete(synchronize_session=False)

        chapter_ids = [chapter.id for chapter in db.session.query(
            CourseChapter).filter_by(course_id=course_id).all()]
        if chapter_ids:
            db.session.query(CourseProgress).filter(CourseProgress.chapter_id.in_(
                chapter_ids)).delete(synchronize_session=False)

        db.session.query(CourseChapter).filter_by(
            course_id=course_id).delete(synchronize_session=False)

        db.session.delete(course)
        db.session.commit()

        flash(
            f"✅ Course '{course.title}' has been deleted successfully!", "success")
    except Exception as e:
        db.session.rollback()
        print(f"❌ Error deleting course: {e}")
        flash("❌ Error deleting course. Please try again.", "danger")

    return redirect(url_for('manage_courses'))

