class ChapterQuizQuestion(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    chapter_id = db.Column(db.Integer, db.ForeignKey(
        'course_chapter.id'), index=True, nullable=False)
    qtype = db.Column(db.String(10), default='mcq')      # 'mcq' or 'tf'
    prompt = db.Column(db.Text, nullable=False)
    # JSON string for mcq {'a':...,'b':...,'c':...,'d':...}
    options = db.Column(db.Text)
    # 'a'/'b'/'c'/'d' for mcq; 'true'/'false' for tf
    correct = db.Column(db.String(10))
    position = db.Column(db.Integer, default=1)

