@app.route('/admin/grade_quiz/<int:chapter_id>', methods=['POST'])
def admin_grade_quiz(chapter_id):
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized access!", "danger")
        return redirect(url_for('admin_login'))

    # Load chapter + same quiz_items and quiz_view as in edit_chapter
    chapter = db.session.get(CourseChapter, chapter_id)
    if not chapter:
        flash("⚠ Chapter not found!", "danger")
        return redirect(url_for('manage_courses'))

    ctype = getattr(chapter, 'chapter_type', 'text') or 'text'

    # Reuse your loading logic
    rel = None
    if hasattr(chapter, 'quiz_items'):
        rel = chapter.quiz_items
    elif hasattr(chapter, 'quiz_questions'):
        rel = chapter.quiz_questions

    from sqlalchemy.orm import load_only
    if rel is not None and hasattr(rel, 'order_by'):
        try:
            quiz_items = rel.order_by(QuizQuestion.position.asc()).all()
        except Exception:
            quiz_items = rel.order_by(QuizQuestion.id.asc()).all()
    else:
        quiz_items = list(rel or [])

    # Build quiz_view (same as in edit route) so template can render consistently
    import json as _json
    quiz_view = []
    if ctype == 'quiz':
        for q in (quiz_items or []):
            entry = {
                "id": getattr(q, "id", None),
                "prompt": getattr(q, "prompt", "") or "",
                "qtype": (getattr(q, "qtype", "mcq") or "mcq").lower(),
                "options": [],
                "correct": (getattr(q, "correct", "") or "").lower()
            }

            used_json = False
            if hasattr(q, "options") and getattr(q, "options", None):
                try:
                    data = _json.loads(q.options) if isinstance(
                        q.options, str) else (q.options or {})
                    if isinstance(data, dict):
                        for key in ["a", "b", "c", "d"]:
                            txt = (data.get(key) or "").strip()
                            if txt:
                                entry["options"].append(
                                    {"key": key, "text": txt})
                        used_json = True
                except Exception:
                    used_json = False

            if not used_json:
                for key in ["a", "b", "c", "d"]:
                    col = f"option_{key}"
                    if hasattr(q, col):
                        txt = (getattr(q, col) or "").strip()
                        if txt:
                            entry["options"].append({"key": key, "text": txt})

            if entry["qtype"] in ("tf", "truefalse"):
                entry["options"] = [{"key": "true", "text": "True"},
                                    {"key": "false", "text": "False"}]
                # normalize stored correct value for tf
                if entry["correct"] not in ("true", "false"):
                    entry["correct"] = (
                        getattr(q, "correct", "true") or "true").lower()

            quiz_view.append(entry)

    # Grade
    total = len(quiz_view)
    answered = 0
    correct_count = 0
    per_q = []  # [{id, selected, correct_key, is_correct}]

    for q in quiz_view:
        field = f"q_{q['id']}"
        selected = (request.form.get(field) or "").lower().strip()
        is_ans = bool(selected)
        is_correct = is_ans and (selected == (q["correct"] or "a").lower())
        if is_ans:
            answered += 1
        if is_correct:
            correct_count += 1

        per_q.append({
            "id": q["id"],
            "selected": selected,
            "correct_key": q["correct"] or "",
            "is_correct": is_correct
        })

    if answered < total:
        flash(
            f"⚠ Please answer all questions (answered {answered} of {total}).", "warning")

    score_pct = round((correct_count / total) * 100, 1) if total else 0.0

    # Reuse the edit_chapter template to show results inline
    return render_template(
        'edit_chapter.html',
        chapter=chapter,
        ctype=ctype,
        quiz_items=quiz_items,
        quiz_count=len(quiz_items),
        quiz_view=quiz_view,
        preview_result={
            "total": total,
            "answered": answered,
            "correct": correct_count,
            "score_pct": score_pct,
            "per_q": {str(x["id"]): x for x in per_q},
        }
    )

