@app.route('/edit_chapter/<int:chapter_id>', methods=['GET', 'POST'])
def edit_chapter(chapter_id):
    # ✅ Ensure Admin Access
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized access!", "danger")
        return redirect(url_for('admin_login'))

    # ✅ Load Chapter
    chapter = db.session.get(CourseChapter, chapter_id)
    if not chapter:
        flash("⚠ Chapter not found!", "danger")
        return redirect(url_for('manage_courses'))

    if request.method == 'POST':
        import json

        # --- base fields ---
        chapter.title = (request.form.get('title') or '').strip()
        chapter.content = (request.form.get('content') or '').strip()

        # --- chapter type (defaults to 'text') ---
        chapter_type = (request.form.get('chapter_type')
                        or getattr(chapter, 'chapter_type', 'text')
                        or 'text').strip().lower()
        if hasattr(chapter, 'chapter_type'):
            chapter.chapter_type = chapter_type

        # --- audio path (only meaningful for audio_gate) ---
        audio_path = (request.form.get('audio_path') or '').strip()
        if hasattr(chapter, 'audio_path'):
            chapter.audio_path = audio_path if chapter_type == 'audio_gate' else None

        db.session.add(chapter)
        db.session.flush()

        # ----- Quiz Upsert (only when chapter is 'quiz') -----
        if getattr(chapter, 'chapter_type', None) == 'quiz':
            # Collect indices like quiz[0][...], quiz[1][...]
            indices = set()
            for k in request.form.keys():
                if k.startswith('quiz['):
                    idx = k.split('[', 1)[1].split(']', 1)[0]
                    if idx.isdigit():
                        indices.add(int(idx))
            indices = sorted(indices)

            # Map existing questions for upsert (support either relationship name)
            existing = {}
            rel = None
            if hasattr(chapter, 'quiz_items'):
                rel = chapter.quiz_items
            elif hasattr(chapter, 'quiz_questions'):
                rel = chapter.quiz_questions

            if rel is not None:
                # Calling .all() to avoid passing an AppenderQuery to Jinja later
                for q in rel.order_by(QuizQuestion.position.asc()).all():
                    existing[q.id] = q

            keep_ids = set()
            pos = 1

            for idx in indices:
                qtype = (request.form.get(
                    f'quiz[{idx}][qtype]') or 'mcq').strip().lower()
                prompt = (request.form.get(
                    f'quiz[{idx}][prompt]') or '').strip()
                qid_raw = request.form.get(
                    f'quiz[{idx}][id]')  # may be None/empty

                if not prompt:
                    continue  # skip empty rows

                # Build option payloads (both discrete columns + JSON)
                opt_a = (request.form.get(f'quiz[{idx}][opt_a]') or '').strip()
                opt_b = (request.form.get(f'quiz[{idx}][opt_b]') or '').strip()
                opt_c = (request.form.get(f'quiz[{idx}][opt_c]') or '').strip()
                opt_d = (request.form.get(f'quiz[{idx}][opt_d]') or '').strip()

                if qtype == 'tf':
                    correct = (request.form.get(
                        f'quiz[{idx}][correct_tf]') or 'true').strip().lower()
                    if correct not in ('true', 'false'):
                        correct = 'true'
                    json_opts = {'a': 'True', 'b': 'False'}
                    # for column schema we also set A/B accordingly
                    col_a, col_b, col_c, col_d = 'True', 'False', None, None
                else:
                    correct = (request.form.get(
                        f'quiz[{idx}][correct]') or 'a').strip().lower()
                    if correct not in ('a', 'b', 'c', 'd'):
                        correct = 'a'
                    json_opts = {'a': opt_a, 'b': opt_b,
                                 'c': opt_c, 'd': opt_d}
                    col_a, col_b, col_c, col_d = opt_a, opt_b, opt_c, opt_d

                # Update vs Insert
                if qid_raw and qid_raw.isdigit() and int(qid_raw) in existing:
                    q = existing[int(qid_raw)]
                    q.qtype = qtype
                    q.prompt = prompt
                    q.position = pos

                    # sync JSON if present
                    if hasattr(q, 'options'):
                        q.options = json.dumps(json_opts)

                    # sync column fields if present
                    if hasattr(q, 'option_a'):
                        q.option_a = col_a or ''
                    if hasattr(q, 'option_b'):
                        q.option_b = col_b or ''
                    if hasattr(q, 'option_c'):
                        q.option_c = col_c or ''
                    if hasattr(q, 'option_d'):
                        q.option_d = col_d or ''
                    if hasattr(q, 'correct'):
                        q.correct = correct

                    db.session.add(q)
                    keep_ids.add(q.id)
                else:
                    q = ChapterQuizQuestion(
                        chapter_id=chapter.id,
                        qtype=qtype,
                        prompt=prompt,
                        position=pos
                    )
                    # set JSON if present
                    if hasattr(q, 'options'):
                        q.options = json.dumps(json_opts)

                    # set column fields if present
                    if hasattr(q, 'option_a'):
                        q.option_a = col_a or ''
                    if hasattr(q, 'option_b'):
                        q.option_b = col_b or ''
                    if hasattr(q, 'option_c'):
                        q.option_c = col_c or ''
                    if hasattr(q, 'option_d'):
                        q.option_d = col_d or ''
                    if hasattr(q, 'correct'):
                        q.correct = correct

                    db.session.add(q)
                    db.session.flush()
                    keep_ids.add(q.id)

                pos += 1

            # Delete any questions removed from the form
            for qid, q in list(existing.items()):
                if qid not in keep_ids:
                    db.session.delete(q)

        db.session.commit()
        flash("✅ Chapter updated successfully!", "success")
        return redirect(url_for('manage_course', course_id=chapter.course_id))

    # ---------- Prepare data for template (Jinja-safe) ----------
    ctype = getattr(chapter, 'chapter_type', 'text') or 'text'

    # ---------- Load quiz items for this chapter ----------
    quiz_items = []
    try:
        rel = None
        if hasattr(chapter, 'quiz_items'):
            rel = chapter.quiz_items
        elif hasattr(chapter, 'quiz_questions'):
            rel = chapter.quiz_questions

        if rel is not None and hasattr(rel, 'order_by'):
            try:
                quiz_items = rel.order_by(
                    ChapterQuizQuestion.position.asc()).all()
            except Exception:
                quiz_items = rel.order_by(ChapterQuizQuestion.id.asc()).all()
        else:
            # ✅ Fallback: direct query (works even without relationships)
            quiz_items = (ChapterQuizQuestion.query
                          .filter_by(chapter_id=chapter.id)
                          .order_by(ChapterQuizQuestion.position.asc(),
                                    ChapterQuizQuestion.id.asc())
                          .all())
    except Exception:
        quiz_items = []

    return render_template(
        'edit_chapter.html',
        chapter=chapter,
        ctype=ctype,
        quiz_items=quiz_items,
        quiz_count=len(quiz_items)
    )

