@app.route('/upload_image', methods=['POST'])
def upload_image():
    if 'image' not in request.files or request.files['image'].filename == '':
        return jsonify({"error": "⚠ No file uploaded. Please try again."}), 400

    file = request.files['image']
    filename = f"{uuid.uuid4().hex}_{secure_filename(file.filename)}"

    upload_dir = os.path.join(current_app.static_folder, 'uploads')
    os.makedirs(upload_dir, exist_ok=True)

    file_path = os.path.join(upload_dir, filename)
    file.save(file_path)

    # Return absolute URL to the Flask-served media endpoint
    file_url = url_for('media', filename=filename, _external=True)

    return jsonify({"uploaded": 1, "url": file_url})


@app.route('/logout')
def logout():
    source = request.args.get('from', '')
    # Log before clearing session
    if session.get('student_id'):
        _log_session('student', session['student_id'], '', 'logout')
    elif session.get('admin_id'):
        _log_session('admin', session.get('admin_email', ''), session.get('admin_name', ''), 'logout')
    session.clear()
    flash('Logged out.', 'info')
    if source == 'admin':
        return redirect(url_for('admin_login'))
    if source == 'student':
        return redirect(url_for('frontpage'))
    return redirect(url_for('frontpage'))

