@app.route('/add_sub_chapter/<int:chapter_id>', methods=['GET', 'POST'])
def add_sub_chapter(chapter_id):
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    chapter = db.session.get(CourseChapter, chapter_id)
    if not chapter:
        flash("⚠ Chapter not found!", "danger")
        return redirect(url_for('manage_courses'))

    if request.method == 'POST':
        sub_title = request.form.get('sub_title', '').strip()
        sub_content = request.form.get('sub_content', '').strip()

        if not sub_title or not sub_content:
            flash("⚠ Sub-chapter title and content cannot be empty!", "danger")
            return redirect(url_for('add_sub_chapter', chapter_id=chapter_id))

        max_position = db.session.query(db.func.max(
            CourseChapter.position)).filter_by(parent_id=chapter.id).scalar()
        new_position = (max_position or 0) + 1

        new_sub_chapter = CourseChapter(
            course_id=chapter.course_id,
            parent_id=chapter.id,
            title=sub_title,
            content=sub_content,
            position=new_position,
        )

        db.session.add(new_sub_chapter)
        db.session.commit()

        flash("✅ Sub-Chapter Added Successfully!", "success")
        return redirect(url_for('edit_chapter', chapter_id=chapter.id))

    return render_template('add_sub_chapter.html', chapter=chapter)

