# Acknowledge_Chapter


@app.route('/acknowledge_chapter/<int:chapter_id>', methods=['POST'])
@require_popia
def acknowledge_chapter(chapter_id):
    if 'student_id' not in session:
        flash("⚠ Please log in first.", "danger")
        return redirect(url_for('login'))

    # Resolve the logged-in student (session['student_id'] is the student_number)
    student_number = str(session['student_id'])
    student = Student.query.filter_by(student_id=student_number).first()
    if not student:
        flash("⚠ Student not found!", "danger")
        return redirect(url_for('login'))
    sid = student.id  # ✅ use integer PK everywhere in CourseProgress

    # Chapter row
    chapter = db.session.get(CourseChapter, chapter_id)
    if not chapter:
        flash("⚠ Chapter not found!", "danger")
        return redirect(url_for('dashboard'))

    # Mascot gate (v1.2). The checkbox is disabled in the browser until the
    # narration (and any video) finishes, but that is only a courtesy; this is
    # the check that actually holds, because it reads the server-side playback
    # record rather than trusting the page.
    blocked = _mascot_gate_blocks(sid, chapter)
    if blocked:
        flash(blocked, "warning")
        return redirect(url_for('chapter_content', course_id=chapter.course_id,
                                chapter_id=chapter.id))

    # Upsert CourseProgress for this (student, course, chapter)
    progress = CourseProgress.query.filter_by(
        student_id=sid, course_id=chapter.course_id, chapter_id=chapter.id
    ).first()

    if not progress:
        progress = CourseProgress(
            student_id=sid,
            course_id=chapter.course_id,
            chapter_id=chapter.id,
            completed=True
        )
        db.session.add(progress)
    else:
        progress.completed = True

    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        current_app.logger.warning(f"acknowledge_chapter commit failed: {e}")
        flash("⚠ Could not save your progress. Please try again.", "danger")
        return redirect(url_for('chapter_content',
                                course_id=chapter.course_id,
                                chapter_id=chapter.id))

    # Next chapter (prefer position if available; else by id)
    q = CourseChapter.query.filter_by(course_id=chapter.course_id)
    if hasattr(CourseChapter, 'position'):
        q = q.order_by(CourseChapter.position.asc(), CourseChapter.id.asc())
    else:
        q = q.order_by(CourseChapter.id.asc())
    chapters = q.all()

    next_chapter = None
    for idx, ch in enumerate(chapters):
        if ch.id == chapter.id and idx + 1 < len(chapters):
            next_chapter = chapters[idx + 1]
            break

    if next_chapter:
        return redirect(url_for('chapter_content',
                                course_id=next_chapter.course_id,
                                chapter_id=next_chapter.id))

    flash("✅ All chapters completed! You're now ready for the final assessment.", "success")
    return redirect(url_for('final_assessment_intro', course_id=chapter.course_id))

