# --- Main route ---
@app.route('/course_content/<int:course_id>/chapter/<int:chapter_id>', methods=['GET', 'POST'])
@require_popia
def chapter_content(course_id, chapter_id):
    if 'student_id' not in session:
        flash("⚠ Please log in first.", "danger")
        return redirect(url_for('login'))

    # Resolve the logged-in student
    student_number = str(session['student_id'])
    student = Student.query.filter_by(student_id=student_number).first()
    if not student:
        flash("⚠ Student not found!", "danger")
        return redirect(url_for('login'))
    sid = student.id  # integer PK for CourseProgress

    # Load course + chapter
    course = Course.query.get_or_404(course_id)
    chapter = CourseChapter.query.get_or_404(chapter_id)
    if chapter.course_id != course.id:
        flash("⚠ Invalid chapter.", "danger")
        return redirect(url_for('dashboard'))

    # Update last_accessed, and stamp first_accessed_at on the very first visit
    # (that timestamp starts the CAA waiting period for the final assessment).
    enrollment = _touch_course_access(sid, course_id)

    # SAFE default
    ctype = (getattr(chapter, 'chapter_type', 'text') or 'text').lower()

    # ------- Prev / Next by intended ordering (order/position), fallback to id -------
    def _ordered_chapters(cid):
        q = CourseChapter.query.filter_by(course_id=cid)
        if hasattr(CourseChapter, 'order'):
            q = q.order_by(CourseChapter.order.asc(), CourseChapter.id.asc())
        elif hasattr(CourseChapter, 'position'):
            q = q.order_by(CourseChapter.position.asc(),
                           CourseChapter.id.asc())
        else:
            q = q.order_by(CourseChapter.id.asc())
        return q.all()

    ordered = _ordered_chapters(course.id)

    prev_chapter = None
    next_chapter = None
    for i, ch in enumerate(ordered):
        if ch.id == chapter.id:
            if i > 0:
                prev_chapter = ordered[i - 1]
            if i + 1 < len(ordered):
                next_chapter = ordered[i + 1]
            break

    # ------- Progress (count completed rows for this student/course) -------
    try:
        completed = CourseProgress.query.filter_by(
            student_id=sid, course_id=course_id, completed=True
        ).count()
        total = CourseChapter.query.filter_by(course_id=course_id).count() or 1
        progress_percentage = round((completed / total) * 100, 1)
    except Exception as e:
        current_app.logger.warning(f"progress calc failed: {e}")
        progress_percentage = 0

    # ------- Quiz handling (only when this chapter is a quiz) -------
    quiz_qs, quiz_result = [], None
    if ctype == 'quiz':
        quiz_qs = (
            ChapterQuizQuestion.query
            .filter_by(chapter_id=chapter.id)
            .order_by(ChapterQuizQuestion.position.asc(), ChapterQuizQuestion.id.asc())
            .all()
        )
        for q in quiz_qs:
            _attach_choices_for_view(q)

        if request.method == 'POST':
            total_q = len(quiz_qs)
            correct = 0
            answered = 0
            per_q = {}

            for q in quiz_qs:
                field = f"q_{q.id}"
                selected = (request.form.get(field) or "").strip()
                selected_l = selected.lower()
                correct_key = (getattr(q, 'correct', '') or '').strip().lower()

                has_options = any([
                    bool(getattr(q, 'option_a', None)),
                    bool(getattr(q, 'option_b', None)),
                    bool(getattr(q, 'option_c', None)),
                    bool(getattr(q, 'option_d', None)),
                ])
                is_tf = (getattr(q, 'qtype', '') or '').lower() in (
                    'tf', 'truefalse', 'true_false')

                if selected:
                    answered += 1

                if is_tf or has_options:
                    is_correct = (selected_l == (correct_key or 'a'))
                else:
                    is_correct = bool(selected)

                if is_correct:
                    correct += 1

                per_q[str(q.id)] = {
                    'selected': selected_l or selected,
                    'correct_key': correct_key,
                    'is_correct': is_correct
                }

            score_pct = round((correct / (total_q or 1)) * 100, 1)
            passed = score_pct >= 100.0

            if passed:
                try:
                    prog = CourseProgress.query.filter_by(
                        student_id=sid,
                        course_id=course_id,
                        chapter_id=chapter_id
                    ).first()
                    if not prog:
                        prog = CourseProgress(
                            student_id=sid,
                            course_id=course_id,
                            chapter_id=chapter_id,
                            completed=True
                        )
                        db.session.add(prog)
                    else:
                        prog.completed = True
                    db.session.commit()
                except Exception as e:
                    current_app.logger.warning(
                        f"quiz progress save failed: {e}")
                    db.session.rollback()
                flash(
                    f"✅ Perfect! You passed the quiz ({score_pct}%).", "success")
            else:
                flash(f"❌ You scored {score_pct}%. Try again.", "danger")

            quiz_result = {
                'total': total_q,
                'correct': correct,
                'answered': answered,
                'score_pct': score_pct,
                'per_q': per_q,
                'passed': passed,
            }

    # ------- Handbook URL from DB -------
    handbook_url = None
    try:
        _hb = Handbook.query.filter_by(course_id=course.id, is_active=True).first()
        if _hb:
            handbook_url = url_for('static', filename='manuals/' + _hb.pdf_filename)
    except Exception:
        handbook_url = None

    # ------- Final render (always reach here, not only inside quiz) -------
    return render_template(
        'chapter_content.html',
        course=course,
        chapter=chapter,
        prev_chapter=prev_chapter,
        next_chapter=next_chapter,
        progress_percentage=progress_percentage,
        # quiz payload
        quiz_qs=quiz_qs,
        quiz_items=quiz_qs,
        quiz_count=len(quiz_qs),
        quiz_result=quiz_result,
        handbook_url=handbook_url,
        # Mascot narration (v1.2). None when this slide has no voiceline, so
        # the template falls through to the existing behaviour.
        mascot=_mascot_payload(chapter, student),
    )

