@app.route('/reset_course', methods=['POST'])
def reset_course():
    """ Admin resets a student's course progress. Students CANNOT reset themselves. """

    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    student_id = request.form.get('student_id')
    course_id = request.form.get('course_id')

    student = db.session.get(Student, student_id)
    course = db.session.get(Course, course_id)

    if not student or not course:
        flash("⚠ Invalid student or course selection!", "danger")
        return redirect(url_for('view_students'))

    try:
        db.session.query(CourseProgress).filter(
            CourseProgress.student_id == student.id,
            CourseProgress.chapter_id.in_(
                db.session.query(CourseChapter.id).filter_by(
                    course_id=course.id)
            )
        ).delete(synchronize_session=False)

        enrollment = CourseEnrollment.query.filter_by(
            student_id=student.id, course_id=course.id).first()
        if enrollment:
            enrollment.reset_count = (enrollment.reset_count or 0) + 1
            enrollment.approved = False
            enrollment.completed = False
            enrollment.progress = 0

            db.session.commit()

        flash(f"✅ {student.name} {student.surname}'s progress for {course.title} has been reset! (Total resets: {enrollment.reset_count})", "success")

    except Exception as e:
        db.session.rollback()
        flash(f"❌ Error resetting progress: {str(e)}", "danger")

    return redirect(url_for('view_students'))

