@app.route('/verify-otp', methods=['GET', 'POST'])
def verify_otp():
    if 'pending_user' not in session:
        return redirect(url_for('signup'))

    email = session['pending_user']
    if request.method == 'POST':
        entered_otp = request.form['otp']

        student = Student.query.filter_by(email=email).first()

        if student and student.otp == entered_otp:
            student.otp = None
            db.session.commit()
            session['student_id'] = student.student_id
            session.pop('pending_user', None)
            flash("OTP verified successfully! Redirecting to dashboard.", "success")
            return redirect(url_for('dashboard'))
        else:
            flash("Invalid OTP. Please try again.", "danger")

    return render_template('verify_otp.html')


@app.route('/resend-otp', methods=['POST'])
def resend_otp():
    """Resend OTP to the user's email."""
    if 'pending_user' not in session:
        return jsonify({'message': 'No pending verification found. Please sign up again.'}), 400

    email = session['pending_user']
    student = Student.query.filter_by(email=email).first()

    if not student:
        return jsonify({'message': 'User not found. Please sign up again.'}), 404

    # Generate a new OTP
    new_otp = str(random.randint(10000000, 99999999))
    student.otp = new_otp
    db.session.commit()

    # Send the OTP
    if send_otp(email, new_otp):
        return jsonify({'message': f'OTP has been resent to {email}. Please check your inbox.'}), 200
    else:
        return jsonify({'message': 'Failed to send OTP. Please try again later.'}), 500


@app.route('/export_students')
def export_students():
    students = Student.query.all()

    data = []
    for student in students:
        data.append({
            "Student ID": student.student_id,
            "Name": student.name,
            "Surname": student.surname,
            "Email": student.email,
            "Cell Number": student.cell_number,
            "National ID": student.national_id,
            "Status": "Banned" if student.is_banned else "Active"
        })

    df = pd.DataFrame(data)
    file_path = "instance/students.xlsx"
    df.to_excel(file_path, index=False, engine='openpyxl')

    return send_file(file_path, as_attachment=True)


