@app.route('/manage_enrollments', methods=['GET', 'POST'])
def manage_enrollments():
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    # --- NEW: handle actions from the enrollments page (unenroll + email)
    if request.method == 'POST':
        action = request.form.get('action')
        student_id = request.form.get('student_id', type=int)
        course_id = request.form.get('course_id', type=int)

        if action == 'unenroll' and student_id and course_id:
            enrollment = CourseEnrollment.query.filter_by(
                student_id=student_id, course_id=course_id).first()
            if not enrollment:
                flash("⚠ Enrollment not found!", "danger")
                return redirect(url_for('manage_enrollments'))

            try:
                student = db.session.get(Student, student_id)
                course = db.session.get(Course, course_id)

                # Send notification email (same helper you use in the /unenroll_student route)
                if student and course:
                    # If your Student model uses full_name instead of name, swap accordingly.
                    student_name = f"{student.name} {student.surname}"
                    send_unenrollment_email(
                        student.email, student_name, course.title)

                db.session.delete(enrollment)
                db.session.commit()

                display_name = getattr(student, 'name', None) or getattr(
                    student, 'full_name', 'Student')
                course_title = getattr(course, 'title', 'course')
                flash(
                    f"✅ {display_name} has been unenrolled from {course_title}. Email sent.", "success")

            except Exception as e:
                db.session.rollback()
                flash(f"❌ Error unenrolling student: {e}", "danger")

            return redirect(url_for('manage_enrollments'))

        # Unknown or incomplete action payload
        flash("⚠ Invalid action or missing identifiers.", "warning")
        return redirect(url_for('manage_enrollments'))

    # --- Existing GET logic (unchanged)
    enrollments = db.session.query(
        CourseEnrollment, Student, Course).join(Student).join(Course).all()
    progress_data = {}

    for enrollment, student, course in enrollments:
        total_chapters = CourseChapter.query.filter_by(
            course_id=course.id).count()
        completed_chapters = CourseProgress.query.filter_by(
            student_id=student.id, course_id=course.id, completed=True
        ).count()

        if total_chapters > 0:
            progress_percentage = round(
                (completed_chapters / total_chapters) * 100)
        else:
            progress_percentage = 0

        # Convert last_accessed from UTC to SAST (UTC+2)
        last_accessed_sast = None
        if enrollment.last_accessed:
            last_accessed_sast = enrollment.last_accessed + timedelta(hours=2)

        progress_data[enrollment.id] = {
            'date_enrolled': enrollment.enrolled_at.strftime('%Y-%m-%d') if enrollment.enrolled_at else "N/A",
            'progress': progress_percentage,
            'last_accessed': last_accessed_sast
        }

    return render_template('manage_enrollments.html', enrollments=enrollments, progress_data=progress_data)

