@app.route('/admin/enrollment/<int:enrollment_id>/set_virtual', methods=['POST'])
def set_enrollment_virtual(enrollment_id):
    """Admin: set delivery_mode, Teams fields, and assessment_unlocked on a CourseEnrollment.

    Also flips the student's account_type hint so post-login routing sends them to the
    virtual dashboard when they have at least one virtual enrollment.
    """
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    enrollment = db.session.get(CourseEnrollment, enrollment_id)
    if not enrollment:
        flash("⚠ Enrollment not found.", "danger")
        return redirect(url_for('manage_enrollments'))

    delivery_mode = (request.form.get('delivery_mode') or 'in_person').strip().lower()
    if delivery_mode not in ('in_person', 'virtual'):
        delivery_mode = 'in_person'

    enrollment.delivery_mode = delivery_mode

    if delivery_mode == 'virtual':
        enrollment.teams_meeting_link = (request.form.get('teams_meeting_link') or '').strip() or None

        session_date_raw = (request.form.get('virtual_session_date') or '').strip()
        if session_date_raw:
            try:
                # HTML5 datetime-local format: 'YYYY-MM-DDTHH:MM'
                enrollment.virtual_session_date = datetime.strptime(session_date_raw, '%Y-%m-%dT%H:%M')
            except ValueError:
                try:
                    enrollment.virtual_session_date = datetime.strptime(session_date_raw, '%Y-%m-%d %H:%M')
                except ValueError:
                    enrollment.virtual_session_date = None
        else:
            enrollment.virtual_session_date = None

        enrollment.assessment_unlocked = bool(request.form.get('assessment_unlocked'))
    else:
        # Reverting to in-person: clear virtual-only fields.
        enrollment.teams_meeting_link = None
        enrollment.virtual_session_date = None
        enrollment.assessment_unlocked = False

    db.session.commit()
    flash("✅ Enrollment delivery settings updated.", "success")
    return redirect(url_for('manage_enrollments'))


@app.route('/admin/enrollments/create_virtual', methods=['GET', 'POST'])
def admin_create_virtual_enrollment():
    """Admin-initiated creation of a virtual enrollment (v1.1.0).

    Only lists courses where course_type='virtual'. Delivery mode is always virtual;
    there is no toggle. Normal enrollments remain student-self-serve and company-portal.
    """
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    if request.method == 'POST':
        student_id = request.form.get('student_id', type=int)
        course_id = request.form.get('course_id', type=int)

        if not student_id or not course_id:
            flash("⚠ Please select both a student and a virtual course.", "danger")
            return redirect(url_for('admin_create_virtual_enrollment'))

        student = db.session.get(Student, student_id)
        course = db.session.get(Course, course_id)
        if not student or not course:
            flash("⚠ Student or course not found.", "danger")
            return redirect(url_for('admin_create_virtual_enrollment'))

        if course.course_type != 'virtual':
            flash("⚠ Only virtual courses can be enrolled via this page.", "danger")
            return redirect(url_for('admin_create_virtual_enrollment'))

        existing = CourseEnrollment.query.filter_by(
            student_id=student.id, course_id=course.id
        ).first()
        if existing:
            flash(f"⚠ {student.name} {student.surname} is already enrolled in {course.title}.", "warning")
            return redirect(url_for('manage_enrollments'))

        enrollment = CourseEnrollment(
            student_id=student.id,
            course_id=course.id,
            approved=True,
            delivery_mode='virtual',
        )
        enrollment.teams_meeting_link = (request.form.get('teams_meeting_link') or '').strip() or None
        session_date_raw = (request.form.get('virtual_session_date') or '').strip()
        if session_date_raw:
            try:
                enrollment.virtual_session_date = datetime.strptime(session_date_raw, '%Y-%m-%dT%H:%M')
            except ValueError:
                enrollment.virtual_session_date = None
        enrollment.assessment_unlocked = bool(request.form.get('assessment_unlocked'))

        db.session.add(enrollment)
        db.session.commit()

        flash(f"✅ Enrolled {student.name} {student.surname} in virtual course {course.title}.", "success")
        return redirect(url_for('manage_enrollments'))

    students = Student.query.order_by(Student.surname.asc(), Student.name.asc()).all()
    courses = Course.query.filter_by(course_type='virtual').order_by(Course.title.asc()).all()

    # Build {student_id: [course_id, ...]} so the client can hide courses the
    # selected student is already enrolled in.
    enrollments_map = {}
    for row in db.session.query(CourseEnrollment.student_id, CourseEnrollment.course_id).all():
        enrollments_map.setdefault(row.student_id, []).append(row.course_id)

    return render_template(
        'admin_create_virtual_enrollment.html',
        students=students,
        courses=courses,
        enrollments_map=enrollments_map,
    )


@app.route('/admin/virtual_training', methods=['GET'])
def admin_virtual_training():
    """Unified Virtual Training hub.

    One screen to create virtual courses, see every virtual course, unlock/lock
    their final assessments, and manage enrolments (add new, remove) per course.
    Replaces the need to hop between Manage Courses / Manage Enrollments / the
    old /admin/virtual_courses page for anything virtual.
    """
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    virtual_courses = (
        Course.query
        .filter(Course.course_type == 'virtual')
        .order_by(Course.title.asc())
        .all()
    )

    # For each course, collect (enrollment, student) rows so we can render a list
    # of enrolled students per course in one query per course.
    course_rows = []
    for c in virtual_courses:
        enrollments = (
            db.session.query(CourseEnrollment, Student)
            .join(Student, CourseEnrollment.student_id == Student.id)
            .filter(CourseEnrollment.course_id == c.id)
            .order_by(Student.surname.asc(), Student.name.asc())
            .all()
        )
        quizzes = (
            VirtualQuiz.query
            .filter_by(course_id=c.id)
            .order_by(VirtualQuiz.position.asc(), VirtualQuiz.id.asc())
            .all()
        )
        handbook = Handbook.query.filter_by(course_id=c.id, is_active=True).first()
        course_rows.append({
            'course': c,
            'enrolled_count': len(enrollments),
            'enrollments': enrollments,
            'assessment_key': c.final_assessment_key or '',
            'quizzes': quizzes,
            'handbook': handbook,
        })

    # All students (for the "Add Student" search picker in each course section).
    students = Student.query.order_by(Student.surname.asc(), Student.name.asc()).all()

    # Pre-compute {student_id: [course_ids already enrolled]} so the picker can
    # hide students who are already in this course. One flat map client-side.
    enrolled_map = {}
    for row in db.session.query(CourseEnrollment.student_id, CourseEnrollment.course_id).all():
        enrolled_map.setdefault(row.student_id, []).append(row.course_id)

    return render_template(
        'admin_virtual_training.html',
        course_rows=course_rows,
        students=students,
        enrolled_map=enrolled_map,
    )


