@app.route('/virtual/<int:course_id>/handbook', methods=['GET'])
def virtual_course_handbook(course_id):
    """Student-side viewer for a virtual course's handbook.

    Requires the student to be enrolled in the course (and approved).
    Renders virtual_handbook.html, which embeds the PDF with PDF.js so the
    browser's native download / print toolbar is not in view.
    """
    if 'student_id' not in session:
        flash("Please log in first.", "warning")
        return redirect(url_for('login'))

    course = db.session.get(Course, course_id)
    if not course or course.course_type != 'virtual':
        flash("⚠ Virtual course not found.", "danger")
        return redirect(url_for('dashboard'))

    student = Student.query.filter_by(student_id=session['student_id']).first()
    if not student:
        flash("⚠ Student not found.", "danger")
        return redirect(url_for('login'))

    enrollment = CourseEnrollment.query.filter_by(
        student_id=student.id,
        course_id=course.id,
        approved=True,
    ).first()
    if not enrollment:
        flash("⚠ You are not enrolled in this course.", "danger")
        return redirect(url_for('dashboard'))

    handbook = Handbook.query.filter_by(course_id=course.id, is_active=True).first()
    if not handbook:
        flash("⚠ No handbook has been uploaded for this course yet.", "warning")
        return redirect(url_for('dashboard'))

    pdf_url = url_for('static', filename=f'manuals/{handbook.pdf_filename}')
    return render_template(
        'virtual_handbook.html',
        course=course,
        handbook=handbook,
        pdf_url=pdf_url,
    )


