@app.route('/admin/courses/create_virtual', methods=['GET', 'POST'])
def admin_create_virtual_course():
    """Dedicated creation page for virtual courses (v1.1.0).

    Collects title, description, and an optional cover image. Creates a Course row
    with course_type='virtual'. Virtual courses have no chapter content — the admin
    builds the final assessment via the existing final assessment tools after save.
    """
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    assessments = load_assessments_cfg() or []
    # Valid keys we'll accept on POST — validated server-side so admins can't pass junk.
    valid_keys = {a.get('key') for a in assessments if a.get('key')}

    if request.method == 'POST':
        title = (request.form.get('title') or '').strip()
        description = (request.form.get('description') or '').strip()
        assessment_key = (request.form.get('final_assessment_key') or '').strip()

        if not title or not description:
            flash("⚠ Title and description are required.", "danger")
            return redirect(url_for('admin_create_virtual_course'))

        if not assessment_key or assessment_key not in valid_keys:
            flash("⚠ Please pick a final assessment for this course.", "danger")
            return redirect(url_for('admin_create_virtual_course'))

        new_course = Course(
            title=title,
            description=description,
            course_type='virtual',
            final_assessment_key=assessment_key,
        )

        cover = request.files.get('cover_image')
        if cover and cover.filename:
            ext = cover.filename.rsplit('.', 1)[-1].lower() if '.' in cover.filename else ''
            if ext in {'png', 'jpg', 'jpeg', 'webp'}:
                upload_dir = os.path.join(current_app.static_folder, 'uploads', 'courses')
                os.makedirs(upload_dir, exist_ok=True)
                fname = f"{uuid.uuid4().hex}_{secure_filename(cover.filename)}"
                cover.save(os.path.join(upload_dir, fname))
                new_course.cover_image = fname
            else:
                flash("⚠ Cover image must be PNG, JPG, or WEBP. Course saved without cover.", "warning")

        db.session.add(new_course)
        db.session.commit()

        flash(f"✅ Virtual course '{title}' created and linked to its final assessment.", "success")
        return redirect(url_for('admin_virtual_training'))

    return render_template('admin_create_virtual_course.html', assessments=assessments)


@app.route('/fix_enrollments')
def fix_enrollments():
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    from datetime import datetime
    updated = 0

    # Fix missing enrolled_at
    enrollments = CourseEnrollment.query.filter_by(enrolled_at=None).all()
    for e in enrollments:
        e.enrolled_at = _now_sast()
        updated += 1

    # Fix missing progress
    progress_updates = CourseEnrollment.query.filter_by(progress=None).all()
    for e in progress_updates:
        e.progress = 0
        updated += 1

    db.session.commit()

    flash(f"✅ Fixed {updated} enrollment fields (date & progress).", "success")
    return redirect(url_for('manage_enrollments'))

