def _appeal_status_rank():
    """Sort expression matching _ticket_status_rank: open items float to top."""
    s = func.lower(AppealDispute.status)
    return case(
        (s == "open", 0),
        (s == "under review", 1),
        (s == "resolved", 3),
        else_=2,
    )


