@app.route('/support', methods=['GET', 'POST'])
def support():
    if 'student_id' not in session:
        flash("⚠ Please log in first.", "danger")
        return redirect(url_for('login'))

    student = Student.query.filter_by(student_id=session['student_id']).first()
    if not student:
        flash("⚠ User not found!", "danger")
        return redirect(url_for('dashboard'))

    courses = Course.query.join(CourseEnrollment).filter(
        CourseEnrollment.student_id == student.id,
        CourseEnrollment.approved == True
    ).all()

    ticket_id = str(random.randint(1000000000, 9999999999))

    if request.method == 'POST':
        course_id = request.form.get('course_id')
        problem_description = request.form.get('problem_description')

        if not course_id or not problem_description.strip():
            flash("⚠ Please complete all fields!", "danger")
            return redirect(url_for('support'))

        new_ticket = SupportTicket(
            ticket_id=ticket_id,
            student_id=student.id,
            course_id=course_id,
            email=student.email,
            problem_description=problem_description,
            status="Open"
        )
        db.session.add(new_ticket)
        db.session.commit()

        course = Course.query.get(course_id)

        send_ticket_confirmation(
            student.email, f"{student.name} {student.surname}", ticket_id, course.title)

        # Send notification to admins
        send_ticket_admin_notification(ticket_id, student, course.title, problem_description)

        flash(f"✅ Support ticket submitted! Ticket ID: {ticket_id}", "success")
        return redirect(url_for('dashboard'))

    # Get student's existing tickets for sidebar display
    tickets = SupportTicket.query.filter_by(student_id=student.id).order_by(
        SupportTicket.created_at.desc()).all()

    # Get student's existing appeals/disputes for the new sub-section
    appeals = AppealDispute.query.filter_by(student_id=student.id).order_by(
        AppealDispute.created_at.desc()).all()

    return render_template('support.html', student=student, courses=courses,
                          ticket_id=ticket_id, tickets=tickets, appeals=appeals,
                          sacaa_appeal_notice=SACAA_APPEAL_NOTICE)

