def send_ticket_closed_summary(ticket):
    """Send conversation summary email when ticket is closed."""
    messages = ticket.messages.order_by(SupportMessage.created_at.asc()).all()

    # Build conversation transcript
    transcript = ""
    transcript += f"ORIGINAL REQUEST ({ticket.created_at.strftime('%d %b %Y, %H:%M')}):\n"
    transcript += f"{ticket.problem_description}\n\n"

    for msg in messages:
        sender = "SUPPORT TEAM" if msg.author_type == 'admin' else "YOU"
        timestamp = msg.created_at.strftime('%d %b %Y, %H:%M')
        transcript += f"{sender} ({timestamp}):\n{msg.body}\n\n"

    subject = f"✅ Ticket #{ticket.ticket_id} Closed — {ticket.student.name} {ticket.student.surname}"
    body = f"""
Dear {ticket.student.name} {ticket.student.surname},

Your support ticket has been resolved and closed.

═══════════════════════════════════════════════════════
        TICKET SUMMARY
═══════════════════════════════════════════════════════

📌 Ticket ID:    {ticket.ticket_id}
📚 Course:       {ticket.course.title}
📅 Opened:       {ticket.created_at.strftime('%d %b %Y, %H:%M')}
📅 Closed:       {_now_sast().strftime('%d %b %Y, %H:%M')}

═══════════════════════════════════════════════════════
        CONVERSATION TRANSCRIPT
═══════════════════════════════════════════════════════

{transcript}
═══════════════════════════════════════════════════════

If you have any further questions, please submit a new support ticket.

Thank you for using Professional Training Support.

Kind regards,
Professional Training Support
    """
    try:
        msg = Message(subject=subject, recipients=[ticket.student.email], body=body)
        mail.send(msg)
        return True
    except Exception as e:
        print(f"❌ Error sending closed summary: {e}")
        return False


