@app.route('/ticket/<int:ticket_id>/reply', methods=['POST'])
def student_ticket_reply(ticket_id):
    """Student reply to their ticket."""
    if 'student_id' not in session:
        flash("⚠ Please log in first.", "danger")
        return redirect(url_for('login'))

    student = Student.query.filter_by(student_id=session['student_id']).first()
    if not student:
        flash("⚠ User not found!", "danger")
        return redirect(url_for('login'))

    ticket = db.session.get(SupportTicket, ticket_id)
    if not ticket or ticket.student_id != student.id:
        flash("⚠ Ticket not found!", "danger")
        return redirect(url_for('my_tickets'))

    if ticket.status == 'Closed':
        flash("⚠ This ticket is closed. You cannot reply.", "danger")
        return redirect(url_for('view_ticket', ticket_id=ticket.id))

    message_body = request.form.get('message', '').strip()
    if not message_body:
        flash("⚠ Message cannot be empty!", "danger")
        return redirect(url_for('view_ticket', ticket_id=ticket.id))

    # Create the message as student
    new_message = SupportMessage(
        ticket_id=ticket.id,
        author_type='student',
        author_email=student.email,
        body=message_body
    )
    db.session.add(new_message)

    # Update ticket status
    if ticket.status == 'Open':
        ticket.status = 'In Progress'

    db.session.commit()

    # Send email notification to admin
    send_reply_notification_to_admin(ticket, message_body)
    flash("✅ Reply sent. Support team has been notified.", "success")

    return redirect(url_for('view_ticket', ticket_id=ticket.id))


