@app.route('/upload_video', methods=['POST'])
def upload_video():
    print("📥 Upload route hit!")
    print("Session:", session)

    if 'student_id' not in session:
        return jsonify({'error': 'Unauthorized access. Please log in first!'}), 403

    student_id = session['student_id']
    student_folder = os.path.join(app.config['UPLOAD_FOLDER'], str(student_id))

    try:
        os.makedirs(student_folder, exist_ok=True)
    except Exception as e:
        return jsonify({'error': f'Error creating directory: {str(e)}'}), 500

    if 'video' not in request.files:
        return jsonify({'error': 'No file uploaded. Please try again!'}), 400

    video = request.files['video']
    if video.filename == '':
        return jsonify({'error': 'No selected file. Please choose a valid video file!'}), 400

    raw_filename = secure_filename(f"{student_id}_uploaded_video.webm")
    raw_video_path = os.path.join(student_folder, raw_filename)

    try:
        video.save(raw_video_path)

        return jsonify({
            'success': True,
            'message': '✅ Upload complete! Please keep your browser open until confirmation.',
            'video_url': url_for('uploaded_file', student_id=student_id, filename=raw_filename)
        })

    except Exception as e:
        return jsonify({'error': f'Failed to save video: {str(e)}'}), 500


