# Upload Video for Add Chapter and create course


ALLOWED_VIDEO_EXTS = {'.mp4', '.webm', '.ogg', '.mov', '.m4v', '.png', '.jpg', '.jpeg', '.svg', '.avif', '.webp', '.pdf'}


@app.route('/editor_upload_media', methods=['POST'])
def editor_upload_video():
    """
    Upload handler for TinyMCE media picker.
    Saves to /static/uploads and returns {"url": "..."}.
    """
    # Accept common keys TinyMCE/file inputs might use
    file = (
        request.files.get('video') or
        request.files.get('file') or
        next(iter(request.files.values()), None)
    )
    if not file or file.filename == '':
        return jsonify(error='No video file provided.'), 400

    ext = os.path.splitext(file.filename)[1].lower()
    if ext not in ALLOWED_VIDEO_EXTS:
        return jsonify(error=f'Unsupported video type: {ext}'), 415

    # Ensure upload dir exists (inside static so it’s directly served)
    dest_dir = os.path.join(app.static_folder, 'uploads')
    os.makedirs(dest_dir, exist_ok=True)

    # Safe unique filename
    safe = secure_filename(file.filename)
    if not safe:
        safe = f'video{ext}'
    fname = f'{uuid4().hex}_{safe}'
    dest_path = os.path.join(dest_dir, fname)

    try:
        file.save(dest_path)
    except Exception as e:
        return jsonify(error=f'Failed to save: {e}'), 500

    # Browser-loadable URL
    url = url_for('static', filename=f'uploads/{fname}', _external=False)
    return jsonify(location=url, url=url), 200


