@app.route('/complete_course/<int:course_id>', methods=['POST'])
@require_popia
def complete_course(course_id):
    """ Mark a course as completed when all chapters are finished """

    if 'student_id' not in session:
        flash("Please log in first.", "danger")
        return redirect(url_for('login'))

    student = Student.query.filter_by(student_id=session['student_id']).first()
    if not student:
        flash("User not found!", "danger")
        return redirect(url_for('login'))

    chapters = CourseChapter.query.filter_by(course_id=course_id).all()
    total_chapters = len(chapters)

    for chapter in chapters:
        progress = CourseProgress.query.filter_by(
            student_id=student.id, chapter_id=chapter.id).first()
        if not progress:
            progress = CourseProgress(
                student_id=student.id, course_id=course_id, chapter_id=chapter.id, completed=True)
            db.session.add(progress)
        else:
            progress.completed = True
    db.session.commit()

    completed_chapters = CourseProgress.query.filter_by(
        student_id=student.id, course_id=course_id, completed=True).count()

    print(
        f"🔍 DEBUG: Total Chapters = {total_chapters}, Completed = {completed_chapters}")

    enrollment = CourseEnrollment.query.filter_by(
        student_id=student.id, course_id=course_id).first()
    if enrollment and completed_chapters >= total_chapters:
        enrollment.completed = True
        db.session.commit()

        print(
            f"✅ DEBUG: Course {course_id} marked as completed for {student.name}")

    flash("🎓 Course marked as complete!", "success")
    return redirect(url_for('dashboard'))


