@app.route('/add_chapter/<int:course_id>', methods=['GET', 'POST'])
def add_chapter(course_id):
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    course = Course.query.get_or_404(course_id)

    if request.method == 'POST':
        title = request.form.get('title')
        chapter_type = request.form.get('chapter_type', 'text').strip().lower()
        content = request.form.get('content')
        audio_path = request.form.get('audio_path', '').strip() or None

        if not title or not title.strip():
            flash("⚠ Chapter title cannot be empty!", "danger")
            return redirect(url_for('add_chapter', course_id=course.id))

        # Order position
        next_position = len(course.chapters) + 1

        new_chapter = CourseChapter(
            course_id=course.id,
            title=title,
            chapter_type=chapter_type,
            content=content,
            position=next_position,
            audio_path=audio_path if chapter_type == "audio_gate" else None
        )

        # QUIZ HANDLING (your current logic stays untouched)
        if chapter_type == 'quiz':
            quiz_question = request.form.get('quiz_question')
            option_a = request.form.get('option_a')
            option_b = request.form.get('option_b')
            option_c = request.form.get('option_c')
            option_d = request.form.get('option_d')
            correct_answer = request.form.get('correct_answer')

            quiz_data = {
                "question": quiz_question,
                "options": {
                    "a": option_a,
                    "b": option_b,
                    "c": option_c,
                    "d": option_d
                },
                "correct": correct_answer
            }

            new_chapter.quiz_data = json.dumps(quiz_data)

        db.session.add(new_chapter)
        db.session.commit()

        flash("✅ Chapter added successfully!", "success")
        return redirect(url_for('manage_courses'))

    return render_template('add_chapter.html', course=course)

