@app.route('/create_user', methods=['GET', 'POST'])
@require_role('Super Admin')
def create_user():
    if request.method == 'POST':
        try:
            name = request.form['name']
            surname = request.form['surname']
            cell_number = request.form['cell_number']
            email = request.form['email']
            password = request.form['password']

            # Role assignment — Super Admins can only create Accountant/Admin
            requested_role = request.form.get('role', 'Admin')
            my_level = get_role_level(session.get('admin_role', ''))
            if my_level < get_role_level('Developer') and requested_role in ('Super Admin', 'Developer'):
                flash("You don't have permission to assign that role.", "danger")
                return redirect(url_for('manage_users'))

            password_hash = generate_password_hash(password)

            new_user = User(
                name=name,
                surname=surname,
                cell_number=cell_number,
                email=email,
                role=requested_role,
                password_hash=password_hash
            )
            db.session.add(new_user)
            db.session.commit()

            flash(f"Admin {name} created successfully!", "success")
            return redirect(url_for('manage_users'))

        except Exception as e:
            flash(f"Error creating user: {str(e)}", "danger")
            return redirect(url_for('manage_users'))

    # GET requests redirect to manage_users (form is now integrated there)
    return redirect(url_for('manage_users'))


