# Token Serializer for Password Reset Links
serializer = URLSafeTimedSerializer(os.environ["URLSAFE_SERIALIZER_KEY"])


def send_reset_link_email(email, full_name, reset_link):
    """ Sends a password reset email with a unique reset link """

    msg = Message(f"🔑 Password Reset — {full_name}", recipients=[email])
    msg.body = f"""
Dear {full_name},

You recently requested to reset your password. Click the link below to reset it:

🔗 Reset Password: {reset_link}

This link will expire in 1 hour. If you did not request this, you can ignore this email.

Regards,  
Professional Training Team
    """

    try:
        print(f"📨 Sending password reset email to {email}...")
        msg.body = msg.body.encode('utf-8').decode('utf-8')
        mail.send(msg)
        print(f"✅ Password reset link sent to {email}")
    except Exception as e:
        print(f"❌ Error sending email: {e}")


# Forgot Password (Request Reset Link)
@app.route('/forgot_password', methods=['GET', 'POST'])
def forgot_password():
    if request.method == 'POST':
        identifier = (request.form.get('identifier') or '').strip()

        # Try unique identifiers first (student_id, national_id)
        student = Student.query.filter(
            (Student.student_id == identifier) |
            (Student.national_id == identifier)
        ).first()

        if not student:
            # Try email — but only if it's unique to one student
            email_matches = Student.query.filter_by(email=identifier).all()
            if len(email_matches) == 1:
                student = email_matches[0]
            elif len(email_matches) > 1:
                flash("⚠ Multiple accounts share this email. Please enter your Student ID or ID Number instead, or contact your company administrator.", "warning")
                return redirect(url_for('forgot_password'))

        if student:
            # Serialize student PK instead of email (safe for shared emails)
            token = serializer.dumps(student.id, salt='password-reset-salt')
            reset_link = url_for('reset_password', token=token, _external=True)
            send_reset_link_email(student.email, f"{student.name} {student.surname}", reset_link)

            flash("✅ A password reset link has been sent to your email.", "success")
        else:
            flash("⚠ No account found. Check your Student ID, Email, or ID Number.", "danger")

        return redirect(url_for('login'))

    return render_template('forgot_password.html')


