# Route: Reset Password (Using Token)
@app.route('/reset_password/<token>', methods=['GET', 'POST'])
def reset_password(token):
    try:
        # Validate token and extract student PK (expires in 1 hour)
        student_pk = serializer.loads(
            token, salt="password-reset-salt", max_age=3600)
    except:
        flash("⚠ Invalid or expired reset link. Request a new one.", "danger")
        return redirect(url_for('forgot_password'))

    # Fetch User by PK (works for both int PK and legacy email tokens)
    if isinstance(student_pk, int):
        user = db.session.get(Student, student_pk)
    else:
        # Backwards compat: old tokens may contain an email string
        user = Student.query.filter_by(email=student_pk).first()
    if not user:
        flash("⚠ No account found!", "danger")
        return redirect(url_for('forgot_password'))

    if request.method == 'POST':
        new_password = request.form.get('new_password')
        confirm_password = request.form.get('confirm_password')

        # Ensure passwords match
        if new_password != confirm_password:
            flash("⚠ Passwords do not match. Try again.", "danger")
            return redirect(url_for('reset_password', token=token))

        if not new_password or len(new_password) < 6:
            flash("⚠ Password must be at least 6 characters!", "danger")
            return redirect(url_for('reset_password', token=token))

        # Hash and Store Password
        hashed_password = generate_password_hash(
            new_password, method='pbkdf2:sha256')
        user.password = hashed_password
        db.session.commit()

        print(f"✅ Password updated for {user.email}")

        # Send Confirmation Email
        try:
            full_name = f"{user.name} {user.surname}"
            msg = Message(f"🔑 Password Reset Confirmation — {full_name}", recipients=[user.email])
            msg.body = f"""
Dear {full_name},

Your password has been successfully reset. You can now log in with your new credentials.

📌 Username: {user.student_id}
🔑 New Password: {new_password}


Regards,
Professional Training Team
            """
            mail.send(msg)
            print(f"✅ Confirmation email sent to {user.email}")

        except Exception as e:
            print(f"❌ Error sending email: {e}")

        # Force Logout if they were logged in
        session.clear()

        flash("✅ Your password has been reset. You can now log in.", "success")
        return redirect(url_for('login'))

    return render_template('reset_password.html')

