@app.route('/search_video', methods=['POST'])
def search_video():
    student_attempt_id = request.form.get('studentattemptid_video')
    base_dir = '/var/www/proml.professionaltraining.co.za/wp-content/uploads/2024/'

    # List to store found video file paths
    found_videos = []

    def recursive_search(directory):
        for root, dirs, files in os.walk(directory):
            for file in files:
                if student_attempt_id in file:  # File matching the studentattemptid
                    found_videos.append(os.path.join(root, file))

    # Start the recursive search from the base directory
    recursive_search(base_dir)

    # Convert file paths to URLs for the web page
    found_videos_urls = [url_for('serve_video', filename=os.path.relpath(
        video, base_dir)) for video in found_videos]

    return jsonify(found_videos_urls)

