@app.route("/", methods=["GET", "POST"])
def index():
    if request.method == "POST":
        try:
            question_index = int(request.form.get("question_index", 0))
            question = questions[question_index]

            response_iter = model.generate_content(
                [video1, question],
                generation_config=generation_config,
                safety_settings=safety_settings,
                stream=True,
            )

            response_text = ""
            for response in response_iter:
                response_text += response.text

            is_yes = "yes" in response_text.lower()

            # Update the session variable
            current_responses = session.get("responses", [])
            # Add debug logging
            app.logger.debug(
                f"Current responses before update: {current_responses}")

            if not isinstance(current_responses, list):
                # Error logging
                app.logger.error("Session 'responses' is not a list!")
                current_responses = []

            session["responses"] = current_responses + [
                {"question": question, "response_text": response_text, "is_yes": is_yes}
            ]
            app.logger.debug(f"Updated responses: {session['responses']}")

            # Move to the next question or indicate completion
            if question_index < len(questions) - 1:
                session["question_index"] = question_index + 1
            else:
                session["completed"] = True

        # Generic error handler
        except Exception as e:
            app.logger.error(f"Error processing request: {e}")  # Log the error
            return render_template(
                "error.html", error_message="An error occurred while processing your request."
            ), 500

    return render_template(
        "index.html",
        questions=questions,
        responses=session.get("responses", []),
        question_index=session.get("question_index", 0),
        completed=session.get("completed", False),
    )

