@app.route('/update_student', methods=['POST'])
def update_student():
    """Admin: edit a student's details and optionally upload a replacement
    selfie or ID document on their behalf. Useful when a company can't /
    doesn't upload the docs themselves.
    """
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    student_id = request.form.get('student_id')
    student = db.session.get(Student, student_id)

    if not student:
        flash("⚠ Student not found!", "danger")
        return redirect(url_for('view_students'))

    # ---- Text fields. Only overwrite when something is actually posted so
    # an admin can save the form after editing just one field without wiping
    # the others.
    for db_field, form_field in (
        ("name", "name"),
        ("surname", "surname"),
        ("email", "email"),
        ("cell_number", "cell_number"),
        ("national_id", "national_id"),
        ("company", "company"),
    ):
        if form_field in request.form:
            value = (request.form.get(form_field) or "").strip()
            setattr(student, db_field, value or None if db_field in {"cell_number", "company"} else value)

    # ---- File uploads. The selfie + ID conventions mirror the student-side
    # onboarding flow (`{student_id}_selfie.jpg`, `{student_id}_id.{ext}`) so
    # the existing rendering / cert / proctor code can find them.
    base_folder = os.path.join(app.config.get('UPLOAD_FOLDER', os.path.join(app.root_path, 'uploads')),
                               student.student_id)
    os.makedirs(base_folder, exist_ok=True)

    SELFIE_EXTS = {'jpg', 'jpeg', 'png'}
    ID_EXTS = {'jpg', 'jpeg', 'png', 'pdf'}

    selfie_file = request.files.get('selfie_file')
    if selfie_file and selfie_file.filename:
        ext = selfie_file.filename.rsplit('.', 1)[-1].lower()
        if ext not in SELFIE_EXTS:
            flash("Selfie must be a JPG, JPEG, or PNG.", "warning")
        else:
            target = os.path.join(base_folder, f"{student.student_id}_selfie.jpg")
            try:
                selfie_file.save(target)
                student.selfie_filename = f"{student.student_id}_selfie.jpg"
            except Exception as e:
                flash(f"⚠ Could not save selfie: {e}", "warning")

    id_file = request.files.get('id_file')
    if id_file and id_file.filename:
        ext = id_file.filename.rsplit('.', 1)[-1].lower()
        if ext not in ID_EXTS:
            flash("ID document must be a JPG, JPEG, PNG, or PDF.", "warning")
        else:
            store_ext = 'pdf' if ext == 'pdf' else 'jpg'
            # Remove the alternate-extension version so the document doesn't
            # exist in two formats at once.
            other_ext = 'jpg' if store_ext == 'pdf' else 'pdf'
            old = os.path.join(base_folder, f"{student.student_id}_id.{other_ext}")
            if os.path.exists(old):
                try:
                    os.remove(old)
                except OSError:
                    pass
            target = os.path.join(base_folder, f"{student.student_id}_id.{store_ext}")
            try:
                id_file.save(target)
            except Exception as e:
                flash(f"⚠ Could not save ID document: {e}", "warning")

    try:
        db.session.commit()
        flash(f"✅ {student.name} {student.surname}'s details updated successfully!", "success")
    except Exception as e:
        db.session.rollback()
        flash(f"❌ Error updating student: {e}", "danger")

    # Optional: regenerate the password-setup token and re-send the invite
    # email to the (possibly just-updated) address. Lets admins correct a
    # mistyped or stale email and redirect the setup link in one action.
    if request.form.get('resend_invite') == '1':
        if not student.email:
            flash("⚠ Cannot resend invite: no email address on file.", "warning")
        else:
            try:
                token = secrets.token_urlsafe(32)
                temp_password = ''.join(random.choices(string.ascii_letters + string.digits, k=12))
                student.password_setup_token = token
                student.password_setup_token_expires = _now_sast() + timedelta(days=30)
                student.password = generate_password_hash(temp_password, method="pbkdf2:sha256")
                db.session.commit()

                setup_url = url_for("setup_password", token=token, _external=True)
                company_name = student.created_by_company.name if student.created_by_company else "Professional Training"
                send_email(
                    student.email,
                    f"Welcome to Professional Training — {student.name} {student.surname}!",
                    f"""<h2 style="color:#17306B; margin:0 0 16px;">Welcome, {student.name}!</h2>
                    <p>You have been registered for training by <strong>{company_name}</strong>.</p>
                    <p>Please click the button below to set your password and get started:</p>
                    <div style="text-align:center; margin:24px 0;">
                      <a href="{setup_url}" style="display:inline-block; background:#17306B; color:#fff; padding:12px 32px; border-radius:8px; text-decoration:none; font-weight:600;">Set Your Password</a>
                    </div>
                    <p style="font-size:13px; color:#64748b;">This link expires in 30 days. If it expires, contact your company administrator.</p>
                    <p style="font-size:13px; color:#64748b;">Your Student ID is: <strong>{student.student_id}</strong></p>
                    <p style="font-size:13px; color:#64748b;">Temporary password (if needed): <strong>{temp_password}</strong></p>"""
                )
                flash(f"📧 Invite resent to {student.email}.", "success")
            except Exception as e:
                db.session.rollback()
                flash(f"⚠ Could not send invite email: {e}", "warning")

    # Preserve the search query the admin had when they opened the edit modal
    # so they land back on the same filtered view (and immediately see the row
    # they just edited).
    return_q = (request.form.get('return_q') or '').strip()
    if return_q:
        return redirect(url_for('view_students', q=return_q))
    return redirect(url_for('view_students'))

