def _resolve_course_name(m):
    """Try to resolve a real course title for a ModerationForm with Unknown Course."""
    cid = to_int_or_none(m.courseid)
    # 1. Direct course ID lookup
    if cid is not None:
        c = db.session.get(Course, cid)
        if c:
            return c.title
    # 2. Match by final_assessment_key
    if m.courseid:
        c = Course.query.filter_by(
            final_assessment_key=str(m.courseid)).first()
        if c:
            return c.title
    # 3. Extract key from filename
    if m.courseid:
        key = extract_course_key_from_filename(str(m.courseid))
        found = find_course_by_key(key) if key else None
        if found:
            return found.title
    # 4. Check student enrollments
    if m.studentid:
        sid_int = to_int_or_none(m.studentid)
        student_obj = Student.query.filter_by(
            student_id=sid_int).first() if sid_int else None
        if student_obj and student_obj.enrollments:
            if len(student_obj.enrollments) == 1:
                return student_obj.enrollments[0].course.title
            elif cid is not None:
                for enr in student_obj.enrollments:
                    if enr.course_id == cid:
                        return enr.course.title
    return None


def _fix_unknown_courses(moderations):
    """Scan moderations and resolve any 'Unknown Course' entries. Returns True if DB was updated."""
    dirty = False
    for m in moderations:
        if m.coursename in ("Unknown Course", "Unknown", None, ""):
            resolved = _resolve_course_name(m)
            if resolved:
                m.coursename = resolved
                dirty = True
    if dirty:
        db.session.commit()
    return dirty


@app.route('/moderation_logs')
def moderation_logs():
    course_filter = request.args.get('course')
    query = ModerationForm.query

    if course_filter:
        query = query.filter_by(coursename=course_filter)

    moderations = query.order_by(ModerationForm.id.desc()).all()
    _fix_unknown_courses(moderations)

    all_courses = db.session.query(ModerationForm.coursename).distinct().all()
    return render_template("moderation_logs.html", moderations=moderations, courses=[c[0] for c in all_courses])

