# UPLOAD_ROOT will be set dynamically using app.config['UPLOAD_FOLDER']
# This is a fallback that will be overridden
UPLOAD_ROOT = None  # Will be set after app.config is properly configured

FILENAME_RE = re.compile(
    r'^\d+_\d{8}_(.+?)_\d{6}\.(?:webm|mp4|mkv|mov)$', re.IGNORECASE
)


def extract_course_key_from_filename(name: str) -> Optional[str]:
    if not name:
        return None
    base = os.path.basename(name)
    m = FILENAME_RE.match(base)
    return m.group(1).lower().strip() if m else None


COURSE_KEY_ALIASES = {
    'asat_cargo': 'asat2',
    'rpas_awareness': 'rpas_final',
    'airside': 'airside_induction',
}

def find_course_by_key(key: str):
    if not key:
        return None
    k = key.lower().strip()
    # 1. Exact match on final_assessment_key
    c = Course.query.filter(
        db.func.lower(Course.final_assessment_key) == k
    ).first()
    if c:
        return c
    # 2. Check alias mapping for known alternate keys
    alias = COURSE_KEY_ALIASES.get(k)
    if alias:
        c = Course.query.filter(
            db.func.lower(Course.final_assessment_key) == alias
        ).first()
        if c:
            return c
    return None


