@app.route('/review_escalation/<int:escalation_id>', methods=['GET', 'POST'])
def review_escalation(escalation_id):
    if 'admin_email' not in session:
        flash("⚠ Please log in as an admin to access this page.", "warning")
        return redirect(url_for('admin_login', next=request.url))

    escalation = ModerationEscalationLog.query.get_or_404(escalation_id)

    # escalation.student_id stores the public number
    student = Student.query.filter_by(student_id=escalation.student_id).first()
    if not student:
        flash("❌ Student not found.", "danger")
        return redirect(url_for("moderation"))

    # course_id can be int or a filename
    course = None
    video_key_filename = None
    course_id_int = to_int_or_none(escalation.course_id)
    if course_id_int is not None:
        course = db.session.get(Course, course_id_int)
    else:
        cid = str(escalation.course_id or "")
        if cid.lower().endswith((".webm", ".mp4", ".mkv", ".mov")):
            video_key_filename = os.path.basename(cid)

    # Moderation form lookup key
    lookup_key = str(course.id) if course else (
        str(escalation.course_id) if escalation.course_id is not None else None)

    mod = None
    if lookup_key:
        mod = (ModerationForm.query
               .filter_by(studentid=str(student.student_id), courseid=str(lookup_key))
               .order_by(ModerationForm.id.desc())
               .first())
    if not mod:
        mod = (ModerationForm.query
               .filter_by(studentid=str(student.student_id))
               .order_by(ModerationForm.id.desc())
               .first())

    # ===== Pull submission using Student PK (fix) =====
    submission = None
    if course is not None:
        submission = (FinalAssessmentSubmission.query
                      .filter_by(student_id=student.id, course_id=course.id)
                      .order_by(FinalAssessmentSubmission.id.desc())
                      .first())
    else:
        submission = (FinalAssessmentSubmission.query
                      .filter_by(student_id=student.id)
                      .order_by(FinalAssessmentSubmission.id.desc())
                      .first())

    # Infer course if still unknown: from submission, else from filename slug
    if course is None and submission and submission.course_id:
        course = db.session.get(Course, submission.course_id)
    if course is None:
        fname = video_key_filename or (
            submission.video_filename if submission else None)
        key = extract_course_key_from_filename(fname) if fname else None
        inferred = find_course_by_key(key) if key else None
        if inferred:
            course = inferred
    if course is None and escalation.course_id:
        # Try by final_assessment_key
        course = Course.query.filter_by(
            final_assessment_key=str(escalation.course_id)).first()
    if course is None and student and student.enrollments:
        # If student has exactly one enrollment, use that
        if len(student.enrollments) == 1:
            course = student.enrollments[0].course

    # Build video url; fallback to filesystem if DB missing
    video_url = None
    if submission and submission.video_filename:
        video_url = url_for(
            'uploaded_file', student_id=student.student_id, filename=submission.video_filename)
    if not video_url:
        # Use the configured upload folder path
        upload_root = app.config.get('UPLOAD_FOLDER', os.path.join(app.root_path, 'uploads'))
        folder = Path(upload_root) / str(student.student_id)
        if folder.exists():
            candidates = sorted(folder.glob(f"{student.student_id}_*.webm"),
                                key=lambda p: p.stat().st_mtime, reverse=True)
            if candidates:
                latest = candidates[0].name
                video_url = url_for(
                    'uploaded_file', student_id=student.student_id, filename=latest)
                if mod and not getattr(mod, "video_filename", None):
                    mod.video_filename = latest

    if request.method == 'POST':
        q1 = request.form.get("q1", "N/A")
        q2 = request.form.get("q2", "N/A")
        q3 = request.form.get("q3", "N/A")
        q4 = request.form.get("q4", "N/A")
        note = (request.form.get("admin_note") or "").strip()
        action = request.form.get("action")
        moderator_email = session.get('admin_email', 'admin')

        if not mod:
            mod = ModerationForm(
                studentid=str(student.student_id),
                studentname=f"{student.name} {student.surname}",
                coursename=(course.title if course else "Unknown Course"),
                courseid=(str(course.id) if course else (
                    str(escalation.course_id) if escalation.course_id is not None else "N/A")),
                coursecompletiondate=_now_sast()
            )
            db.session.add(mod)

        # Update moderation metadata (do NOT overwrite original Q&A answers)
        mod.moderationdate = _now_sast()
        mod.moderatorname = moderator_email
        if submission and submission.video_filename:
            mod.video_filename = submission.video_filename

        # Store reviewer answers on the escalation log
        escalation.review_q1 = q1
        escalation.review_q2 = q2
        escalation.review_q3 = q3
        escalation.review_q4 = q4
        escalation.action_taken = action
        escalation.admin_note = note
        escalation.reviewed_by = moderator_email
        escalation.reviewed_at = _now_sast()

        # Get course title - try multiple sources with video filename fallback
        def extract_friendly_course_name(filename):
            """Extract a friendly course name from video filename."""
            if not filename:
                return None
            lower_fname = str(filename).lower()
            if 'rpas' in lower_fname:
                return "RPAS Final Assessment"
            elif 'drone' in lower_fname:
                return "Drone Operations Final Assessment"
            elif 'aviation' in lower_fname:
                return "Aviation Final Assessment"
            elif 'safety' in lower_fname:
                return "Safety Final Assessment"
            elif 'pilot' in lower_fname:
                return "Pilot Final Assessment"
            return None

        course_title_for_email = None
        if course:
            course_title_for_email = course.title
        # Skip if mod.coursename is "Unknown Course" - try to get a better name
        if not course_title_for_email and mod and mod.coursename and mod.coursename not in ("Unknown Course", "Unknown"):
            # Check if coursename is a friendly name or needs extraction
            extracted = extract_friendly_course_name(str(mod.coursename))
            course_title_for_email = extracted if extracted else mod.coursename
        # Try to extract friendly name from video filename stored in course_id
        if not course_title_for_email and escalation.course_id:
            course_title_for_email = extract_friendly_course_name(str(escalation.course_id))
        if not course_title_for_email:
            course_title_for_email = "Final Assessment"

        subject_line = ""
        html_body = ""

        # LOGIC: Approve escalation = concern was valid, keep student suspended
        #        Decline escalation = concern was not valid, reactivate student
        if action == "approve":
            # Approve the escalation - keep student suspended
            mod.feedback = f"[Escalation Upheld] {note}"
            flash(
                f"✅ Escalation approved. Student {student.student_id} remains suspended.", "success")
            subject_line = f"🚫 Escalation Upheld: {student.student_id}"
            html_body = f"""
                <h3>🚫 Escalation Upheld - Student Remains Suspended</h3>
                <p><strong>Student:</strong> {student.name} {student.surname} ({student.student_id})</p>
                <p><strong>Course:</strong> {course_title_for_email}</p>
                <p><strong>Reviewed By:</strong> {moderator_email}</p>
                <p><strong>Reviewed On:</strong> {utcstamp()}</p>
                <p><strong>Decision Note:</strong><br>{note}</p>
            """
        elif action == "decline":
            # Decline the escalation - reactivate student
            student.is_suspended = False
            mod.feedback = f"[Escalation Declined - Student Reactivated] {note}"
            flash(f"✅ Escalation declined. Student {student.student_id} has been reactivated.", "success")
            subject_line = f"✅ Escalation Declined: {student.student_id}"
            html_body = f"""
                <h3>✅ Escalation Declined - Student Reactivated</h3>
                <p><strong>Student:</strong> {student.name} {student.surname} ({student.student_id})</p>
                <p><strong>Course:</strong> {course_title_for_email}</p>
                <p><strong>Reviewed By:</strong> {moderator_email}</p>
                <p><strong>Reviewed On:</strong> {utcstamp()}</p>
                <p><strong>Reason:</strong><br>{note}</p>
            """
        else:
            flash("⚠ Invalid action submitted.", "warning")

        if subject_line:
            try:
                # Get dynamic email recipients for moderation category
                moderation_recipients = get_recipients_for_category('moderation')
                if not moderation_recipients:
                    moderation_recipients = ["admin@professionaltraining.co.za"]  # Fallback

                msg = EmailMessage()
                msg['Subject'] = subject_line
                msg['From'] = "no-reply@professionaltraining.co.za"
                msg["To"] = moderation_recipients
                msg.set_content(html_body, subtype='html')
                with smtplib.SMTP('smtp.professionaltraining.co.za', 587, timeout=10) as smtp:
                    smtp.starttls()
                    smtp.login('no-reply@professionaltraining.co.za', os.environ.get("MAIL_PASSWORD", "dev-disabled"))
                    smtp.send_message(msg)
                    print("✅ Review notification email sent successfully.")
                    app.logger.info(f"Review notification email sent for escalation {escalation_id}")
            except Exception as e:
                error_msg = str(e)
                print(f"❌ Review email send error: {error_msg}")
                app.logger.error(f"Review email failed: {error_msg}")
                # Log email configuration for debugging
                print(f"📧 Email Config - Server: {app.config.get('MAIL_SERVER')}, Port: {app.config.get('MAIL_PORT')}, TLS: {app.config.get('MAIL_USE_TLS')}")
                print(f"📧 Email Config - Username: {app.config.get('MAIL_USERNAME')}")
                import traceback
                traceback.print_exc()
                flash("⚠ Email could not be sent, but moderation was saved.", "warning")

        db.session.commit()
        return redirect(url_for("moderation"))

    return render_template(
        "review_moderation.html",
        escalation=escalation,
        mod=mod,
        student=student,
        course=course,
        video_url=video_url
    )


