@app.route('/escalate_moderation', methods=["POST"])
def escalate_moderation():
    student_id = (request.form.get("student_id") or "").strip()
    course_id = (request.form.get("course_id") or "").strip()
    course_name_from_form = (request.form.get("course_name") or "").strip()
    escalation_note = (request.form.get("escalation_note") or "").strip()

    # Capture moderation form answers (sent from JavaScript)
    q1 = request.form.get("q1", "")
    q2 = request.form.get("q2", "")
    q3 = request.form.get("q3", "")
    q4 = request.form.get("q4", "")
    q5 = request.form.get("q5", "")
    q6 = request.form.get("q6", "")
    admin_note = (request.form.get("admin_note") or "").strip()

    def to_int_or_none(v):
        try:
            return int(v)
        except (TypeError, ValueError):
            return None

    try:
        print("📥 Received escalation for student:",
              student_id, "course:", course_id)

        sid = to_int_or_none(student_id)
        if not sid:
            flash("❌ Invalid student id.", "danger")
            return redirect(url_for("moderation"))

        student = db.session.get(Student, sid)
        if not student:
            print("❌ Student not found.")
            flash("❌ Student not found.", "danger")
            return redirect(url_for("moderation"))

        student.is_suspended = True
        db.session.commit()
        print("🔒 Student suspended")

        course_int = to_int_or_none(course_id)
        course_obj = db.session.get(
            Course, course_int) if course_int is not None else None

        # Try to find course by other means if not found by ID
        if not course_obj and course_id:
            # Try by final_assessment_key
            course_obj = Course.query.filter_by(
                final_assessment_key=str(course_id)).first()
        if not course_obj and course_id:
            # Try extracting key from filename
            key = extract_course_key_from_filename(str(course_id))
            course_obj = find_course_by_key(key) if key else None
        if not course_obj and student:
            # Fallback: if student has exactly one enrollment, use that course
            if student.enrollments and len(student.enrollments) == 1:
                course_obj = student.enrollments[0].course

        # Use course title from DB, or fallback to form-provided name, or "Unknown Course"
        if course_obj:
            course_title = course_obj.title
        elif course_name_from_form:
            course_title = course_name_from_form
        else:
            course_title = "Unknown Course"
        # keep filename or numeric id
        courseid_to_store = course_obj.id if course_obj else course_id

        # Find or create moderation
        mod = (ModerationForm.query
               .filter_by(studentid=str(student.student_id), courseid=str(courseid_to_store))
               .order_by(ModerationForm.id.desc())
               .first())

        # Determine if we have actual moderation answers
        has_answers = any([q1, q2, q3, q4, q5, q6])

        if not mod:
            print("⚠ No moderation record found. Creating new record.")
            mod = ModerationForm(
                studentattemptid=None,
                studentname=f"{student.name} {student.surname}",
                studentid=student.student_id,
                coursename=course_title,
                courseid=courseid_to_store,
                moderatorname=session.get('admin_email', '(Escalated)'),
                coursecompletiondate=_now_sast(),
                moderationdate=_now_sast(),
                question1=q1 or "Pending", question2=q2 or "Pending", question3=q3 or "Pending",
                question4=q4 or "Pending", question5=q5 or "Pending", question6=q6 or "Pending",
                question7="Pending",
                feedback="Escalated for review",
                video_filename=None,
                admin_note=admin_note or None
            )
            db.session.add(mod)
            db.session.commit()
            print("✅ Moderation created with ID:", mod.id)
        else:
            print("📄 Found existing moderation ID:", mod.id)
            # Update with answers if provided
            if has_answers:
                mod.question1 = q1 or mod.question1
                mod.question2 = q2 or mod.question2
                mod.question3 = q3 or mod.question3
                mod.question4 = q4 or mod.question4
                mod.question5 = q5 or mod.question5
                mod.question6 = q6 or mod.question6
                mod.moderatorname = session.get('admin_email', mod.moderatorname)
                mod.moderationdate = _now_sast()
                if admin_note:
                    mod.admin_note = admin_note
                db.session.commit()
                print("✅ Updated moderation with form answers")

        # NOTE: keep your log's course_id type consistent with your DB column (string vs int)
        escalation_log = ModerationEscalationLog(
            moderation_id=mod.id,
            student_id=student.student_id,
            course_id=course_id,  # if your column is Integer, change to course_int instead
            reason=escalation_note,
            escalated_by=session.get('admin_email', 'system')
        )
        db.session.add(escalation_log)
        db.session.commit()
        print("✅ Escalation log committed with ID:", escalation_log.id)

        review_link = url_for("review_escalation",
                              escalation_id=escalation_log.id, _external=True)

        # Get recipients from database only (no fallback)
        moderation_recipients = get_recipients_for_category('moderation')
        if not moderation_recipients:
            print("⚠ No moderation recipients configured. Escalation email not sent.")
            flash("⚠ Escalation logged but email not sent (no recipients configured).", "warning")
            return redirect(url_for("moderation"))

        # Get national_id for the email
        national_id = student.national_id or "N/A"

        msg = Message(
            subject=f"🚩 Moderation Escalated: {student.name} {student.surname} - {course_title}",
            recipients=moderation_recipients
        )
        # Use msg.html for HTML content (not msg.body which is plain text)
        msg.html = f"""
        <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
            <div style="background: #dc2626; color: white; padding: 20px; border-radius: 8px 8px 0 0;">
                <h2 style="margin: 0;">🚩 Moderation Escalation Alert</h2>
            </div>
            <div style="background: #f8fafc; padding: 20px; border: 1px solid #e2e8f0;">
                <table style="width: 100%; border-collapse: collapse;">
                    <tr>
                        <td style="padding: 8px 0; font-weight: bold; width: 140px;">Student Name:</td>
                        <td style="padding: 8px 0;">{student.name} {student.surname}</td>
                    </tr>
                    <tr>
                        <td style="padding: 8px 0; font-weight: bold;">National ID:</td>
                        <td style="padding: 8px 0;">{national_id}</td>
                    </tr>
                    <tr>
                        <td style="padding: 8px 0; font-weight: bold;">Course:</td>
                        <td style="padding: 8px 0;">{course_title}</td>
                    </tr>
                    <tr>
                        <td style="padding: 8px 0; font-weight: bold;">Escalated By:</td>
                        <td style="padding: 8px 0;">{session.get('admin_email', 'system')}</td>
                    </tr>
                    <tr>
                        <td style="padding: 8px 0; font-weight: bold;">Reason:</td>
                        <td style="padding: 8px 0;">{escalation_note or 'No reason provided'}</td>
                    </tr>
                </table>
            </div>
            <div style="background: #17306B; padding: 20px; border-radius: 0 0 8px 8px;">
                <p style="color: white; margin: 0 0 10px 0;">Click below to review this escalation:</p>
                <a href="{review_link}" style="display: inline-block; background: white; color: #17306B; padding: 12px 24px; text-decoration: none; border-radius: 6px; font-weight: bold;">
                    Review Escalation
                </a>
            </div>
            <p style="color: #64748b; font-size: 12px; margin-top: 15px;">
                🕒 {_now_sast().strftime('%Y-%m-%d %H:%M:%S')} UTC
            </p>
        </div>
        """
        try:
            print("📨 Preparing to send escalation email...")
            mail.send(msg)
            print("✅ Escalation email sent successfully.")
            app.logger.info(f"Escalation email sent successfully for student {student.student_id}")
        except Exception as email_error:
            error_msg = str(email_error)
            print(f"❌ Escalation email sending failed: {error_msg}")
            app.logger.error(f"Escalation email failed: {error_msg}")
            # Log email configuration for debugging
            print(f"📧 Email Config - Server: {app.config.get('MAIL_SERVER')}, Port: {app.config.get('MAIL_PORT')}, TLS: {app.config.get('MAIL_USE_TLS')}")
            print(f"📧 Email Config - Username: {app.config.get('MAIL_USERNAME')}")
            import traceback
            traceback.print_exc()
            flash("⚠ Email failed to send, but escalation was logged.", "warning")

        flash("✅ Escalation recorded and email sent.", "success")
        return redirect(url_for("moderation", escalated=1))

    except Exception as e:
        db.session.rollback()
        print("❌ Exception occurred:", e)
        flash(f"❌ Escalation failed: {e}", "danger")
        return redirect(url_for("moderation"))
