def to_int_or_none(v):
    try:
        return int(v)
    except (TypeError, ValueError):
        return None


def parse_dt_iso(s: str):
    if not s:
        return None
    for fmt in ("%Y-%m-%dT%H:%M", "%Y-%m-%dT%H:%M:%S"):
        try:
            return dt.strptime(s, fmt)
        except ValueError:
            pass
    return None


@app.route('/submit_moderation', methods=['POST'])
def submit_moderation():
    student_id_raw = (request.form.get('student_id') or '').strip()
    course_id_raw = (request.form.get('course_id') or '').strip()
    completion_raw = (request.form.get('completion_date') or '').strip()
    moderation_raw = (request.form.get('moderation_date') or '').strip()
    q1 = request.form.get('q1')
    q2 = request.form.get('q2')
    q3 = request.form.get('q3')
    q4 = request.form.get('q4')
    q5 = request.form.get('q5')
    q6 = request.form.get('q6')
    comments = (request.form.get('comments') or '').strip()

    try:
        sid = to_int_or_none(student_id_raw)
        if not sid:
            flash("❌ Invalid student id.", "danger")
            return redirect(url_for('moderation'))

        student = db.session.get(Student, sid)
        if not student:
            flash("❌ Student not found.", "danger")
            return redirect(url_for('moderation'))

        # course_id may be a real integer OR a filename/attempt key
        course_int = to_int_or_none(course_id_raw)
        course_obj = db.session.get(
            Course, course_int) if course_int is not None else None
        if not course_obj and course_id_raw:
            course_obj = Course.query.filter_by(
                final_assessment_key=str(course_id_raw)).first()
        if not course_obj and course_id_raw:
            key = extract_course_key_from_filename(str(course_id_raw))
            course_obj = find_course_by_key(key) if key else None
        if not course_obj and student and student.enrollments:
            if len(student.enrollments) == 1:
                course_obj = student.enrollments[0].course
        course_title = course_obj.title if course_obj else "Unknown Course"
        # keep filename when not numeric
        courseid_to_store = course_obj.id if course_obj else course_id_raw

        # completion_dt = parse_dt_iso(completion_raw) or dt.utcnow()
        completion_dt = parse_dt_iso(completion_raw) or _now_sast()
        moderation_dt = parse_dt_iso(moderation_raw) or _now_sast()

        # Upsert latest ModerationForm for this student/course key
        mod = (ModerationForm.query
               .filter_by(studentid=str(student.student_id), courseid=str(courseid_to_store))
               .order_by(ModerationForm.id.desc())
               .first())

        def yn(v): return "Yes" if v == "1" else "No"

        if not mod:
            mod = ModerationForm(
                studentattemptid=None,
                studentname=f"{student.name} {student.surname}",
                studentid=student.student_id,           # your public/student number field
                coursename=course_title,
                courseid=courseid_to_store,
                moderatorname=session.get('admin_email', '(Pending)'),
                coursecompletiondate=completion_dt,
                moderationdate=moderation_dt,
                question1=yn(q1), question2=yn(q2), question3=yn(q3),
                question4=yn(q4), question5=yn(q5), question6=yn(q6),
                question7="N/A",
                feedback=comments or "—",
                video_filename=None,
                admin_note=None
            )
            db.session.add(mod)
        else:
            mod.coursename = course_title
            mod.coursecompletiondate = completion_dt
            mod.moderationdate = moderation_dt
            mod.question1 = yn(q1)
            mod.question2 = yn(q2)
            mod.question3 = yn(q3)
            mod.question4 = yn(q4)
            mod.question5 = yn(q5)
            mod.question6 = yn(q6)
            mod.feedback = comments or "—"

        db.session.commit()
        flash("✅ Moderation saved.", "success")
        return redirect(url_for('moderation'))

    except Exception as e:
        db.session.rollback()
        app.logger.exception("Submit moderation failed")
        flash(f"❌ Failed to save moderation: {e}", "danger")
        return redirect(url_for('moderation'))
