def now_utc():
    return _now_sast()


def parse_dt_iso(s: str):
    if not s:
        return None
    for fmt in ("%Y-%m-%dT%H:%M", "%Y-%m-%dT%H:%M:%S"):
        try:
            # assume local input, convert to aware UTC if you want:
            naive = datetime.strptime(s, fmt)
            # if your app runs in local time, convert to UTC as needed; otherwise:
            return naive.replace(tzinfo=timezone.utc)
        except ValueError:
            pass
    return None

