@app.route('/get_student_info/<student_id>')
def get_student_info(student_id):
    # Find student by internal PK
    student = Student.query.filter_by(id=student_id).first()
    if not student:
        return jsonify({"error": "Student not found"}), 404

    completed = []

    # --- Step 1: Get DB-backed completed courses ---
    courses = db.session.query(
        Course.id.label("course_id"),
        Course.title.label("course_name")
    ).join(CourseEnrollment, Course.id == CourseEnrollment.course_id) \
     .filter(
         CourseEnrollment.student_id == student_id,
         CourseEnrollment.completed == True
    ).all()

    completed.extend([dict(row._asdict()) for row in courses])

    # --- Step 2: Look for video files in uploads/<student_number>/ ---
    student_number = student.student_id  # external folder name
    uploads_dir = os.path.join(app.config.get(
        "UPLOAD_FOLDER", "/var/enroll/uploads"), str(student_number))

    # Track which Course IDs Step 1 already added so Step 2 can avoid listing
    # the same submission twice. We also build a map of (assessment key ->
    # Course) for every enrollment so Step 2 can fall back to the enrollment's
    # Course.title when the student has the enrollment but Step 1 didn't pick
    # it up (e.g. the enrollment isn't flagged completed yet but the student
    # has already submitted the proctored attempt).
    step1_course_ids = {c["course_id"] for c in completed}
    key_to_enrolled_course = {}
    if student.enrollments:
        for enr in student.enrollments:
            course = enr.course
            key = getattr(course, "final_assessment_key", None) if course else None
            if key and course:
                key_to_enrolled_course[key.lower()] = course

    def _extract_course_key(filename):
        """Pull the course_key segment from a proctoring filename:
        <student_id>_<YYYYMMDD>_<course_key>_<HHMMSS>.<ext>
        Returns lowercased key or None.
        """
        name = os.path.splitext(filename)[0]
        parts = name.split('_')
        if len(parts) < 3:
            return None
        key_parts = parts[2:]
        if key_parts and key_parts[-1].isdigit() and len(key_parts[-1]) >= 4:
            key_parts = key_parts[:-1]
        return '_'.join(key_parts).lower() if key_parts else None

    def get_friendly_course_name(filename):
        """Resolve a friendly course title from a video filename. Returns None
        when the entry should be skipped because Step 1 already listed this
        enrollment.
        """
        course_key = _extract_course_key(filename)
        if not course_key:
            return f"{os.path.splitext(filename)[0].replace('_', ' ').title()} Final Assessment"

        # Does the student have an enrollment for a Course that uses this key?
        enrolled_course = key_to_enrolled_course.get(course_key)
        if enrolled_course:
            if enrolled_course.id in step1_course_ids:
                # Step 1 already listed this submission with the real title.
                return None
            # Student is enrolled but Step 1 didn't pick it up (enrollment not
            # flagged completed yet). Use the enrollment's Course.title so the
            # admin still sees the correct label.
            return f"{enrolled_course.title} Final Assessment"

        # No matching enrollment — try a global exact match on
        # final_assessment_key or code. The previous implementation used
        # hardcoded substring matches (rpas/drone/aviation/safety/pilot) and a
        # `LIKE %course_key%` title match. Both could return the wrong course
        # when titles or keys overlapped (e.g. a DG D&E video whose key matched
        # a Level 3 Airlines course).
        course_match = Course.query.filter(
            db.or_(
                db.func.lower(Course.final_assessment_key) == course_key,
                db.func.lower(Course.code) == course_key,
            )
        ).first()
        if course_match:
            return f"{course_match.title} Final Assessment"

        # Last resort: show the raw key so the admin sees what was recorded.
        return f"{course_key.replace('_', ' ').title()} Final Assessment"

    if os.path.isdir(uploads_dir):
        for fname in sorted(os.listdir(uploads_dir), reverse=True):
            if fname.lower().endswith((".mp4", ".webm", ".mov", ".avi", ".mkv")):
                friendly_name = get_friendly_course_name(fname)
                if friendly_name is None:
                    continue  # already covered by an explicit enrollment
                completed.append({
                    "course_id": fname,  # use filename as id
                    "course_name": friendly_name
                })

    # --- Step 3: Filter out already-moderated courses ---
    moderated_ids = {
        m.courseid
        for m in ModerationForm.query
            .filter_by(studentid=str(student.student_id))
            .with_entities(ModerationForm.courseid)
            .all()
    }
    completed = [
        c for c in completed
        if str(c["course_id"]) not in moderated_ids
    ]

    # --- Step 4: Return final payload ---
    payload = {
        "name": student.name,
        "national_id": student.national_id,
        "completed_courses": completed
    }
    return jsonify(payload)

