class FinalAssessmentQuestion(db.Model):
    __tablename__ = "final_assessment_question"
    id = db.Column(db.Integer, primary_key=True)

    # legacy FK + new code
    course_id = db.Column(db.Integer, nullable=False)
    # can be NULL on legacy rows
    course_code = db.Column(db.String(64), index=True)

    question = db.Column(db.Text, nullable=False)
    option_a = db.Column(db.String(255), nullable=False)
    option_b = db.Column(db.String(255), nullable=False)
    option_c = db.Column(db.String(255), nullable=False)
    option_d = db.Column(db.String(255), nullable=False)

    # map Python attr `correct` -> DB column `correct_option`
    correct = db.Column('correct_option', db.String(1),
                        nullable=False)  # 'A'/'B'/'C'/'D'

    # Question type for richer formats (v1.1.0)
    # 'mcq' (default, legacy), 'tf', 'dragdrop_zone', future: 'hotspot', 'ordering', 'matching', 'fill_blank'
    qtype = db.Column(db.String(20), default='mcq', nullable=False, index=True)
    # JSON blob whose schema depends on qtype. For 'dragdrop_zone' see VIRTUAL_PORTAL_PLAN.md §5.4.
    payload = db.Column(db.JSON, nullable=True)
    # Background image for dragdrop_zone / hotspot questions.
    image_filename = db.Column(db.String(255), nullable=True)


# ---------- locate the questions JSON for a given course_key ----------

def _find_questions_file_for_course(course_key: str):
    """
    Tries multiple likely paths to find the final questions JSON for this course.
    Prefers whatever was saved in assessments_cfg; falls back to conventions.
    """
    items = load_assessments_cfg()  # you already have this
    meta = next((x for x in items if x.get("key") == course_key), None)

    candidates = []

    # 1) Explicit file path saved in the meta (if your builder stored it)
    if meta and meta.get("questions_file"):
        candidates.append(Path(meta["questions_file"]))

    # 2) Common conventions you used before
    #    /questions/<course_key>/final_questions.json
    candidates.append(QUESTIONS_DIR / course_key / "final_questions.json")
    #    /questions/<course_key>.final.json
    candidates.append(QUESTIONS_DIR / f"{course_key}.final.json")
    #    /questions/<course_key>_final_questions.json
    candidates.append(QUESTIONS_DIR / f"{course_key}_final_questions.json")
    #    /questions/<course_key>.json  (last-ditch)
    candidates.append(QUESTIONS_DIR / f"{course_key}.json")

    for p in candidates:
        try:
            if p.is_file():
                return p
        except Exception:
            pass

    return None


# ---------- tiny normalizers ----------
_whitespace = re.compile(r"\s+", re.M | re.S)


def _norm_text(s):
    if s is None:
        return ""
    s = str(s)
    s = _whitespace.sub(" ", s).strip()
    return s.lower()


def _norm_multi(vals):
    if vals is None:
        return []
    if isinstance(vals, (list, tuple, set)):
        return sorted([_norm_text(v) for v in vals if v is not None])
    # If single value accidentally came through:
    return [_norm_text(vals)]


# ---------- actual grading ----------
def grade_final_answers(course_key: str, submitted_form: dict):
    """
    Returns:
      score (int),
      total_questions (int),
      percentage (int 0..100),
      correct_count (int),
      answers_dict (dict suitable for json.dumps for auditing)

    JSON schema assumptions (flexible):
    Each question object may look like:
      {
        "id": "q1",                            # unique id (preferred). If absent, index is used.
        "type": "mcq_single" | "mcq_multi" |
                 "true_false" | "short_text" |
                 "number" | "free_text",
        "points": 1,                           # optional, default 1
        "prompt": "...",
        "options": [                           # for MCQ/TF
          {"text":"Option A", "correct": true},
          {"text":"Option B"}
        ],
        "answer": "expected text"              # for short_text/number/true_false
                                               # for mcq_multi, could be ["A","C"] or
                                               # rely entirely on options[].correct
      }

    submitted_form should contain the posted answers. Common patterns:
      - Single choice:  form["q_<id>"] = "Option A"
      - Multi choice:   form.getlist("q_<id>") = ["A","C"]
      - Short text:     form["q_<id>"] = "text"
      - Number:         form["q_<id>"] = "3.14"
      - True/False:     form["q_<id>"] in {"true","false"} (or "on"/"off")
    """
    qfile = _find_questions_file_for_course(course_key)
    if not qfile:
        # No questions file; nothing to grade
        return 0, 0, 0, 0, {"error": f"No questions JSON found for {course_key}"}

    try:
        spec = json.loads(qfile.read_text(encoding="utf-8"))
    except Exception as e:
        return 0, 0, 0, 0, {"error": f"Failed to load questions JSON: {e}"}

    # Your JSON may be either a list or a wrapper like {"questions":[...]}
    questions = spec.get("questions") if isinstance(spec, dict) else spec
    if not isinstance(questions, list):
        return 0, 0, 0, 0, {"error": "Questions JSON is not a list or missing 'questions' array."}

    total_points = 0
    earned_points = 0
    correct_count = 0
    audit = []  # list of per-question dicts

    # Helper to pull submitted answer(s)
    def get_submitted(qid):
        # Prefer "q_<id>" naming; fall back to id
        keys = [f"q_{qid}", str(qid)]
        for k in keys:
            if k in submitted_form:
                return submitted_form.getlist(k) if hasattr(submitted_form, "getlist") else submitted_form[k]
        # WTForms / custom names sometimes: just try once more for multi-select pattern
        if hasattr(submitted_form, "getlist"):
            for k in submitted_form.keys():
                if k.endswith(f"_{qid}"):
                    vals = submitted_form.getlist(k)
                    if vals:
                        return vals
        return None

    # Iterate and score
    for idx, q in enumerate(questions, start=1):
        qid = q.get("id") or str(idx)
        qtype = (q.get("type") or "mcq_single").strip().lower()
        points = int(q.get("points") or 1)
        total_points += points

        submitted = get_submitted(qid)

        # Establish the "ground truth" depending on type
        is_correct = False
        expected_for_audit = None
        submitted_for_audit = submitted

        if qtype in ("mcq_single", "mcq_multi", "true_false"):
            # Determine correct option(s)
            correct_opts = []
            for opt in (q.get("options") or []):
                if opt.get("correct"):
                    correct_opts.append(_norm_text(opt.get("text")))

            # If author also stored 'answer' explicitly, merge it in
            if q.get("answer") and qtype != "mcq_multi":
                correct_opts = [_norm_text(q["answer"])]

            expected_for_audit = correct_opts

            if qtype == "mcq_single":
                sub = _norm_text(submitted[0] if isinstance(
                    submitted, (list, tuple)) else submitted)
                is_correct = (sub in correct_opts)

            elif qtype == "mcq_multi":
                subs = _norm_multi(submitted)
                is_correct = (subs == sorted(correct_opts))

            else:  # true_false
                # normalize to "true"/"false"
                def as_bool_token(v):
                    v = _norm_text(v)
                    if v in ("true", "t", "yes", "y", "1", "on"):
                        return "true"
                    if v in ("false", "f", "no", "n", "0", "off"):
                        return "false"
                    return v  # leave as-is
                subs = [as_bool_token(x) for x in (submitted if isinstance(
                    submitted, (list, tuple)) else [submitted])]
                sub = subs[0] if subs else ""
                # if there’s an explicit answer
                if q.get("answer") is not None:
                    expected = as_bool_token(q["answer"])
                    expected_for_audit = expected
                    is_correct = (sub == expected)
                else:
                    # or infer from the single option marked correct
                    if len(correct_opts) == 1:
                        is_correct = (sub == correct_opts[0])

        elif qtype == "short_text":
            expected = q.get("answer")
            # Accept either string or list of acceptable answers
            if isinstance(expected, (list, tuple, set)):
                expected_norm = [_norm_text(x) for x in expected]
                sub_norm = _norm_text(submitted)
                is_correct = sub_norm in expected_norm
                expected_for_audit = expected
            else:
                expected_norm = _norm_text(expected)
                sub_norm = _norm_text(submitted)
                is_correct = (sub_norm == expected_norm)
                expected_for_audit = expected

        elif qtype == "number":
            # numeric compare, allow tiny tolerance; also optional range {min,max}
            # Supports either: answer: 3.14   OR   answer: {"value": 3.14, "tol": 0.01}
            target = q.get("answer")
            try:
                sub = float(submitted if not isinstance(
                    submitted, (list, tuple)) else submitted[0])
            except Exception:
                sub = None

            if isinstance(target, dict):
                val = float(target.get("value"))
                tol = float(target.get("tol", 0.0))
                lo = target.get("min")
                hi = target.get("max")
                expected_for_audit = target
                if sub is not None:
                    if lo is not None and hi is not None:
                        is_correct = (float(lo) <= sub <= float(hi))
                    elif tol > 0:
                        is_correct = isclose(
                            sub, val, rel_tol=0.0, abs_tol=tol)
                    else:
                        is_correct = (sub == val)
            else:
                try:
                    val = float(target)
                    expected_for_audit = val
                    is_correct = (sub is not None and isclose(
                        sub, val, rel_tol=0.0, abs_tol=1e-9))
                except Exception:
                    is_correct = False
                    expected_for_audit = target

        else:
            # free_text or unknown type -> do not auto-grade
            is_correct = False
            expected_for_audit = None  # manual review later

        if is_correct:
            earned_points += points
            correct_count += 1

        audit.append({
            "id": qid,
            "type": qtype,
            "points": points,
            "earned": points if is_correct else 0,
            "is_correct": bool(is_correct),
            "submitted": submitted_for_audit,
            "expected": expected_for_audit,
            "prompt": q.get("prompt", "")
        })

    percentage = int(round((earned_points / total_points)
                     * 100)) if total_points else 0

    # Pack an answers_dict for storage (JSON string in your model)
    answers_dict = {
        "course_key": course_key,
        "questions_file": str(qfile),
        "total_points": total_points,
        "earned_points": earned_points,
        "percentage": percentage,
        "correct_count": correct_count,
        "items": audit,
    }
    return earned_points, len(questions), percentage, correct_count, answers_dict
