@app.route('/admin/add_final_question/<int:course_id>', methods=['GET', 'POST'])
def add_final_question(course_id):
    if 'admin_id' not in session:
        flash("⚠ Admin login required.", "danger")
        return redirect(url_for('admin_login'))

    course = Course.query.get_or_404(course_id)

    if request.method == 'POST':
        questions = request.form.getlist('questions')
        data = request.form.to_dict(flat=False)

        # Extract and create each question
        for index in data:
            if index.startswith('questions['):
                q_id = index.split('[')[1].split(']')[0]
                try:
                    question = request.form.get(f'questions[{q_id}][question]')
                    option_a = request.form.get(f'questions[{q_id}][option_a]')
                    option_b = request.form.get(f'questions[{q_id}][option_b]')
                    option_c = request.form.get(f'questions[{q_id}][option_c]')
                    option_d = request.form.get(f'questions[{q_id}][option_d]')
                    correct_option = request.form.get(
                        f'questions[{q_id}][correct_option]')

                    new_question = FinalAssessmentQuestion(
                        course_id=course.id,
                        question=question,
                        option_a=option_a,
                        option_b=option_b,
                        option_c=option_c,
                        option_d=option_d,
                        correct_option=correct_option
                    )
                    db.session.add(new_question)
                except Exception as e:
                    print(f"❌ Failed to add question {q_id}: {e}")
        db.session.commit()
        flash("✅ All questions saved successfully!", "success")
        return redirect(url_for('add_final_question', course_id=course.id))

    return render_template('add_final_question.html', course=course)

