# --- Compat shim: get_runtime_for_course ---
try:
    get_runtime_for_course
except NameError:
    def get_runtime_for_course(final_key):
        """Load config + questions for a final assessment key."""
        # 1. Try assessments.json config
        cfg_path = os.path.join(app.root_path, "config", "assessments.json")
        cfg = None
        if os.path.exists(cfg_path):
            try:
                with open(cfg_path, encoding="utf-8") as f:
                    all_cfgs = json.load(f)
                for c in all_cfgs:
                    if c.get("key", "").lower() == final_key.lower():
                        cfg = c
                        break
            except Exception:
                pass

        # 2. Build a default config if not found in assessments.json
        if cfg is None:
            cfg = {
                "key": final_key,
                "title": final_key.replace("_", " ").title(),
                "pass_mark": 80,
            }

        # 3. Load questions via the standard loader
        try:
            questions = load_questions(final_key)
        except Exception:
            questions = []
        return cfg, questions
