@app.route('/final_assessment/<int:course_id>', methods=['GET', 'POST'])
@nocache
@require_popia
def final_assessment(course_id):
    if 'student_id' not in session:
        flash("⚠ Please log in first.", "danger")
        return redirect(url_for('login'))

    course = Course.query.get_or_404(course_id)

    # ===== ATTEMPT BLOCKING LOGIC =====
    # Check previous attempts and block if necessary
    student_row = Student.query.filter_by(student_id=session['student_id']).first()
    if student_row:
        # CAA minimum wait (v1.2). Checked before any attempt logic so a student
        # cannot reach the assessment while the waiting period is still running.
        _blocked = _enforce_final_wait(student_row.id, course_id)
        if _blocked:
            return _blocked

        previous_attempts = FinalAssessmentSubmission.query.filter_by(
            student_id=student_row.id,
            course_id=course_id,
            is_active=True
        ).order_by(FinalAssessmentSubmission.submitted_at.desc()).all()

        if previous_attempts:
            attempts_count = len(previous_attempts)
            latest_attempt = previous_attempts[0]
            latest_pct = latest_attempt.percentage or 0

            # Already passed - check if certification has expired (2 years)
            if latest_pct >= 80:
                passed_date = latest_attempt.submitted_at
                if passed_date:
                    cert_expiry = passed_date + timedelta(days=730)  # 2 years
                    if _now_sast() < cert_expiry:
                        # Certification still valid - no retake needed
                        flash("You have already passed this assessment. Your certification is still valid - no retake needed.", "info")
                        return redirect(url_for("dashboard"))
                    # else: Certification expired - allow retake
                else:
                    # No date recorded, block retake
                    flash("You have already passed this assessment. No retake needed.", "info")
                    return redirect(url_for("dashboard"))

            # Check if they've used all allowed attempts
            allowed = _allowed_cap(student_row.id, course_id)
            if attempts_count >= allowed:
                # Out of attempts - check if eligible for retry request (75-79.99% on 2nd attempt)
                if latest_pct < 75:
                    flash("You scored below 75% on your final attempt. Please contact your administrator to request another attempt.", "danger")
                else:
                    flash("You have no attempts remaining. Please request an additional attempt through your dashboard.", "danger")
                return redirect(url_for("dashboard"))

            # Still have automatic attempts remaining - allow retry
    # ===== END BLOCKING LOGIC =====
    course_code = getattr(course, "code", None) or _slug(
        getattr(course, "title", "")) or f"course_{course.id}"
    final_key = _slug(
        getattr(course, "final_assessment_key", None) or course_code)

    # Legacy map unchanged
    special_map = {"airside_induction": "airside_induction",
                   "airside": "airside_induction"}
    ep = special_map.get(final_key)
    if ep:
        print(
            f"FINAL → course_id={course.id} mapped_key={final_key} → redirect endpoint '{ep}'")
        return redirect(url_for(ep))

    # Load questions. Questions created through the course admin editor are
    # stored in FinalAssessmentQuestion, so prefer that bank over JSON when it
    # exists. A student's selected IDs are kept in session for the attempt.
    db_questions = []
    if final_key == "asat_gen":
        db_questions = FinalAssessmentQuestion.query.filter_by(
            course_id=course.id
        ).order_by(FinalAssessmentQuestion.id).all()
    if db_questions:
        cfg = {
            "key": final_key,
            "title": getattr(course, "title", "Final Assessment"),
            "pass_mark": 80,
        }
        question_bank = [
            {
                "id": row.id,
                "question": row.question,
                "options": [row.option_a, row.option_b, row.option_c, row.option_d],
                "correct_index": "ABCD".index((row.correct or "A").upper()),
            }
            for row in db_questions
        ]
        question_count = 50
        selection_key = f"final_assessment_question_ids_{course.id}"
        selected_ids = session.get(selection_key)
        if request.method == "POST" and selected_ids:
            by_id = {row.id: question for row, question in zip(db_questions, question_bank)}
            final_questions = [by_id[qid] for qid in selected_ids if qid in by_id]
        else:
            if len(question_bank) < question_count:
                raise ValueError(
                    f"ASAT/course final has {len(question_bank)} questions; "
                    f"at least {question_count} are required."
                )
            rng = secrets.SystemRandom()
            final_questions = rng.sample(question_bank, question_count)
            rng.shuffle(final_questions)
            session[selection_key] = [question["id"] for question in final_questions]
        source = "database"
    else:
        try:
            cfg, final_questions = get_runtime_for_course(
                final_key)  # (cfg, list-of-dicts)
            source = "json"
        except Exception as e:
            print(f"FINAL load runtime failed for key '{final_key}': {e}")
            cfg, final_questions, source = None, [], "none"

    if not cfg:
        class _Cfg:
            title = getattr(course, "title", "Final Assessment")
            pass_mark = 80
        cfg = _Cfg()

    # Normalize options to map {'a': 'text', ...} and honor correct_index
    letters = "abcdefghijklmnopqrstuvwxyz"
    norm_questions = []
    for idx, raw in enumerate(final_questions or [], start=1):
        q = raw or {}
        qid = q.get("id") or idx
        qtext = (q.get("question") or "").strip()
        raw_opts = q.get("options") or []
        options_map = {}

        if isinstance(raw_opts, dict):
            for k in letters:
                if k in raw_opts:
                    options_map[k] = str(raw_opts[k])
        elif isinstance(raw_opts, list):
            for i, o in enumerate(raw_opts):
                txt = str(o["text"]) if isinstance(
                    o, dict) and "text" in o else str(o)
                if i < len(letters):
                    options_map[letters[i]] = txt

        # --- CORRECT handling (supports correct/answer/correct_index) ---
        corr_raw = q.get("correct")
        if corr_raw is None:
            corr_raw = q.get("answer")
        if corr_raw is None and "correct_index" in q:
            try:
                ci = int(q.get("correct_index"))
                if 0 <= ci < len(options_map):
                    corr = letters[ci]
                elif 1 <= ci <= len(options_map):
                    corr = letters[ci - 1]
                else:
                    corr = "a"
            except Exception:
                corr = "a"
        else:
            corr = corr_raw if corr_raw is not None else "a"
            if isinstance(corr, (list, tuple)):
                corr = corr[0] if corr else "a"
            corr = str(corr).strip().lower()
            if corr.isdigit():
                i = int(corr)
                if 0 <= i < len(options_map):
                    corr = letters[i]
                elif 1 <= i <= len(options_map):
                    corr = letters[i-1]
                else:
                    corr = "a"
            if corr not in options_map:
                low_map = {k: options_map[k].strip().lower()
                           for k in options_map}
                hit = next((k for k, v in low_map.items() if v == corr), None)
                corr = hit or (next(iter(options_map.keys()), "a"))
        # ---------------------------------------------------------------

        entry = {
            "id": qid,
            "question": qtext,
            "options": options_map,
            "correct": corr,
        }
        img = (q.get("image") or "").strip()
        if img:
            entry["image"] = img
        norm_questions.append(entry)

    print(
        f"FINAL map → course_id={course.id} course_code={course_code} mapped_key={final_key} source={source} loaded={len(norm_questions)}")

    student_number = str(session['student_id'])
    student = Student.query.filter_by(student_id=student_number).first()
    if not student:
        flash("Student not found.", "danger")
        return redirect(url_for('login'))

    if request.method == 'POST':
        # ---- everything below stays indented in here ----
        video_session_id = request.form.get('video_session_id', '').strip()

        if video_session_id:
            # Chunked upload mode — finalize chunks
            video_relpath = finalize_video_chunks(student_number, video_session_id, final_key or 'final')
            if not video_relpath:
                msg = "❌ Video chunks could not be assembled. Please try again."
                if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
                    return jsonify(ok=False, message=msg), 400
                flash(msg, "danger")
                return redirect(request.url)
        else:
            # Fallback: single-upload mode
            video_file = request.files.get('video')
            if not video_file or video_file.filename == "":
                msg = "❌ Your video recording is missing. Please ensure your camera is on and recording before submitting."
                if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
                    return jsonify(ok=False, message=msg), 400
                flash(msg, "danger")
                return redirect(request.url)

            safe_title = (getattr(cfg, "title", None) or getattr(
                course, "title", "Final")).replace(" ", "_").replace("/", "_")
            base_name = f"{student_number}_{final_key}_{safe_title}_{_now_sast().strftime('%Y%m%d_%H%M%S')}.webm"
            filename = secure_filename(base_name)

            folder = os.path.join("uploads", str(student_number))
            os.makedirs(folder, exist_ok=True)

            abs_path = os.path.join(folder, filename)
            video_file.save(abs_path)
            video_relpath = os.path.join("uploads", str(
                student_number), filename).replace("\\", "/")

        # ---- Normalize posted values -> letters (robust) ----
        import re

        def _answer_to_letter(raw_value, options_dict):
            """
            Accepts: 'A', 'a', 'A) 2', '1', '2', or full text like 'True'
            Returns 'a'..'z' or '' if no match.
            options_dict is {'a':'text','b':'text',...}
            """
            if raw_value is None:
                return ""
            s = str(raw_value).strip()
            if not s:
                return ""
            letters_local = "abcdefghijklmnopqrstuvwxyz"

            # raw key like 'a'/'B'
            if len(s) == 1 and s.lower() in (k.lower() for k in (options_dict or {}).keys()):
                return s.lower()

            # leading letter token e.g. 'A) 2'
            m = re.match(r'^\s*([A-Za-z])(?:[\)\.\:\-\s]|$)', s)
            if m:
                return m.group(1).lower()

            # numeric (1-based)
            m = re.match(r'^\s*0*([0-9]+)\s*$', s)
            if m:
                idx = int(m.group(1)) - 1
                if 0 <= idx < len(options_dict):
                    return letters_local[idx]

            # exact text match
            s_low = s.lower()
            for k, v in (options_dict or {}).items():
                if str(v).strip().lower() == s_low:
                    return str(k).lower()

            # heuristic trailing letter
            m = re.search(r'([A-Za-z])\s*$', s)
            if m and m.group(1).lower() in (k.lower() for k in (options_dict or {}).keys()):
                return m.group(1).lower()
            return ""

        q_by_id = {str(q['id']): q for q in norm_questions}

        answers = {}
        id_pattern = re.compile(r'(\d+)')
        for field_name, raw_val in request.form.items():
            name_low = field_name.lower()
            if name_low.startswith('q') or name_low.startswith('question'):
                m = id_pattern.search(field_name)
                if not m:
                    continue
                qid = m.group(1)
                qdef = q_by_id.get(qid)
                if not qdef:
                    continue
                letter = _answer_to_letter(raw_val, qdef.get("options", {}))
                if letter:
                    answers[qid] = letter

        # ---- DEBUG (safe) ----
        try:
            print("[final.route] FORM:", dict(request.form))
            print("[final.route] ANSWERS (letters):", answers)
            print("[final.route] CORRECT MAP:", {
                  str(q["id"]): q["correct"] for q in norm_questions})
        except Exception:
            pass

        # --- Grade (letter vs letter)
        score, total = 0, len(norm_questions)
        for q in norm_questions:
            qid = str(q['id'])
            selected = str(answers.get(qid, "")).strip().lower()
            correct = str(q.get("correct") or "a").strip().lower()
            if selected and selected == correct:
                score += 1

        percentage = round((score / total) * 100.0, 2) if total > 0 else 0.0
        pass_mark = getattr(cfg, "pass_mark", 80)
        passed = (percentage >= float(pass_mark))

        # Persist FinalAssessmentSubmission
        try:
            sub_kwargs = dict(
                student_id=student.id,
                course_id=course.id,
                video_filename=video_relpath,
                score=score,
                total_questions=total,
                percentage=percentage,
                review_status="Pending",
                submitted_at=_now_sast(),
                answers_json=json.dumps(answers),
                questions_json=json.dumps(norm_questions),
            )
            if hasattr(FinalAssessmentSubmission, "final_key"):
                sub_kwargs["final_key"] = final_key

            db.session.add(FinalAssessmentSubmission(**sub_kwargs))
            db.session.commit()
        except Exception as e:
            print("FINAL save submission failed:", e)
            db.session.rollback()

        # Persist FinalAssessmentAttempt (auditable)
        try:
            _attempt_id = record_final_attempt(
                student=student,
                course_key=final_key,
                course_id=course.id,
                score=score,
                total=total,
                passed=passed,
                video_relpath=video_relpath,
                answers_dict={k: str(v).strip().lower()
                              for k, v in answers.items()}
            )
            print(
                f"[attempt] saved id={_attempt_id} course_key={final_key} student={student.student_id}")
        except Exception as e:
            print("WARN: record_final_attempt failed:", e)

        # --- Save Q&A PDF into student's folder as student_course_date_.pdf
        try:
            if 'save_finals_qna_pdf_to_student_folder' in globals():
                save_finals_qna_pdf_to_student_folder(
                    student=student,
                    course=course,
                    final_key=final_key,
                    questions=norm_questions,
                    answers={k: str(v).strip().lower()
                             for k, v in answers.items()},
                    score=score,
                    total=total,
                    percentage=percentage,
                    pass_mark=pass_mark,
                    submitted_at=_now_sast(),
                )
            else:
                def _render_html(course, student, questions, answers, score, total, percentage, pass_mark, submitted_at):
                    rows = []
                    for q in questions:
                        qid = q.get("id")
                        qtxt = q.get("question") or ""
                        opts = q.get("options") or {}
                        correct = str(q.get("correct") or "a").strip().lower()
                        chosen = str(answers.get(str(qid), "")).strip().lower()
                        opt_html = []
                        for key, text in opts.items():
                            key_l = str(key).lower()
                            badge = ""
                            if key_l == correct and key_l == chosen:
                                badge = " ✅ (correct)"
                            elif key_l == correct:
                                badge = " ✅"
                            elif key_l == chosen:
                                badge = " ❌"
                            opt_html.append(
                                f"<div><strong>{key_l.upper()}.</strong> {text}{badge}</div>")
                        rows.append(f"""
                        <tr>
                          <td style="vertical-align:top; padding:8px; width:40px;">{qid}</td>
                          <td style="padding:8px;">
                            <div style="margin-bottom:6px;"><strong>Q{qid}.</strong> {qtxt}</div>
                            {''.join(opt_html)}
                            <div style="margin-top:6px; font-size:12px; color:#666;">
                              Chosen: <strong>{(chosen.upper() or '-')}</strong> &nbsp;|&nbsp; Correct: <strong>{correct.upper()}</strong>
                            </div>
                          </td>
                        </tr>
                        """)
                    html = f"""<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <title>Finals Q&A – {course.title} – {student.student_id}</title>
  <style>
    body {{ font-family: Arial, sans-serif; }}
    .meta small {{ color:#555; }}
    table {{ border-collapse: collapse; width:100%; }}
    td, th {{ border:1px solid #ddd; }}
  </style>
</head>
<body>
  <h2>Final Assessment – {course.title}</h2>
  <div class="meta">
    <div><small>Student:</small> <strong>{student.name} {student.surname}</strong> (ID: {student.student_id})</div>
    <div><small>Email:</small> {student.email or '-'}</div>
    <div><small>Submitted:</small> {submitted_at.strftime('%Y-%m-%d %H:%M')}</div>
    <div><small>Score:</small> <strong>{score}/{total}</strong> &nbsp;
         <small>({percentage:.2f}% · pass mark {pass_mark}%)</small></div>
  </div>
  <hr>
  <table>
    <tbody>
      {''.join(rows)}
    </tbody>
  </table>
</body>
</html>
"""
                    return html

                dt_now = _now_sast()
                date_str = dt_now.strftime("%Y-%m-%d")
                pdf_folder = os.path.join("uploads", str(student_number))
                os.makedirs(pdf_folder, exist_ok=True)
                pdf_name = f"{student.student_id}_{course_code}_{date_str}_.pdf"
                pdf_path = os.path.join(pdf_folder, pdf_name)

                html = _render_html(
                    course, student, norm_questions,
                    {k: str(v).strip().lower() for k, v in answers.items()},
                    score, total, percentage, pass_mark, dt_now
                )

                wrote = False
                try:
                    from weasyprint import HTML
                    from io import BytesIO
                    _buf = BytesIO()
                    HTML(string=html, base_url=request.host_url).write_pdf(_buf)
                    with open(pdf_path, "wb") as f:
                        f.write(_buf.getvalue())
                    wrote = True
                except Exception:
                    pass

                if not wrote:
                    try:
                        from reportlab.lib.pagesizes import A4
                        from reportlab.pdfgen import canvas
                        c = canvas.Canvas(pdf_path, pagesize=A4)
                        width, height = A4
                        y = height - 50
                        c.setFont("Helvetica-Bold", 12)
                        c.drawString(
                            40, y, f"Final Assessment – {course.title}")
                        y -= 16
                        c.setFont("Helvetica", 10)
                        c.drawString(
                            40, y, f"Student: {student.name} {student.surname} (ID: {student.student_id})")
                        y -= 14
                        c.drawString(
                            40, y, f"Submitted: {dt_now.strftime('%Y-%m-%d %H:%M')}")
                        y -= 14
                        c.drawString(
                            40, y, f"Score: {score}/{total}  ({percentage:.2f}% ; pass mark {pass_mark}%)")
                        y -= 24
                        for q in norm_questions:
                            qid = q.get("id")
                            qtxt = (q.get("question") or "")[:180]
                            correct = str(q.get("correct") or "a").upper()
                            chosen = str(answers.get(str(qid), "")).upper()
                            for line in [f"Q{qid}. {qtxt}", f"  Chosen: {chosen or '-'}   Correct: {correct}"]:
                                if y < 60:
                                    c.showPage()
                                    y = height - 50
                                    c.setFont("Helvetica", 10)
                                c.drawString(40, y, line)
                                y -= 14
                        c.showPage()
                        c.save()
                    except Exception as e2:
                        current_app.logger.warning(
                            f"Q&A PDF fallback failed: {e2}")
        except Exception as e:
            current_app.logger.warning(f"Finals Q&A PDF save failed: {e}")

        redirect_url = url_for('final_result', course_id=course.id)
        if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            return jsonify(ok=True, redirect=redirect_url)
        return redirect(redirect_url)

    # GET → render page
    # Count existing attempts for this student + course
    existing_attempts = FinalAssessmentAttempt.query.filter_by(
        student_number=str(student.student_id),
        course_key=final_key,
        is_active=True
    ).count()
    current_attempt = existing_attempts + 1

    return render_template(
        'final_assessment_proctor.html',
        title=getattr(cfg, "title", "Final Assessment"),
        pass_mark=getattr(cfg, "pass_mark", 80),
        student_number=student.student_id,
        student_id=student.student_id,
        student_name=f"{student.name} {student.surname}",
        student_email=student.email,
        questions=norm_questions,
        current_attempt=current_attempt,
    )


