####### Helpers #####

# ---- MCQ normalization helpers (compat shim for older graders) ----
_letters = "abcdefghijklmnopqrstuvwxyz"


def _letter_from_index(idx, n):
    try:
        i = int(idx)
    except Exception:
        return ""
    if 0 <= i < n:      # 0-based
        return _letters[i]
    if 1 <= i <= n:     # 1-based
        return _letters[i-1]
    return ""


def _letter_from_text(txt, opts_list):
    if not isinstance(txt, str):
        return ""
    t = txt.strip().lower()
    for i, o in enumerate(opts_list or []):
        if str(o).strip().lower() == t:
            return _letters[i]
    return ""


def _coerce_correct(raw_corr, options):
    """
    Accepts 'a'/'A'/0/1/'1'/['b']/{'key':'c'}/{'index':2}/{'text':'Option'} → 'a'..'z' (fallback 'a').
    'options' can be list[str] OR dict {'a':'...', 'b':'...'}.
    """
    # Normalize options to a simple list in a..z order when dict
    if isinstance(options, dict):
        opts_list = [options[k] for k in _letters if k in options]
    else:
        opts_list = list(options or [])

    # list → first element
    if isinstance(raw_corr, list):
        raw_corr = raw_corr[0] if raw_corr else ""

    # dict cases
    if isinstance(raw_corr, dict):
        if "key" in raw_corr:
            raw_corr = raw_corr["key"]
        elif "index" in raw_corr:
            return _letter_from_index(raw_corr["index"], len(opts_list)) or "a"
        elif "text" in raw_corr:
            return _letter_from_text(raw_corr["text"], opts_list) or "a"
        else:
            raw_corr = ""

    # int → index
    if isinstance(raw_corr, int):
        return _letter_from_index(raw_corr, len(opts_list)) or "a"

    # str cases
    if isinstance(raw_corr, str):
        s = raw_corr.strip()
        if not s:
            return "a"
        # single letter already
        if len(s) == 1 and s.lower() in _letters[:len(opts_list)]:
            return s.lower()
        # numeric string → index
        if s.isdigit():
            return _letter_from_index(int(s), len(opts_list)) or "a"
        # try matching option text
        return _letter_from_text(s, opts_list) or "a"

    # fallback
    return "a"
# ---- end compat shim ----


