class FinalAssessmentSubmission(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    student_id = db.Column(db.Integer, db.ForeignKey(
        'student.id'), nullable=False)

    # Keep cascade on course deletes
    course_id = db.Column(
        db.Integer,
        db.ForeignKey('course.id', ondelete='CASCADE'),
        nullable=False
    )

    # NEW (optional but useful to know which final mapping was used)
    final_key = db.Column(db.String(128), nullable=True)

    video_filename = db.Column(db.String(255), nullable=False)
    score = db.Column(db.Integer)
    total_questions = db.Column(db.Integer)
    percentage = db.Column(db.Float)
    review_status = db.Column(db.String(50), default="Pending")
    submitted_at = db.Column(db.DateTime, default=_now_sast)

    # Archive flag. A reset sets this False instead of deleting the row, so the
    # proctoring video stays attributable (student, course, score, date).
    # Current-state queries must filter is_active=True; admin/moderation views
    # deliberately do not, so staff can still reach reset attempts.
    is_active = db.Column(db.Boolean, default=True,
                          nullable=False, index=True)

    # NEW (for audit/PDF export)
    # e.g. {"12":"b","13":"a",...}
    answers_json = db.Column(db.Text, nullable=True)
    # normalized questions snapshot
    questions_json = db.Column(db.Text, nullable=True)

    student = db.relationship('Student', backref='assessments')
    course = db.relationship('Course', backref=db.backref(
        'assessments', passive_deletes=True))


