@app.route('/final_result/<int:course_id>')
def final_result(course_id):
    if 'student_id' not in session:
        flash("⚠ Please log in first.", "danger")
        return redirect(url_for('login'))

    course = Course.query.get_or_404(course_id)
    student = Student.query.filter_by(
        student_id=str(session['student_id'])).first_or_404()

    sub = (FinalAssessmentSubmission.query
           .filter_by(student_id=student.id, course_id=course.id,
                      is_active=True)
           .order_by(FinalAssessmentSubmission.submitted_at.desc())
           .first())

    if not sub:
        flash("No submission found.", "warning")
        return redirect(url_for('final_assessment', course_id=course.id))

    # Get attempt information for this student + course
    final_key = getattr(course, 'final_assessment_key', None) or course.code
    attempt_info = (FinalAssessmentAttempt.query
                    .filter_by(student_number=str(student.student_id),
                               course_key=final_key, is_active=True)
                    .order_by(FinalAssessmentAttempt.attempt_no.desc())
                    .first())

    current_attempt = attempt_info.attempt_no if attempt_info else 1
    pct = sub.percentage or 0

    # Determine outcome based on score thresholds:
    # Default: 2 attempts per course
    # 80%+ on ANY attempt = PASS
    # After 1st attempt fail (<80%) = Can retry automatically (2nd attempt)
    # After 2nd attempt with <75% = FAIL - contact admin
    # After 2nd attempt with 75-79.99% = Can REQUEST 3rd attempt via dashboard
    passed = pct >= 80
    can_retry_automatically = (pct < 80) and (current_attempt < 2)
    can_request_third = (75 <= pct < 80) and (current_attempt >= 2)
    must_contact_admin = (pct < 75) and (current_attempt >= 2)

    return render_template(
        "final_result.html",
        course=course,
        student=student,
        percentage=pct,
        score=sub.score or 0,
        total=sub.total_questions or 0,
        review_status=sub.review_status or "Pending",
        submitted_at=sub.submitted_at,
        video_filename=sub.video_filename,
        current_attempt=current_attempt,
        passed=passed,
        can_retry_automatically=can_retry_automatically,
        can_request_third=can_request_third,
        must_contact_admin=must_contact_admin,
        attempt_id=attempt_info.id if attempt_info else None,
    )


