# --- Replace your /log_violation with this ---


@app.route('/api/proctor/log', methods=['POST'])
def api_proctor_log():
    try:
        data = request.get_json(silent=True) or {}

        # accept both new 'reason' and legacy 'type'
        reason = (data.get('reason') or data.get('type') or '').strip()
        if not reason:
            return jsonify({"ok": False, "error": "missing reason"}), 400

        # prefer explicit student_id from payload, else fall back to session
        student_id = (data.get('student_id')
                      or session.get('student_id') or None)
        course_key = (data.get('course_key') or None)
        detail = data.get('detail') or {}

        log = ViolationLog(
            timestamp=_now_sast(),
            student_id=student_id,
            course_key=course_key,
            reason=reason,
            detail_json=json.dumps(detail, ensure_ascii=False),
            ip=request.headers.get("X-Forwarded-For", request.remote_addr),
            user_agent=request.headers.get("User-Agent"),
        )
        db.session.add(log)
        db.session.commit()

        # Point-based violation alert system
        threshold_hit = False
        try:
            # Check if alert system is enabled
            alert_settings = ViolationAlertSettings.query.first()
            if not alert_settings:
                # Create default settings if not exists
                alert_settings = ViolationAlertSettings(threshold=10, is_enabled=True)
                db.session.add(alert_settings)
                db.session.commit()

            if not alert_settings.is_enabled:
                print("ℹ️ Violation alert system is disabled - skipping point tracking")
            elif not student_id or not course_key:
                print("⚠️ Missing student_id or course_key - cannot track violation points")
            else:
                # Get point value for this violation reason
                point_config = ViolationPointConfig.query.filter_by(reason_code=reason).first()
                violation_points = point_config.points if point_config else 0

                # Face/dark violations don't accumulate points while timer > 30 min.
                # The boot system handles them separately (boot without losing attempt).
                # This prevents the threshold from being hit prematurely by camera issues.
                BOOT_CUTOFF_SECONDS = 30 * 60
                timer_remaining = data.get("timer_remaining")
                face_dark_reasons = {"no_face_warn", "no_face_fatal", "no_face_recovered",
                                     "too_dark_warn", "too_dark_fatal", "too_dark_recovered"}
                if (reason in face_dark_reasons
                        and timer_remaining is not None
                        and int(timer_remaining) > BOOT_CUTOFF_SECONDS):
                    violation_points = 0
                    print(f"ℹ️ Skipping points for '{reason}' — timer still above 30 min ({timer_remaining}s)")

                if violation_points > 0:
                    # Get or create tracker for this student + course
                    tracker = ViolationAlertTracker.query.filter_by(
                        student_id=str(student_id),
                        course_key=course_key
                    ).first()

                    if not tracker:
                        tracker = ViolationAlertTracker(
                            student_id=str(student_id),
                            course_key=course_key,
                            current_points=0
                        )
                        db.session.add(tracker)

                    # Add points
                    tracker.current_points += violation_points
                    tracker.updated_at = _now_sast()
                    db.session.commit()

                    print(f"📊 Violation points: +{violation_points} for '{reason}' | Total: {tracker.current_points}/{alert_settings.threshold} (Student: {student_id}, Course: {course_key})")

                    # Check if threshold reached
                    if tracker.current_points >= alert_settings.threshold:
                        # Send alert email
                        violation_recipients = get_recipients_for_category('violations')

                        if not violation_recipients:
                            app.logger.warning("No active recipients configured for 'violations' category - skipping email")
                            print("⚠️ No active recipients configured for 'violations' category - skipping email")
                        else:
                            # Get Student object to include name, surname, and national_id
                            student_obj = Student.query.filter_by(student_id=str(student_id)).first()

                            student_name = student_obj.name if student_obj else "N/A"
                            student_surname = student_obj.surname if student_obj else "N/A"
                            student_national_id = student_obj.national_id if student_obj else "N/A"

                            # Get course name from course_key (final_assessment_key)
                            course_obj = Course.query.filter_by(final_assessment_key=course_key).first()
                            course_name = course_obj.title if course_obj else course_key

                            # Get recent violations for this student/course to include in email
                            recent_violations = ViolationLog.query.filter_by(
                                student_id=str(student_id),
                                course_key=course_key
                            ).order_by(ViolationLog.timestamp.desc()).limit(10).all()

                            violation_summary = "\n".join([
                                f"  - {REASON_LABELS.get(v.reason, v.reason)} at {v.timestamp.strftime('%H:%M:%S')}"
                                for v in recent_violations
                            ])

                            # Generate moderation link
                            moderation_url = url_for('moderation', _external=True)

                            msg = Message(
                                subject=f"🚨 Suspicious Activity Alert: {student_name} {student_surname}",
                                recipients=violation_recipients,
                                body=(
                                    f"Student Name: {student_name} {student_surname}\n"
                                    f"Student ID Number: {student_national_id}\n"
                                    f"Platform Student ID: {student_id}\n"
                                    f"Course: {course_name}\n\n"
                                    f"Recent Violations:\n{violation_summary}\n\n"
                                    f"Time (UTC): {_now_sast().strftime('%Y-%m-%d %H:%M:%S')}\n\n"
                                    f"Moderate here: {moderation_url}\n"
                                )
                            )
                            mail.send(msg)
                            print(f"🚨 THRESHOLD REACHED! Alert email sent to {len(violation_recipients)} recipient(s) for: {student_name} {student_surname}")
                            app.logger.info(f"Violation threshold alert sent for student {student_id} (points: {tracker.current_points})")

                        # Flag threshold as hit so client can boot the student
                        threshold_hit = True

                        # Reset tracker after sending alert
                        tracker.current_points = 0
                        tracker.last_alert_at = _now_sast()
                        db.session.commit()
                        print(f"🔄 Points reset to 0 for student {student_id} after alert")
                else:
                    print(f"ℹ️ Violation '{reason}' has 0 points configured - no tracking")

        except Exception as e:
            error_msg = str(e)
            app.logger.error(f"Violation alert system error: {error_msg}")
            print(f"❌ Violation alert system error: {error_msg}")
            import traceback
            traceback.print_exc()

        return jsonify({"ok": True, "id": log.id, "threshold_reached": threshold_hit})
    except Exception as e:
        app.logger.warning(f"/api/proctor/log failed: {e}")
        return jsonify({"ok": False}), 500


@app.route("/api/proctor/boot", methods=["POST"])
def api_proctor_boot():
    """Called by client when student is booted from assessment due to a proctoring violation."""
    data = request.get_json(silent=True) or {}
    course_key = (data.get("course_key") or "").strip()
    reason = (data.get("reason") or "violation_boot").strip()
    timer_remaining = data.get("timer_remaining", 0)
    lose_attempt = bool(data.get("lose_attempt", False))

    sid = session.get("student_id")
    if not sid:
        return jsonify({"ok": False, "error": "not logged in"}), 401

    student = Student.query.filter_by(student_id=sid).first()
    if not student:
        return jsonify({"ok": False, "error": "student not found"}), 404

    norm_key = (course_key or "").strip().lower()

    if lose_attempt:
        attempt = AssessmentAttempt(
            course_key=norm_key,
            student_id=str(sid),
            student_number=str(sid),
            full_name=f"{student.name or ''} {student.surname or ''}".strip(),
            email=student.email,
            score=0,
            passed=False,
            answers_json=json.dumps({"booted": True, "reason": reason}),
            video_filename=None,
            started_at=None,
            finished_at=_now_sast(),
            duration_s=0,
            ip_address=request.headers.get("X-Forwarded-For", request.remote_addr),
            user_agent=request.headers.get("User-Agent"),
        )
        db.session.add(attempt)
        db.session.commit()
        app.logger.info(f"[BOOT] Attempt consumed for student {sid} on {norm_key} (reason: {reason})")

    boot_log = ViolationLog(
        timestamp=_now_sast(),
        student_id=str(sid),
        course_key=course_key,
        reason=f"boot_{reason}",
        detail_json=json.dumps({
            "timer_remaining": timer_remaining,
            "attempt_lost": lose_attempt,
            "original_reason": reason,
        }),
        ip=request.headers.get("X-Forwarded-For", request.remote_addr),
        user_agent=request.headers.get("User-Agent"),
    )
    db.session.add(boot_log)
    db.session.commit()

    redirect_url = url_for("violation_boot_page",
                           reason=reason,
                           lost=int(lose_attempt),
                           course=course_key)
    return jsonify({"ok": True, "redirect": redirect_url})


