@app.route("/api/violations", methods=["GET"])
def api_list_violations():
    """JSON for moderation page: violations by student (+ optional course)."""
    student_id_param = request.args.get("student_id", "").strip()
    course_id = request.args.get("course_id", "").strip()
    limit = int(request.args.get("limit", 50))

    if not student_id_param:
        return jsonify([])

    # The moderation page sends the internal DB PK, but ViolationLog
    # stores the public student_id. Resolve PK → public student_id.
    public_student_id = student_id_param
    try:
        student = db.session.get(Student, int(student_id_param))
        if student and student.student_id:
            public_student_id = str(student.student_id)
    except (ValueError, TypeError):
        pass

    q = ViolationLog.query.filter(ViolationLog.student_id == public_student_id)

    # Narrow by course key if provided.
    if course_id:
        try:
            course = Course.query.get(int(course_id))
        except Exception:
            course = None
        if course:
            keys = set()
            if course.final_assessment_key:
                keys.add(str(course.final_assessment_key))
            for col in ("code", "course_code", "slug", "shortcode"):
                if hasattr(course, col) and getattr(course, col):
                    keys.add(str(getattr(course, col)))
            if keys:
                from sqlalchemy import or_
                q = q.filter(
                    or_(*[ViolationLog.course_key == k for k in keys]))

    logs = (q.order_by(ViolationLog.timestamp.desc())
            .limit(limit).all())

    return jsonify([
        {
            "id": v.id,
            "timestamp": (v.timestamp.isoformat(sep=" ", timespec="seconds") if v.timestamp else ""),
            "student_id": v.student_id,
            "course_key": v.course_key,
            "reason": v.reason or "",
            "reason_label": REASON_LABELS.get(v.reason or "", v.reason or ""),
            "ip": v.ip or "",
            "user_agent": v.user_agent or "",
        } for v in logs
    ])
