@app.route('/violations')
@require_role('Admin')
def view_violations():

    page = request.args.get('page', 1, type=int)
    per_page = 20

    national_id_filter = request.args.get('national_id')
    name_filter = request.args.get('name')
    date = request.args.get('date')  # format: YYYY-MM-DD

    query = ViolationLog.query

    # Filter by national ID - need to find matching student_ids first
    if national_id_filter:
        matching_students = Student.query.filter(
            Student.national_id.ilike(f"%{national_id_filter}%")
        ).all()
        matching_student_ids = [str(s.student_id) for s in matching_students]
        if matching_student_ids:
            query = query.filter(ViolationLog.student_id.in_(matching_student_ids))
        else:
            # No matching students, return empty results
            query = query.filter(ViolationLog.id == -1)

    # Filter by name - search both name and surname
    if name_filter:
        matching_students = Student.query.filter(
            db.or_(
                Student.name.ilike(f"%{name_filter}%"),
                Student.surname.ilike(f"%{name_filter}%"),
                (Student.name + ' ' + Student.surname).ilike(f"%{name_filter}%")
            )
        ).all()
        matching_student_ids = [str(s.student_id) for s in matching_students]
        if matching_student_ids:
            query = query.filter(ViolationLog.student_id.in_(matching_student_ids))
        else:
            # No matching students, return empty results
            query = query.filter(ViolationLog.id == -1)

    if date:
        start = datetime.strptime(date, "%Y-%m-%d")
        end = start.replace(hour=23, minute=59, second=59)
        query = query.filter(ViolationLog.timestamp.between(start, end))

    # Get paginated results
    pagination = query.order_by(ViolationLog.timestamp.desc()).paginate(
        page=page, per_page=per_page, error_out=False)

    # Summary counts by reason (regardless of filter)
    summary_data = db.session.query(
        ViolationLog.reason,
        func.count(ViolationLog.id)
    ).group_by(ViolationLog.reason).all()

    summary_counts = {reason: count for reason, count in summary_data}

    # Build student_map for displaying student names and national IDs
    student_ids = list(set(str(log.student_id) for log in pagination.items if log.student_id))
    student_map = {}
    if student_ids:
        # Query students by student_id field
        students = Student.query.filter(Student.student_id.in_(student_ids)).all()
        for s in students:
            student_map[str(s.student_id)] = {
                'full_name': f"{s.name or ''} {s.surname or ''}".strip() or '—',
                'national_id': s.national_id or '—'
            }

    return render_template('violation_logs.html',
                           logs=pagination.items,
                           total_pages=pagination.pages,
                           page=page,
                           summary_counts=summary_counts,
                           reason_labels=REASON_LABELS,
                           student_map=student_map,
                           )

