@app.route('/violations/export', endpoint="export_violations")
def export_violations():
    """Export all (or filtered) proctoring violations as a CSV with full details."""
    # optional filters to match the /violations page
    student_id = request.args.get('student_id')
    reason = request.args.get('reason')
    date = request.args.get('date')

    query = ViolationLog.query

    if student_id:
        query = query.filter(ViolationLog.student_id.ilike(f"%{student_id}%"))
    if reason:
        query = query.filter(ViolationLog.reason.ilike(f"%{reason}%"))
    if date:
        try:
            start = datetime.strptime(date, "%Y-%m-%d")
            end = start.replace(hour=23, minute=59, second=59)
            query = query.filter(ViolationLog.timestamp.between(start, end))
        except ValueError:
            pass

    logs = query.order_by(ViolationLog.timestamp.desc()).all()

    # write full CSV
    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow([
        "ID",
        "Timestamp (UTC)",
        "Student ID",
        "Course Key",
        "Reason",
        "IP Address",
        "User Agent",
        "Detail JSON",
    ])

    for log in logs:
        writer.writerow([
            log.id,
            log.timestamp.strftime(
                '%Y-%m-%d %H:%M:%S') if log.timestamp else "",
            log.student_id or "",
            log.course_key or "",
            REASON_LABELS.get(log.reason, log.reason) or "",
            log.ip or "",
            log.user_agent or "",
            log.detail_json or "",
        ])

    csv_data = buf.getvalue()

    return Response(
        csv_data,
        mimetype='text/csv; charset=utf-8',
        headers={
            'Content-Disposition': 'attachment; filename=proctoring_violations.csv'}
    )


