@app.route('/violations/settings/points', methods=['POST'])
@require_role('Super Admin')
def violation_settings_points():
    """Update point values for violation types"""
    updated_count = 0

    for reason_code in REASON_LABELS.keys():
        points = request.form.get(f'points_{reason_code}', type=int)
        if points is not None and points >= 0:
            point_config = ViolationPointConfig.query.filter_by(reason_code=reason_code).first()
            if point_config:
                if point_config.points != points:
                    point_config.points = points
                    point_config.updated_at = _now_sast()
                    point_config.updated_by = session.get('admin_email', 'admin')
                    updated_count += 1
            else:
                point_config = ViolationPointConfig(
                    reason_code=reason_code,
                    points=points,
                    updated_by=session.get('admin_email', 'admin')
                )
                db.session.add(point_config)
                updated_count += 1

    db.session.commit()
    flash(f"Updated point values for {updated_count} violation type(s).", "success")
    return redirect(url_for('violation_settings'))


