@app.route('/admin/violation-tester/simulate', methods=['POST'])
@require_role('Developer')
def violation_tester_simulate():
    """Simulate a violation to test the threshold system"""
    student_id = request.form.get('student_id')
    course_key = request.form.get('course_key')
    reason = request.form.get('reason')

    if not student_id or not course_key or not reason:
        flash("Please select a student, course, and violation type.", "danger")
        return redirect(url_for('violation_tester'))

    # Get alert settings
    alert_settings = ViolationAlertSettings.query.first()
    if not alert_settings or not alert_settings.is_enabled:
        flash("Alert system is disabled. Enable it in Alert Settings first.", "warning")
        return redirect(url_for('violation_tester'))

    # Get point value for this violation
    point_config = ViolationPointConfig.query.filter_by(reason_code=reason).first()
    violation_points = point_config.points if point_config else 0

    if violation_points == 0:
        flash(f"Violation '{REASON_LABELS.get(reason, reason)}' has 0 points configured. No tracking occurred.", "warning")
        return redirect(url_for('violation_tester'))

    # Log the violation
    log = ViolationLog(
        timestamp=_now_sast(),
        student_id=student_id,
        course_key=course_key,
        reason=reason,
        detail_json=json.dumps({"simulated": True, "source": "violation_tester"}),
        ip="127.0.0.1",
        user_agent="Violation Tester"
    )
    db.session.add(log)
    db.session.commit()

    # Get or create tracker
    tracker = ViolationAlertTracker.query.filter_by(
        student_id=str(student_id),
        course_key=course_key
    ).first()

    if not tracker:
        tracker = ViolationAlertTracker(
            student_id=str(student_id),
            course_key=course_key,
            current_points=0
        )
        db.session.add(tracker)

    # Add points
    old_points = tracker.current_points
    tracker.current_points += violation_points
    tracker.updated_at = _now_sast()
    db.session.commit()

    # Check if threshold reached
    if tracker.current_points >= alert_settings.threshold:
        # Send alert email
        violation_recipients = get_recipients_for_category('violations')

        if not violation_recipients:
            flash(f"THRESHOLD REACHED ({tracker.current_points}/{alert_settings.threshold}) but no recipients configured!", "danger")
        else:
            try:
                student_obj = Student.query.filter_by(student_id=str(student_id)).first()
                student_name = student_obj.name if student_obj else "Test"
                student_surname = student_obj.surname if student_obj else "Student"
                student_national_id = student_obj.national_id if student_obj else "N/A"

                # Get course name from course_key (final_assessment_key)
                course_obj = Course.query.filter_by(final_assessment_key=course_key).first()
                course_name = course_obj.title if course_obj else course_key

                # Get recent violations
                recent_violations = ViolationLog.query.filter_by(
                    student_id=str(student_id),
                    course_key=course_key
                ).order_by(ViolationLog.timestamp.desc()).limit(10).all()

                violation_summary = "\n".join([
                    f"  - {REASON_LABELS.get(v.reason, v.reason)} at {v.timestamp.strftime('%H:%M:%S')}"
                    for v in recent_violations
                ])

                # Generate moderation link
                moderation_url = url_for('moderation', _external=True)

                msg = Message(
                    subject=f"🚨 [TEST] Suspicious Activity Alert: {student_name} {student_surname}",
                    recipients=violation_recipients,
                    body=(
                        f"[THIS IS A TEST FROM VIOLATION TESTER]\n\n"
                        f"Student Name: {student_name} {student_surname}\n"
                        f"Student ID Number: {student_national_id}\n"
                        f"Platform Student ID: {student_id}\n"
                        f"Course: {course_name}\n\n"
                        f"Recent Violations:\n{violation_summary}\n\n"
                        f"Time (UTC): {_now_sast().strftime('%Y-%m-%d %H:%M:%S')}\n\n"
                        f"Moderate here: {moderation_url}\n"
                    )
                )
                mail.send(msg)
                flash(f"THRESHOLD REACHED! Alert email sent to {len(violation_recipients)} recipient(s). Points: {old_points} + {violation_points} = {tracker.current_points} (threshold: {alert_settings.threshold})", "success")
            except Exception as e:
                flash(f"THRESHOLD REACHED but email failed: {str(e)}", "danger")

        # Reset tracker
        tracker.current_points = 0
        tracker.last_alert_at = _now_sast()
        db.session.commit()
    else:
        flash(f"Violation logged. Points: {old_points} + {violation_points} = {tracker.current_points} (threshold: {alert_settings.threshold})", "info")

    return redirect(url_for('violation_tester'))


