ASSESS_BASE = os.path.join(app.root_path, "uploads", "assessments")
os.makedirs(ASSESS_BASE, exist_ok=True)


def _course_dir(course_code):
    d = os.path.join(ASSESS_BASE, course_code)
    os.makedirs(d, exist_ok=True)
    return d


def load_questions_for_course(course_code):
    """
    Supports:
    1) MCQ sheet with: Question, Option_A, Option_B, Option_C, Option_D, Correct_Option (A/B/C/D)
    2) Minimal sheet with: Question_Text, Correct_Answer  -> auto-distractors
    Returns list[{id, question, option_a..d, correct}] where correct in ['a','b','c','d']
    """
    course_dir = _course_dir(course_code)

    # Allow either JSON (prebuilt) or Excel
    json_path = Path(course_dir) / "questions.json"
    xlsx_path = None
    for cand in ["questions.xlsx", "questions.xls", "questions.csv"]:
        p = Path(course_dir) / cand
        if p.exists():
            xlsx_path = p
            break

    rows = []
    if json_path.exists():
        rows = json.loads(json_path.read_text(encoding="utf-8"))

    elif xlsx_path:
        ext = xlsx_path.suffix.lower()
        if ext == ".csv":
            df = pd.read_csv(xlsx_path)
        else:
            df = pd.read_excel(xlsx_path)

        cols = [c.strip() for c in df.columns]
        df.columns = cols

        # Preferred MCQ format
        if all(c in df.columns for c in ["Question", "Option_A", "Option_B", "Option_C", "Option_D", "Correct_Option"]):
            for i, r in df.iterrows():
                q = str(r["Question"]).strip()
                A = str(r["Option_A"]).strip()
                B = str(r["Option_B"]).strip()
                C = str(r["Option_C"]).strip()
                D = str(r["Option_D"]).strip()
                correct_letter = str(r["Correct_Option"]
                                     ).strip().lower()  # 'a'/'b'/'c'/'d'
                if correct_letter not in ("a", "b", "c", "d"):
                    continue
                rows.append({
                    "question": q,
                    "option_a": A, "option_b": B, "option_c": C, "option_d": D,
                    "correct": correct_letter
                })
        # Minimal format -> auto distractors
        elif all(c in df.columns for c in ["Question_Text", "Correct_Answer"]):
            pool = [str(x).strip()
                    for x in df["Correct_Answer"].dropna().astype(str)]
            for i, r in df.iterrows():
                q = str(r["Question_Text"]).strip()
                correct = str(r["Correct_Answer"]).strip()
                # pick 3 other random answers as distractors
                distractors = [x for x in pool if x and x != correct]
                random.shuffle(distractors)
                opts = [correct] + distractors[:3]
                random.shuffle(opts)
                # map to a-d
                rows.append({
                    "question": q,
                    "option_a": opts[0],
                    "option_b": opts[1],
                    "option_c": opts[2],
                    "option_d": opts[3],
                    "correct": "abcd"[opts.index(correct)]
                })
        else:
            raise ValueError(
                "Excel must have either MCQ columns or Minimal columns as documented.")

        # Persist a normalized questions.json for speed next time
        (Path(course_dir) / "questions.json").write_text(json.dumps(rows,
                                                                    ensure_ascii=False, indent=2), encoding="utf-8")

    else:
        # No files yet: empty -> video only
        rows = []

    # attach ids
    out = []
    for idx, r in enumerate(rows, start=1):
        out.append({"id": idx, **r})
    return out


