# ---- helpers (put near your models or utils) -------------------------------
def _lookup_course(by_value: str):
    """Find a Course by common identifiers (key, slug, id)."""
    v = (by_value or "").strip()
    if not v:
        return None

    # try key
    c = Course.query.filter_by(key=v).first()
    if c:
        return c

    # try slug
    if hasattr(Course, "slug"):
        c = Course.query.filter_by(slug=v).first()
        if c:
            return c

    # try id (numeric)
    if v.isdigit():
        c = Course.query.get(int(v))
        if c:
            return c

    # last resort: course_code column if you actually have one
    if hasattr(Course, "course_code"):
        c = Course.query.filter_by(course_code=v).first()
        if c:
            return c

    return None


def _resolved_code(course):
    """
    Pick a stable identifier to use wherever 'code' was assumed.
    Order: key -> slug -> course_code -> id as string.
    """
    return (
        getattr(course, "key", None)
        or getattr(course, "slug", None)
        or getattr(course, "course_code", None)
        or (str(course.id) if getattr(course, "id", None) is not None else None)
    )


