# --- Helpers ---------------------------------------------------------------


def _lookup_course(code: str):
    """Find course by numeric ID or by key-like fields.

    Only considers real SQLAlchemy columns on the Course table — Python properties
    like ``Course.code`` are skipped because they cannot be used in a WHERE clause.
    """
    if code.isdigit():
        return Course.query.get(int(code))

    real_columns = set(Course.__table__.columns.keys())

    q = Course.query
    filters = []
    for col in ("code", "slug", "course_code", "shortcode", "final_assessment_key"):
        if col in real_columns:
            filters.append(getattr(Course, col) == code)
    if "title" in real_columns:
        filters.append(Course.title.ilike(code))
        filters.append(Course.title.ilike(code.replace("_", " ")))
    return q.filter(or_(*filters)).first() if filters else None


def _resolved_code(course) -> str:
    """Return a stable code for the course even if .code doesn't exist."""
    for col in ("code", "course_code", "slug", "shortcode"):
        if hasattr(course, col) and getattr(course, col):
            return str(getattr(course, col)).strip()
    # fallback from title/id
    base = getattr(course, "title", f"course-{course.id}").strip()
    return base.lower().replace(" ", "_")


