# Question grader dispatch (v1.1.0 Phase 3a)
#
# Every grader takes (question_dict, form) and returns (earned_points, max_points).
# Unknown types return (0, 0) so legacy files with unrecognised entries don't
# crash the assessment — they just contribute nothing to the score.
############## *************************###################

def _normalize_text(value: str, strict: bool = False) -> str:
    """Normalize a text answer for comparison.

    Non-strict mode: lowercase, trim, collapse internal whitespace.
    Strict mode: only trim — preserves case and spacing for exact matches.
    """
    if value is None:
        return ""
    v = str(value).strip()
    if strict:
        return v
    # collapse all whitespace runs to a single space, then lowercase
    import re as _re
    return _re.sub(r"\s+", " ", v).lower()


def _grade_mcq(q, form):
    """Legacy MCQ / True-False grader. One point per question by default.

    Accepts `q_{id}` (new) and `question_{id}` (legacy) form fields.
    """
    qid = q.get("id")
    points = float(q.get("points", 1))
    submitted = (
        form.get(f"q_{qid}")
        or form.get(f"question_{qid}")
        or ""
    ).strip().lower()
    correct = (q.get("correct") or q.get("answer") or "").strip().lower()
    if submitted and correct and submitted == correct:
        return (points, points)
    return (0.0, points)


def _grade_short_answer(q, form):
    """Short-answer text grader.

    Checks the submission against a list of accepted values. By default
    comparison is case-insensitive and whitespace-normalised. Set
    ``"case_sensitive": true`` on the question to enforce strict matching.

    Payload fields:
        prompt / question — the question text
        points            — max marks for a correct answer (default 1)
        accepted          — list of acceptable answers (first is the canonical)
        case_sensitive    — bool, default False
    """
    qid = q.get("id")
    points = float(q.get("points", 1))
    submitted = form.get(f"q_{qid}") or ""
    strict = bool(q.get("case_sensitive", False))

    accepted = q.get("accepted") or []
    if isinstance(accepted, str):
        accepted = [accepted]

    sub_norm = _normalize_text(submitted, strict=strict)
    if not sub_norm:
        return (0.0, points)

    for candidate in accepted:
        if _normalize_text(candidate, strict=strict) == sub_norm:
            return (points, points)
    return (0.0, points)


def _grade_table_fill(q, form):
    """Grid-of-cells grader. Each cell is independently graded.

    Payload fields:
        prompt / question — the question text above the table
        columns — [{id, label, kind: "text"|"select"|"yesno", options?}]
        rows    — [{id, prompt, answers: {col_id: value}, points_per_cell?}]
        case_sensitive — bool, default False (applies to all text cells)

    Form fields are ``q_{qid}_{row_id}_{col_id}`` per cell.
    Returns the sum of cell points earned vs the sum of cell points possible.
    """
    qid = q.get("id")
    strict = bool(q.get("case_sensitive", False))
    columns = q.get("columns") or []
    rows = q.get("rows") or []

    earned = 0.0
    total = 0.0
    for row in rows:
        row_id = row.get("id") or ""
        row_answers = row.get("answers") or {}
        cell_points = float(row.get("points_per_cell", 1))
        for col in columns:
            col_id = col.get("id") or ""
            expected = row_answers.get(col_id)
            if expected is None:
                # Column not graded for this row (e.g. decorative).
                continue
            total += cell_points
            field_name = f"q_{qid}_{row_id}_{col_id}"
            submitted = form.get(field_name) or ""
            if _normalize_text(submitted, strict=strict) == _normalize_text(str(expected), strict=strict):
                earned += cell_points
    return (earned, total)


def _grade_drag_drop(q, form):
    """Drag-and-drop grader (all-or-nothing).

    Each item is either correctly-placed in its expected zone, intentionally
    left unplaced (when ``correct_zone`` is null, i.e. a decoy), or wrong.
    Full marks are awarded only when every item's placement exactly matches
    the expected zone; any mismatch yields zero.

    Payload fields:
        prompt / question / text — the question text
        points     — max marks for the question (default 1)
        background — filename of the target image (served from the question's
                     per-question uploads folder)
        zones      — [{id, x, y, w, h, label}] with x/y/w/h expressed as
                     percentages of the background image dimensions so the
                     layout is resolution-independent
        items      — [{id, image?, label?, correct_zone}] where ``correct_zone``
                     is null for decoys (items the learner must NOT place)

    Form fields are ``q_{qid}_{item_id}`` whose value is the zone_id the
    learner dropped the item into, or empty/missing if the item was left
    unplaced.
    """
    qid = q.get("id")
    points = float(q.get("points", 1))
    items = q.get("items") or []

    if not items:
        return (0.0, points)

    for item in items:
        item_id = item.get("id")
        if not item_id:
            continue
        expected = item.get("correct_zone")
        submitted = (form.get(f"q_{qid}_{item_id}") or "").strip() or None
        if expected != submitted:
            return (0.0, points)

    return (points, points)


QUESTION_GRADERS = {
    "mcq": _grade_mcq,
    "tf":  _grade_mcq,
    "short_answer": _grade_short_answer,
    "table_fill": _grade_table_fill,
    "drag_drop": _grade_drag_drop,
}


def _describe_answer(q, form):
    """Return (selected_display, correct_display) human-readable strings for
    the student's submission and the correct answer to the given question.

    Used to populate the per-question audit list so that the remediation
    report (assessment_result.html) can show what the learner picked and what
    the right answer was, for every question type — not just MCQ. Returns
    plain strings (multi-line for table_fill and drag_drop) so the jsPDF
    renderer can wrap them with splitTextToSize.

    Falls back gracefully on missing data: returns "(not answered)" for an
    absent submission and an empty string for an absent expected answer.
    """
    qid = q.get("id")
    qtype = (q.get("type") or "mcq").lower()

    if qtype in ("mcq", "tf"):
        sel_letter = (form.get(f"q_{qid}") or form.get(f"question_{qid}") or "").strip().upper()
        correct_letter = (q.get("correct") or q.get("answer") or "").strip().upper()[:1]
        options = q.get("options") or {}

        def _fmt(letter):
            if not letter:
                return "(not answered)"
            if isinstance(options, dict) and letter in options:
                return f"{letter}) {options[letter]}"
            return letter

        return _fmt(sel_letter), _fmt(correct_letter)

    if qtype == "short_answer":
        sel = (form.get(f"q_{qid}") or "").strip()
        accepted = q.get("accepted") or []
        if isinstance(accepted, str):
            accepted = [accepted]
        correct = accepted[0] if accepted else ""
        return (sel or "(not answered)"), correct

    if qtype == "table_fill":
        columns = q.get("columns") or []
        rows = q.get("rows") or []
        sel_lines = []
        correct_lines = []
        for row in rows:
            row_id = row.get("id") or ""
            row_prompt = (row.get("prompt") or row_id).strip()
            row_answers = row.get("answers") or {}
            for col in columns:
                col_id = col.get("id") or ""
                col_label = col.get("label") or col_id
                expected = row_answers.get(col_id)
                if expected is None:
                    continue
                field = f"q_{qid}_{row_id}_{col_id}"
                submitted = (form.get(field) or "").strip()
                sel_lines.append(f"{row_prompt} / {col_label}: {submitted or '(blank)'}")
                correct_lines.append(f"{row_prompt} / {col_label}: {expected}")
        return ("\n".join(sel_lines) if sel_lines else "(not answered)",
                "\n".join(correct_lines))

    if qtype == "drag_drop":
        items = q.get("items") or []
        zones = q.get("zones") or []
        zone_label_by_id = {z.get("id"): (z.get("label") or "").strip() for z in zones}

        def _zone_name(zone_id):
            if not zone_id:
                return ""
            label = zone_label_by_id.get(zone_id, "")
            return label if label else f"zone {zone_id[:8]}"

        sel_lines = []
        correct_lines = []
        any_submitted = False
        for idx, it in enumerate(items):
            item_id = it.get("id")
            if not item_id:
                continue
            name = (it.get("label") or "").strip() or f"Item {idx + 1}"

            sel_zone = (form.get(f"q_{qid}_{item_id}") or "").strip() or None
            if sel_zone:
                any_submitted = True
                sel_lines.append(f"{name}: placed in {_zone_name(sel_zone)}")
            else:
                sel_lines.append(f"{name}: left in tray")

            correct_zone = it.get("correct_zone")
            if correct_zone:
                correct_lines.append(f"{name}: should be in {_zone_name(correct_zone)}")
            else:
                correct_lines.append(f"{name}: should stay in tray (decoy)")

        return (("\n".join(sel_lines) if any_submitted else "(not answered)"),
                "\n".join(correct_lines))

    return "(no description available)", ""


def grade_question(q, form):
    """Dispatch grader for a single question. Returns (earned, max)."""
    qtype = (q.get("type") or "mcq").lower()
    grader = QUESTION_GRADERS.get(qtype)
    if not grader:
        current_app.logger.warning(
            "grade_question: unknown question type %r on q%s; skipping", qtype, q.get("id"))
        return (0.0, 0.0)
    try:
        return grader(q, form)
    except Exception as e:
        current_app.logger.exception(
            "grade_question: grader for %r failed on q%s: %s", qtype, q.get("id"), e)
        return (0.0, float(q.get("points", 1)))


@app.route("/run_final/<string:code>", methods=["GET", "POST"])
def run_final(code):
    current_app.logger.warning(
        "RUN_FINAL -> new handler active; code=%s", code)
    """
    GET  -> render proctoring + MCQs for the mapped final of this course
    POST -> receive answers + video, save, grade, persist, show result
    """
    if not code:
        abort(400, description="Missing course code/key")

    # Accept identity from querystring (Moodle/SSO), and also fall back to logged-in session.
    for k in ["student_id", "name", "surname", "company", "national_id", "email"]:
        v = request.args.get(k)
        if v:
            session[f"fa_{k}"] = v

    sid = session.get("fa_student_id") or session.get(
        "student_id")  # fallback to logged-in student
    if not sid:
        flash("Missing student ID. Please login and try again.", "danger")
        return redirect(url_for("login"))

    # Load the course by code/key/slug/id
    course = _lookup_course(code)
    if not course:
        abort(404, description=f"Course not found for '{code}'")
    real_code = _resolved_code(course)

    # Resolve mapped final key (course.final_assessment_key wins)
    base_key = getattr(course, "final_assessment_key", None) or real_code
    final_key = (base_key or "").strip().lower().replace(" ", "_")
    alias_map = {
        # "airside": "airside_induction",
    }
    runtime_key = alias_map.get(final_key, final_key)

    # Load config + questions
    try:
        cfg, questions = get_runtime_for_course(runtime_key)
    except Exception as e:
        print(f"[run_final] failed to load bank for '{runtime_key}': {e}")
        flash("Final assessment content is not available yet. Please try again later.", "danger")
        return redirect(url_for("dashboard"))

    total = len(questions)
    if total == 0:
        flash("No questions found for this assessment.", "danger")
        return redirect(url_for("dashboard"))

    # Randomize the paper for the requested finals and keep that order in the
    # student's session until submission, so POST grading uses the same paper.
    randomized_final_keys = {
        "level_3_airport_and_airlines_air_carrier",
        "level_3_cargo",
        "test_1",
        "asat_cargo",
        "asat2",
        "rpas_final",
        "rpas",
        "rpas_awareness",
        "30",
    }
    question_order_key = f"final_question_order_{course.id}"
    if runtime_key in randomized_final_keys:
        saved_order = session.get(question_order_key)
        question_by_id = {str(q.get("id")): q for q in questions}
        if saved_order and all(str(qid) in question_by_id for qid in saved_order):
            questions = [question_by_id[str(qid)] for qid in saved_order]
        else:
            questions = list(questions)
            secrets.SystemRandom().shuffle(questions)
            session[question_order_key] = [q.get("id") for q in questions]

    # Resolve DB student row (sid is the public student number; we need the internal PK)
    student_row = Student.query.filter_by(student_id=str(sid)).first()
    if not student_row:
        flash("Student not found. Please login again.", "danger")
        return redirect(url_for("login"))

    # CAA minimum wait (v1.2), before any attempt logic runs.
    _blocked = _enforce_final_wait(student_row.id, course.id)
    if _blocked:
        return _blocked

    # ===== ATTEMPT BLOCKING LOGIC =====
    # Check previous attempts to enforce scoring rules:
    # - Below 75% = No automatic retry (must contact admin)
    # - 75-79.99% on attempt 1 = One more attempt allowed
    # - Already used 2 attempts = No more attempts
    previous_attempts = FinalAssessmentSubmission.query.filter_by(
        student_id=student_row.id,
        course_id=course.id,
        is_active=True
    ).order_by(FinalAssessmentSubmission.submitted_at.desc()).all()

    if previous_attempts:
        attempts_count = len(previous_attempts)
        latest_attempt = previous_attempts[0]
        latest_pct = latest_attempt.percentage or 0

        # Check if they already passed (shouldn't retake)
        if latest_pct >= 80:
            flash("You have already passed this assessment. No retake needed.", "info")
            return redirect(url_for("dashboard"))

        # Check if they've used all their allowed attempts
        allowed = _allowed_cap(student_row.id, course.id)
        if attempts_count >= allowed:
            # Out of attempts - check if eligible for retry request (75-79.99% on last attempt)
            if latest_pct < 75:
                flash("You scored below 75% on your final attempt. Please contact your administrator to request another attempt.", "danger")
            else:
                flash("You have no attempts remaining. Please request an additional attempt through your dashboard.", "danger")
            return redirect(url_for("dashboard"))

        # Still have automatic attempts remaining - allow retry
    # ===== END ATTEMPT BLOCKING LOGIC =====

    # Helper: real student folder "uploads/<student_number>"
    def _student_folder(student_number: str) -> str:
        return os.path.join("uploads", str(student_number))

    if request.method == "POST":
        # Save proctoring video
        video_session_id = request.form.get('video_session_id', '').strip()
        stamp = _now_sast().strftime("%Y%m%d_%H%M%S")
        folder = _student_folder(str(sid))
        os.makedirs(folder, exist_ok=True)

        video_name = None
        if video_session_id:
            # Chunked upload mode
            video_relpath = finalize_video_chunks(str(sid), video_session_id, runtime_key or 'final')
            if video_relpath:
                video_name = os.path.basename(video_relpath)
        else:
            # Fallback: single-upload
            video = request.files.get("video")
            if video and video.filename:
                video.seek(0, 2)
                vsize = video.tell()
                video.seek(0)
                if vsize < MIN_PROCTOR_VIDEO_BYTES:
                    print(f"[run_final] VIDEO REJECTED: only {vsize} bytes")
                    msg = "Your proctoring video failed to record properly. Your answers have NOT been submitted. Please ensure your camera is working and try again."
                    if request.headers.get("X-Requested-With", "").lower() == "xmlhttprequest":
                        return jsonify({"error": msg}), 400
                    flash(msg, "danger")
                    return redirect(url_for("dashboard"))

                safe_title = (getattr(cfg, "title", None) or getattr(
                    course, "title", "Final")).replace(" ", "_").replace("/", "_")
                video_name = f"{sid}_{runtime_key}_{safe_title}_{stamp}.webm"
                try:
                    video.save(os.path.join(folder, video_name))
                except Exception as e:
                    print("[run_final] video save failed:", e)

        # Grade answers via per-type dispatch (v1.1.0). Supports legacy mcq/tf,
        # plus short_answer, table_fill, and drag_drop. Unknown types contribute nothing.
        # We sum weighted points across questions rather than raw counts, so
        # a 9-mark table_fill doesn't get squashed to one point.
        earned_points = 0.0
        total_points = 0.0
        correct = 0  # number of questions with a fully-correct answer
        for q in questions:
            q_earned, q_max = grade_question(q, request.form)
            earned_points += q_earned
            total_points += q_max
            if q_max > 0 and q_earned >= q_max:
                correct += 1

        # Back-compat: when every question is 1-point MCQ, total_points == total
        # and earned_points == correct, so the old display semantics are preserved.
        if total_points > 0:
            pct = round((earned_points / total_points) * 100, 2)
        else:
            pct = 0.0
        pass_mark = getattr(cfg, "pass_mark", 80)
        passed = pct >= pass_mark

        # Persist attempt using your FinalAssessmentSubmission schema
        try:
            sub = FinalAssessmentSubmission(
                student_id=student_row.id,      # internal FK id
                course_id=course.id,
                video_filename=video_name or "",
                score=correct,
                total_questions=total,
                percentage=pct,
                review_status="Pending",
                submitted_at=_now_sast(),
            )
            # If your model has final_key column, also set it:
            if hasattr(FinalAssessmentSubmission, "final_key"):
                sub.final_key = runtime_key

            db.session.add(sub)
            db.session.commit()
        except Exception as e:
            print("[run_final] persist failed:", e)
            db.session.rollback()

        # Show result page (matches upgraded assessment_result.html)
        full_name = f"{session.get('fa_name') or ''} {session.get('fa_surname') or ''}".strip(
        )

        # Count attempts for this student + course
        attempts_used = FinalAssessmentSubmission.query.filter_by(
            student_id=student_row.id,
            course_id=course.id,
            is_active=True
        ).count()

        # Check if feedback already submitted for THIS passing attempt (not an
        # older submission for the same course_key from a prior fail/retake).
        fb_q = CourseFeedback.query.filter_by(
            student_id=student_row.id,
            course_key=runtime_key
        )
        fb_cutoff = sub.submitted_at if sub else None
        if fb_cutoff is not None:
            fb_q = fb_q.filter(CourseFeedback.created_at >= fb_cutoff)
        feedback_already_submitted = fb_q.first() is not None

        session.pop(question_order_key, None)

        return render_template(
            "assessment_result.html",
            title=(getattr(cfg, "title", None) or (
                course.title if course else runtime_key.replace('_', ' ').title())),
            full_name=full_name or "Student",
            student_id=sid,
            passed=passed,
            score=pct,
            correct=correct,
            total=total,
            pass_mark=pass_mark,
            runtime_key=runtime_key,          # used for Retake link
            course_code=runtime_key,          # used for feedback route
            back_url=url_for("dashboard"),    # consistent UX
            current_attempt=attempts_used,    # For new scoring logic
            attempt_id=sub.id if sub else None,  # for feedback form
            feedback_already_submitted=feedback_already_submitted,
        )

    # GET -> render proctored page (matches final_assessment_proctor.html expectations)
    return render_template(
        "final_assessment_proctor.html",
        title=(getattr(cfg, "title", None) or (
            course.title if course else runtime_key.replace('_', ' ').title())),
        pass_mark=getattr(cfg, "pass_mark", 80),
        questions=questions,
        student_number=sid,
        student_id=sid,
        student_name=f"{session.get('fa_name') or ''} {session.get('fa_surname') or ''}".strip(
        ),
        student_email=session.get('fa_email', ''),
    )


