def _build_options_and_flags(questions):
    """
    For each question, build:
      - is_multi: True if multiple correct answers
      - options: list of options (TF when applicable; otherwise correct + distractors)
    """
    # Build a pool of components to use as distractors (from all correct items)
    pool = []
    for q in questions:
        pool.extend(q["correct"])
    # Deduplicate while preserving case
    pool = list(dict.fromkeys([p for p in pool if p]))

    out = []
    for q in questions:
        corr = q["correct"]
        is_true_false = len(corr) == 1 and corr[0].lower() in {"true", "false"}
        if is_true_false:
            options = ["True", "False"]
            is_multi = False
        else:
            is_multi = len(corr) > 1
            # Start with all correct options
            options = list(dict.fromkeys(corr))
            # Add distractors not in correct set
            distractors = [p for p in pool if p not in options]
            random.shuffle(distractors)
            target_total = 4 if not is_multi else max(4, len(options) + 2)
            for d in distractors:
                if len(options) >= target_total:
                    break
                options.append(d)
            # Fallback fillers (very unlikely)
            i = 1
            while len(options) < max(4, len(corr)):
                filler = f"Option {i}"
                if filler not in options:
                    options.append(filler)
                i += 1
            random.shuffle(options)
        out.append({**q, "is_multi": is_multi, "options": options})
    return out


def _score_submission(questions, form):
    """
    50 questions => 2% each → 100 total.
    Full marks for an item only when selected set == correct set.
    """
    per_q = 100.0 / len(questions) if questions else 0.0
    score = 0.0
    for idx, q in enumerate(questions, start=1):
        field = f"q{idx}"
        if q["is_multi"]:
            selected = set(form.getlist(field))
        else:
            sel = form.get(field)
            selected = {sel} if sel else set()
        correct_set = set(q["correct"])
        if selected and {s.strip() for s in selected} == {c.strip() for c in correct_set}:
            score += per_q
    return int(round(score))

