# ===================== RPAS Final Assessment (mirrors Airside) =====================
# Prereqs expected to already exist in your app:
# - db (SQLAlchemy), app (Flask)
# - session, request, flash, redirect, url_for, render_template, jsonify
# - send_file, Response (if you used them in Airside PDF route), BytesIO
# - AIRSIDE_UPLOAD_ROOT (we reuse the same /uploads root)
# - AIRSIDE_ADMIN_RECIPIENTS list (we reuse the same admin recipient list)
# - current_student(), client_info(), grade_airside() (we reuse the grader)
# - require_admin()  (admin gate)
# - questions directory alongside the Airside JSON
# - you already created templates/rpas.html (copied from airside.html)
# - you can reuse templates/airside_result.html for results screen

# ---- RPAS constants ----
RPAS_TITLE = "RPAS Final Assessment"
RPAS_PASS_MARK = 80  # %
BASE_DIR = os.path.dirname(__file__)
RPAS_QUESTION_FILE = os.path.join(
    BASE_DIR, "questions", "rpas_final_final_questions.json")

# ---- RPAS question loader ----


def load_rpas_questions():
    if not os.path.exists(RPAS_QUESTION_FILE):
        raise FileNotFoundError(f"Missing {RPAS_QUESTION_FILE}")
    with open(RPAS_QUESTION_FILE, "r", encoding="utf-8") as f:
        data = json.load(f)
    # normalize
    data.sort(key=lambda x: x["id"])
    for q in data:
        if q.get("type") == "tf":
            q.setdefault("options", {"True": "True", "False": "False"})
    return data

# ---- Generic video saver for any course ----


MIN_PROCTOR_VIDEO_BYTES = 50_000   # 50 KB — any real recording is several MB


def save_proctor_video(course_key: str, student_number: str, file_storage):
    """
    Save to uploads/<student_number>/<student_number>_YYYYMMDD_<course_key>_HHMMSS.webm
    Returns rel path from app.root_path or None.
    Raises ValueError if video is present but too small (corrupt/empty).
    """
    if not file_storage or not getattr(file_storage, "filename", None):
        print(f"[{course_key.upper()}] save: no file or empty filename")
        return None

    # Check file size before saving — reject corrupt/empty recordings
    file_storage.seek(0, 2)          # seek to end
    size = file_storage.tell()
    file_storage.seek(0)             # rewind for .save()
    if size < MIN_PROCTOR_VIDEO_BYTES:
        print(f"[{course_key.upper()}] REJECTED: video only {size} bytes (min {MIN_PROCTOR_VIDEO_BYTES})")
        raise ValueError(f"Proctoring video too small ({size} bytes). Recording may have failed.")

    snum = secure_filename(student_number) if student_number else "unsure"
    student_folder = os.path.join(AIRSIDE_UPLOAD_ROOT, snum)
    os.makedirs(student_folder, exist_ok=True)

    now = _now_sast()
    filename = secure_filename(
        f"{snum}_{now.strftime('%Y%m%d')}_{course_key}_{now.strftime('%H%M%S')}.webm")
    abs_path = os.path.join(student_folder, filename)

    print(f"[{course_key.upper()}] save: writing to", abs_path)
    file_storage.save(abs_path)

    if not os.path.exists(abs_path):
        print(f"[{course_key.upper()}] save: file missing after save", abs_path)
        return None

    # e.g. uploads/12345678/...
    rel_path = os.path.relpath(abs_path, app.root_path)
    print(f"[{course_key.upper()}] save: OK rel_path = {rel_path} ({size} bytes)")
    return rel_path

# ---- RPAS attempt model ----


class RpasAttempt(db.Model):
    __tablename__ = "rpas_attempt"

    id = db.Column(db.Integer, primary_key=True)

    # identity
    student_id = db.Column(db.String(32))
    student_number = db.Column(db.String(32))
    full_name = db.Column(db.String(128))
    email = db.Column(db.String(128))

    # results
    score = db.Column(db.Float)
    passed = db.Column(db.Boolean, default=False)
    answers_json = db.Column(db.Text)

    # proctoring
    # relative path: uploads/<num>/file.webm
    video_filename = db.Column(db.String(255))

    # meta
    started_at = db.Column(db.DateTime)
    finished_at = db.Column(db.DateTime)
    duration_s = db.Column(db.Integer)
    ip_address = db.Column(db.String(64))
    user_agent = db.Column(db.String(256))
    created_at = db.Column(db.DateTime, default=_now_sast)

    # Archive flag — see FinalAssessmentSubmission.is_active. A reset flips this
    # instead of deleting the row and its proctoring video.
    is_active = db.Column(db.Boolean, default=True,
                          nullable=False, index=True)

    def __repr__(self):
        return f"<RpasAttempt id={self.id} sid={self.student_id} score={self.score} passed={self.passed}>"

# ---- Email helper (generic) ----


def send_course_admin_email(course_title, full_name, student_id, email_addr, score, passed, attempt_id):
    status = "PASS ✅" if passed else "FAIL ❌"
    subject = f"[{course_title}] {status}: {full_name} ({student_id}) — {score:.2f}%"
    body = f"""
{course_title} assessment completed.

Student: {full_name} ({student_id})
Email: {email_addr or 'N/A'}
Score: {score:.2f}%
Status: {status}
Attempt ID: {attempt_id}
Timestamp (UTC): {_now_sast().isoformat(timespec='seconds')}Z
"""
    # Get recipients from database only (no fallback)
    recipients = get_recipients_for_category('final_results')
    if not recipients:
        print(f"⚠ No final_results recipients configured. {course_title} email not sent.")
        return

    try:
        msg = Message(subject, recipients=recipients, body=body)
        mail.send(msg)
    except Exception as e:
        print(f"[WARN] Failed to send {course_title} admin email: {e}")


