def save_proctor_video(kind: str, student_number: str, file_storage):
    """
    Save to uploads/<student_number>/<student_number>_YYYYMMDD_<kind>_HHMMSS.webm
    Returns a path relative to app.root_path or None.
    """
    if not file_storage or not getattr(file_storage, "filename", None):
        print(f"[{kind.upper()}] save: no file or empty filename")
        return None

    snum = secure_filename(student_number) if student_number else "unknown"
    root = os.path.join(app.root_path, "uploads")
    student_folder = os.path.join(root, snum)
    os.makedirs(student_folder, exist_ok=True)

    now = _now_sast()
    fname = secure_filename(
        f"{snum}_{now.strftime('%Y%m%d')}_{kind}_{now.strftime('%H%M%S')}.webm")
    abs_path = os.path.join(student_folder, fname)

    print(f"[{kind.upper()}] save: writing to {abs_path}")
    file_storage.save(abs_path)

    if not os.path.exists(abs_path):
        print(f"[{kind.upper()}] save: file missing after save {abs_path}")
        return None

    rel_path = os.path.relpath(abs_path, app.root_path)
    print(f"[{kind.upper()}] save: OK rel_path = {rel_path}")
    return rel_path


