# ---- Student route: RPAS (same UX as Airside) ----
from io import BytesIO
from flask import send_file, Response
import json
from sqlalchemy import desc


@app.route("/rpas", methods=["GET", "POST"], endpoint="rpas_final_assessment")
def rpas_final_assessment():
    questions = load_rpas_questions()

    stu = current_student()
    if not stu:
        flash("Please log in first.", "warning")
        return redirect(url_for("login"))

    # Always fetch student object for detailed info
    student_obj = Student.query.filter_by(student_id=stu["student_id"]).first()

    # CAA minimum wait (v1.2). Applied to GET and POST alike, so the paper
    # cannot be fetched early and cannot be submitted early either.
    _blocked = _enforce_final_wait_standalone(student_obj, 'rpas')
    if _blocked:
        return _blocked

    if request.method == "GET":
        # Check attempts before allowing assessment - SCORE-BASED BLOCKING
        if student_obj:
            # Get previous attempts for this student
            previous_attempts = RpasAttempt.query.filter_by(
                student_id=stu["student_id"], is_active=True
            ).order_by(RpasAttempt.submitted_at.desc()).all()

            if previous_attempts:
                attempts_count = len(previous_attempts)
                latest_attempt = previous_attempts[0]
                latest_pct = latest_attempt.percentage or 0

                # Check if they already passed (shouldn't retake)
                if latest_pct >= 80:
                    flash("You have already passed this assessment. No retake needed.", "info")
                    return redirect(url_for("dashboard"))

                # Check if they've used all allowed attempts
                max_allowed = 2  # Default RPAS attempts
                rpas_course = Course.query.filter(
                    db.or_(
                        Course.final_assessment_key == 'rpas',
                        db.func.lower(Course.title).like('%rpas%')
                    )
                ).first()
                if rpas_course:
                    max_allowed = _allowed_cap(student_obj.id, rpas_course.id)

                if attempts_count >= max_allowed:
                    # Out of attempts - check if eligible for retry request
                    if latest_pct < 75:
                        flash("You scored below 75% on your final attempt. Please contact your administrator to request another attempt.", "danger")
                    else:
                        flash("You have no attempts remaining. Please request an additional attempt through your dashboard.", "danger")
                    return redirect(url_for("dashboard"))

                # Still have automatic attempts remaining - allow retry

        session["rpas_started_at"] = _now_sast().isoformat()
        if len(questions) != 50:
            flash(
                f"⚠️ {RPAS_TITLE} not ready. Expected 50 questions, found {len(questions)}. "
                f"Update questions/rpas_final_questions.json.",
                "warning",
            )

        # Get detailed student info from database
        student_first_name = student_obj.name if student_obj else ""
        student_surname = student_obj.surname if student_obj else ""
        student_national_id = student_obj.national_id if student_obj else ""

        # Count existing attempts for back button protection
        attempts_used = RpasAttempt.query.filter_by(
            student_id=stu["student_id"], is_active=True).count()
        current_attempt = attempts_used + 1

        return render_template(
            "rpas.html",  # created by copying airside.html
            title=RPAS_TITLE,
            questions=questions,
            pass_mark=RPAS_PASS_MARK,
            student_name=stu["full_name"],
            student_first_name=student_first_name,
            student_surname=student_surname,
            student_national_id=student_national_id,
            student_id=stu["student_id"],
            student_email=stu["email"],
            student_number=stu.get("student_number"),
            current_attempt=current_attempt,
        )

    # === POST: grade + save video + persist ===
    # Collect answers
    submitted = {}
    for q in questions:
        key = f"q_{q['id']}"
        val = request.form.get(key)
        if val is not None and val != "":
            submitted[str(q["id"])] = val

    # Grade (reuse Airside grader)
    score, correct_count, total, detailed = grade_airside(questions, submitted)
    passed = (score >= RPAS_PASS_MARK)

    # Timings + client meta
    started_iso = session.pop("rpas_started_at", None)
    try:
        started_at = datetime.fromisoformat(started_iso) if started_iso else None
    except Exception:
        started_at = None
    finished_at = _now_sast()
    duration_s = int((finished_at - started_at).total_seconds()) if started_at else 0
    ip, ua = client_info()

    # Resolve student_number robustly
    posted_student_number  = (request.form.get("student_number") or "").strip()
    session_student_number = (session.get("student_number") or "").strip()
    resolved_student_number = posted_student_number or session_student_number or stu["student_id"]

    # Video
    video_session_id = request.form.get('video_session_id', '').strip()
    print("[RPAS] resolved_student_number:", resolved_student_number or "<EMPTY>")
    if video_session_id:
        saved_rel = finalize_video_chunks(resolved_student_number, video_session_id, 'rpas')
    else:
        video_file = request.files.get("video")
        print("[RPAS] files:", list(request.files.keys()))
        saved_rel = save_proctor_video_rpas(resolved_student_number, video_file)
    if saved_rel:
        print("[RPAS] saved_rel:", saved_rel)
        print("[RPAS] abs exists?:", os.path.exists(os.path.join(app.root_path, saved_rel)))
    else:
        print("[RPAS] NOTE: no video saved (saved_rel None)")

    # Persist attempt
    attempt = RpasAttempt(
        student_id=stu["student_id"],
        student_number=resolved_student_number,
        full_name=stu["full_name"],
        email=stu["email"],
        score=score,
        passed=passed,
        answers_json=json.dumps(detailed, ensure_ascii=False),
        video_filename=saved_rel,
        started_at=started_at,
        finished_at=finished_at,
        duration_s=duration_s,
        ip_address=ip,
        user_agent=ua,
        created_at=_now_sast(),
    )
    db.session.add(attempt)
    db.session.commit()

    # Notify admins
    send_course_admin_email(
        RPAS_TITLE,
        stu["full_name"],
        stu["student_id"],
        stu["email"],
        score,
        passed,
        attempt.id,
    )

    # --- Certificate email + enqueue are now deferred until feedback is submitted ---

    # --- Redirect to result (AJAX-friendly) ---
    target = url_for("rpas_result", attempt_id=attempt.id)
    is_ajax = request.headers.get("X-Requested-With", "").lower() == "xmlhttprequest"
    if is_ajax:
        return jsonify({"redirect": target})
    else:
        return redirect(target)


