from flask import render_template
import json


@app.route("/rpas/result/<int:attempt_id>", methods=["GET"], endpoint="rpas_result")
def rpas_result(attempt_id):
    a = RpasAttempt.query.get_or_404(attempt_id)

    detailed = []
    try:
        detailed = json.loads(a.answers_json or "[]")
    except Exception:
        pass

    correct = sum(1 for x in detailed if x.get("is_correct"))
    total = len(detailed)

    # Get Student object to access name, surname, and national_id
    student = None
    if a.student_id:
        student = Student.query.filter_by(student_id=a.student_id).first()

    # Calculate attempts - use granted attempts if available
    attempts_used = RpasAttempt.query.filter_by(
        student_id=a.student_id, is_active=True).count()
    
    # Try to get granted attempts from CourseEnrollment
    student_obj = Student.query.filter_by(student_id=a.student_id).first()
    max_attempts = 2  # Default RPAS attempts
    
    if student_obj:
        # Try to find RPAS course
        rpas_course = Course.query.filter(
            db.or_(
                Course.final_assessment_key == 'rpas',
                db.func.lower(Course.title).like('%rpas%')
            )
        ).first()
        
        if rpas_course:
            # Use granted attempts cap
            max_attempts = _allowed_cap(student_obj.id, rpas_course.id)
    
    attempts_left = max(0, max_attempts - attempts_used)

    return render_template(
        "rpas_result.html",
        title=RPAS_TITLE,
        score=a.score or 0,
        passed=bool(a.passed),
        correct=correct,
        total=total,
        pass_mark=RPAS_PASS_MARK,
        full_name=a.full_name,
        student_id=a.student_id,
        student_name=student.name if student else a.full_name.split()[0] if a.full_name else "N/A",
        student_surname=student.surname if student else (a.full_name.split()[-1] if a.full_name and len(a.full_name.split()) > 1 else "N/A"),
        student_national_id=student.national_id if student else "N/A",
        attempt_id=a.id,
        video_filename=a.video_filename,
        attempts_used=attempts_used,
        attempts_allowed=max_attempts,
        attempts_left=attempts_left,
    )
