# ---- RPAS: list all attempts (admin) ----


@app.route("/admin/student/<student_id>/rpas-attempts")
def admin_rpas_attempts(student_id):
    maybe_redirect = require_admin()
    if maybe_redirect:
        return maybe_redirect

    # Optional student card
    student = None
    try:
        student = Student.query.filter_by(student_id=student_id).first()
    except Exception:
        pass

    attempts = RpasAttempt.query.filter_by(
        student_id=student_id).order_by(desc(RpasAttempt.created_at)).all()
    stats = {
        "count": len(attempts),
        "latest_score": attempts[0].score if attempts else None,
        "latest_passed": attempts[0].passed if attempts else None,
        "latest_when": attempts[0].created_at if attempts else None,
    }

    back_url = url_for(
        "admin_dashboard") if "admin_dashboard" in app.view_functions else url_for("index")

    return render_template(
        "admin_rpas_attempts.html",
        title=f"RPAS Attempts — {student_id}",
        student=student,
        student_id=student_id,
        attempts=attempts,
        stats=stats,
        back_url=back_url,
    )


@app.route("/admin/rpas-attempts", methods=["GET"], endpoint="admin_rpas_attempts_all")
def admin_rpas_attempts_all():
    maybe_redirect = require_admin()
    if maybe_redirect:
        return maybe_redirect

    attempts = RpasAttempt.query.order_by(
        desc(RpasAttempt.created_at)).limit(200).all()
    back_url = url_for(
        "admin_dashboard") if "admin_dashboard" in app.view_functions else url_for("index")

    return render_template(
        "admin_rpas_attempts.html",
        title="RPAS Attempts (All)",
        attempts=attempts,
        back_url=back_url,
    )

# ---- Admin: per-attempt PDF (full Q&A, robust to multi-answer) ----
# ---------- RPAS PDF helpers (robust to list/dict/multiselect) ----------


# ====================== RPAS PDF (Q&A) — robust & RPAS-branded ======================


def _norm_rpas_options(raw):
    """
    Normalize options to a dict of key->text.
    Accepts dict, list[str], list[dict], etc.
    """
    m = {}
    if isinstance(raw, dict):
        for k, v in raw.items():
            m[str(k)] = str(v)
    elif isinstance(raw, list):
        for idx, item in enumerate(raw, start=1):
            if isinstance(item, dict):
                k = item.get("key") or item.get(
                    "value") or item.get("id") or item.get("letter")
                t = item.get("text") or item.get("label") or item.get(
                    "value") or item.get("option") or item.get("answer")
                if k is None:
                    k = str(idx)
                if t is None:
                    t = str(item)
                m[str(k)] = str(t)
            else:
                s = str(item)
                m[str(idx)] = s
                m[s] = s
    m.setdefault("True", "True")
    m.setdefault("False", "False")
    return m


def _norm_keys_list(val):
    """Return list[str] keys from scalar/list/bool/None."""
    if isinstance(val, (list, tuple, set)):
        out = []
        for v in val:
            if v is True:
                out.append("True")
            elif v is False:
                out.append("False")
            else:
                out.append(str(v))
        return out
    if val is True:
        return ["True"]
    if val is False:
        return ["False"]
    if val is None:
        return []
    return [str(val)]


def _keys_and_text_display(choice, opts_map):
    keys = _norm_keys_list(choice)
    texts = [opts_map.get(k, k) for k in keys]
    return ", ".join(keys) if keys else "—", "; ".join(texts) if texts else "—"


def _rows_from_rpas_attempt(attempt, questions):
    q_index = {str(q.get("id")): q for q in (questions or [])}
    try:
        detailed = json.loads(attempt.answers_json or "[]")
    except Exception:
        detailed = []

    rows = []
    correct_count = 0
    total = len(detailed) or len(q_index) or 1

    for d in detailed:
        qid = str(d.get("id") or d.get("qid") or "")
        qbank = q_index.get(qid, {})
        opts = _norm_rpas_options(qbank.get("options", {}))

        ukey = d.get("user_choice")
        ckey = d.get("correct_answer")

        ukeys_disp, utext = _keys_and_text_display(ukey, opts)
        ckeys_disp, ctext = _keys_and_text_display(ckey, opts)

        is_correct = d.get("is_correct")
        if is_correct is None:
            # order-insensitive compare for multiselect
            is_correct = set(_norm_keys_list(ukey)) == set(
                _norm_keys_list(ckey))
        is_correct = bool(is_correct)
        if is_correct:
            correct_count += 1

        rows.append({
            "qid": d.get("id") or d.get("qid"),
            "question": d.get("question") or (qbank.get("question") or ""),
            "user_key": ukeys_disp,
            "user_text": utext,
            "corr_key": ckeys_disp,
            "corr_text": ctext,
            "is_correct": is_correct,
        })

    score = attempt.score if attempt.score is not None else round(
        (correct_count/total)*100, 2)
    passed = attempt.passed if attempt.passed is not None else (
        score >= RPAS_PASS_MARK)
    return rows, score, passed


