# ---- Finals-only helpers (filename-driven) ------------------
FINAL_ONLY_MAP = {
    "RPAS": "RPAS",
    "Aviation_Security_Awareness": "Aviation Security Awareness (Cargo Mail Stores Supplies)",
    "General_Aviation_Security_Awareness": "General Aviation Security Awareness",
    "Level3_Manager_Airports_Airlines": "Level 3 Manager - Airports and Airlines",
}


def _infer_course_from_filename(fname: str):
    """
    We save finals as <Prefix>_FinalAssessment_<studentId>_<timestamp>.webm
    Return (key, human_title) or (None, None) if not a finals file.
    """
    if "_FinalAssessment_" not in fname:
        return None, None
    key = fname.split("_FinalAssessment_")[0]
    title = FINAL_ONLY_MAP.get(key, key)
    return key, title


def _scan_student_finals(student_number: str, base_upload: str):
    """
    List all finals for a single student (by number) in /uploads/<student_number>/.
    Returns list of dict rows with keys:
      filename, key, title, ts (ISO string), path
    """
    rows = []
    student_dir = os.path.join(
        base_upload, secure_filename(str(student_number)))
    if not os.path.isdir(student_dir):
        return rows
    for fname in os.listdir(student_dir):
        if not (fname.endswith(".webm") and "_FinalAssessment_" in fname):
            continue
        key, title = _infer_course_from_filename(fname)
        if not key:
            continue
        fpath = os.path.join(student_dir, fname)
        try:
            ts = datetime.utcfromtimestamp(os.path.getmtime(
                fpath)).isoformat(timespec="seconds") + "Z"
        except Exception:
            ts = None
        rows.append({
            "filename": fname,
            "key": key,
            "title": title,
            "ts": ts,
            "path": fpath,
        })
    # newest first
    rows.sort(key=lambda r: r.get("ts") or "", reverse=True)
    return rows

