# Get course completion date and videos (works with DB ids OR raw filenames)


@app.route('/get_course_attempt/<int:student_id>/<course_id>')
def get_course_attempt(student_id, course_id):
    """
    If course_id is numeric -> pull latest FinalAssessmentSubmission for that course.
    If course_id is non-numeric -> treat it as a raw filename under /uploads/<student_number>/.
    Returns JSON:
      {
        student_number, completion_date (YYYY-MM-DDTHH:MM),
        video_filename, video_url, score, percentage
      }
    """

    # 1) Resolve student + upload folder
    student = Student.query.get(student_id)
    if not student:
        return jsonify({"error": "Student not found"}), 404

    student_number = str(student.student_id)  # folder name
    base_upload = app.config.get("UPLOAD_FOLDER", "/var/enroll/uploads")
    user_dir = os.path.join(base_upload, student_number)

    def fmt_dt(dt_obj):
        """Format for <input type='datetime-local'>."""
        if not dt_obj:
            return ""
        try:
            # if tz-aware, convert to local/server naive; else just format
            if dt_obj.tzinfo is not None:
                dt_obj = dt_obj.astimezone(timezone.utc).replace(tzinfo=None)
            return dt_obj.strftime("%Y-%m-%dT%H:%M")
        except Exception:
            return ""

    # 2) Numeric course_id path → DB lookup
    if course_id.isdigit():
        cid = int(course_id)
        submission = (FinalAssessmentSubmission.query
                      .filter(
                          FinalAssessmentSubmission.course_id == cid,
                          FinalAssessmentSubmission.is_active.is_(True),
                          # student_id might be internal PK; student.student_id often is public number
                          (FinalAssessmentSubmission.student_id == student_id) |
                          (FinalAssessmentSubmission.student_id == student.student_id)
                      )
                      .order_by(FinalAssessmentSubmission.submitted_at.desc())
                      .first())

        video_filename = submission.video_filename if submission and submission.video_filename else ""
        video_url = ""
        if video_filename:
            # Don’t trust DB to store a path. Force our canonical route.
            safe_name = os.path.basename(video_filename)
            video_url = url_for('uploaded_file',
                                student_id=student_number,
                                filename=safe_name)

        return jsonify({
            "student_number": student_number,
            "completion_date": fmt_dt(submission.submitted_at) if submission else "",
            "video_filename": video_filename,
            "video_url": video_url,
            "score": getattr(submission, "score", None) if submission else None,
            "percentage": getattr(submission, "percentage", None) if submission else None
        })

    # 3) Non-numeric course_id → treat as a single filename in <uploads>/<student_number>/
    # Sanitize: block traversal and nested paths
    unsafe = course_id
    filename = os.path.basename(unsafe)  # strips any ../ nonsense

    video_path = os.path.join(user_dir, filename)
    if os.path.isdir(user_dir) and os.path.isfile(video_path):
        try:
            mtime = datetime.fromtimestamp(os.path.getmtime(video_path))
        except Exception:
            mtime = None

        video_url = url_for('uploaded_file',
                            student_id=student_number,
                            filename=filename)

        return jsonify({
            "student_number": student_number,
            "completion_date": fmt_dt(mtime),
            "video_filename": filename,
            "video_url": video_url,
            "score": None,
            "percentage": None
        })

    # 4) Not found
    return jsonify({
        "student_number": student_number,
        "completion_date": "",
        "video_filename": "",
        "video_url": "",
        "score": None,
        "percentage": None,
        "error": "Video not found"
    }), 404

