# --- Auto-provision from link params (name/surname/id/email[/cell]) ---
# Creates a Student using the same fields your /signup uses,
# sends OTP (if email present), and logs them in (session['student_id']).


def _get_arg(*keys, default=None):
    for k in keys:
        v = request.args.get(k)
        if v and str(v).strip():
            return str(v).strip()
    return default


def auto_provision_from_link_using_signup():
    try:
        # If already logged in, nothing to do
        if session.get("student_id"):
            return

        first_name = _get_arg("name", "first_name", "firstname")
        surname = _get_arg("surname", "last_name", "lastname")
        national_id = _get_arg("id", "national_id", "id_number", "identity")
        email = _get_arg("email")
        cell = _get_arg("cell", "cell_number", "mobile", "phone")

        # Need at least a name+surname and (email or national_id) to proceed
        if not first_name or not surname or not (email or national_id):
            return  # silently skip if link has no usable identity

        # Look up by email OR national_id
        q = Student.query
        if email and national_id:
            student = q.filter((Student.email == email.lower()) | (
                Student.national_id == national_id)).first()
        elif email:
            student = q.filter_by(email=email.lower()).first()
        else:
            student = q.filter_by(national_id=national_id).first()

        if student:
            # Log them in with the external student number you use elsewhere
            session["student_id"] = student.student_id
            return

        # Not found -> create a new account (mirrors /signup fields)
        new_student_id = str(random.randint(10000000, 99999999))
        rand_password = secrets.token_urlsafe(12)
        hashed_pw = generate_password_hash(
            rand_password, method='pbkdf2:sha256')
        otp_code = str(random.randint(10000000, 99999999))

        new_student = Student(
            student_id=new_student_id,
            name=first_name,
            surname=surname,
            national_id=national_id,
            email=email.lower() if email else None,
            cell_number=cell,
            password=hashed_pw,
            selfie_filename=None,
            otp=otp_code
        )
        db.session.add(new_student)
        db.session.commit()

        # Ensure their uploads folder exists (matches your /signup behavior)
        uploads_root = app.config.get(
            "UPLOAD_FOLDER", os.path.join(app.root_path, "uploads"))
        os.makedirs(os.path.join(uploads_root, new_student_id), exist_ok=True)

        # Send OTP (best effort)
        if email:
            try:
                send_otp(email, otp_code)
                print(f"✅ OTP sent to {email} | Debug OTP: {otp_code}")
            except Exception as e:
                print(f"⚠️ OTP send failed: {e}")

        # Log them in so the page works immediately
        session["student_id"] = new_student_id

    except Exception as e:
        # Never break the assessment page if auto-provision has an issue
        print(f"⚠️ auto_provision_from_link_using_signup error: {e}")
        return


