def attempts_used(student_number: str, course_key: str) -> int:
    # Archived (reset) attempts must not count against the student.
    return FinalAssessmentAttempt.query.filter_by(
        student_number=student_number, course_key=course_key, is_active=True
    ).count()


def record_attempt(*, student_number: str, course_key: str, filename: str,
                   score_percent: float, total_questions: int, passed: bool):
    prev = attempts_used(student_number, course_key)
    attempt_no = prev + 1
    att = FinalAssessmentAttempt(
        student_number=student_number,
        course_key=course_key,
        filename=filename,
        score=int(round(score_percent)),
        total_questions=total_questions,
        percentage=float(score_percent),
        passed=passed,
        attempt_no=attempt_no,
        submitted_at=_now_sast(),
    )
    db.session.add(att)
    db.session.commit()
    return att.id, attempt_no
