@app.route("/attempt/<int:attempt_id>")
def assessment_submitted_attempt(attempt_id):
    att = FinalAssessmentAttempt.query.get_or_404(attempt_id)

    # Get pass mark from the final's config (fallback 80)
    def _pass_mark_for_key(k: str, default=80):
        try:
            cfg, _ = get_runtime_for_course(k)
            return int(getattr(cfg, "pass_mark", default) or default)
        except Exception:
            return default

    pass_mark = _pass_mark_for_key(att.course_key, default=80)

    # Attempts left & retake eligibility
    MAX_ATTEMPTS = 2
    # Use the recorded attempt_no to avoid double-counting
    attempts_left = max(0, MAX_ATTEMPTS - int(att.attempt_no or 1))
    can_retake = (not bool(att.passed)) and attempts_left > 0

    # Build a sensible retake URL for this final
    SPECIAL_START = {
        # your existing /airside-induction route
        "airside_induction": "airside_induction",
        # add more special finals here if you have bespoke runners
        # "rpas_awareness": "rpas_awareness_take",
    }

    retake_url = None
    if can_retake:
        ep = SPECIAL_START.get(att.course_key)
        if ep:
            retake_url = url_for(ep)
        elif att.course_id:
            # generic mapping-aware path
            retake_url = url_for("final_assessment", course_id=att.course_id)
        else:
            # last resort: dashboard
            retake_url = url_for("dashboard")

    # ⬇️ Render the template that shows pass/fail, attempts left, and rewrite button
    return render_template(
        "assessment_submitted_attempt.html",
        pass_mark=pass_mark,
        pct=att.percentage,
        passed=bool(att.passed),
        attempt_no=int(att.attempt_no or 1),
        attempts_left=attempts_left,
        can_retake=1 if can_retake else 0,
        retake_url=retake_url,
    )
