# --- Final Assessment attempts (auditable history) ---
class FinalAssessmentAttempt(db.Model):
    __tablename__ = "final_assessment_attempts"

    id = db.Column(db.Integer, primary_key=True)

    # who + which assessment
    student_id = db.Column(db.Integer, db.ForeignKey(
        "student.id"), nullable=False)
    student_number = db.Column(db.String(64), nullable=False, index=True)
    course_key = db.Column(db.String(64), nullable=False, index=True)

    # make this a proper FK
    course_id = db.Column(db.Integer, db.ForeignKey(
        "course.id", ondelete="SET NULL"), nullable=True)

    # attempt metadata
    attempt_no = db.Column(db.Integer, nullable=False)
    submitted_at = db.Column(
        db.DateTime, nullable=False, default=_now_sast)

    # scoring
    total_questions = db.Column(db.Integer, nullable=False)
    correct_count = db.Column(db.Integer, nullable=False)
    percentage = db.Column(db.Integer, nullable=False)
    passed = db.Column(db.Boolean, nullable=False, default=False)

    # artifacts
    video_filename = db.Column(db.String(255), nullable=True)
    answers_json = db.Column(db.Text, nullable=True)

    # moderation
    review_status = db.Column(db.String(32), nullable=False, default="Pending")

    # Archive flag — see FinalAssessmentSubmission.is_active. A reset flips this
    # instead of deleting the row and its proctoring video.
    is_active = db.Column(db.Boolean, default=True,
                          nullable=False, index=True)

    # --- relationships ---
    student = db.relationship("Student", backref=db.backref(
        "final_attempts", lazy="dynamic"))
    course = db.relationship("Course", backref=db.backref(
        "final_attempts", passive_deletes=True))


