def client_info():
    ip = (request.headers.get("X-Forwarded-For")
          or request.remote_addr or "")[:60]
    ua = (request.headers.get("User-Agent") or "")[:250]
    return ip, ua


def load_airside_questions():
    """
    Each item:
      {
        "id": 1,
        "type": "mcq" | "tf",
        "question": "text",
        "options": {"A":"...","B":"...","C":"...","D":"..."}  # TF: {"True":"True","False":"False"}
        "answer": "B"  # or "True"/"False"
      }
    """
    if not os.path.exists(AIRSIDE_QUESTION_FILE):
        # Drop a tiny starter if file is missing (so the page still renders)
        starter = [
            {
                "id": 1,
                "type": "mcq",
                "question": "Example MCQ — replace with real Q1",
                "options": {"A": "Option A", "B": "Option B", "C": "Option C", "D": "Option D"},
                "answer": "B",
            },
            {
                "id": 2,
                "type": "tf",
                "question": "Example True/False — replace with real Q2",
                "options": {"True": "True", "False": "False"},
                "answer": "True",
            },
        ]
        with open(AIRSIDE_QUESTION_FILE, "w", encoding="utf-8") as f:
            json.dump(starter, f, ensure_ascii=False, indent=2)

    with open(AIRSIDE_QUESTION_FILE, "r", encoding="utf-8") as f:
        data = json.load(f)

    # normalize/validate a bit
    data.sort(key=lambda x: x["id"])
    for q in data:
        if q.get("type") == "tf":
            q.setdefault("options", {"True": "True", "False": "False"})
    return data

