def grade_airside(questions, submitted):
    """
    Robust grader for dynamic exams.
    Returns (score, correct_count, total, detailed).
    - options can be dict with A/B/C/D or a/b/c/d or a list
    - correct can be 'answer'/'correct' (letter/text/index) or 'correct_index' (0/1-based)
    - submitted values can be 'A','B','A) 2','2','True', etc.
    """
    import re

    # --- local helper: normalize posted value -> letter using {'a':'text', ...}
    def _answer_to_letter(raw_value, options_dict):
        if raw_value is None:
            return ""
        s = str(raw_value).strip()
        if not s:
            return ""
        letters_local = "abcdefghijklmnopqrstuvwxyz"

        # already a key like 'a'/'B'
        if len(s) == 1 and s.lower() in (k.lower() for k in (options_dict or {}).keys()):
            return s.lower()

        # leading letter token (A) / B. / c:
        m = re.match(r'^\s*([A-Za-z])(?:[\)\.\:\-\s]|$)', s)
        if m:
            return m.group(1).lower()

        # pure number (1-based) -> letter
        m = re.match(r'^\s*0*([0-9]+)\s*$', s)
        if m:
            idx = int(m.group(1)) - 1
            if 0 <= idx < len(options_dict):
                return letters_local[idx]

        # exact text match
        s_low = s.lower()
        for k, v in (options_dict or {}).items():
            if str(v).strip().lower() == s_low:
                return str(k).lower()

        # trailing letter heuristic (e.g., "... option C")
        m = re.search(r'([A-Za-z])\s*$', s)
        if m and m.group(1).lower() in (k.lower() for k in (options_dict or {}).keys()):
            return m.group(1).lower()

        return ""

    # --- helper: options -> ordered list of texts
    def _to_opts_list(opts):
        if isinstance(opts, dict):
            ordered = []
            # prefer lettered keys a..z / A..Z
            for k in _letters:
                if k in opts:
                    ordered.append(str(opts[k]))
                elif k.upper() in opts:
                    ordered.append(str(opts[k.upper()]))
            # fallback: insertion order (e.g., TF dict {"True": "True", "False":"False"})
            if not ordered:
                ordered = [str(v) for v in opts.values()]
            return ordered
        elif isinstance(opts, list):
            return [str(x) for x in opts]
        return []

    # 1) Normalize questions -> letter-keyed expectations
    norm = []
    for q in (questions or []):
        qid = q.get("id")
        opts_list = _to_opts_list(q.get("options"))

        # support answer/correct OR correct_index (0- or 1-based)
        raw_corr = q.get("answer") or q.get("correct")
        if raw_corr is None and "correct_index" in q:
            try:
                raw_corr = {"index": int(q.get("correct_index"))}
            except Exception:
                raw_corr = None

        correct_letter = _coerce_correct(raw_corr, opts_list) or "a"

        norm.append({
            "id": qid,
            "opts_list": opts_list,
            "opts_dict": {_letters[i]: txt for i, txt in enumerate(opts_list) if i < len(_letters)},
            "correct": correct_letter,
        })

    # map by id (as strings) for lookups
    q_by_id = {str(q["id"]): q for q in norm}

    # 2) Collect answers from ANY field name that contains the numeric id
    answers = {}
    id_rx = re.compile(r'(\d+)')
    for name, raw_val in (submitted or {}).items():
        # grab the last number in the field name (works for answers[12], q_12, question-12, etc.)
        m = id_rx.findall(name or "")
        if not m:
            continue
        qid = m[-1]
        qdef = q_by_id.get(qid)
        if not qdef:
            continue
        letter = _answer_to_letter(raw_val, qdef["opts_dict"])
        if letter:
            answers[qid] = letter

    # 3) Grade
    score = 0
    total = len(norm)
    detailed = []
    for qid, qdef in q_by_id.items():
        sel = answers.get(qid, "")
        ok = (sel == qdef["correct"])
        if ok:
            score += 1
        detailed.append({
            "id": int(qid),
            "correct": qdef["correct"],
            "selected": sel,
            "is_right": ok,      # keep legacy key
            "is_correct": ok,    # your result template uses this
        })

    # 4) (Optional) debug once while verifying
    try:
        print("[airside.form]", dict(submitted))
        print("[airside.answers]", answers)
        print("[airside.correct]", {qid: qdef["correct"]
              for qid, qdef in q_by_id.items()})
        print(f"[airside.score] {score}/{total}")
    except Exception:
        pass

    return score, score, total, detailed

######################################################################


def send_airside_admin_email(full_name, student_id, email_addr, score, passed, attempt_id):
    status = "PASS ✅" if passed else "FAIL ❌"
    subject = f"[{AIRSIDE_TITLE}] {status}: {full_name} ({student_id}) — {score:.2f}%"
    body = f"""
{AIRSIDE_TITLE} assessment completed.

Student: {full_name} ({student_id})
Email: {email_addr or 'N/A'}
Score: {score:.2f}%
Status: {status}
Attempt ID: {attempt_id}
Timestamp (UTC): {_now_sast().isoformat(timespec='seconds')}Z
"""
    # Get recipients from database only (no fallback)
    recipients = get_recipients_for_category('final_results')
    if not recipients:
        print("⚠ No final_results recipients configured. Email not sent.")
        return

    try:
        from flask_mail import Message  # safe import even if already present
        msg = Message(subject, recipients=recipients, body=body)
        mail.send(msg)
    except Exception as e:
        print(f"[WARN] Failed to send Airside admin email: {e}")


def save_proctor_video_for_airside(student_number, file_storage):
    """
    Save to uploads/<student_number>/<student_number>_YYYYMMDD_airside_HHMMSS.webm
    Returns a path relative to app.root_path or None.
    """
    if not file_storage or not getattr(file_storage, "filename", None):
        print("[AIRSIDE] save: no file or empty filename")
        return None

    # FINAL safeguard (should not trigger with the route changes below)
    snum = secure_filename(student_number) if student_number else "unknown"
    student_folder = os.path.join(AIRSIDE_UPLOAD_ROOT, snum)
    os.makedirs(student_folder, exist_ok=True)

    now = _now_sast()
    filename = secure_filename(
        f"{snum}_{now.strftime('%Y%m%d')}_airside_{now.strftime('%H%M%S')}.webm")
    abs_path = os.path.join(student_folder, filename)

    print("[AIRSIDE] save: writing to", abs_path)
    file_storage.save(abs_path)

    if not os.path.exists(abs_path):
        print("[AIRSIDE] save: file missing after save", abs_path)
        return None

    # e.g. uploads/12345678/...
    rel_path = os.path.relpath(abs_path, app.root_path)
    print("[AIRSIDE] save: OK rel_path =", rel_path)
    return rel_path

