@app.route("/admin/airside/delete-attempt/<int:attempt_id>", methods=["POST"])
def admin_airside_delete_attempt(attempt_id):
    maybe_redirect = require_admin()
    if maybe_redirect:
        return maybe_redirect
    a = AirsideAttempt.query.get_or_404(attempt_id)
    student_id = a.student_id

    # Optional: also remove the video file if present
    try:
        if a.video_filename:
            abs_path = os.path.join(app.root_path, a.video_filename)
            if os.path.exists(abs_path):
                os.remove(abs_path)
    except Exception as e:
        print("[ADMIN] Could not remove video:", e)

    db.session.delete(a)
    db.session.commit()
    flash("Attempt deleted.", "success")
    return redirect(url_for("admin_airside_attempts", student_id=student_id))


@app.route("/admin/airside/reset/<student_id>", methods=["POST"])
def admin_airside_reset(student_id):
    maybe_redirect = require_admin()
    if maybe_redirect:
        return maybe_redirect

    qs = AirsideAttempt.query.filter_by(
        student_id=student_id, is_active=True).all()

    # Archive rather than delete: the attempt row and its proctoring video are
    # kept so moderators can still review them. The student gets a clean slate
    # because every current-state query filters on is_active.
    for a in qs:
        a.is_active = False
    db.session.commit()
    flash(f"All attempts cleared for this student. "
          f"{len(qs)} attempt(s) archived. Videos remain available for review.",
          "success")
    return redirect(url_for("admin_airside_attempts", student_id=student_id))


@app.route("/admin/airside/send-link/<student_id>", methods=["POST"])
def admin_airside_send_link(student_id):
    maybe_redirect = require_admin()
    if maybe_redirect:
        return maybe_redirect

    # Try fetch student for email/name
    student = None
    to_email = None
    full_name = None
    try:
        student = Student.query.filter_by(
            student_id=student_id).first()  # type: ignore
        if student:
            to_email = getattr(student, "email", None)
            nm = (getattr(student, "name", "") or "").strip()
            sn = (getattr(student, "surname", "") or "").strip()
            full_name = f"{nm} {sn}".strip() or None
    except Exception:
        pass

    start_url = url_for("airside_induction", _external=True)
    subject = f"[Airside Induction] New attempt link for {student_id}"
    body = f"""Hello {full_name or student_id},

An Airside Induction assessment attempt has been opened for you.

Start here:
{start_url}

If you have any issues logging in, reply to this email.

Regards,
Professional Training
"""

    try:
        from flask_mail import Message
        recipients = [to_email] if to_email else AIRSIDE_ADMIN_RECIPIENTS
        msg = Message(subject, recipients=recipients, body=body)
        mail.send(msg)
        flash(
            f"Start link sent to {to_email or 'admins (no student email found)'}", "success")
    except Exception as e:
        print("[ADMIN] send-link error:", e)
        flash("Could not send email (see server logs).", "danger")

    return redirect(url_for("admin_airside_attempts", student_id=student_id))

@app.route("/airside/result/<int:attempt_id>", methods=["GET"], endpoint="airside_result")
def airside_result(attempt_id):
    """Display airside assessment result with granted attempts"""
    a = AirsideAttempt.query.get_or_404(attempt_id)
    
    # Parse answers
    try:
        detailed = json.loads(a.answers_json or "[]")
    except Exception:
        detailed = []
    
    correct = sum(1 for x in detailed if x.get("is_correct"))
    total = len(detailed) or 1
    percentage = float(a.score or 0.0)
    passed = bool(a.passed)
    
    # Get student object
    student = Student.query.filter_by(student_id=a.student_id).first()
    student_name = student.name if student else (a.full_name.split()[0] if a.full_name else "N/A")
    student_surname = student.surname if student else (a.full_name.split()[-1] if a.full_name and len(a.full_name.split()) > 1 else "N/A")
    student_national_id = student.national_id if student else "N/A"
    
    # Calculate attempts using granted cap
    attempts_used = AirsideAttempt.query.filter_by(
        student_id=a.student_id, is_active=True).count()
    attempts_allowed = 2  # Default
    attempts_left = 0
    
    if student:
        # Try to find Airside course
        airside_course = Course.query.filter(
            db.or_(
                Course.final_assessment_key == 'airside_induction',
                db.func.lower(Course.title).like('%airside%')
            )
        ).first()

        if airside_course:
            attempts_allowed = _allowed_cap(student.id, airside_course.id)
            attempts_left = max(0, attempts_allowed - attempts_used)

    # Check if feedback already submitted for THIS passing attempt (not an
    # older submission for the same course_key from a prior fail/retake).
    feedback_already_submitted = False
    if student:
        fb_q = CourseFeedback.query.filter_by(
            student_id=student.id,
            course_key="airside_induction"
        )
        fb_cutoff = a.finished_at or a.started_at
        if fb_cutoff is not None:
            fb_q = fb_q.filter(CourseFeedback.created_at >= fb_cutoff)
        feedback_already_submitted = fb_q.first() is not None

    return render_template(
        "assessment_result.html",
        title=AIRSIDE_TITLE,
        score=percentage,
        passed=passed,
        correct=correct,
        total=total,
        pass_mark=AIRSIDE_PASS_MARK,
        student=student,
        student_name=student_name,
        student_surname=student_surname,
        student_national_id=student_national_id,
        full_name=a.full_name or f"{student_name} {student_surname}".strip() or "N/A",
        student_id=a.student_id,
        attempt_id=a.id,
        video_filename=a.video_filename,
        attempts_used=attempts_used,
        attempts_allowed=attempts_allowed,
        attempts_left=attempts_left,
        current_attempt=attempts_used,    # For new scoring logic
        course_code="airside_induction",
        feedback_already_submitted=feedback_already_submitted,
    )

