def render_airside_attempt_html(attempt, rows, score, pass_mark, passed, styles=""):
    """
    rows: list of dicts like:
      {
        'qid': 1,
        'question': '...',
        'user_key': 'A', 'user_text': 'Option text',
        'corr_key': 'B', 'corr_text': 'Option text',
        'is_correct': True/False
      }
    """
    # Default inline styles if not provided
    if not styles:
        styles = """
<style>
  body { font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif; margin: 28px; color:#0f172a; }
  h1 { margin: 0 0 4px 0; font-size: 22px; color:#0f172a; }
  .muted { color:#64748b; }
  .small { font-size: 12px; }
  .mono { font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace; }
  .summary { margin: 10px 0 14px; line-height: 1.4; }
  .badge { display:inline-block; padding:2px 8px; border-radius:999px; font-weight:600; font-size:12px; }
  .ok  { background:#dcfce7; color:#166534; }
  .bad { background:#fee2e2; color:#991b1b; }
  table { width:100%; border-collapse: collapse; margin-top: 10px; }
  thead th { background:#0f172a; color:white; text-align:left; padding:10px; font-weight:700; }
  tbody td { border-top:1px solid #e2e8f0; padding:10px; vertical-align:top; }
  tr:nth-child(even) td { background:#f8fafc; }
</style>
"""

    # Build table rows first
    row_html_parts = []
    for r in rows:
        correctness = '<span class="badge ok">Correct</span>' if r.get(
            'is_correct') else '<span class="badge bad">Incorrect</span>'
        row_html_parts.append(f"""
      <tr>
        <td class="mono">Q{r.get('qid')}</td>
        <td>{(r.get('question') or '').replace('{', '&#123;').replace('}', '&#125;')}</td>
        <td>
          <div><strong>{r.get('user_key') or '—'}</strong> — {r.get('user_text') or '—'}</div>
          <div>{correctness}</div>
        </td>
        <td><strong>{r.get('corr_key') or '—'}</strong> — {r.get('corr_text') or '—'}</td>
      </tr>""")

    rows_html = "\n".join(row_html_parts)

    # Final HTML
    html = f"""<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Airside Attempt — {attempt.student_id}</title>
{styles}
</head>
<body>
  <h1>Airside Induction Training</h1>
  <div class="muted">Full Q&amp;A Report</div>

  <div class="summary">
    <div><strong>Student:</strong> {attempt.full_name or 'N/A'} &nbsp; <span class="mono">({attempt.student_id})</span></div>
    <div><strong>Email:</strong> {attempt.email or 'N/A'}</div>
    <div><strong>Student #:</strong> {attempt.student_number or 'N/A'}</div>
    <div><strong>Attempt ID:</strong> {attempt.id}</div>
    <div><strong>Started:</strong> {attempt.started_at or ''} &nbsp; <strong>Finished:</strong> {attempt.finished_at or ''}</div>
    <div><strong>Duration:</strong> {attempt.duration_s or 0} s</div>
    <div><strong>Score:</strong> {score:.2f}% &nbsp; <strong>Pass mark:</strong> {pass_mark}% &nbsp;
         <span class="badge {'ok' if passed else 'bad'}">{'PASS' if passed else 'FAIL'}</span>
    </div>
    <div class="small muted">IP: {attempt.ip_address or ''} • UA: {attempt.user_agent or ''}</div>
  </div>

  <table>
    <thead>
      <tr>
        <th style="width:60px;">Q#</th>
        <th>Question</th>
        <th style="width:28%;">Student’s Answer</th>
        <th style="width:28%;">Correct Answer</th>
      </tr>
    </thead>
    <tbody>
{rows_html}
    </tbody>
  </table>

  <div class="muted small" style="margin-top:18px;">
    Generated on {_now_sast().strftime('%Y-%m-%d %H:%M:%SZ')} (UTC)
  </div>
</body>
</html>
"""
    fname = f"airside_attempt_{attempt.id}.html"
    return html, fname


def _render_attempt_report_html(attempt):
    """
    Build the rows by merging the stored attempt details with the master question bank
    so we can show the *text* for the chosen options.
    """
    # Load master questions: [{id, type, question, options, answer}, ...]
    questions = load_airside_questions()
    q_index = {str(q["id"]): q for q in questions}

    # Detailed stored as list of dicts we saved at submission time
    try:
        detailed = json.loads(attempt.answers_json or "[]")
    except Exception:
        detailed = []

    rows = []
    correct_count = 0
    total = len(detailed) or len(questions)

    for d in detailed:
        qid_str = str(d.get("id") or d.get("qid") or "")
        qbank = q_index.get(qid_str, {})
        options = qbank.get("options", {}) if isinstance(
            qbank.get("options"), dict) else {}

        user_key = d.get("user_choice")
        corr_key = d.get("correct_answer")

        user_text = options.get(user_key) if user_key in options else (
            user_key if user_key in ("True", "False") else None)
        corr_text = options.get(corr_key) if corr_key in options else (
            corr_key if corr_key in ("True", "False") else None)

        is_correct = bool(d.get("is_correct"))
        if is_correct:
            correct_count += 1

        rows.append({
            "qid": d.get("id") or d.get("qid"),
            "question": d.get("question") or (qbank.get("question") or ""),
            "user_key": user_key,
            "user_text": user_text,
            "corr_key": corr_key,
            "corr_text": corr_text,
            "is_correct": is_correct,
        })

    # Fallback score if not stored
    score = attempt.score if attempt.score is not None else (
        round((correct_count / total) * 100, 2) if total else 0.0)
    passed = attempt.passed if attempt.passed is not None else (
        score >= AIRSIDE_PASS_MARK)

    html, fname = render_airside_attempt_html(
        attempt=attempt,
        rows=rows,
        score=score,
        pass_mark=AIRSIDE_PASS_MARK,
        passed=passed,
    )
    return html, fname
