@app.route("/admin/airside/attempt/<int:attempt_id>/pdf", methods=["GET"], endpoint="admin_airside_attempt_pdf_v2")
@app.route("/admin/airside-attempts/<int:attempt_id>/pdf", methods=["GET"])
def admin_airside_attempt_pdf_v2(attempt_id):
    maybe_redirect = require_admin()
    if maybe_redirect:
        return maybe_redirect

    attempt = AirsideAttempt.query.get_or_404(attempt_id)
    html, fname = _render_attempt_report_html(attempt)

    # Try WeasyPrint first
    try:
        from weasyprint import HTML  # pip install weasyprint
        pdf_io = BytesIO()
        HTML(string=html, base_url=request.host_url).write_pdf(pdf_io)
        pdf_io.seek(0)
        return send_file(
            pdf_io,
            mimetype="application/pdf",
            as_attachment=True,
            download_name=f"airside_attempt_{attempt.id}.pdf",
        )
    except Exception as e:
        # Fallback to HTML (print to PDF in browser)
        return Response(html, mimetype="text/html")


