@app.route("/admin/rpas/attempt/<int:attempt_id>/pdf", methods=["GET"], endpoint="admin_rpas_attempt_pdf_v2")
def admin_rpas_attempt_pdf_v2(attempt_id):
    maybe_redirect = require_admin()
    if maybe_redirect:
        return maybe_redirect

    attempt = RpasAttempt.query.get_or_404(attempt_id)

    # Build Q&A rows using the RPAS bank (same pattern as Airside)
    questions = load_rpas_questions()
    q_index = {str(q["id"]): q for q in questions}
    try:
        detailed = json.loads(attempt.answers_json or "[]")
    except Exception:
        detailed = []

    rows, correct_count = [], 0
    total = len(detailed) or len(questions)
    for d in detailed:
        qid_str = str(d.get("id") or d.get("qid") or "")
        qbank = q_index.get(qid_str, {})
        opts = qbank.get("options", {}) if isinstance(
            qbank.get("options"), dict) else {}
        ukey, ckey = d.get("user_choice"), d.get("correct_answer")
        utext = opts.get(ukey) if ukey in opts else (
            ukey if ukey in ("True", "False") else None)
        ctext = opts.get(ckey) if ckey in opts else (
            ckey if ckey in ("True", "False") else None)
        is_correct = bool(d.get("is_correct"))
        if is_correct:
            correct_count += 1
        rows.append({
            "qid": d.get("id") or d.get("qid"),
            "question": d.get("question") or (qbank.get("question") or ""),
            "user_key": ukey,
            "user_text": utext,
            "corr_key": ckey,
            "corr_text": ctext,
            "is_correct": is_correct,
        })

    score = attempt.score if attempt.score is not None else (
        round((correct_count / total) * 100, 2) if total else 0.0)
    passed = attempt.passed if attempt.passed is not None else (
        score >= RPAS_PASS_MARK)

    html, _fname = render_airside_attempt_html(
        attempt=attempt,
        rows=rows,
        score=score,
        pass_mark=RPAS_PASS_MARK,
        passed=passed,
    )

    # Try WeasyPrint first; fallback to HTML
    try:
        from weasyprint import HTML
        pdf_io = BytesIO()
        HTML(string=html, base_url=request.host_url).write_pdf(pdf_io)
        pdf_io.seek(0)
        return send_file(
            pdf_io,
            mimetype="application/pdf",
            as_attachment=True,
            download_name=f"rpas_attempt_{attempt.id}.pdf",
        )
    except Exception as e:
        print("[RPAS PDF] WeasyPrint failed:", e)
        return Response(html, mimetype="text/html")

