# ---- Admin: reset/delete RPAS attempts ----


@app.route("/admin/rpas/reset/<student_id>", methods=["POST"], endpoint="admin_rpas_reset")
def admin_rpas_reset(student_id):
    maybe_redirect = require_admin()
    if maybe_redirect:
        return maybe_redirect

    # Archive all RPAS attempts for this student. The rows and their proctoring
    # videos are kept for moderation; is_active=False hides them from the
    # student's attempt count and progress.
    qs = RpasAttempt.query.filter_by(
        student_id=student_id, is_active=True).all()

    for a in qs:
        a.is_active = False

    db.session.commit()

    flash(f"All RPAS attempts cleared for this student. "
          f"{len(qs)} attempt(s) archived. Videos remain available for review.",
          "success")

    # ✅ Redirect back to the main attempts list
    return redirect(url_for("admin_rpas_attempts_all"))

