@app.route("/admin/rpas/delete-attempt/<int:attempt_id>", methods=["POST"], endpoint="admin_rpas_delete_attempt")
def admin_rpas_delete_attempt(attempt_id):
    maybe_redirect = require_admin()
    if maybe_redirect:
        return maybe_redirect

    a = RpasAttempt.query.get_or_404(attempt_id)
    student_id = a.student_id

    # Remove video file if present
    try:
        if a.video_filename:
            abs_path = os.path.join(app.root_path, a.video_filename)
            if os.path.exists(abs_path):
                os.remove(abs_path)
    except Exception as e:
        print("[ADMIN/RPAS] Could not remove video:", e)

    db.session.delete(a)
    db.session.commit()
    flash("RPAS attempt deleted.", "success")

    # Prefer returning to per-student page if we know it, else the "all attempts" view
    if "admin_rpas_attempts" in app.view_functions and student_id:
        return redirect(url_for("admin_rpas_attempts", student_id=student_id))
    return redirect(url_for("admin_rpas_attempts_all"))

