# ---------------------------
# Level 3 Cargo – Route
# ---------------------------


@app.route("/level_3_Cargo", methods=["GET", "POST"])
def level_3_Cargo():
    """
    Level 3 Cargo final assessment page.
    - GET: render exam using questions from /questions/level3cargo.json
    - POST: (when you wire it) handle video + answers upload and return JSON {"redirect": "..."}
    """
    if request.method == "POST":
        # TODO: handle video/answers like your other finals, then:
        # return jsonify({"redirect": url_for("assessment_submitted_attempt", attempt_id=new_id)})
        return jsonify({"redirect": url_for("admin_dashboard")})

    # ---- GET: load questions and render ----
    qfile = os.path.join(app.root_path, "questions", "level3cargo.json")
    questions = []
    title = "Level 3 Cargo"

    if os.path.exists(qfile):
        with open(qfile, "r", encoding="utf-8") as f:
            raw = json.load(f)
        # title if present
        title = raw.get("title") or title

        # Accept BOTH shapes:
        # A) {"questions":[{"text":..., "options":[...], "is_multi": bool}, ...]}
        # B) {"questions":[{"question":..., "type": "single|multi|true_false",
        #                   "options":[{"label":"A","text":"...","correct":true/false}, ...]}]}
        for q in raw.get("questions", []):
            if "text" in q and "options" in q:
                # Already in template shape
                questions.append({
                    "text": q["text"],
                    "options": q["options"],
                    "is_multi": bool(q.get("is_multi", False))
                })
            else:
                # Convert from labeled options to plain strings
                opts = [o.get("text", "") for o in q.get("options", [])]
                qtype = (q.get("type") or "").lower()
                is_multi = (qtype == "multi")
                # Treat true/false as single choice
                questions.append({
                    "text": q.get("question", ""),
                    "options": opts,
                    "is_multi": is_multi
                })

        # Keep the legacy Level 3 Cargo entry point randomized as well. The
        # mapped assessment route snapshots its order per attempt separately.
        secrets.SystemRandom().shuffle(questions)

    # Fallback if file missing/empty
    course = {"title": title}
    return render_template(
        "Level_3_Cargo_Final.html",
        course=course,
        questions=questions,
        exam_minutes=60  # or whatever you want
    )
