# ==== MCQ Editor: Question + Options + Correct ====

QUESTIONS_DIR = "/var/enroll/questions"


def _safe_json_filename(name: str) -> str:
    base = os.path.basename(name)
    if not base.lower().endswith(".json") or base.startswith(".") or "/" in base or "\\" in base:
        abort(400, "Invalid file name")
    return base


def _q(obj, *keys):
    for k in keys:
        if isinstance(obj, dict) and k in obj and obj[k] not in (None, ""):
            return str(obj[k])
    return None


def _list_from_keys(obj, keys):
    return [obj[k] for k in keys if k in obj and obj[k] not in (None, "")]


def _to_mcq(struct):
    """
    Normalize many shapes to: {'q': str, 'options': [str,...], 'correct_index': int}
    Supported inputs include:
      - {'question', 'options'|'answers'|'choices', 'correct_index'|'correct'|'answer'|'correct_answer'}
      - {'q', 'a','b','c','d', 'correct' ('A'..'D' or text)}
      - {'A','B','C','D'} style
      - list or {'questions': [...]}
    """
    if isinstance(struct, dict) and 'questions' in struct:
        struct = struct['questions']

    out = []
    if not isinstance(struct, list):
        return out

    for item in struct:
        qtext = _q(item, 'question', 'Question', 'q', 'prompt', 'text')
        options = []
        correct_index = 0

        # options via list fields
        for key in ('options', 'answers', 'choices', 'Options', 'Answers'):
            if isinstance(item, dict) and isinstance(item.get(key), list):
                options = []
                for o in item[key]:
                    if o is None:
                        options.append("")
                    elif isinstance(o, dict):
                        options.append(o.get("text", str(o)))
                    else:
                        options.append(str(o))
                break

        # lettered fields (a,b,c,d or A,B,C,D)
        if not options and isinstance(item, dict):
            letter_keys = ['a', 'b', 'c', 'd', 'e', 'A', 'B', 'C', 'D', 'E']
            opts = _list_from_keys(item, letter_keys)
            if opts:
                options = [str(x) for x in opts]

        # if still no options but we have a single correct answer, at least keep one
        corr_text = _q(item, 'answer', 'correct_answer',
                       'correctAnswer', 'correct')
        if not options and corr_text:
            options = [corr_text]

        # figure out correct
        if isinstance(item, dict):
            if isinstance(item.get('correct_index'), int):
                correct_index = max(
                    0, min(item['correct_index'], max(0, len(options)-1)))
            else:
                # 'correct' could be letter or exact text
                corr = item.get('correct') or item.get(
                    'correct_answer') or item.get('answer')
                if isinstance(corr, str):
                    # letter?
                    letters = ['A', 'B', 'C', 'D', 'E', 'F', 'G']
                    if corr.upper() in letters:
                        idx = letters.index(corr.upper())
                        if idx < len(options):
                            correct_index = idx
                    else:
                        # text match
                        try:
                            correct_index = options.index(corr)
                        except ValueError:
                            correct_index = 0

        if qtext is None:
            qtext = ""
        # ensure at least 2 editable rows
        while len(options) < 2:
            options.append("")

        out.append({'q': qtext, 'options': options,
                   'correct_index': correct_index})
    return out

