@app.post('/questions/mcq/upload-image')
def upload_question_image():
    """AJAX endpoint: upload an image for an MCQ question card."""
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        return jsonify(error='Unauthorized'), 403

    f = request.files.get('image')
    if not f or f.filename == '':
        return jsonify(error='No file selected.'), 400

    ext = f.filename.rsplit('.', 1)[-1].lower() if '.' in f.filename else ''
    if ext not in ALLOWED_IMG:
        return jsonify(error='Unsupported file type. Use PNG/JPG/WEBP.'), 400

    if request.content_length and request.content_length > MAX_BYTES:
        return jsonify(error='Image too large (max 5 MB).'), 400

    fname = f"{uuid.uuid4().hex}_{secure_filename(f.filename)}"
    f.save(os.path.join(QUESTION_IMG_DIR, fname))

    return jsonify(ok=True, filename=fname,
                   url=url_for('static', filename=f'uploads/questions/{fname}'))


@app.post('/questions/mcq/delete-image')
def delete_question_image():
    """AJAX endpoint: delete a question image file."""
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        return jsonify(error='Unauthorized'), 403

    fname = request.json.get('filename', '') if request.is_json else request.form.get('filename', '')
    if not fname:
        return jsonify(error='No filename provided.'), 400

    safe = os.path.basename(fname)
    path = os.path.join(QUESTION_IMG_DIR, safe)
    if os.path.isfile(path):
        os.remove(path)
    return jsonify(ok=True)


def _safe_json_filename(name: str) -> str:
    # keep your existing sanitizer if you already have one
    return os.path.basename(name)


def _is_unit_quiz_file(name: str) -> bool:
    return name.lower().endswith("_unit_questions.json")


def _editor_dir_for(filename: str) -> str:
    return UNIT_QUIZ_DIR if _is_unit_quiz_file(filename) else QUESTIONS_DIR


def _list_all_mcq_files():
    try:
        finals = [f for f in os.listdir(QUESTIONS_DIR) if f.endswith(".json")]
    except Exception:
        finals = []
    try:
        units = [f for f in os.listdir(UNIT_QUIZ_DIR) if f.endswith(".json")]
    except Exception:
        units = []
    # one combined list, sorted, de-duplicated
    return sorted(set(finals + units), key=str.lower)


def _to_mcq(raw):
    """Keep your existing normalizer. This stub expects {'questions': [...] }."""
    items = raw.get("questions") if isinstance(raw, dict) else raw
    if not isinstance(items, list):
        return []
    out = []
    for it in items:
        q = (it.get("question") if isinstance(it, dict) else it.get("q")) or ""
        ops_raw = it.get("options") or []
        # Normalize options: handle both plain strings and {"key":..,"text":..} dicts
        ops = []
        for o in ops_raw:
            if isinstance(o, dict):
                ops.append(o.get("text", str(o)))
            else:
                ops.append(str(o) if o is not None else "")
        ci = it.get("correct_index", 0)
        entry = {"q": q, "options": ops,
                 "correct_index": ci if isinstance(ci, int) else 0}
        img = it.get("image", "")
        if img:
            entry["image"] = img
        out.append(entry)
    return out

