@app.route("/questions/mcq/<path:filename>", methods=["GET", "POST"])
def questions_mcq(filename):
    # auth – adjust if you use a helper
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash('Unauthorized Access!', 'danger')
        return redirect(url_for('admin_login'))

    # choose the correct folder based on filename
    # keeps just the basename + .json
    fname = _safe_json_filename(filename)
    folder = _editor_dir_for(fname)                     # finals vs unit folder
    fpath = os.path.join(folder, fname)

    if request.method == "POST":
        payload = request.form.get("payload", "")
        try:
            data = json.loads(payload)

            # validate & clean
            cleaned = []
            for item in data:
                q = (item.get('q') or "").strip()
                opts = [str(x).strip() for x in (item.get('options') or [])]
                opts = [o for o in opts if o != ""]
                if len(opts) < 2 or not q:
                    continue
                ci = item.get('correct_index', 0)
                if not isinstance(ci, int) or ci < 0 or ci >= len(opts):
                    ci = 0
                entry = {'question': q, 'options': opts, 'correct_index': ci}
                img = (item.get('image') or '').strip()
                if img:
                    entry['image'] = img
                cleaned.append(entry)

            # backup
            if os.path.isfile(fpath):
                ts = _now_sast().strftime("%Y%m%d-%H%M%S")
                with open(fpath, "rb") as src, open(f"{fpath}.bak-{ts}", "wb") as dst:
                    dst.write(src.read())

            # write out (same format you already use)
            with open(fpath, "w", encoding="utf-8") as f:
                json.dump({'questions': cleaned}, f,
                          indent=2, ensure_ascii=False)
                f.write("\n")

            flash("✅ Saved questions.", "success")
        except Exception as e:
            flash(f"❌ Save failed: {e}", "danger")

        return redirect(url_for("questions_mcq", filename=fname))

    # GET
    if not os.path.isfile(fpath):
        flash("File not found.", "danger")
        return redirect(url_for('admin_dashboard'))

    try:
        with open(fpath, "r", encoding="utf-8") as f:
            raw = json.load(f)
        mcq = _to_mcq(raw)
    except Exception as e:
        flash(f"❌ Could not parse JSON: {e}", "danger")
        mcq = []

    last_saved = datetime.utcfromtimestamp(
        os.path.getmtime(fpath)).strftime("%Y-%m-%d %H:%M UTC")

    # show files from BOTH folders in the sidebar
    finals = [f for f in (os.listdir(QUESTIONS_DIR) if os.path.isdir(
        QUESTIONS_DIR) else []) if f.endswith(".json")]
    units = [f for f in (os.listdir(UNIT_QUIZ_DIR) if os.path.isdir(
        UNIT_QUIZ_DIR) else []) if f.endswith(".json")]
    files = sorted(set(finals + units), key=str.lower)

    return render_template(
        "questions_mcq.html",
        selected=fname,
        files=files,
        mcq=mcq,
        last_saved=last_saved
    )
