@app.route("/admin/students")
def admin_students():
    # Fetch students
    students = (
        db.session.query(Student)
        .order_by(Student.registration_date.desc())
        .all()
    )

    # Build enrollments_by_student using CourseEnrollment + Course
    enrollments_by_student = {}

    # Preload enrollments + course to avoid N+1
    student_ids_db = [s.id for s in students]  # DB PKs
    enrollments = (
        db.session.query(CourseEnrollment)
        .options(joinedload(CourseEnrollment.course))
        .filter(CourseEnrollment.student_id.in_(student_ids_db))
        .all()
    )

    # Map DB PK -> external student_id
    pk_to_external = {s.id: s.student_id for s in students}

    for ce in enrollments:
        sid_external = pk_to_external.get(ce.student_id)
        if not sid_external:
            continue
        # Convert last_accessed from UTC to SAST (UTC+2)
        last_accessed_sast = ce.last_accessed + timedelta(hours=2) if ce.last_accessed else None
        enrollments_by_student.setdefault(sid_external, []).append({
            "enrollment_id": ce.id,
            "course_id": ce.course_id,
            "course_title": ce.course.title if ce.course else "—",
            "approved": bool(ce.approved),
            "completed": bool(ce.completed),
            "certificate_issued": bool(ce.certificate_issued),
            "certificate_issued_date": ce.certificate_issued_date,
            "enrolled_at": ce.enrolled_at,
            "last_accessed": last_accessed_sast,
        })

    return render_template(
        "view_students.html",
        students=students,
        enrollments_by_student=enrollments_by_student,
        # keep passing your existing context (attempts_stats_*, etc.)
    )
