# Shared Question-Set Builder (v1.1.0 Phase 3a.ii)
#
# One UI to author mcq / tf / short_answer / table_fill / drag_drop questions for ANY
# question set, identified by a key. Writes the exact JSON schema that
# grade_question() and the player partials already consume, so the same
# builder serves virtual-course quizzes AND final assessments.
############## *************************###################

def _question_set_path(key: str, for_write: bool = False) -> str:
    """Resolve the JSON file for a question-set key.

    On read, mirrors load_questions()'s candidate order so existing files are
    found. On write, always uses the canonical <key>_final_questions.json
    (the name load_questions checks first).
    """
    base = os.path.join(app.root_path, "questions")
    os.makedirs(base, exist_ok=True)
    canonical = os.path.join(base, f"{key}_final_questions.json")
    if for_write:
        return canonical
    for fname in (f"{key}_final_questions.json", f"{key}_questions.json", f"{key}.json"):
        p = os.path.join(base, fname)
        if os.path.exists(p):
            return p
    # case-insensitive fallback
    try:
        files = {n.lower(): n for n in os.listdir(base)}
        for fname in (f"{key}_final_questions.json", f"{key}_questions.json", f"{key}.json"):
            if fname.lower() in files:
                return os.path.join(base, files[fname.lower()])
    except FileNotFoundError:
        pass
    return canonical


def _load_question_set(key: str) -> list:
    """Load the raw (un-normalized) question list as authored. Empty if none."""
    path = _question_set_path(key)
    if not os.path.exists(path):
        return []
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (json.JSONDecodeError, OSError):
        return []
    if isinstance(data, dict):
        for k in ("questions", "data", "items"):
            if isinstance(data.get(k), list):
                data = data[k]
                break
    if not isinstance(data, list):
        return []
    # ensure each has id/type/position so the editor is stable
    for i, q in enumerate(data, start=1):
        try:
            q["id"] = int(q.get("id", i))
        except (TypeError, ValueError):
            q["id"] = i
        if not q.get("type"):
            q["type"] = "mcq"
        if "position" not in q:
            q["position"] = i
    data.sort(key=lambda x: (x.get("position", x.get("id", 0)), x.get("id", 0)))
    return data


def _save_question_set(key: str, questions: list) -> None:
    """Persist the question list, renumbering position 1..N by current order."""
    for idx, q in enumerate(questions, start=1):
        q["position"] = idx
    path = _question_set_path(key, for_write=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(questions, f, ensure_ascii=False, indent=2)


def _next_question_id(questions: list) -> int:
    return (max((int(q.get("id", 0)) for q in questions), default=0) + 1)


def _dragdrop_question_dir(key: str, qid) -> str:
    """Filesystem path of the per-question asset folder under
    static/uploads/questions/<key>/<qid>/. Created on demand."""
    base = os.path.join(app.root_path, "static", "uploads", "questions", str(key), str(qid))
    os.makedirs(base, exist_ok=True)
    return base


def _save_dragdrop_asset(key: str, qid, file_storage) -> Optional[str]:
    """Save an uploaded image into the per-question folder and return the
    path relative to ``static/uploads/questions/`` (i.e. ``<key>/<qid>/<name>``)
    so it can be stored in the question payload and resolved later via
    ``url_for('static', filename='uploads/questions/' + path)``.

    Returns None if no file was supplied (caller falls back to the previously
    stored filename in that case). Filenames are run through
    ``secure_filename`` and made unique within the folder.
    """
    if not file_storage or not file_storage.filename:
        return None
    base_dir = _dragdrop_question_dir(key, qid)
    safe_name = secure_filename(file_storage.filename) or f"asset_{uuid4().hex[:8]}.bin"
    target = os.path.join(base_dir, safe_name)
    if os.path.exists(target):
        stem, ext = os.path.splitext(safe_name)
        safe_name = f"{stem}_{uuid4().hex[:6]}{ext}"
        target = os.path.join(base_dir, safe_name)
    file_storage.save(target)
    return f"{key}/{qid}/{safe_name}"


def _delete_dragdrop_folder(key: str, qid) -> None:
    """Remove the per-question asset folder when a drag_drop question is deleted."""
    folder = os.path.join(app.root_path, "static", "uploads", "questions", str(key), str(qid))
    if os.path.isdir(folder):
        try:
            shutil.rmtree(folder)
        except OSError as e:
            app.logger.warning("Failed to remove drag_drop asset folder %s: %s", folder, e)


def _parse_question_from_form(form, qid: int, files=None, key: Optional[str] = None) -> dict:
    """Build one question dict from submitted builder form fields.

    Field conventions (single question per submit):
      type, question, points, hint
      mcq:          opt_a..opt_d, correct (A/B/C/D)
      tf:           correct (True/False)
      short_answer: accepted (newline-separated), case_sensitive (checkbox)
      table_fill:   payload_json (the columns+rows object as JSON text from the
                    Alpine editor); validated here.
      drag_drop:    payload_json describing zones + items + the field names of
                    any uploaded image files. The actual file bytes live in
                    ``files`` (request.files) under those field names; this
                    function persists them to the per-question folder and
                    rewrites the payload to store the saved relative paths.
                    Items can also carry an ``image_existing`` field that
                    preserves the previously-saved image when the admin did
                    not upload a replacement.
    """
    qtype = (form.get("type") or "mcq").strip().lower()
    q = {
        "id": qid,
        "type": qtype,
        "question": (form.get("question") or "").strip(),
        "points": max(1, form.get("points", type=int) or 1),
    }
    hint = (form.get("hint") or "").strip()
    if hint:
        q["hint"] = hint

    if qtype == "mcq":
        opts = {}
        for letter in ("A", "B", "C", "D", "E"):
            val = (form.get(f"opt_{letter.lower()}") or "").strip()
            if val:
                opts[letter] = val
        q["options"] = opts
        q["correct"] = (form.get("correct") or "").strip().upper()[:1]

    elif qtype == "tf":
        q["options"] = {"A": "True", "B": "False"}
        # Read 'tf_correct' (not 'correct') so the MCQ block's hidden 'correct'
        # field doesn't override the TF admin choice.
        tf_choice = (form.get("tf_correct") or form.get("correct") or "").strip().lower()
        q["correct"] = "A" if tf_choice in ("a", "true", "t", "1") else "B"

    elif qtype == "short_answer":
        raw = form.get("accepted") or ""
        accepted = [line.strip() for line in raw.replace(",", "\n").splitlines() if line.strip()]
        q["accepted"] = accepted
        q["case_sensitive"] = bool(form.get("case_sensitive"))

    elif qtype == "table_fill":
        try:
            payload = json.loads(form.get("payload_json") or "{}")
        except json.JSONDecodeError:
            payload = {}
        q["columns"] = payload.get("columns") or []
        q["rows"] = payload.get("rows") or []

    elif qtype == "drag_drop":
        try:
            payload = json.loads(form.get("payload_json") or "{}")
        except json.JSONDecodeError:
            payload = {}

        files = files or {}

        # Background: prefer a freshly-uploaded file, fall back to existing path.
        bg_field = payload.get("background_field")
        bg_existing = payload.get("background_existing")
        background_path = ""
        if bg_field and key is not None:
            saved = _save_dragdrop_asset(key, qid, files.get(bg_field))
            if saved:
                background_path = saved
        if not background_path and bg_existing:
            background_path = bg_existing
        q["background"] = background_path

        # Zones: coerce to numbers, drop malformed rows.
        zones = []
        for z in (payload.get("zones") or []):
            try:
                zones.append({
                    "id": str(z.get("id") or "").strip(),
                    "x": float(z.get("x") or 0),
                    "y": float(z.get("y") or 0),
                    "w": float(z.get("w") or 0),
                    "h": float(z.get("h") or 0),
                    "label": (z.get("label") or "").strip(),
                })
            except (TypeError, ValueError):
                continue
        q["zones"] = zones
        valid_zone_ids = {z["id"] for z in zones}

        # Items: resolve image files, validate correct_zone references.
        items = []
        for item_meta in (payload.get("items") or []):
            item_id = str(item_meta.get("id") or "").strip()
            if not item_id:
                continue
            entry = {
                "id": item_id,
                "label": (item_meta.get("label") or "").strip(),
            }
            cz = item_meta.get("correct_zone")
            entry["correct_zone"] = cz if (cz in valid_zone_ids) else None

            img_field = item_meta.get("image_field")
            img_existing = item_meta.get("image_existing")
            image_path = ""
            if img_field and key is not None:
                saved = _save_dragdrop_asset(key, qid, files.get(img_field))
                if saved:
                    image_path = saved
            if not image_path and img_existing:
                image_path = img_existing
            if image_path:
                entry["image"] = image_path

            items.append(entry)
        q["items"] = items

    return q


@app.route("/admin/question-builder/<key>", methods=["GET"])
def admin_question_builder(key):
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))
    questions = _load_question_set(key)
    # Try to surface a friendly title from assessments.json
    title = key
    try:
        for a in (load_assessments_cfg() or []):
            if a.get("key") == key:
                title = a.get("title", key)
                break
    except Exception:
        pass
    return_to = request.args.get("return_to") or url_for("admin_final_assessments")
    return render_template(
        "admin_question_builder.html",
        key=key, title=title, questions=questions, return_to=return_to,
    )


@app.route("/admin/question-builder/<key>/save", methods=["POST"])
def admin_question_builder_save(key):
    """Add a new question or update an existing one (qid in form)."""
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))

    questions = _load_question_set(key)
    edit_id = request.form.get("qid", type=int)

    if edit_id:
        idx = next((i for i, q in enumerate(questions) if int(q.get("id", -1)) == edit_id), None)
        if idx is None:
            flash("⚠ Question not found.", "danger")
            return redirect(url_for("admin_question_builder", key=key))
        new_q = _parse_question_from_form(request.form, edit_id, files=request.files, key=key)
        new_q["position"] = questions[idx].get("position", idx + 1)
        questions[idx] = new_q
        flash("✅ Question updated.", "success")
    else:
        new_qid = _next_question_id(questions)
        new_q = _parse_question_from_form(request.form, new_qid, files=request.files, key=key)
        questions.append(new_q)
        flash("✅ Question added.", "success")

    _save_question_set(key, questions)
    return redirect(url_for("admin_question_builder", key=key,
                            return_to=request.form.get("return_to") or None))


@app.route("/admin/question-builder/<key>/delete/<int:qid>", methods=["POST"])
def admin_question_builder_delete(key, qid):
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access!", "danger")
        return redirect(url_for('admin_login'))
    all_qs = _load_question_set(key)
    target = next((q for q in all_qs if int(q.get("id", -1)) == qid), None)
    questions = [q for q in all_qs if int(q.get("id", -1)) != qid]
    _save_question_set(key, questions)
    # If the deleted question was drag_drop, also remove its per-question asset folder.
    if target and (target.get("type") or "").lower() == "drag_drop":
        _delete_dragdrop_folder(key, qid)
    flash("✅ Question deleted.", "success")
    return redirect(url_for("admin_question_builder", key=key))


@app.route("/admin/question-builder/<key>/reorder", methods=["POST"])
def admin_question_builder_reorder(key):
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        return jsonify(ok=False, error="unauthorized"), 401
    order = request.json.get("order") if request.is_json else None
    if not order:
        return jsonify(ok=False, error="no order"), 400
    questions = _load_question_set(key)
    by_id = {int(q.get("id")): q for q in questions}
    reordered = [by_id[i] for i in order if i in by_id]
    # append any not mentioned (safety)
    reordered += [q for q in questions if int(q.get("id")) not in set(order)]
    _save_question_set(key, reordered)
    return jsonify(ok=True)


