def load_questions(course_key: str):
    """
    Returns a list[dict] of questions.
    Accepts files shaped as:
      - [{"id": 1, "question": "...", "options": {...}, "answer": "A"}, ...]
      - {"questions":[...]}

    Each question is normalized to carry a ``type`` field. Legacy MCQ-shaped
    questions (no type, but have options+correct) default to ``"mcq"`` so
    existing assessments keep working unchanged. New v1.1.0 types supported:
    ``short_answer``, ``table_fill``, ``drag_drop``. Unknown types pass through
    untouched and are skipped by the grader rather than causing a crash.
    """
    base = os.path.join(app.root_path, "questions")
    candidates = [
        f"{course_key}_final_questions.json",
        f"{course_key}_questions.json",
        f"{course_key}.json",
    ]

    def _normalize(payload):
        # turn dict-with-key into a list if needed
        if isinstance(payload, dict):
            for k in ("questions", "data", "items"):
                if k in payload and isinstance(payload[k], list):
                    payload = payload[k]
                    break
        if not isinstance(payload, list):
            raise ValueError(
                "Questions file must be a list or a dict containing a list.")
        # sort & coerce ids + type field
        for i, q in enumerate(payload, start=1):
            try:
                q["id"] = int(q.get("id", i))
            except Exception:
                q["id"] = i
            # normalize options: list -> dict {"A": "text", ...}
            letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
            if isinstance(q.get("options"), list):
                q["options"] = {letters[idx]: opt for idx,
                                opt in enumerate(q["options"])}
            # Translate correct_index → correct letter if the file uses the
            # index-based shape (e.g. {"correct_index": 0} meaning "A").
            if "correct_index" in q and not q.get("correct"):
                try:
                    idx = int(q["correct_index"])
                    if 0 <= idx < len(letters):
                        q["correct"] = letters[idx]
                except Exception:
                    pass
            # Default legacy rows to "mcq" so existing assessments keep working.
            if not q.get("type"):
                q["type"] = "mcq"
        # Sort by explicit position when the builder has set one (lets admins
        # reorder without renumbering ids), else fall back to id order.
        payload.sort(key=lambda x: (x.get("position", x.get("id", 0)), x.get("id", 0)))
        return payload

    # exact names
    for fname in candidates:
        path = os.path.join(base, fname)
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                return _normalize(json.load(f))

    # case-insensitive fallback
    try:
        files = {n.lower(): n for n in os.listdir(base)}
        for fname in candidates:
            if fname.lower() in files:
                path = os.path.join(base, files[fname.lower()])
                with open(path, "r", encoding="utf-8") as f:
                    return _normalize(json.load(f))
    except FileNotFoundError:
        pass

    raise FileNotFoundError(
        f"No questions found for {course_key}. Tried {', '.join(candidates)} in {base}"
    )

########################### **************################

# --- Scoring helper (place right below load_questions) ---


def evaluate_final(course_key: str, submitted: dict):
    """
    Loads questions JSON and compares to submitted answers.
    Returns (score, total, percentage:int, passed:bool).
    """
    try:
        questions = load_questions(course_key)
    except Exception as e:
        print(f"[evaluate_final] load failed for {course_key}: {e}")
        return (0, 0, 0, False)

    score = 0
    total = len(questions)

    for q in questions:
        qid = str(q["id"])
        correct_answer = str(q.get("answer", "")).strip()
        student_answer = str(submitted.get(qid, "")).strip()

        # MCQ: options present => compare letter (A/B/C/…)
        if q.get("options"):
            if student_answer.upper() == correct_answer.upper():
                score += 1
        else:
            # Free-text: simple case-insensitive exact match
            if student_answer.lower() == correct_answer.lower():
                score += 1

    pct = round((score / total) * 100) if total else 0
    passed = pct >= 80  # Pass mark is 80%
    return score, total, pct, passed


def compute_and_record_final_attempt(
    *, student, course_key, course_id=None, video_relpath=None, submitted_answers: dict
    ):
    """
    DO NOT change your existing record_final_attempt.
    This helper computes (score/total/percentage/passed) and calls it.
    """
    score, total, percentage, passed = evaluate_final(
        course_key, submitted_answers)
    return record_final_attempt(
        student=student,
        course_key=course_key,
        course_id=course_id,
        score=score,
        total=total,
        passed=passed,
        video_relpath=video_relpath,
        answers_dict=submitted_answers,
    )
# --- end helper ---


