@app.route("/final/<course_key>/submit", methods=["POST"])
def final_submit_generic(course_key):
    # collect answers from the form. Expect fields like name="q_12" value="A" or free text
    answers = {}
    for k, v in request.form.items():
        if k.startswith("q_"):
            qid = k.split("_", 1)[1]  # "q_12" -> "12"
            answers[qid] = v

    # resolve student + course_id
    student = Student.query.filter_by(
        student_id=session.get("student_id")).first()
    course = Course.query.filter_by(key=course_key).first(
    ) if "key" in Course.__table__.c else None
    course_id = course.id if course else None

    # your video path if you saved it earlier; else leave None
    video_relpath = request.form.get("video_relpath") or None

    attempt_id, attempt_no = compute_and_record_final_attempt(
        student=student,
        course_key=course_key,
        course_id=course_id,
        video_relpath=video_relpath,
        submitted_answers=answers,
    )

    # redirect to your existing result page (keep your UX as-is)
    # if you have a per-key result route, use it; otherwise reuse your generic
    return redirect(url_for("assessment_submitted_attempt", attempt_id=attempt_id))


