def save_proctor_video(kind: str, student_number: str, file_storage):
    if not file_storage or not getattr(file_storage, "filename", None):
        return None
    snum = secure_filename(student_number) if student_number else "unknown"
    root = os.path.join(app.root_path, "uploads", snum)
    os.makedirs(root, exist_ok=True)
    now = _now_sast()
    fname = secure_filename(
        f"{snum}_{now.strftime('%Y%m%d')}_{kind}_{now.strftime('%H%M%S')}.webm")
    abs_path = os.path.join(root, fname)
    file_storage.save(abs_path)
    return os.path.relpath(abs_path, app.root_path) if os.path.exists(abs_path) else None


def register_assessment(app, course_key: str, title: str, pass_mark: int):
    tpl_take = "proctored_assessment.html"
    tpl_result = "assessment_result.html"

    def take():
        qs = load_questions(course_key)
        stu = current_student()
        if not stu:
            flash("Please log in first.", "warning")
            return redirect(url_for("login"))

        if request.method == "GET":
            session[f"{course_key}_started_at"] = _now_sast().isoformat()
            if len(qs) != 50:
                flash(
                    f"⚠️ {title} not ready. Expected 50 Qs, found {len(qs)}.", "warning")

            # Count existing attempts for this student + course
            existing_attempts = AssessmentAttempt.query.filter_by(
                course_key=course_key,
                student_id=stu["student_id"],
                is_active=True
            ).count()
            current_attempt = existing_attempts + 1

            return render_template(
                tpl_take,
                title=title,
                questions=qs,
                pass_mark=pass_mark,
                student_name=stu["full_name"],
                student_id=stu["student_id"],
                student_email=stu["email"],
                student_number=stu.get("student_number"),
                current_attempt=current_attempt,
                course_key=course_key,  # For violation tracking
            )

        # POST
        submitted = {
            str(q["id"]): request.form.get(f"q_{q['id']}")
            for q in qs
            if request.form.get(f"q_{q['id']}") not in (None, "")
        }

        # score = number correct (count). Convert to percentage for display/storage.
        started_iso = session.pop(f"{course_key}_started_at", None)
        started_at = datetime.fromisoformat(
            started_iso) if started_iso else None
        finished_at = _now_sast()
        duration_s = int(
            (finished_at - started_at).total_seconds()) if started_at else 0
        ip, ua = client_info()

        posted_number = (request.form.get("student_number") or "").strip()
        session_number = (session.get("student_number") or "").strip()
        # ← fixed typo
        resolved_number = posted_number or session_number or stu["student_id"]

        video_session_id = request.form.get('video_session_id', '').strip()
        if video_session_id:
            video_rel = finalize_video_chunks(resolved_number, video_session_id, course_key)
        else:
            video_file = request.files.get("video")
            try:
                video_rel = save_proctor_video(course_key, resolved_number, video_file)
            except ValueError as ve:
                print(f"[{course_key}] VIDEO REJECTED: {ve}")
                msg = "Your proctoring video failed to record properly. Your answers have NOT been submitted. Please ensure your camera is working and try again."
                if request.headers.get("X-Requested-With", "").lower() == "xmlhttprequest":
                    return jsonify({"error": msg}), 400
                flash(msg, "danger")
            return redirect(url_for("dashboard"))

        attempt = AssessmentAttempt(
            course_key=course_key,
            student_id=stu["student_id"],
            student_number=resolved_number,
            full_name=stu["full_name"],
            email=stu["email"],
            score=percentage,                 # ← store % so templates/emails are sane
            passed=passed,                    # ← computed from percentage vs pass mark
            answers_json=json.dumps(detailed, ensure_ascii=False),
            video_filename=video_rel,
            started_at=started_at,
            finished_at=finished_at,
            duration_s=duration_s,
            ip_address=ip,
            user_agent=ua,
        )
        db.session.add(attempt)
        db.session.commit()

        print("[attempt saved] id=", attempt.id, "score=",
              attempt.score, "passed=", attempt.passed)

        # email should also report the percentage, not the raw correct count
        send_course_admin_email(
            title, stu["full_name"], stu["student_id"], stu["email"], percentage, passed, attempt.id
        )

        # --- Certificate email + enqueue are now deferred until feedback is submitted ---

        target = url_for(f"{course_key}_result", attempt_id=attempt.id)
        if request.headers.get("X-Requested-With", "").lower() == "xmlhttprequest":
            return jsonify({"redirect": target})
        return redirect(target)

    def result(attempt_id: int):
        """Display the result page for a completed assessment attempt."""
        a = AssessmentAttempt.query.get_or_404(attempt_id)

        # --- Decode and calculate score metrics ---
        detailed = json.loads(a.answers_json or "[]") if a.answers_json else []
        correct = sum(1 for x in detailed if x.get("is_right"))
        total = len(detailed) or 1
        percentage = round((correct / total) * 100.0, 2)

        # --- Normalize pass mark (handle str/int/float safely) ---
        try:
            pm = float(pass_mark)
        except Exception:
            pm = float(str(pass_mark).replace("%", "").strip() or 80)

        passed = percentage >= pm

        # --- Fetch Student object to get name, surname, and national_id ---
        student = None
        student_name = "N/A"
        student_surname = "N/A"
        student_national_id = "N/A"
        student_platform_id = a.student_id or "N/A"
        
        if a.student_id:
            try:
                # Try to find student by student_id (platform ID)
                student = Student.query.filter_by(student_id=str(a.student_id)).first()
                if student:
                    student_name = student.name or "N/A"
                    student_surname = student.surname or "N/A"
                    student_national_id = student.national_id or "N/A"
                    student_platform_id = student.student_id or str(a.student_id)
            except Exception as e:
                print(f"[RESULT] Error fetching student: {e}")

        # --- Optional debug output (comment out in production) ---
        try:
            print(
                f"[RESULT] Attempt {attempt_id}: {correct}/{total} correct → "
                f"{percentage:.2f}% (Pass mark {pm}%) → {'PASS' if passed else 'FAIL'}"
            )
        except Exception:
            pass

        # --- Calculate attempts using granted cap ---
        attempts_used = (
            db.session.query(func.count(AssessmentAttempt.id))
            .filter(
                AssessmentAttempt.student_id == a.student_id,
                AssessmentAttempt.course_key == course_key,
            ).scalar()
        ) or 0
        
        # Get granted attempts cap
        attempts_allowed = ATTEMPTS_ALLOWED  # Default fallback
        attempts_left = 0
        
        if student:
            course_id = _resolve_course_id_from_key(course_key)
            if course_id:
                attempts_allowed = _allowed_cap(student.id, course_id)
                attempts_left = max(0, attempts_allowed - attempts_used)

        # --- Render the result page ---
        return render_template(
            "assessment_result.html",
            title=title,
            score=percentage,          # numeric percentage
            passed=passed,             # boolean
            correct=correct,
            total=total,
            pass_mark=int(pm),         # show as clean integer %
            student=student,           # Pass Student object
            student_name=student_name,
            student_surname=student_surname,
            student_national_id=student_national_id,
            full_name=a.full_name or f"{student_name} {student_surname}".strip() or "N/A",
            student_id=student_platform_id,
            attempt_id=a.id,
            video_filename=a.video_filename,
            attempts_used=attempts_used,
            attempts_allowed=attempts_allowed,  # Use granted cap
            attempts_left=attempts_left,
            current_attempt=attempts_used,      # For new scoring logic
            # for Retake button logic
            course_id=getattr(a, "course_id", None),
            course_code=course_key,                    # fallback course reference
        )

    # Register the routes explicitly (no decorator, no app context required)
    app.add_url_rule(
        f"/{course_key}",
        endpoint=f"{course_key}_take",
        view_func=take,
        methods=["GET", "POST"],
    )
    app.add_url_rule(
        f"/{course_key}/result/<int:attempt_id>",
        endpoint=f"{course_key}_result",
        view_func=result,
        methods=["GET"],
    )

