def send_course_admin_email(course_title, full_name, student_id, email_addr, score, passed, attempt_id):
    try:
        # Get recipients from database only (no fallback)
        recipients = get_recipients_for_category('final_results')
        if not recipients:
            print(f"⚠ No final_results recipients configured. {course_title} email not sent.")
            return

        status = "PASS ✅" if passed else "FAIL ❌"
        s = 0.0 if score is None else float(score)
        subject = f"[{course_title}] {status}: {full_name} ({student_id}) — {s:.2f}%"
        body = (
            f"{course_title} assessment completed.\n\n"
            f"Student: {full_name} ({student_id})\nEmail: {email_addr or 'N/A'}\n"
            f"Score: {s:.2f}%\nStatus: {status}\nAttempt ID: {attempt_id}\n"
            f"Timestamp (UTC): {_now_sast().isoformat(timespec='seconds')}Z\n"
            f"Link: {url_for('moderate')}Z\n"
        )

        msg = Message(subject=subject, recipients=recipients, body=body)
        mail.send(msg)
    except Exception:
        logging.exception("Failed to send admin email")


