def persist_attempt_record(
    *,
    course_key: str,
    stu: dict,
    student_number: str,
    score: int,
    percentage: float,
    passed: bool,
    detailed: list,
    video_rel: str,
    started_at,
    finished_at,
    duration_s: int,
    ip: str,
    ua: str,
    ):
    """
    Saves an AssessmentAttempt row and also appends a JSON backup file under:
      uploads/<student_number or student_id>/attempts/<course_key>_attempts.json
    Returns the created attempt object.
    """
    attempt = AssessmentAttempt(
        course_key=course_key,
        student_id=stu["student_id"],
        student_number=student_number,
        full_name=stu["full_name"],
        email=stu["email"],
        score=score,
        passed=passed,
        answers_json=json.dumps(detailed, ensure_ascii=False),
        video_filename=video_rel,
        started_at=started_at,
        finished_at=finished_at,
        duration_s=duration_s,
        ip_address=ip,
        user_agent=ua,
    )
    db.session.add(attempt)
    db.session.flush()   # gives attempt.id

    try:
        folder_key = (student_number or stu["student_id"]).strip()
        backup_dir = os.path.join("uploads", folder_key, "attempts")
        os.makedirs(backup_dir, exist_ok=True)
        backup_path = os.path.join(backup_dir, f"{course_key}_attempts.json")

        payload = {
            "attempt_id": attempt.id,
            "course_key": course_key,
            "student_id": stu["student_id"],
            "student_number": student_number,
            "full_name": stu["full_name"],
            "email": stu["email"],
            "score": score,
            "percentage": percentage,
            "passed": passed,
            "started_at": started_at.isoformat() if started_at else None,
            "finished_at": finished_at.isoformat() if finished_at else None,
            "duration_s": duration_s,
            "ip": ip,
            "user_agent": ua,
            "video_filename": video_rel,
            "detailed": detailed,
            "saved_at": _now_sast().isoformat(),
        }

        existing = []
        if os.path.exists(backup_path):
            try:
                with open(backup_path, "r", encoding="utf-8") as f:
                    existing = json.load(f)
                    if not isinstance(existing, list):
                        existing = []
            except Exception:
                existing = []

        existing.append(payload)
        with open(backup_path, "w", encoding="utf-8") as f:
            json.dump(existing, f, ensure_ascii=False, indent=2)
    except Exception as e:
        current_app.logger.warning(f"[attempt-backup] Failed: {e}")

    db.session.commit()
    return attempt


