# ---- helpers (place near your other helpers) --------------------------------
ATTEMPTS_ALLOWED = 1  # policy: 3 attempts per course


def normalize_course_key(key: str) -> str:
    return (key or "").strip().lower().replace(" ", "_")


def attempts_used(student_id: int, course_key: str) -> int:
    k = normalize_course_key(course_key)
    try:
        return (
            db.session.query(db.func.count(AssessmentAttempt.id))
            .filter(AssessmentAttempt.student_id == student_id)
            .filter(AssessmentAttempt.course_key == k)
            .scalar()
            or 0
        )
    except Exception:
        return 0
