def register_assessment(course_key: str, title: str, pass_mark: int):
    tpl_take = "proctored_assessment.html"   # shared take template
    tpl_result = "assessment_result.html"      # shared result template

    # normalize once so counting/saving is consistent ("Desktop_Test" == "desktop_test")
    norm_key = (course_key or "").strip().lower()
    # normalize once so counting/saving is consistent
    norm_key = (course_key or "").strip().lower()
    assessment_cfg = next(
        (item for item in load_assessments_cfg()
         if normalize_course_key(item.get("key")) == norm_key),
        {},
    )
    question_count = assessment_cfg.get("question_count")
    randomized_keys = {
        "level_3_airport_and_airlines_air_carrier",
        "level_3_cargo",
        "test_1",
        "asat2",
        "rpas_final",
        "rpas",
        "30",
    }

    # ----- NEW: Idempotency guard -----
    take_ep = f"{course_key}_take"
    result_ep = f"{course_key}_result"
    if _endpoint_exists(take_ep) and _endpoint_exists(result_ep):
        app.logger.debug(
            "Endpoints already exist for %s; skipping re-register", course_key)
        return
# ----------------------------------

    def take():
        print(f"[TAKE ROUTE] Entered take() for course_key={course_key}, norm_key={norm_key}")
        stu = current_student()
        if not stu:
            flash("Please log in first.", "warning")
            return redirect(url_for("login"))

        attempt = (AssessmentAttempt.query
                   .filter(
                       AssessmentAttempt.student_id == str(stu["student_id"]),
                       AssessmentAttempt.course_key == norm_key,
                       AssessmentAttempt.is_active.is_(True),
                       AssessmentAttempt.finished_at.is_(None),
                   )
                   .order_by(AssessmentAttempt.created_at.desc())
                   .first())
        qs = None
        if attempt:
            try:
                qs = json.loads(attempt.questions_json or "")
                if not isinstance(qs, list) or not qs:
                    raise ValueError("question snapshot is empty or invalid")
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                app.logger.error(
                    "Invalid question snapshot for attempt %s: %s", attempt.id, exc)
                flash("This assessment attempt could not be resumed safely. Please contact PAS.", "danger")
                return redirect(url_for("dashboard"))

        # Preserve the existing retry/idempotency behavior before any
        # unfinished-attempt or eligibility guard can reject a retried POST.
        duplicate = None
        if request.method == "POST":
            recent_cutoff = _now_sast() - timedelta(seconds=60)
            duplicate = (AssessmentAttempt.query
                         .filter(
                             AssessmentAttempt.student_id == stu["student_id"],
                             AssessmentAttempt.course_key == norm_key,
                             AssessmentAttempt.finished_at >= recent_cutoff,
                         )
                         .order_by(AssessmentAttempt.finished_at.desc())
                         .first())
            if duplicate:
                app.logger.info(
                    "Duplicate submission suppressed for student %s on %s; returning attempt %d",
                    stu["student_id"], norm_key, duplicate.id)
                target = url_for(f"{course_key}_result", attempt_id=duplicate.id)
                if request.headers.get("X-Requested-With", "").lower() == "xmlhttprequest":
                    return jsonify({"redirect": target})
                return redirect(target)

        # ---- Enforce attempt policy using SCORE-BASED RULES ----
        # Rules: 80%+ = Pass (no more needed), 75-79% = 1 retry, <75% = Fail (contact admin)
        student_obj = Student.query.filter_by(student_id=stu["student_id"]).first()
        cap = ATTEMPTS_ALLOWED  # Default fallback

        # Get attempts used
        used = (
            db.session.query(func.count(AssessmentAttempt.id))
            .filter(
                AssessmentAttempt.student_id == stu["student_id"],
                AssessmentAttempt.course_key == norm_key,
                AssessmentAttempt.is_active.is_(True),
                AssessmentAttempt.finished_at.isnot(None),
            ).scalar()
        ) or 0

        # Get the latest attempt's score
        latest_attempt = AssessmentAttempt.query.filter_by(
            student_id=stu["student_id"],
            course_key=norm_key,
            is_active=True
        ).filter(AssessmentAttempt.finished_at.isnot(None)).order_by(
            AssessmentAttempt.created_at.desc()).first()

        latest_score = latest_attempt.score if latest_attempt else None

        # DEBUG: Print blocking info
        print(f"[BLOCKING DEBUG] course_key={norm_key}, student_id={stu['student_id']}, used={used}, latest_score={latest_score}")

        # Get the allowed attempts cap (includes admin-approved extra attempts)
        allowed_cap = 2  # Default
        if student_obj:
            course_id = _resolve_course_id_from_key(norm_key)
            if course_id:
                allowed_cap = _allowed_cap(student_obj.id, course_id)

                # Safety net: Check for approved RetryRequest if enrollment wasn't updated
                if allowed_cap == 2 and used >= 2:
                    approved_request = RetryRequest.query.filter_by(
                        student_id=student_obj.id,
                        course_id=course_id,
                        status='approved'
                    ).first()
                    if approved_request:
                        allowed_cap = 3  # Grant the approved 3rd attempt
                        print(f"[BLOCKING DEBUG] Found approved RetryRequest, setting allowed_cap=3")

        print(f"[BLOCKING DEBUG] allowed_cap={allowed_cap}")

        # Use score-based logic to determine attempts left (with allowed cap)
        left = _calculate_attempts_left(latest_score, used, allowed_cap)
        print(f"[BLOCKING DEBUG] _calculate_attempts_left({latest_score}, {used}, {allowed_cap}) = {left}")

        # ---- If no attempts remain, show the info page (do NOT redirect) ----
        if not attempt and left <= 0:
            return render_template(
                "no_attempts_left.html",
                course_title=title,
                course_key=course_key,            # original key for display/links
                attempts_allowed=used,  # They used all their attempts
                attempts_used=used,
                contact_email="digital@professional.za.com",
                contact_phone="+27 10 594 5417",
            ), 200

        # ---------- GET ----------
        if request.method == "GET":
            # ---- Readiness gate ----
            # Show preparation/disclaimer screen with face detection check
            # before starting the actual proctored assessment.
            if not request.args.get("ready"):
                return render_template(
                    "assessment_readiness.html",
                    title=title,
                    course_key=course_key,
                    student_name=stu["full_name"],
                    attempts_left=left,
                )

            # ---- Student confirmed ready — proceed to assessment ----
            if not attempt:
                try:
                    question_bank = load_questions(course_key)
                    if question_count is None:
                        qs = list(question_bank)
                        if norm_key in randomized_keys:
                            secrets.SystemRandom().shuffle(qs)
                    else:
                        if (isinstance(question_count, bool)
                                or not isinstance(question_count, int)
                                or question_count <= 0):
                            raise ValueError(
                                f"Invalid question_count for {course_key}: {question_count}"
                            )
                        if len(question_bank) < question_count:
                            raise ValueError(
                                f"Assessment has {len(question_bank)} questions; "
                                f"at least {question_count} are required."
                            )
                        rng = secrets.SystemRandom()
                        qs = rng.sample(question_bank, question_count)
                        rng.shuffle(qs)
                    attempt = AssessmentAttempt(
                        course_key=norm_key,
                        student_id=str(stu["student_id"]),
                        student_number=stu.get("student_number") or str(stu["student_id"]),
                        full_name=stu["full_name"],
                        email=stu["email"],
                        started_at=_now_sast(),
                        questions_json=json.dumps(qs, ensure_ascii=False),
                    )
                    db.session.add(attempt)
                    db.session.commit()
                except Exception as exc:
                    db.session.rollback()
                    app.logger.exception("Could not create assessment attempt: %s", exc)
                    flash("This assessment could not be started safely. Please try again.", "danger")
                    return redirect(url_for("dashboard"))

            session[f"{norm_key}_started_at"] = (
                attempt.started_at or _now_sast()).isoformat()

            # Reset violation point tracker so leftover points from a
            # previous attempt don't cause an instant boot.
            try:
                tracker = ViolationAlertTracker.query.filter_by(
                    student_id=str(stu["student_id"]),
                    course_key=norm_key
                ).first()
                if tracker and tracker.current_points > 0:
                    tracker.current_points = 0
                    tracker.updated_at = _now_sast()
                    db.session.commit()
            except Exception:
                db.session.rollback()

            if question_count is not None and len(qs) != question_count:
                flash(
                    f"⚠️ {title} not ready. Expected {question_count} Qs, found {len(qs)}.", "warning")

            # Get detailed student info from database
            student_first_name = student_obj.name if student_obj else ""
            student_surname = student_obj.surname if student_obj else ""
            student_national_id = student_obj.national_id if student_obj else ""

            return render_template(
                tpl_take,
                title=title,
                questions=qs,
                pass_mark=pass_mark,
                student_name=stu["full_name"],
                student_first_name=student_first_name,
                student_surname=student_surname,
                student_national_id=student_national_id,
                student_id=stu["student_id"],
                student_email=stu["email"],
                student_number=stu.get("student_number"),
                attempts_left=left,               # optional UI hint
                attempts_allowed=cap,  # Use granted cap instead of hardcoded
                course_key=norm_key,  # For violation tracking
            )

        # ---------- POST ----------
        if not attempt:
            flash("This assessment attempt is no longer available. Please start a new attempt.", "danger")
            return redirect(url_for("dashboard"))

        # Guard again (multi-tabs/back-button race)
        # Grade answers via the v1.1.0 dispatch table so we support mcq, tf,
        # short_answer, and table_fill uniformly. We sum weighted points across
        # questions rather than counting raw 1-per-question hits, so e.g. a
        # 9-mark table_fill actually contributes 9 marks.
        #
        # Replaces the legacy call to grade_airside(qs, submitted), which only
        # understood MCQ and would silently score every non-MCQ question as
        # wrong (observed as "2/7 = 28.57%" with a mixed-type assessment).
        earned_points = 0.0
        total_points = 0.0
        correct_count = 0  # number of questions fully correct
        detailed = []
        for q in qs:
            q_earned, q_max = grade_question(q, request.form)
            earned_points += q_earned
            total_points += q_max
            fully_correct = q_max > 0 and q_earned >= q_max
            if fully_correct:
                correct_count += 1
            sel_disp, corr_disp = _describe_answer(q, request.form)
            detailed.append({
                "id": q.get("id"),
                "type": (q.get("type") or "mcq").lower(),
                "prompt": q.get("question", ""),
                "points": q_max,
                "earned": q_earned,
                "is_correct": bool(fully_correct),
                "is_right": bool(fully_correct),  # legacy key for older result templates
                # Type-aware human-readable strings for the remediation report.
                # The PDF generator reads these first; falls back to its legacy
                # MCQ-specific extraction when they are absent (old attempts).
                "selected_display": sel_disp,
                "correct_display": corr_disp,
            })

        # Back-compat variables. "score" and "total" downstream are used for
        # pass-mark checks, emails, and result page display; pointing them at
        # weighted point sums keeps every downstream consumer consistent.
        score = earned_points
        total = total_points

        pm = float(pass_mark) if isinstance(pass_mark, (int, float)
                                            ) else float(str(pass_mark).replace("%", "") or 80)
        percentage = round((earned_points / total_points) * 100.0, 2) if total_points else 0.0
        passed = (percentage >= pm)

        # Meta / audit info
        started_iso = session.pop(f"{norm_key}_started_at", None)
        started_at = datetime.fromisoformat(
            started_iso) if started_iso else None
        finished_at = _now_sast()
        duration_s = int(
            (finished_at - started_at).total_seconds()) if started_at else 0
        ip, ua = client_info()

        posted_number = (request.form.get("student_number") or "").strip()
        session_number = (session.get("student_number") or "").strip()
        resolved_number = posted_number or session_number or str(
            stu["student_id"]).strip()

        # Proctoring video.
        # NOTE: Despite the historical "(optional)" comment, this is NOT optional
        # for proctored final assessments. CAA / regulatory compliance requires
        # 100% video evidence of every assessment attempt. The block below saves
        # the recording; the compliance gate immediately after REJECTS the whole
        # submission if no usable video came through.
        video_session_id = request.form.get('video_session_id', '').strip()
        video_rel = None
        try:
            if video_session_id:
                video_rel = finalize_video_chunks(resolved_number, video_session_id, norm_key)
            else:
                video_file = request.files.get("video")
                video_rel = save_proctor_video(norm_key, resolved_number, video_file)
        except ValueError as _video_err:
            # save_proctor_video raises ValueError when the video is too small
            # (corrupt or empty). Treat as "no video" so the gate below fires.
            app.logger.warning(
                "Proctor video rejected (too small) for student=%s course=%s: %s",
                stu["student_id"], norm_key, _video_err)
            video_rel = None

        # ----- Compliance gate: video MUST exist and be a real recording -----
        # Without a video file, the proctoring evidence chain is broken and the
        # attempt does NOT count. We do not persist an AssessmentAttempt, we do
        # not score, we do not enqueue a certificate. Student is told to fix
        # their camera / mic and retake. Their attempt counter is not consumed
        # because no row is created.
        video_ok = False
        if video_rel:
            try:
                full_video_path = os.path.join(app.root_path, video_rel) if not os.path.isabs(video_rel) else video_rel
                if os.path.isfile(full_video_path) and os.path.getsize(full_video_path) >= MIN_PROCTOR_VIDEO_BYTES:
                    video_ok = True
            except Exception:
                video_ok = False

        if not video_ok:
            app.logger.error(
                "[COMPLIANCE] Proctored submission REJECTED, no usable video. "
                "student=%s course=%s video_rel=%s",
                stu["student_id"], norm_key, video_rel)
            msg = ("This attempt could not be submitted because the proctoring "
                   "video did not record. Regulations require video evidence "
                   "for every final assessment. Please check your camera and "
                   "microphone, then start a fresh attempt. This attempt has "
                   "NOT been counted.")
            if request.headers.get("X-Requested-With", "").lower() == "xmlhttprequest":
                return jsonify({"error": msg}), 400
            flash(msg, "danger")
            return redirect(url_for("dashboard"))
        # ---------------------------------------------------------------------

        # Persist the existing in-progress attempt.
        attempt.student_id = str(stu["student_id"])
        attempt.student_number = resolved_number
        attempt.full_name = stu["full_name"]
        attempt.email = stu["email"]
        attempt.score = percentage
        attempt.passed = passed
        attempt.answers_json = json.dumps(detailed, ensure_ascii=False)
        attempt.video_filename = video_rel
        attempt.started_at = started_at or attempt.started_at
        attempt.finished_at = finished_at
        attempt.duration_s = duration_s
        attempt.ip_address = ip
        attempt.user_agent = ua
        db.session.commit()

        # Close the open AssessmentSession (heartbeat tracking) for this student
        # + course. Lets the assessment monitor show "finished" instead of leaving
        # the session listed as still-active until it goes stale.
        try:
            open_sess = (AssessmentSession.query
                         .filter_by(student_number=str(stu["student_id"]),
                                    course_key=norm_key,
                                    finished_at=None)
                         .order_by(AssessmentSession.started_at.desc())
                         .first())
            if open_sess:
                open_sess.finished_at = finished_at
                open_sess.finish_reason = 'submitted'
                db.session.commit()
        except Exception as _e:
            current_app.logger.warning(f"[heartbeat] failed to close session: {_e}")
            db.session.rollback()

        # Admin email (optional)
        try:
            subject = f"[Assessment Result] {title} — {'PASS' if passed else 'FAIL'} ({percentage:.2f}%)"
            body = (
                f"Course: {title}\n"
                f"Student: {stu['full_name']} ({stu['student_id']})\n"
                f"Email: {stu['email']}\n"
                f"Result: {'PASS' if passed else 'FAIL'}\n"
                f"Score: {percentage:.2f}% ({score}/{total})\n"
                f"Pass Mark: {int(pm)}%\n"
                f"Attempt ID: {attempt.id}\n"
                f"Attempts used: {used + 1} / {ATTEMPTS_ALLOWED}\n"
            )
            send_course_admin_email(title, stu['full_name'], stu['student_id'], email_addr, score, passed, attempt.id, subject, body)
        except Exception as e:
            current_app.logger.warning(f"[email] admin mail suppressed: {e}")

        # --- Certificate email + enqueue are now deferred until feedback is submitted ---

        target = url_for(f"{course_key}_result", attempt_id=attempt.id)
        if request.headers.get("X-Requested-With", "").lower() == "xmlhttprequest":
            return jsonify({"redirect": target})
        return redirect(target)

    def result(attempt_id):
        a = AssessmentAttempt.query.get_or_404(attempt_id)
        detailed = json.loads(a.answers_json or "[]") if a.answers_json else []
        correct = sum(1 for x in detailed if x.get("is_correct"))
        total = len(detailed)
        
        # Count attempts used (a.student_id is platform student_id, which is a string)
        norm_key = normalize_course_key(course_key)
        used = (
            db.session.query(func.count(AssessmentAttempt.id))
            .filter(
                AssessmentAttempt.student_id == str(a.student_id),
                AssessmentAttempt.course_key == norm_key,
                AssessmentAttempt.is_active.is_(True),
                AssessmentAttempt.finished_at.isnot(None),
            )
            .scalar()
        ) or 0

        # --- Fetch Student object to get name, surname, and national_id ---
        student = None
        student_name = "N/A"
        student_surname = "N/A"
        student_national_id = "N/A"
        student_platform_id = a.student_id or "N/A"
        
        # Get granted attempts cap
        attempts_allowed = ATTEMPTS_ALLOWED  # Default fallback
        attempts_left = 0
        
        if a.student_id:
            try:
                # Try to find student by student_id (platform ID)
                student = Student.query.filter_by(student_id=str(a.student_id)).first()
                if student:
                    student_name = student.name or "N/A"
                    student_surname = student.surname or "N/A"
                    student_national_id = student.national_id or "N/A"
                    student_platform_id = student.student_id or str(a.student_id)
                    
                    # Get granted attempts cap
                    course_id = _resolve_course_id_from_key(course_key)
                    if course_id:
                        attempts_allowed = _allowed_cap(student.id, course_id)
                        attempts_left = max(0, attempts_allowed - used)
            except Exception as e:
                print(f"[RESULT] Error fetching student: {e}")
        if a.score >= 90:
            attempts_allowed = 1
            attempts_left = 0
            attempts_used = used
            current_attempt = used
        elif a.score >= 75 and a.score < 90:
            if used >= 2:
                attempts_allowed = 2
                attempts_left = 0
                attempts_used = used
                current_attempt = used
            elif used == 1:
                attempts_allowed = 2
                attempts_left = 1
                attempts_used = used
                current_attempt = used
        else:
            attempts_allowed = 1
            attempts_left = 0
            attempts_used = used
            current_attempt = used

        # Check if feedback already submitted for THIS passing attempt.
        # A plain existence check would wrongly say "already submitted" on a
        # fresh pass if any older feedback row exists for this course_key
        # (e.g. from a prior fail-then-retake cycle), so only count feedback
        # created at/after this attempt finished.
        feedback_already_submitted = False
        if student:
            fb_q = CourseFeedback.query.filter_by(
                student_id=student.id,
                course_key=course_key
            )
            fb_cutoff = a.finished_at or a.created_at
            if fb_cutoff is not None:
                fb_q = fb_q.filter(CourseFeedback.created_at >= fb_cutoff)
            feedback_already_submitted = fb_q.first() is not None

        return render_template(
            tpl_result,
            title=title,
            # lets the template build /{course_key} retake link
            course_key=course_key,
            course_code=course_key,     # used for feedback route
            score=a.score,
            passed=bool(a.passed),
            correct=correct,
            total=total,
            pass_mark=pass_mark,
            student=student,           # Pass Student object
            student_name=student_name,
            student_surname=student_surname,
            student_national_id=student_national_id,
            full_name=a.full_name or f"{student_name} {student_surname}".strip() or "N/A",
            student_id=student_platform_id,
            attempt_id=a.id,
            video_filename=a.video_filename,
            attempts_allowed=attempts_allowed,  # Use granted cap
            attempts_left=attempts_left,
            attempts_used=used,
            current_attempt=used,    # For new scoring logic
            feedback_already_submitted=feedback_already_submitted,
        )

    # Register the take + result routes via Werkzeug's low-level URL map.
    # We bypass Flask's @app.route / app.add_url_rule on purpose: those call
    # _check_setup_finished, which refuses any route added after the first
    # request has been handled (Flask 2.2+). That breaks dynamic registration
    # when an admin creates a new Final Assessment at runtime, leaving the
    # /<course_key> take URL unreachable until the server restarts.
    from werkzeug.routing import Rule
    if not _endpoint_exists(take_ep):
        app.url_map.add(Rule(f"/{course_key}", endpoint=take_ep, methods=["GET", "POST"]))
        app.view_functions[take_ep] = take
    if not _endpoint_exists(result_ep):
        app.url_map.add(Rule(f"/{course_key}/result/<int:attempt_id>", endpoint=result_ep, methods=["GET"]))
        app.view_functions[result_ep] = result
############## *************************###################


# --- Make `has_endpoint()` available in Jinja templates ---


def has_endpoint(name: str) -> bool:
    """
    Return True if a Flask endpoint exists (by name), else False.
    Lets templates guard url_for() calls safely.
    """
    try:
        return bool(name) and name in current_app.view_functions
    except Exception:
        return False


@app.context_processor
def inject_helpers():
    # exposes has_endpoint() to all templates
    return dict(has_endpoint=has_endpoint)

