# @app.route("/<course_key>", methods=["GET"])


def start_final(course_key):
    if "student_id" not in session:
        flash("⚠ Please log in first.", "danger")
        return redirect(url_for("login"))

    student = Student.query.filter_by(student_id=session["student_id"]).first()
    if not student:
        flash("Student not found.", "danger")
        return redirect(url_for("login"))

    used, left = get_attempt_counts(student.id, course_key)

    # Block if they used all attempts
    if left <= 0:
        flash("🚫 No attempts remaining. Contact admin to reset.", "danger")
        return redirect(url_for("dashboard"))

    # Continue to the final assessment
    # or whatever your actual final route is
    return redirect(url_for("run_final", code=course_key))


