# ---- Final attempts (Admin) ----

ATTEMPTS_ALLOWED = 1


def normalize_course_key(k: str) -> str:
    return (k or "").strip().lower()


def get_attempt_counts(student_id: int, course_key: str):
    """
    Return (used, left, cap) for a student's final assessment attempts on a given course.
    Uses granted attempts from CourseEnrollment.allowed_attempts or AttemptsAdjustment.
    Prefers FinalAssessmentAttempt if you're using it; otherwise falls back to AssessmentAttempt.
    """
    from sqlalchemy import func

    norm_key = normalize_course_key(course_key)
    
    # Get student internal PK (student_id param is internal PK)
    student = Student.query.get(student_id) if isinstance(student_id, int) else None
    if not student:
        # Try to find by platform student_id
        student = Student.query.filter_by(student_id=str(student_id)).first()
    
    if not student:
        # Fallback to hardcoded if student not found
        used = 0
        left = ATTEMPTS_ALLOWED
        return used, left
    
    student_pk = student.id
    
    # Resolve course_id from course_key
    course_id = _resolve_course_id_from_key(norm_key)
    
    # Get granted attempts cap (uses CourseEnrollment.allowed_attempts or AttemptsAdjustment)
    if course_id:
        cap = _allowed_cap(student_pk, course_id)
    else:
        # Fallback if course_id not found
        cap = ATTEMPTS_ALLOWED

    # Try FinalAssessmentAttempt first (if you are writing there)
    used_final = 0
    if course_id:
        used_final = (
            db.session.query(func.count(FinalAssessmentAttempt.id))
            .filter(
                FinalAssessmentAttempt.student_id == student_pk,
                FinalAssessmentAttempt.course_id == course_id
            )
            .scalar()
        ) or 0

    if used_final > 0:
        used = used_final
    else:
        # Fallback: count in AssessmentAttempt (your current save path)
        # Use platform student_id for AssessmentAttempt
        platform_student_id = student.student_id
        used = (
            db.session.query(func.count(AssessmentAttempt.id))
            .filter(
                AssessmentAttempt.student_id == platform_student_id,
                AssessmentAttempt.course_key == norm_key
            )
            .scalar()
        ) or 0

    left = max(0, cap - used)
    return used, left


############################

# ---- Final attempts (Admin) with smart fallback ----

ATTEMPTS_ALLOWED = 1


def _calculate_attempts_left(score, attempts_used, allowed_cap=2):
    """
    Calculate attempts left based on score rules and allowed cap:
    - No attempts yet: 1 (allow first attempt)
    - 80%+ (PASS): 0 left (already won)
    - After attempt with fail (<80%): 1 left if attempts_used < allowed_cap
    - After using all allowed attempts and didn't pass: 0 left

    allowed_cap: The maximum attempts allowed (default 2, can be 3+ if admin approved)
    """
    if score is None:
        # No score yet - allow first attempt if they haven't used any
        return 1 if attempts_used == 0 else 0
    if score >= 80:
        # Passed - no more attempts needed
        return 0
    # Any fail score (<80%)
    if attempts_used < allowed_cap:
        # Still have attempts left under the allowed cap
        return 1
    # Used all allowed attempts and didn't pass
    return 0


def _items_from_final(rows):
    """Rows from FinalAssessmentAttempt -> normalized items"""
    # Student FK here is Student.id
    students_by_pk = {s.id: s for s in Student.query.all()}
    courses_by_id = {c.id: c for c in Course.query.all()}
    items = []
    for r in rows:
        s = students_by_pk.get(r.student_id)
        # Skip orphaned attempts (student no longer exists)
        if not s:
            continue
        used = int(r.attempts_used or 0)

        # Get the latest attempt's score to determine attempts_left
        latest_attempt = FinalAssessmentAttempt.query.filter_by(
            student_id=r.student_id,
            course_key=r.course_key,
            is_active=True
        ).order_by(FinalAssessmentAttempt.submitted_at.desc()).first()

        latest_score = latest_attempt.percentage if latest_attempt else None
        # Get allowed cap for this student/course (includes admin-approved extra attempts)
        allowed_cap = _allowed_cap(r.student_id, r.course_id) if r.course_id else 2
        left = _calculate_attempts_left(latest_score, used, allowed_cap)

        c = courses_by_id.get(r.course_id)
        items.append({
            "course_key": r.course_key,
            "course_id": r.course_id,
            "course_title": (c.title if c else (r.course_key or (f"Course #{r.course_id}" if r.course_id else "Unknown course"))),
            "student_id": r.student_id,                 # PK id
            "student_number": r.student_number or s.student_id,
            "student_name": s.name or s.email or f"Student #{s.id}",
            "attempts_used": used,
            "attempts_left": left,
            "latest_score": latest_score,
            "last_attempt_at": r.last_attempt_at,
        })
    return items


def _items_from_legacy(rows):
    """Rows from AssessmentAttempt -> normalized items"""
    # Legacy student_id is the public student_number (NOT the PK)
    students_by_public = {str(s.student_id): s for s in Student.query.all()}
    # Also lookup by course_key to get proper course title
    courses_by_key = {}
    for c in Course.query.all():
        if c.final_assessment_key:
            courses_by_key[c.final_assessment_key] = c
    items = []
    for r in rows:
        # r.student_id is public id in legacy (student_number)
        s = students_by_public.get(str(r.student_id))
        # Skip orphaned attempts (student no longer exists)
        if not s:
            continue
        used = int(r.attempts_used or 0)

        # Get the latest attempt's score to determine attempts_left
        latest_attempt = AssessmentAttempt.query.filter_by(
            student_id=str(r.student_id),
            course_key=r.course_key,
            is_active=True
        ).order_by(AssessmentAttempt.created_at.desc()).first()

        latest_score = latest_attempt.score if latest_attempt else None
        # Get allowed cap for this student/course (includes admin-approved extra attempts)
        c = courses_by_key.get(r.course_key)
        allowed_cap = _allowed_cap(s.id, c.id) if c else 2
        left = _calculate_attempts_left(latest_score, used, allowed_cap)

        items.append({
            "course_key": r.course_key,
            "course_id": c.id if c else None,
            "course_title": c.title if c else (r.course_key or "Unknown course"),
            "student_id": s.id,                    # Now we have PK via lookup
            "student_number": s.student_id,
            "student_name": s.name or s.email or f"Student #{s.id}",
            "attempts_used": used,
            "attempts_left": left,
            "latest_score": latest_score,
            "last_attempt_at": r.last_attempt_at,
        })
    return items

####################################################


@app.route("/admin/final-attempts", methods=["GET"])
def admin_final_attempts():
    require_admin()

    source = request.args.get("source")  # optional: "final" or "legacy"
    filt_course_key = request.args.get("course_key", type=str)
    filt_course_id = request.args.get("course_id",  type=int)

    items = []
    used_source = None

    # Prefer FinalAssessmentAttempt unless ?source=legacy
    if source in (None, "", "final"):
        qf = db.session.query(
            FinalAssessmentAttempt.course_key.label("course_key"),
            FinalAssessmentAttempt.course_id.label("course_id"),
            FinalAssessmentAttempt.student_id.label("student_id"),
            FinalAssessmentAttempt.student_number.label("student_number"),
            func.count(FinalAssessmentAttempt.id).label("attempts_used"),
            func.max(FinalAssessmentAttempt.submitted_at).label(
                "last_attempt_at"),
        )
        if filt_course_key:
            qf = qf.filter(FinalAssessmentAttempt.course_key ==
                           filt_course_key)
        if filt_course_id:
            qf = qf.filter(FinalAssessmentAttempt.course_id == filt_course_id)

        qf = qf.group_by(
            FinalAssessmentAttempt.course_key,
            FinalAssessmentAttempt.course_id,
            FinalAssessmentAttempt.student_id,
            FinalAssessmentAttempt.student_number,
        )

        final_rows = qf.all()
        if final_rows:
            items = _items_from_final(final_rows)
            used_source = "final"

    # If still empty, fall back to legacy AssessmentAttempt (or if source=legacy)
    if not items and source in (None, "", "legacy"):
        qa = db.session.query(
            AssessmentAttempt.course_key.label("course_key"),
            AssessmentAttempt.student_id.label("student_id"),  # public id here
            func.count(AssessmentAttempt.id).label("attempts_used"),
            func.max(getattr(AssessmentAttempt, "finished_at",
                     AssessmentAttempt.id)).label("last_attempt_at"),
        )
        if filt_course_key:
            qa = qa.filter(AssessmentAttempt.course_key == filt_course_key)
        qa = qa.group_by(AssessmentAttempt.course_key,
                         AssessmentAttempt.student_id)
        legacy_rows = qa.all()
        if legacy_rows:
            items = _items_from_legacy(legacy_rows)
            used_source = "legacy"

    if not items:
        flash("No attempts found. Try switching source (?source=legacy) or remove filters.", "warning")

    # Course list for filter dropdown
    all_courses = Course.query.order_by(Course.title.asc()).all()

    # Attach internal IDs for legacy rows (needed for Grant Attempts form)
    if used_source == "legacy" and items:
        fixed_items = []
        for i in items:
            try:
                if isinstance(i, dict):
                    i = attach_internal_ids_for_legacy(i)
                else:
                    i = attach_internal_ids_for_legacy(i)
            except Exception as e:
                print(f"[WARN] Failed to attach IDs for {i}: {e}")
            fixed_items.append(i)
        items = fixed_items

    # Little hint about which source was used
    if used_source:
        flash(f"Showing data from: {used_source.upper()}", "info")

    return render_template(
        "admin_final_attempts.html",
        items=items,
        attempts_allowed=ATTEMPTS_ALLOWED,
        all_courses=all_courses,
        selected_course_key=filt_course_key,
        selected_course_id=filt_course_id,
        used_source=used_source,
    )

