# Helper to link the legacy


def attach_internal_ids_for_legacy(item):
    """
    Enrich a legacy summary row (dict or object) with internal PKs:
      student_pk = Student.id
      course_pk  = Course.id
    Uses:
      - student_number (preferred) or student_id (legacy public code)
      - course_key
    """

    # uniform accessors
    is_dict = isinstance(item, dict)

    def get(k, default=None):
        return item.get(k, default) if is_dict else getattr(item, k, default)

    student_number = (get("student_number") or get("student_id") or "").strip()
    course_key = (get("course_key") or "").strip().lower()

    # resolve student by public code -> internal PK
    stu = Student.query.filter_by(
        student_id=student_number).first() if student_number else None

    # resolve course by key -> internal PK (adjust field if you use slug/code)
    crs = None
    if course_key:
        if hasattr(Course, "key"):
            crs = Course.query.filter(db.func.lower(
                Course.key) == course_key).first()
        # fallbacks if your model uses a different field name
        if not crs:
            for attr in ("slug", "shortcode", "code"):
                if hasattr(Course, attr):
                    crs = Course.query.filter(db.func.lower(
                        getattr(Course, attr)) == course_key).first()
                    if crs:
                        break

    # write back
    if is_dict:
        item["student_pk"] = (stu.id if stu else None)
        item["course_pk"] = (crs.id if crs else None)
    else:
        setattr(item, "student_pk", stu.id if stu else None)
        setattr(item, "course_pk",  crs.id if crs else None)

    return item

########################################################
# Another Helper


def _resolve_course_id_from_key(course_key: str):
    """
    Map a legacy course_key (e.g. 'desktop_test', 'asat_gen') to Course.id.
    Order of attempts:
      1) assessments config (load_assessments_cfg)
      2) known real columns on Course (final_assessment_key, key, slug, shortcode, code)
      3) title (last resort)
    Only queries instrumented columns (no @property).
    """
    if not course_key:
        return None

    k = (course_key or "").strip().lower()

    # 1) Your config mapping (usually authoritative)
    try:
        items = load_assessments_cfg()
        meta = next((x for x in items if (
            x.get("key") or "").lower() == k), None)
        if meta and meta.get("course_id"):
            return int(meta["course_id"])
    except Exception:
        pass

    # 2) Try real columns on Course
    candidates = ("final_assessment_key", "key", "slug", "shortcode", "code")
    for attr in candidates:
        col = getattr(Course, attr, None)
        if isinstance(col, InstrumentedAttribute):  # ensures it's a mapped DB column
            crs = Course.query.filter(db.func.lower(col) == k).first()
            if crs:
                return crs.id

    # 3) Fallback to title match if nothing else works
    col = getattr(Course, "title", None)
    if isinstance(col, InstrumentedAttribute):
        crs = Course.query.filter(db.func.lower(Course.title) == k).first()
        if crs:
            return crs.id

    return None

    #########################


def attach_internal_ids_for_legacy(item):
    """
    Enrich a legacy summary row (dict or obj) with:
      - student_pk (Student.id) from public Student.student_id
      - course_pk  (Course.id)   from course_key via resolver above
    Safe for dicts OR objects.
    """
    is_dict = isinstance(item, dict)
    get = (lambda k, d=None: item.get(k, d)) if is_dict else (
        lambda k, d=None: getattr(item, k, d))

    student_number = (get("student_number") or get("student_id") or "").strip()
    course_key = (get("course_key") or "").strip()

    stu = Student.query.filter_by(
        student_id=student_number).first() if student_number else None
    cid = _resolve_course_id_from_key(course_key)

    if is_dict:
        item["student_pk"] = (stu.id if stu else None)
        item["course_pk"] = cid
    else:
        setattr(item, "student_pk", stu.id if stu else None)
        setattr(item, "course_pk",  cid)

    return item

########################


def _column_exists(model, colname: str) -> bool:
    try:
        return colname in model.__table__.columns.keys()
    except Exception:
        return False


def _allowed_cap(student_id: int, course_id: int) -> int:
    """Return current cap (works with or without CourseEnrollment.allowed_attempts)."""
    has_col = _column_exists(CourseEnrollment, "allowed_attempts")
    enr = (CourseEnrollment.query
           .filter_by(student_id=student_id, course_id=course_id)
           .first())
    base = 2  # Default: 2 attempts per course

    # DEBUG: Log enrollment details
    print(f"🔧 _allowed_cap DEBUG → student_id={student_id}, course_id={course_id}, has_col={has_col}, enr={enr}, enr.allowed_attempts={getattr(enr, 'allowed_attempts', 'N/A') if enr else 'N/A'}")

    if has_col and enr and getattr(enr, "allowed_attempts", None) is not None:
        print(f"🔧 _allowed_cap DEBUG → Using enrollment.allowed_attempts={enr.allowed_attempts}")
        return int(enr.allowed_attempts)
    # fallback: 2 + sum(adjustments)
    delta_sum = (db.session.query(func.coalesce(func.sum(AttemptsAdjustment.delta), 0))
                 .filter_by(student_id=student_id, course_id=course_id)
                 .scalar()) or 0
    return base + int(delta_sum)


