# Helper Above

@app.route("/admin/enrollment/<int:enrollment_id>/attempts", methods=["GET"])
def admin_enrollment_attempts(enrollment_id):
    """JSON endpoint: return all attempt history for an enrollment."""
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < get_role_level('Admin'):
        return jsonify(ok=False, message="Insufficient permissions."), 403

    enr = CourseEnrollment.query.get(enrollment_id)
    if not enr:
        return jsonify(ok=False, message="Enrollment not found."), 404

    student = Student.query.get(enr.student_id)
    course = Course.query.get(enr.course_id)
    key = course.final_assessment_key if course else ""

    attempts = []

    # 1. FinalAssessmentAttempt (new system)
    if key:
        fas = (FinalAssessmentAttempt.query
               .filter_by(student_id=enr.student_id, course_id=enr.course_id)
               .order_by(FinalAssessmentAttempt.attempt_no.asc())
               .all())
        for fa in fas:
            attempts.append({
                "attempt_no": fa.attempt_no,
                "score": round(fa.percentage) if fa.percentage is not None else None,
                "passed": fa.passed,
                "date": fa.submitted_at.strftime("%d %b %Y %H:%M") if fa.submitted_at else None,
                "source": "final"
            })

    # 2. FinalAssessmentSubmission (intermediate)
    if not attempts:
        subs = (FinalAssessmentSubmission.query
                .filter_by(student_id=enr.student_id, course_id=enr.course_id)
                .order_by(FinalAssessmentSubmission.submitted_at.asc())
                .all())
        for i, sub in enumerate(subs, 1):
            attempts.append({
                "attempt_no": i,
                "score": round(sub.percentage) if sub.percentage is not None else None,
                "passed": sub.percentage is not None and sub.percentage >= 80,
                "date": sub.submitted_at.strftime("%d %b %Y %H:%M") if sub.submitted_at else None,
                "source": "submission"
            })

    # 3. AssessmentAttempt (legacy)
    if not attempts and student:
        aas = (AssessmentAttempt.query
               .filter_by(student_id=str(student.student_id), course_key=key)
               .order_by(AssessmentAttempt.created_at.asc())
               .all())
        for i, aa in enumerate(aas, 1):
            attempts.append({
                "attempt_no": i,
                "score": round(aa.score) if aa.score is not None else None,
                "passed": aa.passed if aa.passed is not None else False,
                "date": aa.created_at.strftime("%d %b %Y %H:%M") if aa.created_at else None,
                "source": "legacy"
            })

    return jsonify(ok=True, attempts=attempts)


@app.route("/api/enrollment/<int:enrollment_id>/chapters", methods=["GET"])
def api_enrollment_chapters(enrollment_id):
    """JSON endpoint: return per-chapter breakdown for an enrollment.
    Accessible to Admins and Company users (who own the student)."""
    is_admin = 'admin_id' in session
    is_company = 'company_id' in session

    if not is_admin and not is_company:
        return jsonify(ok=False, message="Insufficient permissions."), 403

    enr = CourseEnrollment.query.get(enrollment_id)
    if not enr:
        return jsonify(ok=False, message="Enrollment not found."), 404

    # Company users can only see their own students. Admins are not subject to
    # this: an admin who has also opened the company portal in the same browser
    # carries company_id in the same session, and without the is_admin guard the
    # ownership test would deny them any student outside that one company.
    if is_company and not is_admin:
        student = Student.query.get(enr.student_id)
        if not student or student.created_by_company_id != session["company_id"]:
            return jsonify(ok=False, message="Access denied."), 403

    chapters = (CourseChapter.query
                .filter_by(course_id=enr.course_id)
                .order_by(CourseChapter.position.asc())
                .all())

    completed_ids = {
        cp.chapter_id
        for cp in CourseProgress.query
            .filter_by(student_id=enr.student_id, course_id=enr.course_id, completed=True)
            .with_entities(CourseProgress.chapter_id)
            .all()
    }

    result = []
    for ch in chapters:
        result.append({
            "title": ch.title,
            "type": ch.chapter_type or "content",
            "completed": ch.id in completed_ids,
            "position": ch.position,
        })

    # Check feedback status
    feedback_submitted = CourseFeedback.query.filter_by(
        student_id=enr.student_id, course_id=enr.course_id
    ).first() is not None
    if not feedback_submitted:
        course_obj = db.session.get(Course, enr.course_id)
        key = (getattr(course_obj, "final_assessment_key", None)
               or str(course_obj.id)).strip().lower().replace(" ", "_") if course_obj else None
        if key:
            feedback_submitted = CourseFeedback.query.filter_by(
                student_id=enr.student_id, course_key=key
            ).first() is not None

    return jsonify(ok=True, chapters=result, feedback_submitted=feedback_submitted)


@app.route("/admin/enrollment/<int:enrollment_id>/attempts/add", methods=["POST"])
def admin_quick_add_attempt(enrollment_id):
    """JSON endpoint: grant +1 attempt for an enrollment (used by the '+' button in view_students)."""
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < get_role_level('Super Admin'):
        return jsonify(ok=False, message="Insufficient permissions."), 403

    admin_id = session.get("admin_id")
    enr = CourseEnrollment.query.get(enrollment_id)
    if not enr:
        return jsonify(ok=False, message="Enrollment not found."), 404

    try:
        has_col = _column_exists(CourseEnrollment, "allowed_attempts")
        before = _allowed_cap(enr.student_id, enr.course_id)
        new_cap = before + 1

        if has_col:
            enr.allowed_attempts = new_cap
            db.session.add(enr)

        db.session.add(AttemptsAdjustment(
            student_id=enr.student_id,
            course_id=enr.course_id,
            delta=1,
            allowed_attempts=new_cap,
            reason="Quick-add from student view",
            admin_id=admin_id
        ))
        db.session.commit()

        used, left = get_attempt_counts(enr.student_id,
                                        enr.course.final_assessment_key if enr.course else "")
        return jsonify(ok=True, new_cap=new_cap, attempts_used=used, attempts_left=left)
    except Exception as e:
        db.session.rollback()
        return jsonify(ok=False, message=str(e)), 500


@app.route("/admin/enrollment/<int:enrollment_id>/attempts/remove", methods=["POST"])
def admin_quick_remove_attempt(enrollment_id):
    """JSON endpoint: remove 1 allowed attempt from an enrollment (used by the '-' button in view_students)."""
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < get_role_level('Super Admin'):
        return jsonify(ok=False, message="Insufficient permissions."), 403

    admin_id = session.get("admin_id")
    enr = CourseEnrollment.query.get(enrollment_id)
    if not enr:
        return jsonify(ok=False, message="Enrollment not found."), 404

    try:
        has_col = _column_exists(CourseEnrollment, "allowed_attempts")
        before = _allowed_cap(enr.student_id, enr.course_id)

        used, _ = get_attempt_counts(enr.student_id,
                                     enr.course.final_assessment_key if enr.course else "")
        if before <= used:
            return jsonify(ok=False, message="Cannot reduce below attempts already used."), 400
        if before <= 1:
            return jsonify(ok=False, message="Cannot reduce below 1."), 400

        new_cap = before - 1

        if has_col:
            enr.allowed_attempts = new_cap
            db.session.add(enr)

        db.session.add(AttemptsAdjustment(
            student_id=enr.student_id,
            course_id=enr.course_id,
            delta=-1,
            allowed_attempts=new_cap,
            reason="Quick-remove from student view",
            admin_id=admin_id
        ))
        db.session.commit()

        left = max(0, new_cap - used)
        return jsonify(ok=True, new_cap=new_cap, attempts_used=used, attempts_left=left)
    except Exception as e:
        db.session.rollback()
        return jsonify(ok=False, message=str(e)), 500


@app.route("/admin/final-attempts/grant", methods=["POST"])
def admin_grant_attempts():
    require_admin()
    admin_id = session.get("admin_id")

    student_id = request.form.get("student_id", type=int)
    course_id = request.form.get("course_id",  type=int)
    delta = max(1, request.form.get("delta", type=int, default=1))
    reason = (request.form.get("reason")
              or "Additional attempt(s) granted").strip()
    course_key = request.form.get("course_key")
    used_source = request.form.get("source") or request.args.get("source")

    if not (student_id and course_id and delta):
        flash("Missing student, course, or delta.", "danger")
        return redirect(url_for("admin_final_attempts",
                                course_id=course_id, student_id=student_id, source=used_source))

    try:
        has_col = _column_exists(CourseEnrollment, "allowed_attempts")

        enr = (CourseEnrollment.query
               .filter_by(student_id=student_id, course_id=course_id)
               .with_for_update()
               .first())
        if not enr:
            # create enrollment (cap handled below)
            enr = CourseEnrollment(student_id=student_id, course_id=course_id)
            if has_col:
                enr.allowed_attempts = 2
            db.session.add(enr)
            db.session.flush()

        before = _allowed_cap(student_id, course_id)
        new_cap = before + delta

        # keep column in sync if it exists
        if has_col:
            enr.allowed_attempts = new_cap
            db.session.add(enr)

        # audit row always
        db.session.add(AttemptsAdjustment(
            student_id=student_id,
            course_id=course_id,
            delta=delta,
            allowed_attempts=new_cap,
            reason=reason,
            admin_id=admin_id
        ))

        db.session.commit()
        note = "" if has_col else " (note: column not present; using adjustments fallback)"
        flash(
            f"Granted {delta} additional attempt(s). New limit: {new_cap}.{note}", "success")
    except Exception as e:
        db.session.rollback()
        flash(f"Error granting attempts: {e}", "danger")

    next_args = {}
    if course_id:
        next_args["course_id"] = course_id
    if course_key:
        next_args["course_key"] = course_key
    if used_source:
        next_args["source"] = used_source
        next_args["student_id"] = student_id
    return redirect(url_for("admin_final_attempts", **next_args))

