@app.route("/admin/final-attempts/reset", methods=["POST"])
def admin_reset_final_attempts():
    require_admin()

    # "final" or "legacy"
    source = (request.form.get("source") or "final").lower()
    # PK for FINAL, public ID for LEGACY
    student_id = request.form.get("student_id")
    course_id = request.form.get(
        "course_id", type=int)          # only for FINAL
    # for FINAL or LEGACY
    course_key = request.form.get("course_key")

    if not student_id or (not course_id and not course_key):
        flash("Missing student or course identifier.", "danger")
        return redirect(url_for("admin_final_attempts"))

    deleted = 0
    try:
        if source == "final":
            q = FinalAssessmentAttempt.query.filter(
                FinalAssessmentAttempt.student_id == int(student_id),
                FinalAssessmentAttempt.is_active.is_(True),
            )
            if course_id:
                q = q.filter(FinalAssessmentAttempt.course_id == course_id)
            if course_key:
                q = q.filter(FinalAssessmentAttempt.course_key == course_key)
            deleted = q.update({"is_active": False},
                               synchronize_session=False)

        # LEGACY AssessmentAttempt (student_id here is the public “student number”)
        else:
            q = AssessmentAttempt.query.filter(
                AssessmentAttempt.student_id == student_id,
                AssessmentAttempt.is_active.is_(True),
            )
            if course_key:
                q = q.filter(AssessmentAttempt.course_key == course_key)
            # legacy has no course_id column
            deleted = q.update({"is_active": False},
                               synchronize_session=False)

        db.session.commit()
        flash(f"Reset successful. Archived {deleted} attempt(s). "
              f"Submitted videos remain available for review.", "success")
    except Exception as e:
        db.session.rollback()
        flash(f"Error resetting attempts: {e}", "danger")

    # bounce back preserving filters and the source you were viewing
    next_args = {}
    if course_id:
        next_args["course_id"] = course_id
    if course_key:
        next_args["course_key"] = course_key
    if source:
        next_args["source"] = source
    return redirect(url_for("admin_final_attempts", **next_args))


