@app.route("/admin/retry-requests")
def admin_retry_requests():
    """View and manage student retry requests (3rd attempt requests)."""
    require_admin()

    status_filter = request.args.get("status", "pending")

    if status_filter == "all":
        requests = RetryRequest.query.order_by(
            RetryRequest.created_at.desc()
        ).all()
    else:
        requests = RetryRequest.query.filter_by(
            status=status_filter
        ).order_by(RetryRequest.created_at.desc()).all()

    # Count by status for tabs
    pending_count = RetryRequest.query.filter_by(status='pending').count()
    approved_count = RetryRequest.query.filter_by(status='approved').count()
    rejected_count = RetryRequest.query.filter_by(status='rejected').count()

    return render_template(
        "admin_retry_requests.html",
        requests=requests,
        status_filter=status_filter,
        pending_count=pending_count,
        approved_count=approved_count,
        rejected_count=rejected_count
    )


@app.route("/admin/retry-requests/<int:request_id>/approve", methods=["POST"])
def admin_approve_retry(request_id):
    """Approve a student's retry request, granting them a 3rd attempt."""
    require_admin()
    admin_id = session.get("admin_id")

    retry_req = RetryRequest.query.get_or_404(request_id)

    if retry_req.status != 'pending':
        flash("This request has already been processed.", "warning")
        return redirect(url_for("admin_retry_requests"))

    try:
        # Mark as approved
        retry_req.status = 'approved'
        retry_req.processed_at = _now_sast()
        retry_req.processed_by = admin_id
        retry_req.admin_note = request.form.get("note", "")

        # Increment allowed_attempts in enrollment
        enrollment = CourseEnrollment.query.filter_by(
            student_id=retry_req.student_id,
            course_id=retry_req.course_id
        ).first()

        if enrollment:
            current_cap = enrollment.allowed_attempts or 2
            enrollment.allowed_attempts = current_cap + 1
        else:
            # Create enrollment if missing (edge case)
            enrollment = CourseEnrollment(
                student_id=retry_req.student_id,
                course_id=retry_req.course_id,
                approved=True,
                allowed_attempts=3
            )
            db.session.add(enrollment)

        # Get the new allowed_attempts value for the audit record
        new_allowed = enrollment.allowed_attempts

        # Also create an AttemptsAdjustment audit record
        db.session.add(AttemptsAdjustment(
            student_id=retry_req.student_id,
            course_id=retry_req.course_id,
            delta=1,
            allowed_attempts=new_allowed,
            reason="3rd attempt request approved",
            admin_id=admin_id
        ))

        db.session.commit()
        flash(f"Approved retry request for {retry_req.student.name} {retry_req.student.surname} - {retry_req.course.title}. They now have a 3rd attempt.", "success")

    except Exception as e:
        db.session.rollback()
        flash(f"Error approving request: {e}", "danger")

    return redirect(url_for("admin_retry_requests"))


@app.route("/admin/retry-requests/<int:request_id>/reject", methods=["POST"])
def admin_reject_retry(request_id):
    """Reject a student's retry request."""
    require_admin()
    admin_id = session.get("admin_id")

    retry_req = RetryRequest.query.get_or_404(request_id)

    if retry_req.status != 'pending':
        flash("This request has already been processed.", "warning")
        return redirect(url_for("admin_retry_requests"))

    try:
        retry_req.status = 'rejected'
        retry_req.processed_at = _now_sast()
        retry_req.processed_by = admin_id
        retry_req.admin_note = request.form.get("reason", "No reason provided")

        db.session.commit()
        flash(f"Rejected retry request for {retry_req.student.name} {retry_req.student.surname}.", "info")

    except Exception as e:
        db.session.rollback()
        flash(f"Error rejecting request: {e}", "danger")

    return redirect(url_for("admin_retry_requests"))


@app.route("/api/retry-requests/count")
def api_retry_requests_count():
    """API endpoint to get pending retry requests count (for dashboard badge)."""
    if get_role_level(session.get('admin_role', '')) < 2:
        return jsonify({"error": "Unauthorized"}), 401
    count = RetryRequest.query.filter_by(status='pending').count()
    return jsonify({"count": count})


@app.route("/api/retry-requests/all-counts")
def api_retry_requests_all_counts():
    """API endpoint to get all retry request counts by status (for tab badges)."""
    if get_role_level(session.get('admin_role', '')) < 2:
        return jsonify({"error": "Unauthorized"}), 401
    pending = RetryRequest.query.filter_by(status='pending').count()
    approved = RetryRequest.query.filter_by(status='approved').count()
    rejected = RetryRequest.query.filter_by(status='rejected').count()
    return jsonify({
        "pending": pending,
        "approved": approved,
        "rejected": rejected,
        "total": pending + approved + rejected
    })


