# ============ DEVELOPER TESTING TOOLS ============
# Secret admin tools for simulating assessment results during testing

@app.route("/admin/dev-tools", methods=["GET"])
@require_role('Super Admin')
def admin_dev_tools():
    """Developer testing tools - simulate assessment results without taking exams."""
    # Get all students for dropdown
    students = Student.query.order_by(Student.surname.asc()).all()

    # Get all courses for dropdown
    courses = Course.query.order_by(Course.title.asc()).all()

