@app.route("/admin/dev-tools/simulate", methods=["POST"])
@require_role('Super Admin')
def admin_dev_simulate_result():
    """Simulate a final assessment submission with a chosen percentage."""
    student_id = request.form.get("student_id", type=int)
    course_id = request.form.get("course_id", type=int)
    percentage = request.form.get("percentage", type=float)

    if not student_id or not course_id or percentage is None:
        flash("Missing required fields (student, course, or percentage).", "danger")
        return redirect(url_for("admin_dev_tools"))

    # Validate student exists
    student = Student.query.get(student_id)
    if not student:
        flash(f"Student ID {student_id} not found.", "danger")
        return redirect(url_for("admin_dev_tools"))

    # Validate course exists
    course = Course.query.get(course_id)
    if not course:
        flash(f"Course ID {course_id} not found.", "danger")
        return redirect(url_for("admin_dev_tools"))

    # Create simulated submission
    score = int(percentage)  # Simulated score
    total_questions = 100  # Simulated total

    submission = FinalAssessmentSubmission(
        student_id=student_id,
        course_id=course_id,
        final_key=course.final_assessment_key or f"dev_sim_{course_id}",
        video_filename="DEV_SIMULATED_NO_VIDEO.webm",
        score=score,
        total_questions=total_questions,
        percentage=percentage,
        review_status="DEV_SIMULATED",
        submitted_at=_now_sast(),
        answers_json=json.dumps({"simulated": True, "dev_tool": True})
    )

    try:
        db.session.add(submission)
        db.session.commit()

        # Determine outcome message
        if percentage >= 80:
            outcome = "PASS"
        elif percentage >= 75:
            outcome = "SECOND CHANCE (75-79%)"
        else:
            outcome = "FAIL (Below 75%)"

        flash(f"✅ Simulated result created: {student.name} {student.surname} → {course.title} → {percentage}% ({outcome})", "success")
    except Exception as e:
        db.session.rollback()
        flash(f"Error creating simulated result: {e}", "danger")

    return redirect(url_for("admin_dev_tools"))


@app.route("/admin/dev-tools/reset-all", methods=["POST"])
@require_role('Super Admin')
def admin_dev_reset_all_attempts():
    """Delete ALL attempts for a student-course combination (for testing)."""
    student_id = request.form.get("student_id", type=int)
    course_id = request.form.get("course_id", type=int)

    if not student_id or not course_id:
        flash("Missing student or course ID.", "danger")
        return redirect(url_for("admin_dev_tools"))

    student = Student.query.get(student_id)
    course = Course.query.get(course_id)

    if not student or not course:
        flash("Student or course not found.", "danger")
        return redirect(url_for("admin_dev_tools"))

    deleted_count = 0
    student_id_str = student.student_id  # The 8-digit string ID for RpasAttempt/AirsideAttempt

    try:
        # Archive FinalAssessmentSubmission (row + proctoring video are kept)
        fas_deleted = FinalAssessmentSubmission.query.filter_by(
            student_id=student_id, course_id=course_id, is_active=True
        ).update({"is_active": False}, synchronize_session=False)
        deleted_count += fas_deleted

        # Also archive FinalAssessmentAttempt if exists
        try:
            faa_deleted = FinalAssessmentAttempt.query.filter_by(
                student_id=student_id, course_id=course_id, is_active=True
            ).update({"is_active": False}, synchronize_session=False)
            deleted_count += faa_deleted
        except Exception:
            pass  # Table may not exist

        # Archive RpasAttempt (uses string student_id)
        try:
            rpas_deleted = RpasAttempt.query.filter_by(
                student_id=student_id_str, is_active=True
            ).update({"is_active": False}, synchronize_session=False)
            deleted_count += rpas_deleted
        except Exception:
            pass

        # Archive AirsideAttempt (uses string student_id)
        try:
            airside_deleted = AirsideAttempt.query.filter_by(
                student_id=student_id_str, is_active=True
            ).update({"is_active": False}, synchronize_session=False)
            deleted_count += airside_deleted
        except Exception:
            pass

        # Delete from AssessmentAttempt (generic dynamic assessments like rpas_final)
        # Try multiple possible course_key values
        assessment_attempt_deleted = 0
        try:
            possible_keys = []
            # Add final_assessment_key if set
            if course.final_assessment_key:
                possible_keys.append(course.final_assessment_key)
                possible_keys.append(course.final_assessment_key.lower())
            # Add course slug/title variations
            if hasattr(course, 'slug') and course.slug:
                possible_keys.append(course.slug)
                possible_keys.append(course.slug.lower())
            # Add course title normalized
            if course.title:
                title_key = course.title.lower().replace(' ', '_').replace('-', '_')
                possible_keys.append(title_key)
                possible_keys.append(f"{title_key}_final")
            # Load ALL keys from assessments config (most reliable)
            try:
                for item in (load_assessments_cfg() or []):
                    if item.get('key'):
                        possible_keys.append(item['key'])
            except Exception:
                pass
            # Common patterns as fallback
            possible_keys.extend(['rpas_final', 'airside_induction', 'asat_gen', 'rpas_awareness'])

            # Remove duplicates
            possible_keys = list(set(k for k in possible_keys if k))

            for key in possible_keys:
                try:
                    count = AssessmentAttempt.query.filter_by(
                        student_id=student_id_str, course_key=key,
                        is_active=True
                    ).update({"is_active": False},
                             synchronize_session=False)
                    assessment_attempt_deleted += count
                except Exception:
                    pass
            deleted_count += assessment_attempt_deleted
        except Exception:
            pass

        # Delete VirtualQuizAttempts for every VirtualQuiz under this course
        # (v1.1.0 Phase 3e). Same rationale as in admin_dev_reset_everything:
        # without this, a passed quiz stays passed across resets and the
        # tester can't actually replay the unlock-final gating flow.
        vqa_deleted = 0
        try:
            quiz_ids = [
                vq.id for vq in
                VirtualQuiz.query.filter_by(course_id=course_id).all()
            ]
            if quiz_ids:
                vqa_deleted = VirtualQuizAttempt.query.filter(
                    VirtualQuizAttempt.student_id == student_id,
                    VirtualQuizAttempt.quiz_id.in_(quiz_ids),
                ).delete(synchronize_session=False)
                deleted_count += vqa_deleted
        except Exception:
            pass

        # Reset the enrollment's allowed_attempts back to default (2)
        enrollment = CourseEnrollment.query.filter_by(
            student_id=student_id, course_id=course_id
        ).first()
        if enrollment and hasattr(enrollment, 'allowed_attempts'):
            enrollment.allowed_attempts = 2

        # Clear any existing certificate-queue entry and prior feedback for
        # this student-course. Without this, a stale 'done'/'pending' queue
        # row silently blocks re-enqueue on the next pass (idempotency guard
        # in _trigger_certificate_after_feedback), and old feedback can make
        # the feedback form look already-submitted.
        cq_deleted = CertificateQueue.query.filter_by(
            student_id=student_id, course_id=course_id
        ).delete(synchronize_session=False)
        deleted_count += cq_deleted

        fb_deleted = CourseFeedback.query.filter_by(
            student_id=student_id, course_id=course_id
        ).delete(synchronize_session=False)
        if possible_keys:
            fb_deleted += CourseFeedback.query.filter(
                CourseFeedback.student_id == student_id,
                func.lower(CourseFeedback.course_key).in_([k.lower() for k in possible_keys])
            ).delete(synchronize_session=False)
        deleted_count += fb_deleted

        db.session.commit()
        flash(f"✅ Deleted {deleted_count} attempt(s) for {student.name} {student.surname} (including RPAS/Airside/Dynamic/{vqa_deleted} quiz). Attempts reset to fresh state.", "success")
    except Exception as e:
        db.session.rollback()
        flash(f"Error resetting attempts: {e}", "danger")

    return redirect(url_for("admin_dev_tools"))


@app.route("/admin/dev-tools/set-progress-100", methods=["POST"])
@require_role('Super Admin')
def admin_dev_set_progress_100():
    """Set a student's course progress to 100% (mark all chapters complete)."""
    student_id = request.form.get("student_id", type=int)
    course_id = request.form.get("course_id", type=int)

    if not student_id or not course_id:
        flash("Missing student or course ID.", "danger")
        return redirect(url_for("admin_dev_tools"))

    student = Student.query.get(student_id)
    course = Course.query.get(course_id)

    if not student or not course:
        flash("Student or course not found.", "danger")
        return redirect(url_for("admin_dev_tools"))

    # Get all chapters for this course
    chapters = CourseChapter.query.filter_by(course_id=course_id).all()

    if not chapters:
        flash(f"No chapters found for course: {course.title}", "warning")
        return redirect(url_for("admin_dev_tools"))

    try:
        completed_count = 0
        for chapter in chapters:
            # Check if progress record exists
            progress = CourseProgress.query.filter_by(
                student_id=student_id,
                course_id=course_id,
                chapter_id=chapter.id
            ).first()

            if progress:
                # Update existing record
                progress.completed = True
            else:
                # Create new progress record
                progress = CourseProgress(
                    student_id=student_id,
                    course_id=course_id,
                    chapter_id=chapter.id,
                    completed=True
                )
                db.session.add(progress)
            completed_count += 1

        # IMPORTANT: Reset enrollment.completed to False so "FINAL" button shows
        enrollment = CourseEnrollment.query.filter_by(
            student_id=student_id, course_id=course_id
        ).first()
        if enrollment:
            enrollment.completed = False
            # This tool exists to jump straight to the final, so it also has to
            # satisfy the CAA waiting period. The gate itself is deliberately
            # left alone: rather than adding a bypass inside
            # _enforce_final_wait, which would be a hole in a regulatory
            # control, the enrollment is backdated so the five hours have
            # genuinely elapsed. Derived from the constant so a change to the
            # CAA requirement carries through automatically.
            enrollment.first_accessed_at = (
                _now_sast()
                - timedelta(hours=FINAL_ASSESSMENT_MIN_WAIT_HOURS, minutes=5))

        # ALSO archive any existing FinalAssessmentSubmission records so
        # has_submitted_final = False, which makes dashboard show "FINAL" not
        # "MARK". Archiving (not deleting) keeps the proctoring videos.
        deleted_submissions = FinalAssessmentSubmission.query.filter_by(
            student_id=student_id, course_id=course_id, is_active=True
        ).update({"is_active": False}, synchronize_session=False)

        # Also archive FinalAssessmentAttempt if exists
        try:
            FinalAssessmentAttempt.query.filter_by(
                student_id=student_id, course_id=course_id, is_active=True
            ).update({"is_active": False}, synchronize_session=False)
        except Exception:
            pass

        # Archive RpasAttempt records (uses string student_id)
        rpas_deleted = 0
        student_id_str = student.student_id  # 8-digit string ID
        try:
            rpas_deleted = RpasAttempt.query.filter_by(
                student_id=student_id_str, is_active=True
            ).update({"is_active": False}, synchronize_session=False)
        except Exception:
            pass

        # Delete AirsideAttempt records (uses string student_id)
        airside_deleted = 0
        try:
            airside_deleted = AirsideAttempt.query.filter_by(
                student_id=student_id_str, is_active=True
            ).update({"is_active": False}, synchronize_session=False)
        except Exception:
            pass

        db.session.commit()
        total_cleared = deleted_submissions + rpas_deleted + airside_deleted
        msg = f"✅ Set {student.name} {student.surname}'s progress in '{course.title}' to 100%"
        if total_cleared:
            msg += f" (cleared {total_cleared} previous attempt(s))"
        msg += ". Dashboard will now show '🎯 FINAL' button"
        if enrollment:
            msg += (f", and the {FINAL_ASSESSMENT_MIN_WAIT_HOURS} hour waiting "
                    f"period has been cleared so the final can be started "
                    f"straight away")
        msg += "!"
        flash(msg, "success")
    except Exception as e:
        db.session.rollback()
        flash(f"Error setting progress: {e}", "danger")

    return redirect(url_for("admin_dev_tools"))


