@app.route("/admin/dev-tools/reset-everything", methods=["POST"])
@require_role('Super Admin')
def admin_dev_reset_everything():
    """Reset EVERYTHING for a student-course: progress to 0%, all attempts deleted, enrollment.completed = False."""
    student_id = request.form.get("student_id", type=int)
    course_id = request.form.get("course_id", type=int)

    if not student_id or not course_id:
        flash("Missing student or course ID.", "danger")
        return redirect(url_for("admin_dev_tools"))

    student = Student.query.get(student_id)
    course = Course.query.get(course_id)

    if not student or not course:
        flash("Student or course not found.", "danger")
        return redirect(url_for("admin_dev_tools"))

    try:
        # 1. Delete all chapter progress records
        progress_deleted = CourseProgress.query.filter_by(
            student_id=student_id, course_id=course_id
        ).delete()

        # 2. Archive all FinalAssessmentSubmission records (videos are kept)
        fas_deleted = FinalAssessmentSubmission.query.filter_by(
            student_id=student_id, course_id=course_id, is_active=True
        ).update({"is_active": False}, synchronize_session=False)

        # 3. Archive all FinalAssessmentAttempt records (if exists)
        faa_deleted = 0
        try:
            faa_deleted = FinalAssessmentAttempt.query.filter_by(
                student_id=student_id, course_id=course_id, is_active=True
            ).update({"is_active": False}, synchronize_session=False)
        except Exception:
            pass

        # 4. Archive RpasAttempt records (uses string student_id)
        rpas_deleted = 0
        student_id_str = student.student_id  # 8-digit string ID
        try:
            rpas_deleted = RpasAttempt.query.filter_by(
                student_id=student_id_str, is_active=True
            ).update({"is_active": False}, synchronize_session=False)
        except Exception:
            pass

        # 5. Archive AirsideAttempt records (uses string student_id)
        airside_deleted = 0
        try:
            airside_deleted = AirsideAttempt.query.filter_by(
                student_id=student_id_str, is_active=True
            ).update({"is_active": False}, synchronize_session=False)
        except Exception:
            pass

        # 6. Delete AssessmentAttempt records (generic dynamic assessments like rpas_final)
        assessment_attempt_deleted = 0
        try:
            possible_keys = []
            # Add final_assessment_key if set
            if course.final_assessment_key:
                possible_keys.append(course.final_assessment_key)
                possible_keys.append(course.final_assessment_key.lower())
            # Add course slug/title variations
            if hasattr(course, 'slug') and course.slug:
                possible_keys.append(course.slug)
                possible_keys.append(course.slug.lower())
            # Add course title normalized
            if course.title:
                title_key = course.title.lower().replace(' ', '_').replace('-', '_')
                possible_keys.append(title_key)
                possible_keys.append(f"{title_key}_final")
            # Load ALL keys from assessments config (most reliable)
            try:
                for item in (load_assessments_cfg() or []):
                    if item.get('key'):
                        possible_keys.append(item['key'])
            except Exception:
                pass
            # Common patterns as fallback
            possible_keys.extend(['rpas_final', 'airside_induction', 'asat_gen', 'rpas_awareness'])

            # Remove duplicates
            possible_keys = list(set(k for k in possible_keys if k))

            for key in possible_keys:
                try:
                    count = AssessmentAttempt.query.filter_by(
                        student_id=student_id_str, course_key=key,
                        is_active=True
                    ).update({"is_active": False},
                             synchronize_session=False)
                    assessment_attempt_deleted += count
                except Exception:
                    pass
        except Exception:
            pass

        # 7. Delete any RetryRequest records for this student-course
        retry_requests_deleted = 0
        try:
            retry_requests_deleted = RetryRequest.query.filter_by(
                student_id=student_id, course_id=course_id
            ).delete()
        except Exception:
            pass

        # 8. Delete any AttemptsAdjustment records for this student-course
        adjustments_deleted = 0
        try:
            adjustments_deleted = AttemptsAdjustment.query.filter_by(
                student_id=student_id, course_id=course_id
            ).delete()
        except Exception:
            pass

        # 9. Delete VirtualQuizAttempts for every VirtualQuiz under this course
        # (v1.1.0 Phase 3e). Without this, a tester who passed a pre-final
        # quiz couldn't retake it after a Reset Everything — the dashboard
        # would still show that quiz as passed, leaving the final unlocked
        # without going through the quiz flow again.
        vqa_deleted = 0
        try:
            quiz_ids = [
                vq.id for vq in
                VirtualQuiz.query.filter_by(course_id=course_id).all()
            ]
            if quiz_ids:
                vqa_deleted = VirtualQuizAttempt.query.filter(
                    VirtualQuizAttempt.student_id == student_id,
                    VirtualQuizAttempt.quiz_id.in_(quiz_ids),
                ).delete(synchronize_session=False)
        except Exception:
            pass

        # 10. Reset enrollment flags
        enrollment = CourseEnrollment.query.filter_by(
            student_id=student_id, course_id=course_id
        ).first()
        if enrollment:
            enrollment.completed = False
            if hasattr(enrollment, 'allowed_attempts'):
                enrollment.allowed_attempts = 2

        # 11. Clear any existing certificate-queue entry and prior feedback for
        # this student-course. Without this, a stale 'done'/'pending' queue
        # row silently blocks re-enqueue on the next pass (idempotency guard
        # in _trigger_certificate_after_feedback), and old feedback can make
        # the feedback form look already-submitted.
        cq_deleted = CertificateQueue.query.filter_by(
            student_id=student_id, course_id=course_id
        ).delete(synchronize_session=False)

        fb_deleted = CourseFeedback.query.filter_by(
            student_id=student_id, course_id=course_id
        ).delete(synchronize_session=False)
        if possible_keys:
            fb_deleted += CourseFeedback.query.filter(
                CourseFeedback.student_id == student_id,
                func.lower(CourseFeedback.course_key).in_([k.lower() for k in possible_keys])
            ).delete(synchronize_session=False)

        db.session.commit()

        total_deleted = progress_deleted + fas_deleted + faa_deleted + rpas_deleted + airside_deleted + assessment_attempt_deleted + retry_requests_deleted + adjustments_deleted + vqa_deleted + cq_deleted + fb_deleted
        flash(f"✅ FULL RESET for {student.name} {student.surname}: {progress_deleted} chapters, {fas_deleted + faa_deleted} final attempts, {rpas_deleted} RPAS, {airside_deleted} Airside, {assessment_attempt_deleted} dynamic attempts, {retry_requests_deleted} retry requests, {vqa_deleted} pre-final quiz attempts, {cq_deleted} certificate-queue entries, {fb_deleted} feedback rows cleared!", "success")
    except Exception as e:
        db.session.rollback()
        flash(f"Error resetting: {e}", "danger")

    return redirect(url_for("admin_dev_tools"))

