# ============ CERTIFICATE QUEUE ============

@app.route("/admin/certificate-queue")
@require_admin
def admin_certificate_queue():
    """Admin page to track pending and completed certificates.

    The Done tab is paginated and filterable so admins can see every
    historical certificate, not just the most recent 100. Filters accepted
    on the query string:
      ``q``        free-text match against student name / email / national_id
                   / company / course_title (case-insensitive LIKE)
      ``course_id`` restrict to one course's done certificates
      ``from``     done_at >= this ISO date (yyyy-mm-dd)
      ``to``       done_at <= end-of-day on this ISO date
      ``page``     1-based page index, 50 rows per page
    The Pending tab is unaffected (never had a row cap).
    """
    check_and_send_overdue_reminders()

    tab = request.args.get("tab", "pending")
    now = _now_sast()
    cutoff_24h = now - timedelta(hours=24)

    pending = CertificateQueue.query.filter_by(
        status='pending').order_by(CertificateQueue.passed_at.asc()).all()

    # --- Flag entries whose student has an unresolved appeal/dispute ---
    # No schema change on CertificateQueue; looked up and attached at request
    # time so past rows are never touched.
    open_appeal_pairs = set(
        db.session.query(AppealDispute.student_id, AppealDispute.course_id)
        .filter(AppealDispute.status != 'Resolved')
        .all()
    )
    for entry in pending:
        entry.has_open_appeal = (
            (entry.student_id, entry.course_id) in open_appeal_pairs
            or (entry.student_id, None) in open_appeal_pairs
        )

    # --- Done tab: filter + paginate ---
    done_q = CertificateQueue.query.filter_by(status='done')

    q_text = (request.args.get('q') or '').strip()
    if q_text:
        pattern = f'%{q_text}%'
        done_q = done_q.filter(db.or_(
            CertificateQueue.student_name.ilike(pattern),
            CertificateQueue.student_email.ilike(pattern),
            CertificateQueue.national_id.ilike(pattern),
            CertificateQueue.company.ilike(pattern),
            CertificateQueue.course_title.ilike(pattern),
        ))

    filter_course_id = request.args.get('course_id', type=int)
    if filter_course_id:
        done_q = done_q.filter(CertificateQueue.course_id == filter_course_id)

    from_str = (request.args.get('from') or '').strip()
    to_str = (request.args.get('to') or '').strip()
    if from_str:
        try:
            from_dt = datetime.fromisoformat(from_str)
            done_q = done_q.filter(CertificateQueue.done_at >= from_dt)
        except ValueError:
            from_str = ''  # blank out so the input doesn't repopulate with garbage
    if to_str:
        try:
            to_dt = datetime.fromisoformat(to_str).replace(
                hour=23, minute=59, second=59, microsecond=999999
            )
            done_q = done_q.filter(CertificateQueue.done_at <= to_dt)
        except ValueError:
            to_str = ''

    per_page = 50
    total_done = done_q.count()
    total_pages = max(1, (total_done + per_page - 1) // per_page)
    page = max(1, min(total_pages, request.args.get('page', type=int) or 1))

    done = (
        done_q.order_by(CertificateQueue.done_at.desc())
        .offset((page - 1) * per_page)
        .limit(per_page)
        .all()
    )
    for entry in done:
        entry.has_open_appeal = (
            (entry.student_id, entry.course_id) in open_appeal_pairs
            or (entry.student_id, None) in open_appeal_pairs
        )

    # Course options for the filter dropdown: every distinct course that has
    # ever produced a completed certificate, alphabetised by title.
    course_options = (
        db.session.query(
            CertificateQueue.course_id,
            CertificateQueue.course_title,
        )
        .filter_by(status='done')
        .distinct()
        .order_by(CertificateQueue.course_title.asc())
        .all()
    )

    overdue_count = sum(1 for e in pending if e.passed_at <= cutoff_24h)

    return render_template(
        "admin_certificate_queue.html",
        pending=pending,
        done=done,
        tab=tab,
        overdue_count=overdue_count,
        now=now,
        timedelta=timedelta,
        # Filter / pagination context for the Done tab.
        done_total=total_done,
        done_page=page,
        done_total_pages=total_pages,
        done_per_page=per_page,
        filter_q=q_text,
        filter_course_id=filter_course_id,
        filter_from=from_str,
        filter_to=to_str,
        course_options=course_options,
    )


def _save_certificate_pdf(entry, f):
    """Save a certificate PDF file and update the entry. Returns True on success."""
    ext = f.filename.rsplit('.', 1)[-1].lower() if '.' in f.filename else ''
    if ext != 'pdf':
        flash('Only PDF files are accepted for certificates.', 'danger')
        return False
    cert_dir = os.path.join(get_upload_root(), 'certificates', str(entry.student_id))
    os.makedirs(cert_dir, exist_ok=True)
    # Delete old file if replacing
    if entry.certificate_pdf:
        old_path = os.path.join(get_upload_root(), entry.certificate_pdf)
        try:
            os.remove(old_path)
        except OSError:
            pass
    fname = f"{uuid.uuid4().hex}_{secure_filename(f.filename)}"
    f.save(os.path.join(cert_dir, fname))
    entry.certificate_pdf = f"certificates/{entry.student_id}/{fname}"
    return True


@app.route("/admin/certificate-queue/<int:entry_id>/done", methods=["POST"])
@require_admin
def certificate_queue_done(entry_id):
    """Mark a certificate as done (issued), optionally with a PDF upload."""
    entry = CertificateQueue.query.get_or_404(entry_id)
    entry.status = 'done'
    entry.done_at = _now_sast()
    entry.done_by = session.get('admin_name', 'Admin')
    f = request.files.get('certificate_pdf')
    if f and f.filename:
        if not _save_certificate_pdf(entry, f):
            return redirect(url_for('admin_certificate_queue'))
    db.session.commit()
    flash(f"Certificate for {entry.student_name} marked as done.", "success")
    return redirect(url_for('admin_certificate_queue'))


@app.route("/admin/certificate-queue/<int:entry_id>/upload-pdf", methods=["POST"])
@require_admin
def certificate_queue_upload_pdf(entry_id):
    """Upload or replace a certificate PDF on an already-done entry."""
    entry = CertificateQueue.query.get_or_404(entry_id)
    f = request.files.get('certificate_pdf')
    if not f or not f.filename:
        flash('No file selected.', 'warning')
        return redirect(url_for('admin_certificate_queue'))
    if _save_certificate_pdf(entry, f):
        db.session.commit()
        flash(f"Certificate PDF uploaded for {entry.student_name}.", "success")
    return redirect(url_for('admin_certificate_queue'))


@app.route("/admin/certificate-queue/<int:entry_id>/delete-pdf", methods=["POST"])
@require_admin
def certificate_queue_delete_pdf(entry_id):
    """Delete a certificate PDF from a done entry."""
    entry = CertificateQueue.query.get_or_404(entry_id)
    if entry.certificate_pdf:
        old_path = os.path.join(get_upload_root(), entry.certificate_pdf)
        try:
            os.remove(old_path)
        except OSError:
            pass
        entry.certificate_pdf = None
        db.session.commit()
        flash(f"Certificate PDF deleted for {entry.student_name}.", "success")
    return redirect(url_for('admin_certificate_queue'))


@app.route("/certificate/<int:entry_id>/download")
def download_certificate_pdf(entry_id):
    """Download a certificate PDF. Accessible by admin, company owner, or the student."""
    entry = CertificateQueue.query.get_or_404(entry_id)
    if not entry.certificate_pdf:
        abort(404)
    # Auth check.
    # NOTE: session['student_id'] stores the *public* Student.student_id (an
    # 8-char String). CertificateQueue.student_id is the *internal* Student.id
    # (integer FK). The earlier check compared them directly and silently 403'd
    # every direct-student download. Direct students fell through; company-affiliated
    # students were masked because the company portal owner hit the is_company branch
    # on their behalf. Compare via the loaded Student to get the public string back.
    is_admin = 'admin_id' in session
    is_company = 'company_id' in session and entry.student and \
        entry.student.created_by_company_id == session.get('company_id')
    is_student = 'student_id' in session and entry.student and \
        entry.student.student_id == session.get('student_id')
    if not (is_admin or is_company or is_student):
        abort(403)
    file_path = os.path.join(get_upload_root(), entry.certificate_pdf)
    if not os.path.isfile(file_path):
        abort(404)
    dl_name = f"{entry.student_name} - {entry.course_title} Certificate.pdf"
    return send_file(file_path, as_attachment=True, download_name=dl_name)


@app.route("/api/certificate-queue/counts")
def api_certificate_queue_counts():
    """JSON endpoint for dashboard badge polling."""
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        return jsonify(error='Unauthorized'), 401
    now = _now_sast()
    cutoff_24h = now - timedelta(hours=24)
    pending_count = CertificateQueue.query.filter_by(status='pending').count()
    overdue_count = CertificateQueue.query.filter(
        CertificateQueue.status == 'pending',
        CertificateQueue.passed_at <= cutoff_24h,
    ).count()
    return jsonify(pending=pending_count, overdue=overdue_count)


@app.route("/admin/certificate-queue/test-reminder", methods=["POST"])
@require_admin
def certificate_queue_test_reminder():
    """Debug: force-send the overdue reminder email."""
    recipients = get_recipients_for_category('certificate_queue')
    if not recipients:
        flash("No recipients configured for 'Certificate Queue Reminders'. "
              "Add them under Email Recipients.", "warning")
        return redirect(url_for('admin_certificate_queue'))

    cutoff = _now_sast() - timedelta(hours=24)
    overdue = CertificateQueue.query.filter(
        CertificateQueue.status == 'pending',
        CertificateQueue.passed_at <= cutoff,
    ).all()

    if not overdue:
        # Send a test with all pending items for debugging
        overdue = CertificateQueue.query.filter_by(status='pending').all()

    if not overdue:
        flash("No pending certificates to include in the test email.", "info")
        return redirect(url_for('admin_certificate_queue'))

    rows_html = ""
    for e in overdue:
        hours = round((_now_sast() - e.passed_at).total_seconds() / 3600, 1)
        label = f"{hours}h overdue" if hours >= 24 else f"{hours}h ago"
        rows_html += f"""<tr>
            <td style="padding:8px;border:1px solid #e2e8f0">{e.student_name}</td>
            <td style="padding:8px;border:1px solid #e2e8f0">{e.company or '—'}</td>
            <td style="padding:8px;border:1px solid #e2e8f0">{e.course_title}</td>
            <td style="padding:8px;border:1px solid #e2e8f0">{e.score:.0f}%</td>
            <td style="padding:8px;border:1px solid #e2e8f0">{e.passed_at.strftime('%d %b %Y, %H:%M')}</td>
            <td style="padding:8px;border:1px solid #e2e8f0;font-weight:700">{label}</td>
        </tr>"""

    html_body = f"""
    <h2 style="color:#C7A434">[TEST] Certificate Queue Reminder</h2>
    <p>This is a <strong>test email</strong> triggered manually from the admin panel.</p>
    <p><strong>{len(overdue)}</strong> certificate(s) listed:</p>
    <table style="width:100%;border-collapse:collapse;margin:16px 0">
        <tr style="background:#17306B;color:#fff">
            <th style="padding:8px;text-align:left">Student</th>
            <th style="padding:8px;text-align:left">Company</th>
            <th style="padding:8px;text-align:left">Course</th>
            <th style="padding:8px;text-align:left">Score</th>
            <th style="padding:8px;text-align:left">Passed At</th>
            <th style="padding:8px;text-align:left">Status</th>
        </tr>
        {rows_html}
    </table>
    """

    subject = f"[TEST] Certificate Queue Reminder — {len(overdue)} item(s)"
    sent_to = []
    for recipient in recipients:
        try:
            send_email(recipient, subject, html_body)
            sent_to.append(recipient)
        except Exception as exc:
            flash(f"Failed to send to {recipient}: {exc}", "danger")

    if sent_to:
        flash(f"Test email sent to: {', '.join(sent_to)}", "success")
    return redirect(url_for('admin_certificate_queue'))


@app.route("/admin/certificate-queue/export")
@require_admin
def certificate_queue_export():
    """Export completed certificates as an Excel spreadsheet."""
    done = CertificateQueue.query.filter_by(
        status='done').order_by(CertificateQueue.done_at.desc()).all()

    rows = []
    for e in done:
        rows.append({
            "Student Name": e.student_name or '',
            "Email": e.student_email or '',
            "National ID": e.national_id or '',
            "Company": e.company or '',
            "Course": e.course_title or '',
            "Score (%)": round(e.score, 1) if e.score else '',
            "Passed At": e.passed_at.strftime('%Y-%m-%d %H:%M') if e.passed_at else '',
            "Certificate Done At": e.done_at.strftime('%Y-%m-%d %H:%M') if e.done_at else '',
            "Done By": e.done_by or '',
        })

    df = pd.DataFrame(rows)
    file_path = os.path.join('instance', 'completed_certificates.xlsx')
    df.to_excel(file_path, index=False, engine='openpyxl')
    return send_file(file_path, as_attachment=True,
                     download_name='completed_certificates.xlsx')


# ─── Manual Certificate Enqueue ───────────────────────────────────
@app.route("/api/certificate-queue/search-student")
@require_role('Admin')
def api_cert_queue_search_student():
    """Search students for manual certificate enqueue."""
    q = (request.args.get("q") or "").strip()
    if len(q) < 2:
        return jsonify(students=[])
    like = f"%{q}%"
    students = Student.query.filter(
        or_(Student.name.ilike(like), Student.surname.ilike(like),
            Student.email.ilike(like), Student.student_id.ilike(like),
            Student.national_id.ilike(like))
    ).limit(10).all()
    return jsonify(students=[{
        "id": s.id, "student_id": s.student_id,
        "name": f"{s.name} {s.surname}", "email": s.email,
    } for s in students])


@app.route("/api/certificate-queue/student-attempts/<int:student_id>")
@require_role('Admin')
def api_cert_queue_student_attempts(student_id):
    """Get passing final assessment attempts for a student (not already in queue)."""
    student = db.session.get(Student, student_id)
    if not student:
        return jsonify(attempts=[])

    results = []

    # FinalAssessmentAttempt (passed=True)
    fa_attempts = FinalAssessmentAttempt.query.filter(
        ((FinalAssessmentAttempt.student_id == student.id) |
         (FinalAssessmentAttempt.student_number == student.student_id)),
        FinalAssessmentAttempt.passed == True
    ).order_by(FinalAssessmentAttempt.submitted_at.desc()).all()

    for a in fa_attempts:
        course = db.session.get(Course, a.course_id) if a.course_id else None
        if not course:
            course = Course.query.filter(
                db.or_(Course.final_assessment_key == a.course_key)
            ).first()
        if not course:
            continue
        already = CertificateQueue.query.filter_by(
            student_id=student.id, course_id=course.id).first()
        results.append({
            "type": "final", "attempt_id": a.id,
            "course_id": course.id, "course_title": course.title,
            "score": a.percentage, "date": a.submitted_at.strftime("%d %b %Y") if a.submitted_at else "",
            "already_queued": already is not None,
        })

    # AssessmentAttempt (score >= 80)
    aa_attempts = AssessmentAttempt.query.filter_by(
        student_id=str(student.student_id)
    ).filter(AssessmentAttempt.score >= 80).order_by(
        AssessmentAttempt.created_at.desc()
    ).all()

    seen_courses = {r["course_id"] for r in results}
    for a in aa_attempts:
        course = Course.query.filter(
            db.or_(Course.final_assessment_key == a.course_key)
        ).first()
        if not course or course.id in seen_courses:
            continue
        seen_courses.add(course.id)
        already = CertificateQueue.query.filter_by(
            student_id=student.id, course_id=course.id).first()
        results.append({
            "type": "assessment", "attempt_id": a.id,
            "course_id": course.id, "course_title": course.title,
            "score": a.score, "date": a.created_at.strftime("%d %b %Y") if a.created_at else "",
            "already_queued": already is not None,
        })

    return jsonify(attempts=results)


@app.route("/admin/certificate-queue/manual-enqueue", methods=["POST"])
@require_role('Admin')
def admin_cert_queue_manual_enqueue():
    """Manually add a student's passing attempt to the certificate queue."""
    student_id = request.form.get("student_id", type=int)
    course_id = request.form.get("course_id", type=int)
    score = request.form.get("score", type=float)

    student = db.session.get(Student, student_id)
    course = db.session.get(Course, course_id)
    if not student or not course:
        flash("Student or course not found.", "danger")
        return redirect(url_for("admin_certificate_queue"))

    existing = CertificateQueue.query.filter_by(
        student_id=student.id, course_id=course.id).first()
    if existing:
        flash(f"{student.name} {student.surname} already has a certificate entry for {course.title}.", "warning")
        return redirect(url_for("admin_certificate_queue"))

    enqueue_certificate(student, course, score or 0)
    flash(f"Certificate for {student.name} {student.surname} - {course.title} added to queue.", "success")
    return redirect(url_for("admin_certificate_queue"))


# ============ ATTENDANCE REGISTER ============

def _query_completed_students(company_id, course_id, student_ids=None):
    """Query students who completed a course (based on done certificates).
       company_id=None means all students regardless of company."""
    q = (
        db.session.query(Student, CourseEnrollment, CertificateQueue)
        .join(CertificateQueue, CertificateQueue.student_id == Student.id)
        .join(CourseEnrollment, db.and_(
            CourseEnrollment.student_id == Student.id,
            CourseEnrollment.course_id == CertificateQueue.course_id,
        ))
        .filter(CertificateQueue.course_id == course_id)
        .filter(CertificateQueue.status == 'done')
    )
    if company_id:
        q = q.filter(Student.created_by_company_id == company_id)
    q = q.order_by(Student.surname, Student.name)
    if student_ids:
        q = q.filter(Student.id.in_(student_ids))
    return q.all()


def _generate_attendance_pdf(company, course, results):
    """Build attendance register PDF and return as send_file response."""
    rows = []
    for student, enr, cert in results:
        rows.append({
            'name': student.name,
            'surname': student.surname,
            'national_id': student.national_id or '',
            'email': student.email or '',
            'enrolled_at': enr.enrolled_at,
            'completed_at': (cert.passed_at if cert else enr.certificate_issued_date),
            'score': f"{cert.score:.0f}%" if cert and cert.score else 'N/A',
            'cert_status': cert.done_at.strftime('%d %b %Y') if cert and cert.status == 'done' and cert.done_at else ('Pending' if cert else '—'),
        })
    html = render_template('partials/attendance_register_pdf.html',
                           company=company, course=course, rows=rows, now=_now_sast())
    from weasyprint import HTML
    pdf_io = BytesIO()
    HTML(string=html, base_url=request.host_url).write_pdf(pdf_io)
    pdf_io.seek(0)
    safe_company = secure_filename(company.name or 'company')
    safe_course = secure_filename(course.title or 'course')
    return send_file(pdf_io, mimetype='application/pdf', as_attachment=True,
                     download_name=f"Attendance_Register_{safe_company}_{safe_course}.pdf")


@app.route("/admin/attendance-register")
@require_admin
def admin_attendance_register():
    """Admin page to generate attendance registers."""
    companies = Company.query.filter_by(approved=True).order_by(Company.name).all()
    courses = Course.query.order_by(Course.title).all()
    company_id = request.args.get('company_id', type=int)  # 0 = all students
    course_id = request.args.get('course_id', type=int)
    students = []
    selected_company = None
    selected_course = None
    if company_id is not None and course_id:
        if company_id > 0:
            selected_company = db.session.get(Company, company_id)
        selected_course = db.session.get(Course, course_id)
        if selected_course and (company_id == 0 or selected_company):
            students = _query_completed_students(company_id if company_id > 0 else None, course_id)
    return render_template('admin_attendance_register.html',
                           companies=companies, courses=courses, students=students,
                           selected_company=selected_company, selected_course=selected_course,
                           company_id=company_id, course_id=course_id)


@app.route("/admin/attendance-register/pdf", methods=["POST"])
@require_admin
def admin_attendance_register_pdf():
    """Generate attendance register PDF for admin."""
    company_id = request.form.get('company_id', type=int)
    course_id = request.form.get('course_id', type=int)
    student_ids = request.form.getlist('student_ids', type=int)
    if company_id is None or not course_id or not student_ids:
        flash("Please select a company, course, and at least one student.", "warning")
        return redirect(url_for('admin_attendance_register'))
    course = db.session.get(Course, course_id)
    if not course:
        abort(404)
    if company_id > 0:
        company = db.session.get(Company, company_id)
        if not company:
            abort(404)
    else:
        # "All Students" — create a dummy company object for the PDF header
        company = type('obj', (object,), {'name': 'All Companies / Private Students'})()
    results = _query_completed_students(company_id if company_id > 0 else None, course_id, student_ids)
    if not results:
        flash("No matching students found.", "warning")
        return redirect(url_for('admin_attendance_register', company_id=company_id, course_id=course_id))
    return _generate_attendance_pdf(company, course, results)


@app.route("/company/attendance-register")
@require_company
def company_attendance_register():
    """Company portal page to generate attendance registers."""
    cid = session["company_id"]
    company = db.session.get(Company, cid)
    cu = db.session.get(CompanyUser, session["company_user_id"])
    # Get courses that have done certificates for this company (branch-scoped)
    course_q = (
        db.session.query(CertificateQueue.course_id)
        .join(Student, Student.id == CertificateQueue.student_id)
        .filter(Student.created_by_company_id == cid)
        .filter(CertificateQueue.status == 'done')
    )
    if cu and cu.branch_id:
        course_q = course_q.filter(Student.branch_id == cu.branch_id)
    course_ids = course_q.distinct().all()
    course_id_list = [c[0] for c in course_ids]
    courses = Course.query.filter(Course.id.in_(course_id_list)).order_by(Course.title).all() if course_id_list else []
    selected_course_id = request.args.get('course_id', type=int)
    students = []
    selected_course = None
    if selected_course_id:
        selected_course = db.session.get(Course, selected_course_id)
        if selected_course:
            # Branch scoping
            base_q = Student.query.filter_by(created_by_company_id=cid)
            if cu and cu.branch_id:
                base_q = base_q.filter_by(branch_id=cu.branch_id)
            student_ids_scoped = [s.id for s in base_q.all()]
            if student_ids_scoped:
                students = _query_completed_students(cid, selected_course_id, student_ids_scoped)
    return render_template('company/attendance_register.html',
                           company=company, courses=courses, students=students,
                           selected_course=selected_course, course_id=selected_course_id)


@app.route("/company/attendance-register/pdf", methods=["POST"])
@require_company
def company_attendance_register_pdf():
    """Generate attendance register PDF for company portal."""
    cid = session["company_id"]
    company = db.session.get(Company, cid)
    course_id = request.form.get('course_id', type=int)
    student_ids = request.form.getlist('student_ids', type=int)
    if not course_id or not student_ids:
        flash("Please select a course and at least one student.", "warning")
        return redirect(url_for('company_attendance_register'))
    course = db.session.get(Course, course_id)
    if not course:
        abort(404)
    # Force company scope
    results = _query_completed_students(cid, course_id, student_ids)
    if not results:
        flash("No matching students found.", "warning")
        return redirect(url_for('company_attendance_register', course_id=course_id))
    return _generate_attendance_pdf(company, course, results)


# ============ EMAIL RECIPIENTS MANAGEMENT ============

@app.route("/admin/email-recipients", methods=["GET"])
@require_role('Super Admin')
def admin_email_recipients():
    """Manage email notification recipients dynamically."""
    # Get all recipients grouped by category
    recipients_by_category = {}
    for cat_key, cat_info in EMAIL_CATEGORIES.items():
        recipients = EmailRecipient.query.filter_by(category=cat_key).order_by(EmailRecipient.email).all()
        recipients_by_category[cat_key] = {
            'info': cat_info,
            'recipients': recipients
        }

    return render_template(
        "admin_email_recipients.html",
        categories=EMAIL_CATEGORIES,
        recipients_by_category=recipients_by_category
    )


@app.route("/admin/email-recipients/add", methods=["POST"])
@require_role('Super Admin')
def admin_email_recipients_add():
    """Add a new email recipient to a category."""
    category = request.form.get("category", "").strip()
    email = request.form.get("email", "").strip().lower()
    name = request.form.get("name", "").strip()

    if not category or not email:
        flash("Category and email are required.", "danger")
        return redirect(url_for("admin_email_recipients"))

    if category not in EMAIL_CATEGORIES:
        flash("Invalid category.", "danger")
        return redirect(url_for("admin_email_recipients"))

    # Check if already exists
    existing = EmailRecipient.query.filter_by(category=category, email=email).first()
    if existing:
        flash(f"{email} is already in {EMAIL_CATEGORIES[category]['name']}.", "warning")
        return redirect(url_for("admin_email_recipients"))

    try:
        recipient = EmailRecipient(
            category=category,
            email=email,
            name=name or None,
            is_active=True,
            added_by=session.get('admin_email', 'admin')
        )
        db.session.add(recipient)
        db.session.commit()
        flash(f"Added {email} to {EMAIL_CATEGORIES[category]['name']}.", "success")
    except Exception as e:
        db.session.rollback()
        flash(f"Error adding recipient: {e}", "danger")

    return redirect(url_for("admin_email_recipients"))


@app.route("/admin/email-recipients/toggle/<int:recipient_id>", methods=["POST"])
@require_role('Super Admin')
def admin_email_recipients_toggle(recipient_id):
    """Toggle a recipient's active status."""
    recipient = EmailRecipient.query.get(recipient_id)
    if not recipient:
        flash("Recipient not found.", "danger")
        return redirect(url_for("admin_email_recipients"))

    try:
        recipient.is_active = not recipient.is_active
        db.session.commit()
        status = "activated" if recipient.is_active else "deactivated"
        flash(f"{recipient.email} has been {status}.", "success")
    except Exception as e:
        db.session.rollback()
        flash(f"Error toggling recipient: {e}", "danger")

    return redirect(url_for("admin_email_recipients"))


@app.route("/admin/email-recipients/delete/<int:recipient_id>", methods=["POST"])
@require_role('Super Admin')
def admin_email_recipients_delete(recipient_id):
    """Delete a recipient."""
    recipient = EmailRecipient.query.get(recipient_id)
    if not recipient:
        flash("Recipient not found.", "danger")
        return redirect(url_for("admin_email_recipients"))

    try:
        email = recipient.email
        category_name = EMAIL_CATEGORIES.get(recipient.category, {}).get('name', recipient.category)
        db.session.delete(recipient)
        db.session.commit()
        flash(f"Removed {email} from {category_name}.", "success")
    except Exception as e:
        db.session.rollback()
        flash(f"Error deleting recipient: {e}", "danger")

    return redirect(url_for("admin_email_recipients"))


