@app.route("/admin/patch-notes/add", methods=["POST"])
@require_role('Developer')
def admin_patch_notes_add():
    """Add a new patch note entry."""
    import json

    version = request.form.get("version", "").strip()
    note_date = request.form.get("date", "").strip()
    title = request.form.get("title", "").strip()
    changes_raw = request.form.get("changes", "").strip()

    if not version or not note_date or not title or not changes_raw:
        flash("All fields are required.", "danger")
        return redirect(url_for("admin_patch_notes"))

    # Parse changes (one per line)
    changes = [line.strip() for line in changes_raw.split("\n") if line.strip()]

    if not changes:
        flash("At least one change is required.", "danger")
        return redirect(url_for("admin_patch_notes"))

    config_path = os.path.join(os.path.dirname(__file__), "config", "patch_notes.json")

    try:
        # Load existing notes
        notes = []
        try:
            with open(config_path, "r", encoding="utf-8") as f:
                notes = json.load(f)
        except FileNotFoundError:
            notes = []

        # Generate new ID
        max_id = max((n.get("id", 0) for n in notes), default=0)
        new_id = max_id + 1

        # Create new note (change_reviews is empty → all items default to "review")
        new_note = {
            "id": new_id,
            "date": note_date,
            "version": version,
            "title": title,
            "changes": changes,
            "change_reviews": {}
        }

        # Add to list
        notes.append(new_note)

        # Save back to file
        with open(config_path, "w", encoding="utf-8") as f:
            json.dump(notes, f, indent=2, ensure_ascii=False)

        flash(f"Patch note v{version} added — items awaiting review.", "success")
    except Exception as e:
        flash(f"Error adding patch note: {e}", "danger")

    return redirect(url_for("admin_patch_notes"))


@app.route("/admin/patch-notes/delete/<int:note_id>", methods=["POST"])
@require_role('Developer')
def admin_patch_notes_delete(note_id):
    """Delete a patch note entry."""
    import json

    config_path = os.path.join(os.path.dirname(__file__), "config", "patch_notes.json")

    try:
        # Load existing notes
        with open(config_path, "r", encoding="utf-8") as f:
            notes = json.load(f)

        # Find and remove the note
        original_count = len(notes)
        notes = [n for n in notes if n.get("id") != note_id]

        if len(notes) == original_count:
            flash("Patch note not found.", "warning")
            return redirect(url_for("admin_patch_notes"))

        # Save back to file
        with open(config_path, "w", encoding="utf-8") as f:
            json.dump(notes, f, indent=2, ensure_ascii=False)

        flash("Patch note deleted successfully!", "success")
    except Exception as e:
        flash(f"Error deleting patch note: {e}", "danger")

    return redirect(url_for("admin_patch_notes"))


@app.route("/admin/patch-notes/edit/<int:note_id>", methods=["POST"])
@require_role('Developer')
def admin_patch_notes_edit(note_id):
    """Edit an existing patch note entry."""
    import json

    version = request.form.get("version", "").strip()
    note_date = request.form.get("date", "").strip()
    title = request.form.get("title", "").strip()
    changes_raw = request.form.get("changes", "").strip()

    if not version or not note_date or not title or not changes_raw:
        flash("All fields are required.", "danger")
        return redirect(url_for("admin_patch_notes"))

    # Parse changes (one per line)
    changes = [line.strip() for line in changes_raw.split("\n") if line.strip()]

    if not changes:
        flash("At least one change is required.", "danger")
        return redirect(url_for("admin_patch_notes"))

    config_path = os.path.join(os.path.dirname(__file__), "config", "patch_notes.json")

    try:
        # Load existing notes
        with open(config_path, "r", encoding="utf-8") as f:
            notes = json.load(f)

        # Find and update the note
        found = False
        for note in notes:
            if note.get("id") == note_id:
                note["version"] = version
                note["date"] = note_date
                note["title"] = title
                note["changes"] = changes
                found = True
                break

        if not found:
            flash("Patch note not found.", "warning")
            return redirect(url_for("admin_patch_notes"))

        # Save back to file
        with open(config_path, "w", encoding="utf-8") as f:
            json.dump(notes, f, indent=2, ensure_ascii=False)

        flash(f"Patch note v{version} updated successfully!", "success")
    except Exception as e:
        flash(f"Error updating patch note: {e}", "danger")

    return redirect(url_for("admin_patch_notes"))


@app.route("/admin/patch-notes/<int:note_id>/change-status", methods=["POST"])
@require_role('Super Admin')
def admin_patch_notes_change_status(note_id):
    """Set the review status of an individual change item (Super Admin+)."""
    import json as _json
    from datetime import date

    is_ajax = request.headers.get("X-Requested-With") == "XMLHttpRequest"

    idx = request.form.get("index", "").strip()
    new_status = request.form.get("status", "").strip().lower()
    status_note = request.form.get("status_note", "").strip() or None

    if new_status not in ("review", "approved", "problem"):
        if is_ajax:
            return jsonify(ok=False, error="Invalid status."), 400
        flash("Invalid status.", "danger")
        return redirect(url_for("admin_patch_notes"))

    config_path = os.path.join(os.path.dirname(__file__), "config", "patch_notes.json")

    try:
        with open(config_path, "r", encoding="utf-8") as f:
            notes = _json.load(f)

        found = False
        review_data = None
        for note in notes:
            if note.get("id") == note_id:
                if "change_reviews" not in note:
                    note["change_reviews"] = {}
                review_data = {
                    "status": new_status,
                    "by": session.get("admin_email", "unknown"),
                    "at": date.today().isoformat(),
                    "note": status_note if new_status == "problem" else None
                }
                note["change_reviews"][idx] = review_data
                found = True
                break

        if not found:
            if is_ajax:
                return jsonify(ok=False, error="Patch note not found."), 404
            flash("Patch note not found.", "warning")
            return redirect(url_for("admin_patch_notes"))

        with open(config_path, "w", encoding="utf-8") as f:
            _json.dump(notes, f, indent=2, ensure_ascii=False)

        if is_ajax:
            return jsonify(ok=True, review=review_data)

        labels = {"review": "set to Review", "approved": "approved", "problem": "flagged as Problem"}
        flash(f"Item {labels[new_status]}.", "success")
    except Exception as e:
        if is_ajax:
            return jsonify(ok=False, error=str(e)), 500
        flash(f"Error updating item status: {e}", "danger")

    return redirect(url_for("admin_patch_notes"))

