ASSESSMENTS_CFG_DIR = os.path.join(app.root_path, "config")
ASSESSMENTS_CFG_FILE = os.path.join(ASSESSMENTS_CFG_DIR, "assessments.json")
QUESTIONS_DIR = os.path.join(app.root_path, "questions")


def load_assessments_cfg():
    os.makedirs(ASSESSMENTS_CFG_DIR, exist_ok=True)
    if not os.path.exists(ASSESSMENTS_CFG_FILE):
        with open(ASSESSMENTS_CFG_FILE, "w", encoding="utf-8") as f:
            json.dump([], f, ensure_ascii=False, indent=2)
        return []
    with open(ASSESSMENTS_CFG_FILE, "r", encoding="utf-8") as f:
        try:
            return json.load(f) or []
        except json.JSONDecodeError:
            return []


def save_assessments_cfg(items):
    os.makedirs(ASSESSMENTS_CFG_DIR, exist_ok=True)
    with open(ASSESSMENTS_CFG_FILE, "w", encoding="utf-8") as f:
        json.dump(items, f, ensure_ascii=False, indent=2)


def _slugify_assessment_key(value: str) -> str:
    """Turn arbitrary admin input into a URL-safe assessment key.

    Lowercase, ampersands become 'and', any non-alphanumeric run collapses
    to a single underscore, leading/trailing underscores stripped.
    """
    s = (value or "").strip().lower()
    if not s:
        return ""
    s = re.sub(r"&", " and ", s)
    s = re.sub(r"[^a-z0-9]+", "_", s)
    s = re.sub(r"_+", "_", s)
    return s.strip("_")


def _unique_assessment_key(base: str, items: list) -> str:
    """Append _2, _3, ... if base collides with an existing key."""
    base = base or "assessment"
    existing = {(x.get("key") or "").lower() for x in (items or [])}
    if base not in existing:
        return base
    n = 2
    while f"{base}_{n}" in existing:
        n += 1
    return f"{base}_{n}"

# Make the list available to all templates as 'assessments_catalog'


@app.context_processor
def inject_assessments_catalog():
    return {"assessments_catalog": load_assessments_cfg()}

