def ensure_questions_scaffold(course_key: str, qfile: str, count: int = 0):
    os.makedirs(QUESTIONS_DIR, exist_ok=True)
    path = os.path.join(QUESTIONS_DIR, qfile)
    if os.path.exists(path):
        return path
    scaffold = []
    # Any placeholders requested are shaped for the v1.1.0 Question Builder:
    # options as a dict keyed A/B/C/D, correct as a letter, explicit type.
    for i in range(1, count + 1):
        scaffold.append({
            "id": i,
            "type": "mcq",
            "question": f"Placeholder Q{i} for {course_key}",
            "options": {"A": "Option A", "B": "Option B", "C": "Option C", "D": "Option D"},
            "correct": "A",
            "points": 1,
            "explanation": ""
        })
    with open(path, "w", encoding="utf-8") as f:
        json.dump(scaffold, f, ensure_ascii=False, indent=2)
    return path

