def attempts_status(student_pk: int, course_pk: int, *, course_key: str = None):
    """
    Return (used, cap, left) for a student/course.
    cap: CourseEnrollment.allowed_attempts if present, else 3 + SUM(AttemptsAdjustment.delta)
    used: FINAL attempts (+ LEGACY attempts if course_key is provided)
    """
    cap = _allowed_cap(student_pk, course_pk)

    # used in FINAL
    used = (db.session.query(func.count(FinalAssessmentAttempt.id))
            .filter(FinalAssessmentAttempt.student_id == student_pk)
            .filter(FinalAssessmentAttempt.course_id == course_pk)
            .scalar()) or 0

    # include LEGACY attempts if we know the legacy key + student public code
    if course_key:
        stu = Student.query.get(student_pk)
        if stu and stu.student_id:
            used_legacy = (db.session.query(func.count(AssessmentAttempt.id))
                           .filter(AssessmentAttempt.student_id == stu.student_id)
                           .filter(AssessmentAttempt.course_key == course_key)
                           .scalar()) or 0
            used += used_legacy

    left = max(0, int(cap) - int(used))
    return int(used), int(cap), int(left)


