@app.route("/admin/attempts/<course_key>", methods=["GET"], endpoint="admin_attempts_for_course")
@require_admin
def admin_attempts_for_course(course_key):
    # --- meta/title ---
    title_text = f"{course_key} Attempts (All)"
    configured_course_id = None
    meta = None
    try:
        items = load_assessments_cfg()
        # exact match first, then case-insensitive fallback
        meta = next((x for x in items if x.get("key") == course_key), None)
        if not meta:
            meta = next((x for x in items if (x.get("key") or "").lower() == (
                course_key or "").lower()), None)
        if meta:
            title_text = f"{meta.get('title', 'Assessment')} Attempts (All)"
            configured_course_id = meta.get("course_id")
    except Exception:
        meta = None

    # optional debug switch
    debug = request.args.get("debug") == "1"
    dbg = {"course_key_param": course_key}

    # ---------- Source A: legacy FinalAssessmentAttempt ----------
    fa_attempts = []
    try:
        fa_q = (
            FinalAssessmentAttempt.query
            .filter(
                or_(
                    FinalAssessmentAttempt.course_key == course_key,
                    (FinalAssessmentAttempt.course_id ==
                     configured_course_id) if configured_course_id else False,
                )
            )
            .order_by(desc(FinalAssessmentAttempt.submitted_at))
            .limit(500)
        )
        fa_attempts = fa_q.all()
    except Exception as e:
        if debug:
            dbg["fa_err"] = str(e)

    # ---------- Source B: dynamic AssessmentAttempt ----------
    assess_attempts = []
    try:
        assess_q = (
            AssessmentAttempt.query
            .filter(func.lower(AssessmentAttempt.course_key) == (course_key or "").lower())
            .order_by(desc(AssessmentAttempt.finished_at))
            .limit(500)
        )
        assess_attempts = assess_q.all()

        if debug and not assess_attempts:
            distinct_keys = [k[0] for k in db.session.query(
                func.lower(AssessmentAttempt.course_key)).distinct().all()]
            dbg["assess_keys_in_db"] = distinct_keys
    except Exception as e:
        if debug:
            dbg["assess_err"] = str(e)

    # ---------- PDF endpoint picker (optional) ----------
    def _first_existing_endpoint(candidates):
        for ep in candidates:
            if ep in app.view_functions:
                return ep
        return None

    pdf_ep = _first_existing_endpoint([
        "admin_final_attempt_pdf",
        "admin_attempt_pdf",
        "admin_rpas_attempt_pdf_v2",
        "admin_rpas_attempt_pdf",
        "admin_airside_attempt_pdf_v2",
        "admin_airside_attempt_pdf",
    ])

    rows = []

    # ---------- normalize legacy final attempts ----------
    for a in (fa_attempts or []):
        student = a.student
        course = a.course

        # robust id/name fallbacks
        student_number = (
            getattr(student, "student_id", None)
            or getattr(student, "id", None)
            or getattr(a, "student_number", None)
        )
        first = (getattr(student, "name", "") or getattr(
            student, "first_name", "") or "").strip()
        last = (getattr(student, "surname", "") or getattr(
            student, "last_name", "") or "").strip()
        student_name = (f"{first} {last}".strip() if (
            first or last) else "")  # may be ""

        video_url = None
        if student_number and getattr(a, "video_filename", None):
            try:
                video_url = url_for(
                    "uploaded_file", student_id=student_number, filename=a.video_filename)
            except Exception:
                video_url = None

        try:
            pdf_url = url_for(pdf_ep, attempt_id=a.id) if pdf_ep else None
        except Exception:
            pdf_url = None

        rows.append({
            "id": a.id,
            "student_number": student_number,
            # 👈 explicit alias for template
            "student_id": student_number,
            # None -> shows as "—" in template if you do that
            "student_name": student_name or None,
            "course_title": getattr(course, "title", f"Course {a.course_id}"),
            "course_id": a.course_id,
            "submitted_at": a.submitted_at,
            "score": a.correct_count,
            "total": a.total_questions,
            "percentage": float(a.percentage or 0.0),
            "review_status": a.review_status,
            "video_url": video_url,
            "pdf_url": pdf_url,
            "student_attempts_url": url_for("admin_attempts_for_student", student_number=student_number) if student_number else None,
            "result_url": None,
            "passed": (float(a.percentage or 0.0) >= float(getattr(a, "pass_mark", 80))),
            "source": "final",
        })

    # ---------- normalize dynamic assessment attempts ----------
    for a in (assess_attempts or []):
        student_number = a.student_number or a.student_id

        # name fallbacks
        first = getattr(a, "first_name", "") or ""
        last = getattr(a, "last_name", "") or ""
        student_name = (getattr(a, "full_name", None)
                        or f"{first} {last}".strip()) or None

        try:
            detailed = json.loads(
                a.answers_json or "[]") if a.answers_json else []
            correct = sum(1 for x in detailed if x.get("is_right"))
            total = len(detailed) or 1
        except Exception:
            detailed, correct, total = [], 0, 1

        percentage = float(a.score or 0.0)  # stored as %

        video_url = None
        if student_number and getattr(a, "video_filename", None):
            try:
                video_url = url_for(
                    "uploaded_file", student_id=student_number, filename=a.video_filename)
            except Exception:
                video_url = None

        try:
            result_url = url_for(f"{course_key}_result", attempt_id=a.id)
        except Exception:
            result_url = None

        rows.append({
            "id": a.id,
            "student_number": student_number,
            # 👈 explicit alias for template
            "student_id": student_number,
            "student_name": student_name,
            "email": getattr(a, "email", None),
            "course_title": (meta.get("title") if meta else course_key),
            "course_id": getattr(a, "course_id", None),
            "submitted_at": a.finished_at or a.started_at,
            "score": correct,
            "total": total,
            "percentage": percentage,
            "review_status": None,
            "video_url": video_url,
            "pdf_url": None,
            "student_attempts_url": url_for("admin_attempts_for_student", student_number=student_number) if student_number else None,
            "result_url": result_url,
            "passed": bool(a.passed),
            "source": "assess",
        })

    # newest first
    rows.sort(key=lambda r: (r["submitted_at"] or datetime.min), reverse=True)

    if debug:
        try:
            print("[ADMIN DEBUG] course_key param:", course_key)
            print("[ADMIN DEBUG] FinalAssessmentAttempt count:", len(fa_attempts))
            print("[ADMIN DEBUG] AssessmentAttempt count:", len(assess_attempts))
            for a in assess_attempts[:5]:
                print("[ADMIN DEBUG] assess row -> id:", a.id,
                      "course_key:", a.course_key, "finished:", a.finished_at)
        except Exception:
            pass

    back_url = url_for(
        "admin_dashboard") if "admin_dashboard" in app.view_functions else url_for("index")

    # --- filters (ALWAYS provide to avoid template UndefinedError) ---
    current_filters = {
        "course_key": course_key,
        "q": request.args.get("q", ""),
        "source": request.args.get("source", ""),      # "final" / "assess"
        "passed": request.args.get("passed", ""),      # "1" / "0"
        "min_pct": request.args.get("min_pct", ""),
        "max_pct": request.args.get("max_pct", ""),
        "student": request.args.get("student", ""),    # number or name
        "student_id": request.args.get("student_id", ""),
        "from": request.args.get("from", ""),          # date
        "to": request.args.get("to", ""),              # date
    }

    # --- pagination (also pass 'pages' alias some templates expect) ---
    try:
        page = int(request.args.get("page", 1) or 1)
    except ValueError:
        page = 1
    try:
        per_page = int(request.args.get("per_page", 50) or 50)
    except ValueError:
        per_page = 50
    if per_page <= 0:
        per_page = 50
    if page <= 0:
        page = 1

    total = len(rows)
    total_pages = max(1, (total + per_page - 1) // per_page)
    if page > total_pages:
        page = total_pages
    start = (page - 1) * per_page
    end = start + per_page
    page_rows = rows[start:end]

    has_prev = page > 1
    has_next = page < total_pages
    prev_page = page - 1 if has_prev else None
    next_page = page + 1 if has_next else None
    pages = total_pages  # alias

    return render_template(
        "admin_attempts.html",
        title=title_text,
        rows=page_rows,              # page slice
        attempts=page_rows,          # legacy alias
        count=total,
        back_url=back_url,
        course_key=course_key,
        current_filters=current_filters,  # <<< critical
        # pagination vars
        page=page,
        per_page=per_page,
        total=total,
        total_pages=total_pages,
        pages=pages,                 # alias for templates using 'pages'
        has_prev=has_prev,
        has_next=has_next,
        prev_page=prev_page,
        next_page=next_page,
        debug_info=dbg if debug else None,
    )


