def _endpoint_exists(name: str) -> bool:
    """Return True if a Flask endpoint name is already registered."""
    try:
        for rule in app.url_map.iter_rules():
            if rule.endpoint == name:
                return True
    except Exception:
        pass
    return False


def ensure_assessment_registered(course_key: str, title: Optional[str] = None, pass_mark: Optional[int] = None) -> None:
    """
    Idempotently ensure /{course_key} (take) and /{course_key}/result/... routes exist NOW.
    Uses registry to fill missing title/pass_mark if not provided.
    """
    if not course_key:
        return

    take_ep = f"{course_key}_take"
    result_ep = f"{course_key}_result"
    if _endpoint_exists(take_ep) and _endpoint_exists(result_ep):
        return  # already present

    # Fill from registry if needed
    if title is None or pass_mark is None:
        try:
            for it in (load_assessments_cfg() or []):
                if it.get("key") == course_key:
                    title = title or it.get("title") or course_key.upper()
                    pass_mark = int(
                        pass_mark if pass_mark is not None else it.get("pass_mark", 80))
                    break
        except Exception:
            pass

    # Fallbacks
    title = title or course_key.upper()
    pass_mark = int(pass_mark or 80)

    try:
        register_assessment(course_key, title, pass_mark=pass_mark)
        app.logger.info("Registered assessment routes for %s", course_key)
    except AssertionError as e:
        app.logger.debug(
            "Routes already existed during ensure_assessment_registered(%s): %s", course_key, e)
    except Exception as e:
        app.logger.warning(
            "Could not register routes for %s: %s", course_key, e)


