@app.route("/admin/final-assessments/new", methods=["GET", "POST"], endpoint="admin_new_final_assessment")
@require_admin
def admin_new_final_assessment():
    if request.method == "GET":
        return render_template("admin_assessment_new.html")

    raw_key = (request.form.get("course_key") or "").strip()
    title = (request.form.get("title") or "").strip()
    pass_mark = int(request.form.get("pass_mark") or 80)
    icon = (request.form.get("icon") or "").strip() or "fa-file-alt"

    if not title:
        flash("Title is required.", "warning")
        return render_template("admin_assessment_new.html")

    # Always sanitise the key server-side. If the admin left it blank, derive
    # it from the title so they never need to think about URL formatting.
    course_key = _slugify_assessment_key(raw_key) or _slugify_assessment_key(title)
    if not course_key:
        flash("Could not build a URL-safe key from the title. Please use letters or numbers.", "warning")
        return render_template("admin_assessment_new.html")

    # Derive default qfile
    qfile = f"{course_key}_final_questions.json"
    ensure_questions_scaffold(course_key, qfile)

    # Update registry
    items = load_assessments_cfg()
    if any((x.get("key") or "").lower() == course_key for x in items):
        # Auto-disambiguate so the admin isn't stuck staring at a "already exists" error.
        new_key = _unique_assessment_key(course_key, items)
        flash(f"An assessment with key '{course_key}' already existed; using '{new_key}' instead.", "info")
        course_key = new_key
        qfile = f"{course_key}_final_questions.json"
        ensure_questions_scaffold(course_key, qfile)
        items.append({
            "key": course_key,
            "title": title,
            "pass_mark": pass_mark,
            "icon": icon,
            "qfile": qfile,
            "pdf_endpoint": None,
        })
        save_assessments_cfg(items)
    else:
        items.append({
            "key": course_key,
            "title": title,
            "pass_mark": pass_mark,
            "icon": icon,
            "qfile": qfile,
            # Set this if/when you have a PDF route for this course
            "pdf_endpoint": None,
        })
        save_assessments_cfg(items)
        flash(f"Created assessment '{course_key}'.", "success")

    # Ensure routes exist immediately (idempotent; safe if already present)
    ensure_assessment_registered(course_key, title=title, pass_mark=pass_mark)

    # Done: redirect to the new Attempts page (works immediately).
    return redirect(url_for("admin_attempts_for_course", course_key=course_key))


