def get_kpis():
    """Compute dashboard KPIs with safe fallbacks."""
    now = _now_sast()
    seven_days_ago = now - timedelta(days=7)
    one_day_ago = now - timedelta(days=1)

    # --- Active Students ---
    # Preferred: distinct students that have any enrollment (if CourseEnrollment exists)
    try:
        # Avoid circular import issues: referenced by name, not imported at top
        # if your models are in the same file, this import is not needed
        from app import CourseEnrollment
        active_students = (
            db.session.query(func.count(func.distinct(
                CourseEnrollment.student_id))).scalar()
            or 0
        )
    except Exception:
        # Fallback: students not banned/suspended
        active_students = (
            Student.query
            .filter(~Student.is_suspended, ~Student.is_banned)
            .count()
        )

    # --- Attempts in last 24h ---
    attempts_24h = (
        AssessmentAttempt.query
        .filter(
            or_(
                AssessmentAttempt.created_at >= one_day_ago,
                AssessmentAttempt.finished_at >= one_day_ago
            )
        )
        .count()
    )

    # --- Pass rate (7d) ---
    total_7d = (
        AssessmentAttempt.query
        .filter(
            or_(
                AssessmentAttempt.created_at >= seven_days_ago,
                AssessmentAttempt.finished_at >= seven_days_ago
            )
        )
        .count()
    )
    passed_7d = (
        AssessmentAttempt.query
        .filter(
            AssessmentAttempt.passed.is_(True),
            or_(
                AssessmentAttempt.created_at >= seven_days_ago,
                AssessmentAttempt.finished_at >= seven_days_ago
            )
        )
        .count()
    )
    pass_rate_7d = round((passed_7d / total_7d) * 100, 1) if total_7d else 0.0

    # --- Open support tickets ---
    # Accepts 'Open' or any case variant
    open_tickets = (
        SupportTicket.query
        .filter(SupportTicket.status.ilike("open"))
        .count()
    )

    return dict(
        kpi_active_students=active_students,
        kpi_attempts_24h=attempts_24h,
        kpi_pass_rate_7d=pass_rate_7d,
        kpi_open_tickets=open_tickets,
    )

