# 1) Put this helper somewhere (e.g., near other helpers)
def _resolve_take_endpoint_for_course(course):
    key = (getattr(course, "final_assessment_key", None)
           or course.code or "").strip().lower().replace(" ", "_")
    take_ep = None
    try:
        for it in (load_assessments_cfg() or []):
            if it.get("key") == key:
                take_ep = (it.get("take_endpoint") or f"{key}_take").strip()
                break
    except Exception:
        pass
    if not take_ep:
        special_map = {
            "airside_induction": "airside_induction",
            "airside": "final_assessment_airside",
        }
        take_ep = special_map.get(key, f"{key}_take")
    return take_ep


