# Backward-compatible: accept course_code, course_key, or course_id
# Backward-compatible: accept course_code, course_key, or course_id
# put these imports near your other Flask imports


def _run_final_impl(course_code=None, **kwargs):
    """
    Robust final dispatcher: resolves course by code/id, then
    jumps to the correct endpoint. Tries with course_id first.
    """

    # --- normalize inputs to a course_code or Course object ---
    if course_code is None:
        course_code = kwargs.get("course_key") or kwargs.get("code")

    course = None
    # Resolve from course_id if provided
    if course_code is None and kwargs.get("course_id") is not None:
        c = Course.query.get_or_404(kwargs["course_id"])
        course = c
        for col in ("code", "course_code", "slug", "shortcode"):
            if hasattr(c, col) and getattr(c, col):
                course_code = str(getattr(c, col)).strip()
                break

    # Guard
    if course_code is None and course is None:
        abort(400, "Final assessment course code/key missing")

    # Resolve Course by various identifiers if needed
    if course is None:
        raw = str(course_code).strip()
        # numeric -> treat as ID
        if raw.isdigit():
            course = Course.query.get_or_404(int(raw))
        else:
            # exact matches on typical code columns
            for col in ("code", "course_code", "slug", "shortcode"):
                if hasattr(Course, col):
                    found = Course.query.filter(
                        getattr(Course, col) == raw).first()
                    if found:
                        course = found
                        break
            # last resort: title-ish lookup
            if course is None and hasattr(Course, "title"):
                from sqlalchemy import or_
                cc = raw.replace("_", " ")
                course = Course.query.filter(
                    or_(Course.title == cc, Course.title.ilike(cc))).first()

    if course is None:
        abort(404)

    # --- resolve endpoint name ---
    take_ep = _resolve_take_endpoint_for_course(course) or "final_assessment"

    # Build candidate endpoint names to try
    def exists(ep): return ep in current_app.view_functions
    candidates = [take_ep]
    if take_ep.endswith("_take"):
        key = take_ep[:-5]
        candidates += [f"{key}-take", f"{key}__take", key]

    # Try with course_id first, then without
    tried = []
    for ep in candidates:
        if not exists(ep):
            tried.append((ep, "missing"))
            continue
        # with course_id (common case: /final_assessment/<int:course_id>)
        try:
            tried.append((ep, "with course_id"))
            return redirect(url_for(ep, course_id=course.id))
        except BuildError:
            pass
        # without params (plain /something)
        try:
            tried.append((ep, "no params"))
            return redirect(url_for(ep))
        except BuildError:
            pass
        except Exception:
            pass

    # Log and fall back to generic final_assessment
    try:
        current_app.logger.warning("run_final fallback: take_ep=%r candidates=%r course_id=%r",
                                   take_ep, tried, getattr(course, "id", None))
    except Exception:
        pass

    flash("Final assessment endpoint isn’t registered for this course. Using the standard final.", "warning")
    return redirect(url_for("final_assessment", course_id=course.id))


# overwrite the existing endpoint’s function (your pattern)
app.view_functions['run_final'] = _run_final_impl

