def _course_take_dispatch(course_key):
    # Special-case mapping
    if course_key == "airside_induction":
        return redirect(url_for("airside_induction"))

    # Try common endpoint names you already use
    candidates = [
        f"{course_key}_take",              # e.g. rpas_take
        f"{course_key}_final_assessment",  # e.g. rpas_final_assessment
        course_key,                        # sometimes endpoint == key
    ]

    for ep in candidates:
        if ep in current_app.view_functions:
            return redirect(url_for(ep))

    abort(
        404, description=f"No take endpoint found for '{course_key}'. Tried: {', '.join(candidates)}")


