def utcstamp():
    return utcnow().strftime('%Y-%m-%d %H:%M:%S SAST')


ARCHIVE_FILE = os.path.join(os.path.dirname(__file__), 'finals_archived.json')


def load_archived_keys():
    try:
        with open(ARCHIVE_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
            return set(data.get('archived', []))
    except Exception:
        return set()


def save_archived_keys(keys_set):
    data = {'archived': sorted(list(keys_set))}
    with open(ARCHIVE_FILE, 'w') as f:
        json.dump(data, f, indent=2)


def fa_artifacts(course_key):
    """Return dict of files generated for this final assessment; tweak patterns to your project."""
    root = os.path.dirname(__file__)
    qfile = os.path.join(root, 'static', 'questions', 'mcq',
                         f'{course_key}_final_questions.json')

    tmpl_patterns = [
        os.path.join(root, 'templates', f'final_assessment_{course_key}.html'),
        os.path.join(root, 'templates',
                     f'assessment_submitted_{course_key}.html'),
        os.path.join(root, 'templates', f'admin_{course_key}_attempts.html'),
        os.path.join(root, 'templates', f'{course_key}_results.html'),
        os.path.join(root, 'templates', '**',
                     f'*{course_key}*.html'),  # catch-alls
    ]

    found = []
    if os.path.isfile(qfile):
        found.append(qfile)
    for pat in tmpl_patterns:
        for p in glob.glob(pat, recursive=True):
            if os.path.isfile(p) and p not in found:
                found.append(p)

    return {'all_files': found}


def make_backup_zip(files, prefix):
    buf = io.BytesIO()
    ts = utcnow().strftime('%Y%m%d_%H%M%S')
    with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as zf:
        zf.writestr(
            'README.txt', f'Backup created at {utcstamp()} for {prefix}\n')
        for path in files:
            if os.path.isfile(path):
                arcname = f'files/{os.path.relpath(path, os.path.dirname(__file__))}'
                zf.write(path, arcname)
    buf.seek(0)
    # also save a copy to disk
    backdir = os.path.join(os.path.dirname(__file__), 'backups')
    os.makedirs(backdir, exist_ok=True)
    outpath = os.path.join(backdir, f'{secure_filename(prefix)}_{ts}.zip')
    with open(outpath, 'wb') as f:
        f.write(buf.getvalue())
    return buf, outpath


def safe_remove(path):
    try:
        if os.path.isfile(path):
            os.remove(path)
            return True
    except Exception as _:
        pass
    return False
