@app.route("/unit_quiz/placement/<int:course_id>", methods=["POST"])
def save_unit_quiz_placement(course_id):
    if 'admin_id' not in session:
        return {"ok": False, "error": "unauthorized"}, 403

    course = Course.query.get_or_404(course_id)
    code = (course.code or f"course_{course.id}").lower().replace(" ", "_")
    placement_path = os.path.join(UNIT_QUIZ_DIR, f"{code}_placement.json")

    data = request.get_json(silent=True) or {}
    mapping = data.get("mapping", [])
    # mapping is a list like: [{"after_chapter_id": 12, "question_id": 1}, ...]
    try:
        with open(placement_path, "w", encoding="utf-8") as f:
            json.dump(mapping, f, ensure_ascii=False, indent=2)
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "error": str(e)}, 500

