MAX_ATTEMPTS = 1


def get_logged_in_student():
    # Adjust to your session keys
    return {
        "id": session.get("student_id_int") or session.get("student_pk") or session.get("student_id"),
        "number": session.get("student_number") or session.get("student_id"),
        "full_name": session.get("full_name", "Student"),
        "email": session.get("email", ""),
    }


def load_questions_from_json(path):
    import os
    import json
    full = os.path.join(app.root_path, path)
    with open(full, "r", encoding="utf-8") as f:
        return json.load(f)

