@app.route("/courses/<course_key>/take", methods=["GET"])
def course_take(course_key):
    if course_key not in COURSES:
        abort(404)
    if "student_id" not in session:
        flash("Please log in first.", "warning")
        return redirect(url_for("login"))

    stu = get_logged_in_student()

    # Get student object to check granted attempts
    student_obj = Student.query.filter_by(student_id=stu.get("student_id") or stu.get("number")).first()
    
    # Resolve course_id from course_key
    course_id = _resolve_course_id_from_key(course_key)

    # CAA minimum wait (v1.2), before attempts are calculated or the paper shown.
    if student_obj and course_id:
        _blocked = _enforce_final_wait(student_obj.id, course_id)
        if _blocked:
            return _blocked

    # Get granted attempts cap
    if student_obj and course_id:
        max_attempts = _allowed_cap(student_obj.id, course_id)
    else:
        max_attempts = MAX_ATTEMPTS  # Fallback
    
    # attempts used
    used = (FinalAssessmentAttempt.query
            .filter_by(student_number=stu["number"], course_key=course_key,
                       is_active=True)
            .count())
    attempts_left = max(0, max_attempts - used)
    if attempts_left <= 0:
        flash("You have no attempts remaining for this final.", "warning")
        return render_template(
            "assessment_result.html",
            title=COURSES[course_key]["title"],
            course_code=course_key,
            pass_mark=COURSES[course_key]["pass_mark"],
            pct=0,
            passed=False,
            attempt_no=used,
            correct=0,
            total=0,
            attempts_left=0,
            current_attempt=used,    # For new scoring logic
            can_retake=0,
            retake_url=None,
            attempt_id=None,
            message="No attempts remaining.",
        )

    # Load questions + render generic assessment page
    cfg = COURSES[course_key]
    questions = load_questions_from_json(cfg["questions_path"])
    return render_template(
        "final_assessment.html",
        title=cfg["title"],
        course_key=course_key,
        questions=questions,
        pass_mark=cfg["pass_mark"],
        # identity:
        student_name=stu["full_name"],
        student_id=stu["number"],
        student_email=stu["email"],
        student_number=stu["number"],
        submit_url=url_for("course_submit", course_key=course_key),
    )


