@app.route("/courses/<course_key>/submit", methods=["POST"])
def course_submit(course_key):
    if course_key not in COURSES:
        abort(404)
    if "student_id" not in session:
        flash("Please log in first.", "warning")
        return redirect(url_for("login"))

    cfg = COURSES[course_key]
    stu = get_logged_in_student()

    # --- read payload from form (adapt if your JS uses different keys) ---
    total_q = int(request.form.get("total_q", 0))
    correct = int(request.form.get("correct", 0))
    # optional override if client calculates
    pct_override = request.form.get("pct")
    # raw JSON string (store as-is)
    answers_json = request.form.get("answers_json")
    video_filename = request.form.get("video_filename")  # optional

    if pct_override:
        try:
            pct = int(round(float(pct_override)))
        except ValueError:
            pct = int(round((correct / total_q) * 100)) if total_q else 0
    else:
        pct = int(round((correct / total_q) * 100)) if total_q else 0

    passed = pct >= int(cfg["pass_mark"])

    # --- attempt sequence ---
    prior_tries = (FinalAssessmentAttempt.query
                   .filter_by(student_number=stu["number"],
                              course_key=course_key, is_active=True)
                   .count())
    attempt_no = prior_tries + 1
    if attempt_no > MAX_ATTEMPTS:
        flash("No attempts remaining.", "warning")
        return redirect(url_for("course_take", course_key=course_key))

    # --- save attempt exactly per your model ---
    faa = FinalAssessmentAttempt(
        student_id=stu["id"],                 # FK to Student.id (internal PK)
        student_number=stu["number"],         # external ID/folder
        course_key=course_key,                # e.g., "airside", "rpas", etc.
        course_id=None,                       # set if you map numeric course ids
        attempt_no=attempt_no,                # 1..3
        submitted_at=_now_sast(),       # matches your column
        total_questions=total_q,
        correct_count=correct,
        percentage=pct,                       # Integer 0..100 (rounded)
        passed=passed,
        video_filename=video_filename or None,
        answers_json=answers_json or None,
        review_status="Pending",              # default moderation state
    )
    db.session.add(faa)
    db.session.commit()

    # --- notify (optional) ---
    try:
        send_course_admin_email(cfg["title"], stu["full_name"], stu["number"],
                                stu["email"], pct, passed, faa.id)
    except Exception as e:
        app.logger.warning(f"Admin email failed: {e}")

    # --- Certificate email + enqueue are now deferred until feedback is submitted ---

    # --- retake logic ---
    used = prior_tries + 1
    attempts_left = max(0, MAX_ATTEMPTS - used)
    can_retake = (not passed) and (attempts_left > 0)

    # Check if feedback already submitted for THIS passing attempt (not an
    # older submission for the same course_key from a prior fail/retake).
    feedback_already_submitted = CourseFeedback.query.filter(
        CourseFeedback.student_id == stu["id"],
        CourseFeedback.course_key == course_key,
        CourseFeedback.created_at >= faa.submitted_at
    ).first() is not None

    return render_template(
        "assessment_result.html",
        title=cfg["title"],
        course_code=course_key,
        pass_mark=cfg["pass_mark"],
        pct=pct,
        passed=passed,
        attempt_no=attempt_no,
        correct=correct,
        total=total_q,
        attempts_left=attempts_left,
        current_attempt=attempt_no,    # For new scoring logic
        can_retake=1 if can_retake else 0,
        retake_url=url_for(
            "course_take", course_key=course_key) if can_retake else None,
        attempt_id=faa.id,
        feedback_already_submitted=feedback_already_submitted,
    )
