@app.route("/admin/attempts/student/<student_number>", methods=["GET"])
@require_admin
def admin_attempts_for_student(student_number):
    course_key = request.args.get("course")

    # FinalAssessmentAttempt
    fa_q = FinalAssessmentAttempt.query.filter_by(
        student_number=student_number)
    if course_key:
        fa_q = fa_q.filter_by(course_key=course_key)
    fa_rows = fa_q.order_by(desc(FinalAssessmentAttempt.submitted_at)).all()

    # AssessmentAttempt
    assess_q = AssessmentAttempt.query.filter_by(student_number=student_number)
    if course_key:
        assess_q = assess_q.filter_by(course_key=course_key)
    assess_rows = assess_q.order_by(desc(AssessmentAttempt.finished_at)).all()

    # try to display name
    student_name = None
    try:
        s = Student.query.filter_by(student_id=student_number).first()
        if s:
            student_name = f"{getattr(s, 'name', '') or getattr(s, 'first_name', '')} {getattr(s, 'surname', '') or getattr(s, 'last_name', '')}".strip(
            ) or None
    except Exception:
        pass

    # normalize to a single list (you can reuse the mapping logic above if you want)
    def _map_fa(a):
        percentage = float(getattr(a, "percentage", 0.0) or 0.0)
        return {
            "id": a.id,
            "course_key": a.course_key,
            "submitted_at": a.submitted_at,
            "percentage": percentage,
            "passed": (percentage >= float(getattr(a, "pass_mark", 80))),
            "result_url": None,
        }

    def _map_assess(a):
        pct = float(a.score or 0.0)
        try:
            detailed = json.loads(
                a.answers_json or "[]") if a.answers_json else []
            total = len(detailed) or 1
        except Exception:
            total = 1
        try:
            result_url = url_for(f"{a.course_key}_result", attempt_id=a.id)
        except Exception:
            result_url = None
        return {
            "id": a.id,
            "course_key": a.course_key,
            "submitted_at": a.finished_at or a.started_at,
            "percentage": pct,
            "passed": bool(a.passed),
            "result_url": result_url,
        }

    merged = [_map_fa(x) for x in fa_rows] + [_map_assess(x)
                                              for x in assess_rows]
    merged.sort(key=lambda r: (r["submitted_at"]
                or datetime.min), reverse=True)

    return render_template(
        "admin_attempts_student.html",
        student_number=student_number,
        student_name=student_name,
        attempts=merged,
        course_key=course_key
    )

