def evaluate_final(course_key: str, submitted: dict):
    """
    Evaluate a student's answers for a given course_key.
    - submitted is dict {question_id: student_answer}
    - Returns (correct_count, total_questions, percentage, passed)
    """
    try:
        questions = load_questions(course_key)
    except Exception as e:
        print(
            f"[evaluate_final] Failed to load questions for {course_key}: {e}")
        return (0, 0, 0, False)

    correct = 0
    total = len(questions)

    for q in questions:
        qid = str(q["id"])
        correct_answer = str(q.get("answer", "")).strip()
        student_answer = str(submitted.get(qid, "")).strip()

        # MCQ (case-insensitive compare, A/B/C)
        if q.get("options") and student_answer.upper() == correct_answer.upper():
            correct += 1

        # Free text (simple lowercase compare)
        elif not q.get("options") and student_answer.lower() == correct_answer.lower():
            correct += 1

    pct = round((correct / total) * 100) if total > 0 else 0
    passed = pct >= 80  # Pass mark is 80%
    return (correct, total, pct, passed)


def record_final_attempt(*, student, course_key, course_id, score, total, passed, video_relpath, answers_dict):
    """
    Create an auditable attempt row in final_assessment_attempts.
    Returns (attempt_id, attempt_no).
    """
    # Normalize/defensive
    course_key = str(course_key or "").strip()
    student_number = str(student.student_id)
    total = int(total or 0)
    score = int(score or 0)
    percentage = int(round((score / total) * 100)) if total else 0
    video_relpath = (video_relpath or "").replace("\\", "/")

    try:
        # --- Optional duplicate guard: same video within last 2 minutes
        two_minutes_ago = _now_sast() - timedelta(minutes=2)
        dupe = (FinalAssessmentAttempt.query
                .filter(
                    FinalAssessmentAttempt.student_number == student_number,
                    FinalAssessmentAttempt.course_key == course_key,
                    FinalAssessmentAttempt.video_filename == video_relpath,
                    FinalAssessmentAttempt.submitted_at >= two_minutes_ago,
                )
                .order_by(desc(FinalAssessmentAttempt.id))
                .first())
        if dupe:
            return dupe.id, dupe.attempt_no

        # --- Next attempt number (use SELECT MAX to avoid off-by-one with stale rows)
        last = (FinalAssessmentAttempt.query
                .with_entities(FinalAssessmentAttempt.attempt_no)
                .filter_by(student_number=student_number,
                           course_key=course_key, is_active=True)
                .order_by(desc(FinalAssessmentAttempt.attempt_no))
                .first())
        attempt_no = (last[0] if last else 0) + 1

        row = FinalAssessmentAttempt(
            student_id=student.id,
            student_number=student_number,
            course_key=course_key,
            course_id=course_id,
            attempt_no=attempt_no,
            total_questions=total,
            correct_count=score,
            percentage=percentage,
            passed=bool(passed),
            video_filename=video_relpath or None,
            answers_json=json.dumps(answers_dict or {}),
            review_status="Pending",
            submitted_at=_now_sast(),
        )

        db.session.add(row)
        db.session.flush()   # get row.id without committing yet
        attempt_id = row.id

        db.session.commit()
        return attempt_id, attempt_no

    except Exception as e:
        db.session.rollback()
        print(f"[record_final_attempt] ERROR: {e}")
        # Re-raise or return a sentinel; raising helps you catch issues during dev
        raise

