@app.route("/admin/popia-content", methods=["GET", "POST"])
def edit_popia_content():
    # 🔒 Admin-only check
    if 'admin_id' not in session or get_role_level(session.get('admin_role', '')) < 2:
        flash("⚠ Unauthorized Access! Please log in as an admin.", "danger")
        return redirect(url_for('admin_login'))

    content_path = app.config.get(
        "POPIA_CONTENT_PATH", "/var/enroll/popia_content.html")
    backup_dir = app.config.get("POPIA_BACKUP_DIR", "/var/enroll/backups")
    os.makedirs(backup_dir, exist_ok=True)

    if request.method == "POST":
        new_content = request.form.get("content", "")
        new_version = request.form.get("version", "").strip()

        # Backup current file
        if os.path.exists(content_path):
            ts = datetime.now().strftime("%Y%m%d-%H%M%S")
            backup_path = os.path.join(backup_dir, f"popia_content.{ts}.html")
            try:
                with open(content_path, "r", encoding="utf-8") as src, \
                        open(backup_path,  "w", encoding="utf-8") as dst:
                    dst.write(src.read())
            except Exception as e:
                flash(f"⚠ Backup failed: {e}", "danger")

        # Save new file
        tmp_path = content_path + ".tmp"
        with open(tmp_path, "w", encoding="utf-8") as f:
            f.write(new_content)
        os.replace(tmp_path, content_path)

        if new_version:
            app.config["POPIA_VERSION"] = new_version  # non-persistent bump

        flash("✅ POPIA content saved" +
              (f" • version set to {new_version}" if new_version else ""), "success")
        return redirect(url_for("edit_popia_content"))

    # GET: load existing content
    try:
        with open(content_path, "r", encoding="utf-8") as f:
            current = f.read()
    except Exception:
        current = "<h3>(No POPIA content yet)</h3>"

    return render_template(
        "admin_popia_editor.html",
        content=current,
        version=app.config.get("POPIA_VERSION", "1")
    )

