ALLOWED_ORIGINS = {"https://lms.proftrain.co.za"}


def _preflight_response():
    resp = make_response("", 204)
    origin = request.headers.get("Origin")
    if origin in ALLOWED_ORIGINS:
        resp.headers["Access-Control-Allow-Origin"] = origin
    resp.headers["Vary"] = "Origin"
    resp.headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS"
    resp.headers["Access-Control-Allow-Headers"] = "Content-Type, X-Requested-With"
    resp.headers["Access-Control-Max-Age"] = "600"
    return resp


def _corsify(resp):
    origin = request.headers.get("Origin")
    if origin in ALLOWED_ORIGINS:
        resp.headers["Access-Control-Allow-Origin"] = origin
        resp.headers["Vary"] = "Origin"
    return resp


@app.route("/moodle_videos", methods=["GET", "POST", "OPTIONS"])
def moodle_videos():
    if request.method == "OPTIONS":
        return _preflight_response()
    # Return empty payload or a safe default
    data = {"ok": True, "videos": []}
    return _corsify(jsonify(data))
