@app.route("/company/register", methods=["GET", "POST"])
def company_register():
    if request.method == "POST":
        name = (request.form.get("company_name") or "").strip()
        email = (request.form.get("email") or "").strip().lower()
        contact_email = (request.form.get("contact_email") or "").strip().lower() or email
        pwd = (request.form.get("password") or "").strip()
        full_name = (request.form.get("full_name") or "").strip()
        contact_name = (request.form.get("contact_name") or "").strip()

        vat_number = (request.form.get("vat_number") or "").strip()
        street_address = (request.form.get("street_address") or "").strip()
        contact_phone = (request.form.get("contact_phone") or "").strip()
        cellphone = (request.form.get("cellphone") or "").strip()

        if not name or not email or not pwd or not contact_name:
            flash("Company name, contact name, email and password are required.", "danger")
            return render_template("company/register.html")
        if not vat_number:
            flash("VAT number is required.", "danger")
            return render_template("company/register.html")
        if not street_address:
            flash("Street address is required.", "danger")
            return render_template("company/register.html")
        if not contact_phone and not cellphone:
            flash("At least one phone number (telephone or cellphone) is required.", "danger")
            return render_template("company/register.html")

        # Check for existing company user with same email
        if CompanyUser.query.filter(db.func.lower(CompanyUser.email) == email).first():
            flash("An account with this email already exists. Please log in.", "danger")
            return render_template("company/register.html")

        # Create company + owner user
        c = Company(
            name=name,
            reg_no=(request.form.get("reg_no") or "").strip(),
            industry=(request.form.get("industry") or "").strip(),
            postal_address=(request.form.get("postal_address") or "").strip(),
            postal_code=(request.form.get("postal_code") or "").strip(),
            street_address=(request.form.get("street_address") or "").strip(),
            street_postal_code=(request.form.get("street_postal_code") or "").strip(),
            vat_number=(request.form.get("vat_number") or "").strip(),
            purchase_order_number=(request.form.get("purchase_order_number") or "").strip(),
            purchase_order_attached=(request.form.get("purchase_order_attached") == "yes"),
            entity_responsible=(request.form.get("entity_responsible") or "").strip(),
            contact_name=contact_name,
            contact_email=contact_email,
            contact_phone=(request.form.get("contact_phone") or "").strip(),
            cellphone=(request.form.get("cellphone") or "").strip(),
            approved=False,
        )

        otp_code = str(random.randint(10000000, 99999999))
        u = CompanyUser(
            company=c,
            full_name=full_name or "Company Owner",
            email=email,
            is_owner=True,
            otp=otp_code,
        )
        u.set_password(pwd)
        db.session.add_all([c, u])
        db.session.commit()

        # Send OTP email
        send_email(email, "Your OTP for Company Registration",
                   f"""<h2 style="color:#17306B; margin:0 0 16px;">Verify Your Email</h2>
                   <p>Hi {full_name or 'there'},</p>
                   <p>Your one-time PIN for <strong>{name}</strong> registration is:</p>
                   <div style="text-align:center; margin:24px 0;">
                     <span style="font-size:32px; font-weight:700; letter-spacing:6px; color:#17306B;">{otp_code}</span>
                   </div>
                   <p style="color:#64748b; font-size:13px;">This PIN is valid for your registration session.</p>""")

        session["pending_company_user"] = email
        flash("OTP sent! Please verify your email.", "info")
        return redirect(url_for("company_verify_otp"))

    return render_template("company/register.html")

