@app.route("/company/forgot-password", methods=["GET", "POST"])
def company_forgot_password():
    """Self-service password reset for company portal users (v1.1.2).

    POST takes an email, generates a one-shot token (60-minute TTL), emails
    a reset link, and ALWAYS shows the same generic success message regardless
    of whether the email is registered. The uniform response prevents using
    this endpoint to enumerate which emails have company portal accounts.
    """
    if request.method == "POST":
        email = (request.form.get("email") or "").strip().lower()
        if email:
            u = CompanyUser.query.filter_by(email=email, active=True).first()
            if u:
                token = secrets.token_urlsafe(32)
                u.password_reset_token = token
                u.password_reset_token_expires = _now_sast() + timedelta(minutes=60)
                db.session.commit()
                try:
                    reset_url = url_for("company_reset_password", token=token, _external=True)
                    send_email(
                        u.email,
                        "Reset your Company Portal password",
                        f"""<h2 style="color:#17306B; margin:0 0 16px;">Password reset</h2>
                        <p>Hi {u.full_name},</p>
                        <p>We received a request to reset your password for the Professional Training Company Portal.</p>
                        <p>Click the button below to choose a new password. This link is valid for 60 minutes.</p>
                        <div style="text-align:center; margin:24px 0;">
                          <a href="{reset_url}" style="display:inline-block; background:#17306B; color:#fff; padding:12px 32px; border-radius:8px; text-decoration:none; font-weight:600;">Reset Password</a>
                        </div>
                        <p style="font-size:13px; color:#64748b;">If you did not ask for this, you can safely ignore the email. Your password will not change.</p>"""
                    )
                except Exception as e:
                    # Don't expose mail failures to the user; we already
                    # committed the token and the user can try again.
                    app.logger.warning(f"company_forgot_password send_email failed: {e}")
        # Always render the same neutral message, regardless of whether the
        # email matched a real account.
        return render_template("company/forgot_password.html", sent=True)
    return render_template("company/forgot_password.html", sent=False)


@app.route("/company/reset-password/<token>", methods=["GET", "POST"])
def company_reset_password(token):
    """Consumes a `password_reset_token` and sets a new password.

    GET: show the new-password form if the token is valid and unexpired.
    POST: validate token + minimum length, hash, clear the token, redirect.
    """
    u = CompanyUser.query.filter_by(password_reset_token=token, active=True).first()
    expired = (
        u is None or
        u.password_reset_token_expires is None or
        u.password_reset_token_expires < _now_sast()
    )

    if request.method == "POST":
        if expired:
            flash("This reset link has expired. Please request a new one.", "danger")
            return redirect(url_for("company_forgot_password"))
        new_pwd = (request.form.get("password") or "").strip()
        confirm = (request.form.get("confirm") or "").strip()
        if len(new_pwd) < 8:
            flash("Password must be at least 8 characters.", "warning")
            return render_template("company/reset_password.html", token=token, expired=False)
        if new_pwd != confirm:
            flash("Passwords do not match.", "warning")
            return render_template("company/reset_password.html", token=token, expired=False)
        u.password_hash = generate_password_hash(new_pwd, method="pbkdf2:sha256")
        u.password_reset_token = None
        u.password_reset_token_expires = None
        db.session.commit()
        flash("Password updated. Please log in with your new password.", "success")
        return redirect(url_for("company_login"))

    return render_template("company/reset_password.html", token=token, expired=expired)


