@app.route("/company/popia", methods=["GET", "POST"])
def company_popia():
    if not session.get("company_user_id"):
        flash("Please log in first.", "warning")
        return redirect(url_for("company_login"))
    cu = db.session.get(CompanyUser, session["company_user_id"])
    if not cu:
        flash("Account not found.", "danger")
        return redirect(url_for("company_login"))

    version = current_app.config.get("POPIA_VERSION", "1")
    existing = CompanyPopiaConsent.query.filter_by(
        company_user_id=cu.id, version=version).first()
    if existing:
        company = db.session.get(Company, cu.company_id)
        if company and not company.approved:
            return redirect(url_for("company_pending"))
        return redirect(url_for("company_dashboard"))

    if request.method == "POST":
        if request.form.get("accept") != "on":
            flash("Please tick the checkbox to accept.", "danger")
            return redirect(url_for("company_popia"))
        consent = CompanyPopiaConsent(
            company_user_id=cu.id,
            version=version,
            ip_address=_client_ip(),
            user_agent=(request.headers.get("User-Agent") or "")[:2000],
        )
        db.session.add(consent)
        try:
            db.session.commit()
        except Exception:
            db.session.rollback()
            flash("Could not record POPIA acceptance.", "danger")
            return redirect(url_for("company_popia"))
        flash("POPIA acceptance recorded.", "success")
        company = db.session.get(Company, cu.company_id)
        if company and not company.approved:
            return redirect(url_for("company_pending"))
        return redirect(url_for("company_dashboard"))

    # Load POPIA content
    popia_path = os.path.join(app.root_path, "popia_content.html")
    popia_html = ""
    if os.path.exists(popia_path):
        with open(popia_path, "r", encoding="utf-8") as f:
            popia_html = f.read()
    return render_template("company/popia.html", version=version, popia_html=popia_html)

