@app.route("/company/dashboard")
@require_company
def company_dashboard():
    cid = session["company_id"]
    company = db.session.get(Company, cid)
    cu = db.session.get(CompanyUser, session["company_user_id"])
    is_main_admin = cu and cu.branch_id is None

    # Scope students: main admin sees all, branch admin sees only their branch
    if is_main_admin:
        students = Student.query.filter_by(created_by_company_id=cid).order_by(Student.date_joined.desc()).all()
    else:
        students = Student.query.filter_by(created_by_company_id=cid, branch_id=cu.branch_id).order_by(Student.date_joined.desc()).all()

    # Build progress map
    progress_map = {}
    now = _now_sast()
    for s in students:
        for enr in s.enrollments:
            prog = _build_enrollment_progress(s, enr, now)
            if prog:
                progress_map[enr.id] = prog

    # Per-student renewal-urgency sort (v1.1.2). Lower tier = more urgent;
    # students with the soonest expiry float to the top and "two years out"
    # certs sink to the bottom, matching Chantell's brief:
    #     0 = expired (already overdue)
    #     1 = critical (<= 30 days)
    #     2 = flag    (31-90 days)     <-- the highlight band
    #     3 = soon    (91-365 days)
    #     4 = healthy (1+ years out)
    #     5 = no certificate on record
    def _student_urgency(stu):
        soonest = None
        for enr in stu.enrollments:
            prog = progress_map.get(enr.id)
            if not prog:
                continue
            ce = prog.get('cert_expiry')
            if ce is None:
                continue
            if soonest is None or ce < soonest:
                soonest = ce
        if soonest is None:
            return (5, 0, stu.date_joined or now)
        days = (soonest - now).days
        if days < 0:
            tier = 0
        elif days <= 30:
            tier = 1
        elif days <= 90:
            tier = 2
        elif days <= 365:
            tier = 3
        else:
            tier = 4
        # Within a tier, the closer expiry shows higher. date_joined breaks
        # final ties so the order is stable.
        return (tier, days, stu.date_joined or now)

    students = sorted(students, key=_student_urgency)

    # Branches (only for main admin)
    branches = CompanyBranch.query.filter_by(company_id=cid).order_by(CompanyBranch.name.asc()).all() if is_main_admin else []
    branch_map = {b.id: b for b in branches}
    # Branch admins for each branch
    branch_admins = {}
    if is_main_admin:
        for b in branches:
            branch_admins[b.id] = CompanyUser.query.filter_by(company_id=cid, branch_id=b.id, active=True).all()
    # Student counts per branch
    branch_student_counts = {}
    if is_main_admin:
        for b in branches:
            branch_student_counts[b.id] = Student.query.filter_by(created_by_company_id=cid, branch_id=b.id).count()
        branch_student_counts[0] = Student.query.filter_by(created_by_company_id=cid, branch_id=None).count()

    current_branch = None
    if cu and cu.branch_id:
        current_branch = db.session.get(CompanyBranch, cu.branch_id)

    # Approved courses for settings
    all_courses = Course.query.order_by(Course.title).all()
    approved_course_ids = {c.id for c in company.approved_courses}

    return render_template("company/dashboard.html",
                           company=company, students=students, progress_map=progress_map,
                           is_main_admin=is_main_admin, branches=branches,
                           branch_admins=branch_admins, branch_student_counts=branch_student_counts,
                           branch_map=branch_map, current_branch=current_branch,
                           all_courses=all_courses, approved_course_ids=approved_course_ids,
                           now=now)

