@app.route("/company/students/create", methods=["POST"])
@require_company
def company_create_student():
    cid = session["company_id"]
    company = db.session.get(Company, cid)
    cu = db.session.get(CompanyUser, session["company_user_id"])

    name = (request.form.get("name") or "").strip()
    surname = (request.form.get("surname") or "").strip()
    email = (request.form.get("email") or "").strip().lower()
    national_id = (request.form.get("national_id") or "").strip()
    cell_number = (request.form.get("cell_number") or "").strip()

    if not name or not surname or not email or not national_id:
        flash("Name, surname, email and national ID are required.", "danger")
        return redirect(url_for("company_dashboard"))

    # Check for existing student by national ID only
    # (email duplicates are expected — company students share the company contact's email)
    existing = Student.query.filter(Student.national_id == national_id).first()
    if existing:
        flash(f"A student with this ID number already exists (Student ID: {existing.student_id}).", "warning")
        return redirect(url_for("company_dashboard"))

    # Determine branch: branch admin auto-assigns their branch; main admin can pick from form
    if cu and cu.branch_id:
        student_branch_id = cu.branch_id
    else:
        raw = request.form.get("branch_id") or ""
        student_branch_id = int(raw) if raw.isdigit() else None

    # Generate student
    student_id = str(random.randint(10_000_000, 99_999_999))
    temp_password = ''.join(random.choices(string.ascii_letters + string.digits, k=12))
    token = secrets.token_urlsafe(32)

    student = Student(
        student_id=student_id,
        name=name,
        surname=surname,
        email=email,
        national_id=national_id,
        cell_number=cell_number,
        password=generate_password_hash(temp_password, method="pbkdf2:sha256"),
        password_setup_token=token,
        password_setup_token_expires=_now_sast() + timedelta(days=30),
        created_by_company_id=cid,
        branch_id=student_branch_id,
    )
    db.session.add(student)

    # Also create CompanyEmployee link
    emp = CompanyEmployee(
        company_id=cid,
        full_name=f"{name} {surname}",
        email=email,
        national_id=national_id,
        phone=cell_number,
    )
    db.session.add(emp)
    db.session.flush()
    emp.student_id = student.id
    db.session.commit()

    # Send email with password setup link
    setup_url = url_for("setup_password", token=token, _external=True)
    send_email(email, "Welcome to Professional Training!",
               f"""<h2 style="color:#17306B; margin:0 0 16px;">Welcome, {name}!</h2>
               <p>You have been registered for training by <strong>{company.name}</strong>.</p>
               <p>Please click the button below to set your password and get started:</p>
               <div style="text-align:center; margin:24px 0;">
                 <a href="{setup_url}" style="display:inline-block; background:#17306B; color:#fff; padding:12px 32px; border-radius:8px; text-decoration:none; font-weight:600;">Set Your Password</a>
               </div>
               <p style="font-size:13px; color:#64748b;">This link expires in 30 days. If it expires, contact your company administrator.</p>
               <p style="font-size:13px; color:#64748b;">Your Student ID is: <strong>{student_id}</strong></p>
               <p style="font-size:13px; color:#64748b;">Temporary password (if needed): <strong>{temp_password}</strong></p>""")

    flash(f"Student {name} {surname} created. An invite email has been sent to {email}.", "success")
    return redirect(url_for("company_dashboard"))

