@app.route("/company/edit_student/<int:student_id>", methods=["POST"])
@require_company
def company_edit_student(student_id):
    """Company portal: edit a student's basic profile (name, surname, email,
    cell) and optionally regenerate + resend the password setup invite to the
    edited email address. Mirrors the admin-side flow on /update_student.

    Security: the student MUST belong to this company. Branch admins can only
    edit students in their own branch.
    """
    cid = session["company_id"]
    company = db.session.get(Company, cid)
    cu = db.session.get(CompanyUser, session.get("company_user_id"))

    student = Student.query.filter_by(id=student_id, created_by_company_id=cid).first()
    if not student:
        flash("Student not found.", "danger")
        return redirect(url_for("company_dashboard"))

    # Branch admins can only touch their own branch's students.
    if cu and cu.branch_id is not None and student.branch_id != cu.branch_id:
        flash("You can only edit students in your own branch.", "danger")
        return redirect(url_for("company_dashboard"))

    # Apply the text edits. Only overwrite when the form key is present so the
    # company admin can clear cell_number with an empty input without wiping
    # the rest of the row.
    if "name" in request.form:
        student.name = (request.form.get("name") or student.name).strip()
    if "surname" in request.form:
        student.surname = (request.form.get("surname") or student.surname).strip()
    if "email" in request.form:
        new_email = (request.form.get("email") or "").strip()
        if new_email:
            student.email = new_email
    if "cell_number" in request.form:
        student.cell_number = (request.form.get("cell_number") or "").strip() or None

    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        flash(f"Could not save changes: {e}", "danger")
        return redirect(url_for("company_dashboard"))

    flash(f"✅ {student.name} {student.surname} updated.", "success")

    # Optional: regenerate the setup token and email the freshly-updated
    # address. Use this when the company admin needs to correct a typo and
    # redirect the link to the right inbox in one action.
    if request.form.get("resend_invite") == "1":
        if not student.email:
            flash("⚠ Cannot resend invite: no email address on file.", "warning")
        else:
            try:
                token = secrets.token_urlsafe(32)
                temp_password = ''.join(random.choices(string.ascii_letters + string.digits, k=12))
                student.password_setup_token = token
                student.password_setup_token_expires = _now_sast() + timedelta(days=30)
                student.password = generate_password_hash(temp_password, method="pbkdf2:sha256")
                db.session.commit()

                setup_url = url_for("setup_password", token=token, _external=True)
                send_email(
                    student.email,
                    f"Welcome to Professional Training — {student.name} {student.surname}!",
                    f"""<h2 style=\"color:#17306B; margin:0 0 16px;\">Welcome, {student.name}!</h2>
                    <p>You have been registered for training by <strong>{company.name}</strong>.</p>
                    <p>Please click the button below to set your password and get started:</p>
                    <div style=\"text-align:center; margin:24px 0;\">
                      <a href=\"{setup_url}\" style=\"display:inline-block; background:#17306B; color:#fff; padding:12px 32px; border-radius:8px; text-decoration:none; font-weight:600;\">Set Your Password</a>
                    </div>
                    <p style=\"font-size:13px; color:#64748b;\">This link expires in 30 days. If it expires, contact your company administrator.</p>
                    <p style=\"font-size:13px; color:#64748b;\">Your Student ID is: <strong>{student.student_id}</strong></p>
                    <p style=\"font-size:13px; color:#64748b;\">Temporary password (if needed): <strong>{temp_password}</strong></p>"""
                )
                flash(f"📧 Invite resent to {student.email}.", "success")
            except Exception as e:
                db.session.rollback()
                flash(f"⚠ Could not send invite email: {e}", "warning")

    return redirect(url_for("company_dashboard"))


