@app.route("/company/employees/<int:emp_id>/upload", methods=["POST"])
@require_company
def company_employee_upload(emp_id):
    cid = session["company_id"]
    emp = CompanyEmployee.query.filter_by(
        id=emp_id, company_id=cid).first_or_404()
    f = request.files.get("file")
    doc_type = (request.form.get("doc_type") or "other").strip().lower()
    if not f or f.filename == "":
        flash("Please choose a file.", "warning")
        return redirect(url_for("company_dashboard"))
    if not _allowed_file(f.filename):
        flash("Unsupported file type.", "danger")
        return redirect(url_for("company_dashboard"))

    safe = secure_filename(f.filename)
    company_dir = os.path.join(
        app.config["COMPANY_UPLOAD_FOLDER"], f"company_{cid}", f"emp_{emp_id}")
    os.makedirs(company_dir, exist_ok=True)
    path = os.path.join(company_dir, safe)
    f.save(path)

    doc = EmployeeDocument(employee_id=emp.id, doc_type=doc_type,
                           filename=os.path.relpath(path, app.root_path))
    db.session.add(doc)
    db.session.commit()
    flash("Document uploaded.", "success")
    return redirect(url_for("company_dashboard"))
