# put this once at module level (AFTER Student is defined)
WRITABLE_STUDENT_FIELDS = {c.key for c in Student.__table__.columns}


def _maybe(value, default=""):
    return (value or default)


def _split_full_name(full_name):
    full_name = (full_name or "").strip()
    if not full_name:
        return "", ""
    parts = full_name.split()
    first = parts[0]
    last = " ".join(parts[1:]) if len(parts) > 1 else ""
    return first, last


@app.route("/company/employees/<int:emp_id>/register_student", methods=["POST"])
@require_company
def company_employee_register_student(emp_id):
    from werkzeug.security import generate_password_hash
    cid = session["company_id"]
    emp = CompanyEmployee.query.filter_by(
        id=emp_id, company_id=cid).first_or_404()

    # 1) Try find existing student by email (case-insensitive)
    student = None
    if emp.email:
        student = Student.query.filter(db.func.lower(
            Student.email) == emp.email.lower()).first()

    # 2) (optional) Try match by national_id if both sides have it
    if not student and hasattr(emp, "national_id") and "national_id" in WRITABLE_STUDENT_FIELDS and emp.national_id:
        student = Student.query.filter_by(national_id=emp.national_id).first()

    created = False
    if not student:
        created = True

        # Build candidate payload from employee fields; only keep real columns.
        first_name = last_name = None
        if "first_name" in WRITABLE_STUDENT_FIELDS or "last_name" in WRITABLE_STUDENT_FIELDS:
            # Prefer explicit emp fields if present; otherwise split full_name
            if hasattr(emp, "first_name") or hasattr(emp, "last_name"):
                first_name = getattr(emp, "first_name", None)
                last_name = getattr(emp, "last_name", None)
            else:
                first_name, last_name = _split_full_name(
                    getattr(emp, "full_name", ""))

        candidate = {
            # name fields (only kept if actual columns)
            "first_name": first_name,
            "last_name":  last_name,
            # for schemas using name/surname
            "name":       getattr(emp, "name", None),
            "surname":    getattr(emp, "surname", None),

            # contact
            "email": _maybe(emp.email, f"company{cid}_emp{emp.id}@example.invalid").lower(),
            "phone": getattr(emp, "phone", None),
            # map phone -> cell_number if that’s your column
            "cell_number": getattr(emp, "phone", None),

            # ids
            "national_id": getattr(emp, "national_id", None),
            "company_id": cid if "company_id" in WRITABLE_STUDENT_FIELDS else None,
        }

        # filter to real columns and drop Nones/empty
        clean = {k: v.strip() if isinstance(v, str) else v
                 for k, v in candidate.items()
                 if k in WRITABLE_STUDENT_FIELDS and v not in (None, "")}

        # Instantiate
        student = Student(**clean)

        # Password handling
        raw_password = (request.form.get("password") or "Temp1234!")
        if hasattr(student, "set_password"):
            student.set_password(raw_password)
        elif hasattr(Student, "password"):
            # write-only property with a setter
            student.password = raw_password
        elif "password_hash" in WRITABLE_STUDENT_FIELDS:
            student.password_hash = generate_password_hash(
                raw_password, method="pbkdf2:sha256")
        else:
            # If you have a custom helper:
            try:
                student.password_hash = hash_password(raw_password)  # noqa: F821
            except NameError:
                pass  # no-op if neither exists

        db.session.add(student)
        db.session.flush()  # assign student.id

    # 3) Link employee -> student
    emp.student_id = student.id
    db.session.add(emp)
    db.session.commit()

    flash(("Employee registered as a student and linked." if created
           else "Employee linked to existing student."), "success")
    return redirect(url_for("company_dashboard"))


