@app.route("/company/courses")
@require_company
def company_courses():
    cid = session["company_id"]
    company = db.session.get(Company, cid)
    students = Student.query.filter_by(created_by_company_id=cid).order_by(Student.name).all()
    # Only show courses the company has approved, and never virtual ones —
    # virtual enrollments are admin-only, not company-portal.
    if company.approved_courses:
        approved_ids = [c.id for c in company.approved_courses]
        courses = Course.query.filter(
            Course.id.in_(approved_ids),
            (Course.course_type == 'normal') | (Course.course_type.is_(None)),
        ).order_by(Course.title).all()
    else:
        courses = []

    # Split into two groups for the picker so the admin can tell at a glance
    # who's new (no enrollments yet, "must be enrolled") from who already has
    # at least one course on record. Keeps the underlying form flat.
    students_unenrolled = [s for s in students if not s.enrollments]
    students_enrolled = [s for s in students if s.enrollments]

    return render_template("company/courses.html",
                           students=students,
                           students_unenrolled=students_unenrolled,
                           students_enrolled=students_enrolled,
                           courses=courses)


@app.route("/company/cart")
@require_company
def company_cart():
    cid = session["company_id"]
    raw = session.get("company_cart", [])
    # raw is a list of {"course_id": int, "student_id": int}
    # Group by course
    from collections import OrderedDict
    grouped = OrderedDict()
    for item in raw:
        c_id = item["course_id"]
        s_id = item["student_id"]
        if c_id not in grouped:
            grouped[c_id] = {"course": db.session.get(Course, c_id), "student_ids": []}
        if s_id not in grouped[c_id]["student_ids"]:
            grouped[c_id]["student_ids"].append(s_id)
    lines = []
    for c_id, data in grouped.items():
        if data["course"]:
            students = [db.session.get(Student, sid) for sid in data["student_ids"]]
            students = [s for s in students if s]
            lines.append({"course": data["course"], "students": students})
    company = db.session.get(Company, cid)
    total_credits = sum(len(l["students"]) for l in lines)
    return render_template("company/cart.html", lines=lines,
                           company_credits=company.enrollment_credits or 0,
                           total_credits=total_credits)


@app.route("/company/cart/add", methods=["POST"])
@require_company
def company_cart_add():
    course_id = request.form.get("course_id", type=int)
    student_ids = request.form.getlist("student_ids", type=int)
    if not course_id or not student_ids:
        flash("Please select at least one student.", "warning")
        return redirect(url_for("company_courses"))
    course = db.session.get(Course, course_id)
    if not course or getattr(course, 'course_type', 'normal') == 'virtual':
        flash("Virtual courses cannot be enrolled via the company portal. Contact your administrator.", "warning")
        return redirect(url_for("company_courses"))
    cart = session.get("company_cart", [])
    for sid in student_ids:
        entry = {"course_id": course_id, "student_id": sid}
        if entry not in cart:
            cart.append(entry)
    session["company_cart"] = cart
    flash("Added to cart.", "success")
    return redirect(url_for("company_courses"))


@app.route("/company/cart/remove", methods=["POST"])
@require_company
def company_cart_remove():
    course_id = request.form.get("course_id", type=int)
    student_id = request.form.get("student_id", type=int)
    cart = session.get("company_cart", [])
    if student_id:
        cart = [e for e in cart if not (e["course_id"] == course_id and e["student_id"] == student_id)]
    else:
        cart = [e for e in cart if e["course_id"] != course_id]
    session["company_cart"] = cart
    flash("Removed from cart.", "success")
    return redirect(url_for("company_cart"))


@app.route("/company/checkout", methods=["POST"])
@require_company
def company_checkout():
    cid = session["company_id"]
    company = db.session.get(Company, cid)
    cart = session.get("company_cart", [])
    if not cart:
        flash("Cart is empty.", "warning")
        return redirect(url_for("company_cart"))

    # Count unique enrollments needed (skip already-enrolled)
    needed = 0
    for item in cart:
        existing = CourseEnrollment.query.filter_by(
            student_id=item["student_id"], course_id=item["course_id"]).first()
        if not existing:
            needed += 1

    # Credit check
    balance = company.enrollment_credits or 0
    if balance < needed:
        flash(f"Not enough credits. You have {balance} but need {needed}. Contact your administrator to purchase more credits.", "danger")
        return redirect(url_for("company_cart"))

    order = CompanyOrder(company_id=cid, status="created", total_cents=0)
    db.session.add(order)
    db.session.flush()
    enrolled_count = 0
    for item in cart:
        course = db.session.get(Course, item["course_id"])
        student = db.session.get(Student, item["student_id"])
        if not course or not student:
            continue
        existing = CourseEnrollment.query.filter_by(student_id=student.id, course_id=course.id).first()
        if existing:
            continue
        enrollment = CourseEnrollment(student_id=student.id, course_id=course.id, approved=True)
        db.session.add(enrollment)
        enrolled_count += 1

    # Deduct credits
    company.enrollment_credits = balance - enrolled_count
    txn = CreditTransaction(
        company_id=cid,
        amount=-enrolled_count,
        balance_after=company.enrollment_credits,
        description=f"Enrolled {enrolled_count} student(s) via company portal",
    )
    db.session.add(txn)
    order.status = "paid"
    db.session.commit()
    session.pop("company_cart", None)
    flash(f"Checkout complete! {enrolled_count} enrollment(s) created. {enrolled_count} credit(s) used. Remaining: {company.enrollment_credits}", "success")
    return redirect(url_for("company_dashboard"))


