@app.route('/api/student/approved-courses', methods=['GET'])
def api_student_approved_courses():
    """Returns the list of approved course IDs for the logged-in student.
    Used by dashboard to auto-refresh when new courses are approved."""
    if 'student_id' not in session:
        return jsonify({"error": "Unauthorized"}), 401

    # Get the student object using the session student_id (student number)
    user = Student.query.filter_by(student_id=session['student_id']).first()
    if not user:
        return jsonify({"error": "Student not found"}), 404

    # Query enrollments using the database primary key (user.id)
    approved_enrollments = CourseEnrollment.query.filter_by(
        student_id=user.id,
        approved=True
    ).all()

    approved_ids = [e.course_id for e in approved_enrollments]
    return jsonify({
        "approved_course_ids": approved_ids,
        "count": len(approved_ids)
    })

