############## Password Setup (Company-created Students) ###################

@app.route("/setup-password/<token>", methods=["GET", "POST"])
def setup_password(token):
    student = Student.query.filter_by(password_setup_token=token).first()
    if not student:
        flash("Invalid or expired link. Please contact your company administrator.", "danger")
        return redirect(url_for("login"))
    if student.password_setup_token_expires and student.password_setup_token_expires < _now_sast():
        flash("This link has expired. Please contact your company administrator for a new one.", "danger")
        return redirect(url_for("login"))

    if request.method == "POST":
        password = request.form.get("password") or ""
        confirm = request.form.get("confirm_password") or ""
        if password != confirm:
            flash("Passwords do not match.", "danger")
            return render_template("setup_password.html", student=student)
        if not is_strong_password(password):
            flash("Password must be at least 8 characters with uppercase, lowercase, digit and special character.", "danger")
            return render_template("setup_password.html", student=student)

        student.password = generate_password_hash(password, method="pbkdf2:sha256")
        student.password_setup_token = None
        student.password_setup_token_expires = None
        student.otp = None  # Clear any OTP so they can log in directly
        db.session.commit()
        flash("Password set! You can now log in.", "success")
        return redirect(url_for("login"))

    return render_template("setup_password.html", student=student)

