@app.route("/admin/company-approvals")
@require_accountant_or_role('Super Admin')
def admin_company_approvals():
    pending_companies = Company.query.filter_by(approved=False, rejected=False).order_by(Company.created_at.desc()).all()
    return render_template("admin/company_approvals.html", pending_companies=pending_companies)


@app.route("/admin/company/<int:company_id>/approve", methods=["POST"])
@require_accountant_or_role('Super Admin')
def admin_approve_company(company_id):
    company = db.session.get(Company, company_id)
    if not company:
        flash("Company not found.", "danger")
        return redirect(url_for("admin_company_approvals"))
    company.approved = True
    company.approved_at = _now_sast()
    company.approved_by = session.get("admin_id")
    db.session.commit()

    # Send approval email to all company users
    for cu in company.users:
        send_email(cu.email, "Company Registration Approved!",
                   f"""<h2 style="color:#17306B; margin:0 0 16px;">Registration Approved</h2>
                   <p>Hi {cu.full_name},</p>
                   <p>Great news! Your company <strong>{company.name}</strong> has been approved on Professional Training.</p>
                   <p>You can now log in and start managing your students and enrollments.</p>
                   <div style="text-align:center; margin:24px 0;">
                     <a href="{url_for('company_login', _external=True)}" style="display:inline-block; background:#17306B; color:#fff; padding:12px 32px; border-radius:8px; text-decoration:none; font-weight:600;">Log In Now</a>
                   </div>""")

    flash(f"Company '{company.name}' has been approved.", "success")
    return redirect(url_for("admin_company_approvals"))


@app.route("/admin/company/<int:company_id>/reject", methods=["POST"])
@require_accountant_or_role('Super Admin')
def admin_reject_company(company_id):
    company = db.session.get(Company, company_id)
    if not company:
        flash("Company not found.", "danger")
        return redirect(url_for("admin_company_approvals"))
    reason = (request.form.get("rejection_reason") or "").strip() or "No reason provided."
    company.rejected = True
    company.rejected_at = _now_sast()
    company.rejection_reason = reason
    db.session.commit()

    # Send rejection email
    for cu in company.users:
        send_email(cu.email, "Company Registration Update",
                   f"""<h2 style="color:#17306B; margin:0 0 16px;">Registration Update</h2>
                   <p>Hi {cu.full_name},</p>
                   <p>Unfortunately, your company <strong>{company.name}</strong> registration could not be approved at this time.</p>
                   <p><strong>Reason:</strong> {reason}</p>
                   <p>If you believe this is an error, please contact us at
                   <a href="mailto:info@professionaltraining.co.za">info@professionaltraining.co.za</a>.</p>""")

    flash(f"Company '{company.name}' has been rejected.", "info")
    return redirect(url_for("admin_company_approvals"))


