############## Company System Schema Migration ###################
def _ensure_company_schema():
    """Add new columns for company system if they don't exist (SQLite safe)."""
    with app.app_context():
        insp = sa_inspect(db.engine)

        # --- New table: company_popia_consent ---
        if not insp.has_table("company_popia_consent"):
            CompanyPopiaConsent.__table__.create(bind=db.engine, checkfirst=True)
            print("✅ Created table: company_popia_consent")

        # --- Company model new columns ---
        if insp.has_table("company"):
            existing = {c["name"] for c in insp.get_columns("company")}
            new_cols = [
                ("postal_address", "VARCHAR(240)"),
                ("postal_code", "VARCHAR(20)"),
                ("street_address", "VARCHAR(240)"),
                ("street_postal_code", "VARCHAR(20)"),
                ("vat_number", "VARCHAR(40)"),
                ("purchase_order_number", "VARCHAR(80)"),
                ("purchase_order_attached", "BOOLEAN DEFAULT 0"),
                ("entity_responsible", "VARCHAR(160)"),
                ("cellphone", "VARCHAR(60)"),
                ("approved", "BOOLEAN DEFAULT 0"),
                ("approved_at", "DATETIME"),
                ("approved_by", "INTEGER"),
                ("rejected", "BOOLEAN DEFAULT 0"),
                ("rejected_at", "DATETIME"),
                ("rejection_reason", "TEXT"),
            ]
            for col, col_type in new_cols:
                if col not in existing:
                    db.session.execute(text(f"ALTER TABLE company ADD COLUMN {col} {col_type}"))
                    print(f"  ✅ Added company.{col}")
            db.session.commit()

        # --- CompanyUser model new columns ---
        if insp.has_table("company_user"):
            existing = {c["name"] for c in insp.get_columns("company_user")}
            if "otp" not in existing:
                db.session.execute(text("ALTER TABLE company_user ADD COLUMN otp VARCHAR(8)"))
                db.session.commit()
                print("  ✅ Added company_user.otp")

        # --- Student model new columns ---
        if insp.has_table("student"):
            existing = {c["name"] for c in insp.get_columns("student")}
            student_cols = [
                ("company", "VARCHAR(160)"),
                ("password_setup_token", "VARCHAR(64)"),
                ("password_setup_token_expires", "DATETIME"),
                ("created_by_company_id", "INTEGER"),
            ]
            for col, col_type in student_cols:
                if col not in existing:
                    db.session.execute(text(f"ALTER TABLE student ADD COLUMN {col} {col_type}"))
                    print(f"  ✅ Added student.{col}")
            db.session.commit()

        # --- Drop UNIQUE constraint on student.email ---
        # Company students share the company contact's email, so email cannot be unique.
        # SQLite requires table recreation to remove an inline UNIQUE constraint.
        try:
            row = db.session.execute(text(
                "SELECT sql FROM sqlite_master WHERE type='table' AND name='student'"
            )).fetchone()
            if row and 'UNIQUE (email)' in row[0]:
                print("  🔄 Removing UNIQUE constraint on student.email ...")
                # Get current column list to build a safe INSERT
                cols = [c["name"] for c in insp.get_columns("student")]
                col_list = ", ".join(cols)
                # Rebuild CREATE TABLE from original, stripping only the email UNIQUE
                import re
                original_sql = row[0]
                # Remove  ", \n\tUNIQUE (email)"  or  ",\nUNIQUE (email)"  patterns
                new_sql = re.sub(r',\s*UNIQUE\s*\(email\)', '', original_sql)
                # Also handle if UNIQUE (email) comes before other constraints (unlikely but safe)
                new_sql = re.sub(r'UNIQUE\s*\(email\)\s*,', '', new_sql)
                db.session.execute(text("ALTER TABLE student RENAME TO _student_old"))
                db.session.execute(text(new_sql))
                db.session.execute(text(f"INSERT INTO student ({col_list}) SELECT {col_list} FROM _student_old"))
                db.session.execute(text("DROP TABLE _student_old"))
                # Recreate indexes that were on the old table
                db.session.execute(text("CREATE INDEX IF NOT EXISTS ix_student_email ON student (email)"))
                db.session.execute(text("CREATE INDEX IF NOT EXISTS ix_student_date_joined ON student (date_joined)"))
                db.session.execute(text("CREATE INDEX IF NOT EXISTS ix_student_popi_accepted_at ON student (popi_accepted_at)"))
                db.session.execute(text("CREATE INDEX IF NOT EXISTS ix_student_popi_version ON student (popi_version)"))
                db.session.execute(text("CREATE INDEX IF NOT EXISTS ix_student_company ON student (company)"))
                db.session.commit()
                print("  ✅ Removed UNIQUE constraint on student.email")
        except Exception as e:
            db.session.rollback()
            print(f"  ⚠️ Could not remove email unique constraint: {e}")

        # --- New table: company_branch ---
        if not insp.has_table("company_branch"):
            CompanyBranch.__table__.create(bind=db.engine, checkfirst=True)
            print("  ✅ Created table: company_branch")

        # --- CompanyUser: branch_id column ---
        if insp.has_table("company_user"):
            existing_cu = {c["name"] for c in insp.get_columns("company_user")}
            if "branch_id" not in existing_cu:
                db.session.execute(text("ALTER TABLE company_user ADD COLUMN branch_id INTEGER"))
                db.session.commit()
                print("  ✅ Added company_user.branch_id")

        # --- Student: branch_id column ---
        if insp.has_table("student"):
            existing_st = {c["name"] for c in insp.get_columns("student")}
            if "branch_id" not in existing_st:
                db.session.execute(text("ALTER TABLE student ADD COLUMN branch_id INTEGER"))
                db.session.commit()
                print("  ✅ Added student.branch_id")

        print("[OK] Company schema migration complete.")

        # --- ModerationEscalationLog review question columns ---
        if insp.has_table("moderation_escalation_log"):
            existing = {c["name"] for c in insp.get_columns("moderation_escalation_log")}
            esc_cols = [
                ("review_q1", "VARCHAR(10)"),
                ("review_q2", "VARCHAR(10)"),
                ("review_q3", "VARCHAR(10)"),
                ("review_q4", "VARCHAR(10)"),
            ]
            for col, col_type in esc_cols:
                if col not in existing:
                    db.session.execute(text(f"ALTER TABLE moderation_escalation_log ADD COLUMN {col} {col_type}"))
                    print(f"  ✅ Added moderation_escalation_log.{col}")
            db.session.commit()

_ensure_company_schema()
############## End Company System Schema Migration ###################


