# ─── Assessment Monitor (Final Assessment Heartbeat) ───────────────
def _build_assessment_session_rows():
    """Shared builder for the assessment monitor route + its JSON refresh."""
    now = _now_sast()
    stale_cutoff = now - timedelta(minutes=3)        # no heartbeat in 3 min -> stale
    recent_cutoff = now - timedelta(hours=24)        # only show finishes from last 24h

    # Auto-mark any open session that stopped heartbeating long ago. Keeps the
    # "active" list honest after closed tabs or crashes.
    stale_open = (AssessmentSession.query
                  .filter(AssessmentSession.finished_at.is_(None),
                          AssessmentSession.last_heartbeat_at < stale_cutoff)
                  .all())
    if stale_open:
        for s in stale_open:
            s.finished_at = s.last_heartbeat_at
            s.finish_reason = 'stale'
        db.session.commit()

    active = (AssessmentSession.query
              .filter(AssessmentSession.finished_at.is_(None))
              .order_by(AssessmentSession.started_at.desc())
              .all())
    recent_finished = (AssessmentSession.query
                       .filter(AssessmentSession.finished_at.isnot(None),
                               AssessmentSession.finished_at >= recent_cutoff)
                       .order_by(AssessmentSession.finished_at.desc())
                       .all())

    def _row(s):
        elapsed = (s.finished_at or now) - s.started_at
        return {
            'id': s.id,
            'student_name': f"{s.student.name} {s.student.surname}" if s.student else '—',
            'student_number': s.student_number or (s.student.student_id if s.student else ''),
            'course_key': s.course_key,
            'started_at': s.started_at,
            'last_heartbeat_at': s.last_heartbeat_at,
            'finished_at': s.finished_at,
            'finish_reason': s.finish_reason,
            'elapsed_seconds': int(elapsed.total_seconds()),
        }

    return [_row(s) for s in active], [_row(s) for s in recent_finished]


@app.route('/admin/assessment-monitor')
@require_role('Admin')
def admin_assessment_monitor():
    """Live view of who is currently in a Final Assessment, plus the last
    24h of finished sittings. Refreshes itself every 15s."""
    active_rows, finished_rows = _build_assessment_session_rows()
    return render_template('admin_assessment_monitor.html',
                           active_rows=active_rows,
                           finished_rows=finished_rows)


@app.route('/api/assessment-monitor')
@require_role('Admin')
def api_assessment_monitor():
    """JSON for the assessment monitor's auto-refresh."""
    active_rows, finished_rows = _build_assessment_session_rows()

    def _ser(rows):
        return [{**r,
                 'started_at': r['started_at'].isoformat() if r['started_at'] else None,
                 'last_heartbeat_at': r['last_heartbeat_at'].isoformat() if r['last_heartbeat_at'] else None,
                 'finished_at': r['finished_at'].isoformat() if r['finished_at'] else None,
                 } for r in rows]

    return jsonify(active=_ser(active_rows), finished=_ser(finished_rows))


# ─── Session Logs Admin Page ───────────────────────────────────────
@app.route('/admin/session-logs')
@require_role('Developer')
def admin_session_logs():
    """View login/logout audit trail."""
    page_num = request.args.get('page', 1, type=int)
    per_page = 50
    user_type_filter = request.args.get('type', '')
    search = request.args.get('q', '').strip()

    query = SessionLog.query

    if user_type_filter:
        query = query.filter_by(user_type=user_type_filter)
    if search:
        like = f"%{search}%"
        query = query.filter(
            (SessionLog.user_id.ilike(like)) |
            (SessionLog.user_name.ilike(like)) |
            (SessionLog.ip_address.ilike(like))
        )

    total = query.count()
    logs = (query.order_by(SessionLog.timestamp.desc())
            .offset((page_num - 1) * per_page)
            .limit(per_page)
            .all())

    total_pages = (total + per_page - 1) // per_page

    return render_template('session_logs.html',
                           logs=logs,
                           page=page_num,
                           total_pages=total_pages,
                           total=total,
                           type_filter=user_type_filter,
                           search=search)


# ─── Handbook table bootstrap ───────────────────────────────────────
def _ensure_handbook_table():
    """Create the handbooks table if missing and seed the 3 existing hardcoded handbooks."""
    with app.app_context():
        insp = sa_inspect(db.engine)

        if not insp.has_table("handbooks"):
            Handbook.__table__.create(bind=db.engine, checkfirst=True)
            print("  ✅ Created table: handbooks")

        if not insp.has_table("handbook_page_map"):
            HandbookPageMap.__table__.create(bind=db.engine, checkfirst=True)
            print("  ✅ Created table: handbook_page_map")

        # Seed the 3 existing hardcoded handbooks (only if table is empty)
        try:
            if Handbook.query.count() == 0:
                seeds = [
                    {"course_id": 26, "title": "ASAT General Learner Handbook",
                     "pdf_filename": "ASAT_General_Learner_Handbook_Jan 2026.pdf", "version": "Jan 2026"},
                    {"course_id": 25, "title": "ASAT Cargo Learner Handbook",
                     "pdf_filename": "ASAT Cargo - Learner Handbook - Jan 2026.pdf", "version": "Jan 2026"},
                    {"course_id": 27, "title": "RPAS Security Manual",
                     "pdf_filename": "RPAS_Security_Manual_2025.pdf", "version": "2025"},
                ]
                for s in seeds:
                    db.session.add(Handbook(
                        course_id=s["course_id"], title=s["title"],
                        pdf_filename=s["pdf_filename"], version=s["version"],
                        published_at=datetime.now(), is_active=True,
                    ))
                db.session.commit()
                print("  ✅ Seeded 3 existing handbooks into DB")
        except Exception as e:
            print(f"  ⚠ Handbook seed skipped: {e}")

_ensure_handbook_table()


def _ensure_taskboard_tables():
    """Create board_tasks and sprint_submissions tables if they don't exist."""
    with app.app_context():
        insp = sa_inspect(db.engine)
        if not insp.has_table("board_tasks"):
            BoardTask.__table__.create(bind=db.engine, checkfirst=True)
            print("  ✅ Created table: board_tasks")
        if not insp.has_table("sprint_submissions"):
            SprintSubmission.__table__.create(bind=db.engine, checkfirst=True)
            print("  ✅ Created table: sprint_submissions")

_ensure_taskboard_tables()


