@app.route('/api/taskboard/tasks/<int:task_id>', methods=['PATCH'])
@require_role('Super Admin')
def api_taskboard_update(task_id):
    """Update task fields. Score requires Developer role."""
    task = db.session.get(BoardTask, task_id)
    if not task:
        return jsonify({"ok": False, "error": "Not found"}), 404
    data = request.get_json(silent=True) or {}
    role_level = ROLE_LEVELS.get(session.get('admin_role', ''), 0)

    if "title" in data:
        task.title = (data["title"] or "").strip() or task.title
    if "description" in data:
        task.description = (data["description"] or "").strip() or None
    if "score" in data:
        if role_level < 3:
            return jsonify({"ok": False, "error": "Only Super Admins and Developers can edit task points"}), 403
        task.score = int(data["score"]) if data["score"] is not None else None
        task.scored_by = session.get("admin_email", session.get("admin_name", ""))
    if "status" in data and data["status"] in ("backlog", "sprint"):
        # Block moving tasks into/out of sprint if sprint is locked this week
        if task.status != data["status"]:
            now = _now_sast()
            latest = SprintSubmission.query.order_by(SprintSubmission.submitted_at.desc()).first()
            if latest and latest.submitted_at and latest.submitted_at.isocalendar()[:2] == now.isocalendar()[:2]:
                return jsonify({"ok": False, "error": "Sprint is locked until next week"}), 400
        task.status = data["status"]
    if "position" in data:
        task.position = int(data["position"])

    task.updated_at = _now_sast()
    db.session.commit()
    return jsonify({"ok": True})


