def api_taskboard_reorder():
    """Reorder sprint tasks."""
    data = request.get_json(silent=True) or {}
    order = data.get("order", [])
    for pos, tid in enumerate(order):
        task = db.session.get(BoardTask, int(tid))
        if task and task.status == 'sprint':
            task.position = pos
    db.session.commit()
    return jsonify({"ok": True})


@app.route('/api/taskboard/sprint/submit', methods=['POST'])
@require_role('Super Admin')
def api_taskboard_submit_sprint():
    """Submit the current sprint as the weekly work order."""
    # Prevent double-submit in the same ISO week
    now = _now_sast()
    latest = SprintSubmission.query.order_by(SprintSubmission.submitted_at.desc()).first()
    if latest and latest.submitted_at and latest.submitted_at.isocalendar()[:2] == now.isocalendar()[:2]:
        return jsonify({"ok": False, "error": "Sprint already submitted this week"}), 400
    sprint_tasks = BoardTask.query.filter_by(status='sprint').order_by(BoardTask.position).all()
    if not sprint_tasks:
        return jsonify({"ok": False, "error": "No tasks in sprint"}), 400
    total = sum(t.score or 0 for t in sprint_tasks)
    now = _now_sast()
    week_num = now.isocalendar()[1]
    week_label = f"Week {week_num} — {now.strftime('%b %d')}"
    snapshot = json.dumps([
        {"id": t.id, "title": t.title, "score": t.score, "position": t.position}
        for t in sprint_tasks
    ])
    sub = SprintSubmission(
        week_label=week_label,
        submitted_by=session.get("admin_email", session.get("admin_name", "Unknown")),
        total_points=total,
        task_snapshot_json=snapshot,
    )
    db.session.add(sub)
    db.session.commit()
    return jsonify({"ok": True, "week_label": week_label, "total_points": total})


@app.route('/api/taskboard/sprint/unlock', methods=['POST'])
@require_role('Developer')
def api_taskboard_unlock_sprint():
    """Developer-only: remove all of this week's submissions to unlock the sprint."""
    now = _now_sast()
    monday = now - timedelta(days=now.weekday())
    week_start = monday.replace(hour=0, minute=0, second=0, microsecond=0)
    deleted = SprintSubmission.query.filter(SprintSubmission.submitted_at >= week_start).delete()
    db.session.commit()
    if not deleted:
        return jsonify({"ok": False, "error": "Sprint is not locked"}), 400
    return jsonify({"ok": True})


