    print("="*60)
    print(f"Starting server on http://localhost:5000")
    print(f"Database: {app.config['SQLALCHEMY_DATABASE_URI']}")
    print("Press Ctrl+C to stop the server")
    print("="*60 + "\n")
    app.run(host="127.0.0.1", port=5000, debug=True, use_reloader=False)

